        \State \code{Z = Polyrelax.Z;}
        \State \code{P = Polyrelax.Hrep;}
	\end{algorithmic}
	\normalsize
\end{algorithm}	



\subsection{Discrete-time systems with bounded uncertainties} \label{sec:simulation}

The \code{DTsystem} class implements simulation routines. It enables a user-friendly interface for advanced features such as state estimation for a few classes of discrete-time systems subject to bounded uncertainties. 

The first class is a linear system described by
\begin{subequations} \label{eq:systemlinear}
\begin{align}
    \mbf{x}_k & = \mbf{A} \mbf{x}_{k-1} + \mbf{B}_w \mbf{w}_{k-1} + \mbf{B}_u \mbf{u}_{k-1}, \\
    \mbf{y}_k & = \mbf{C} \mbf{x}_{k} + \mbf{D}_v \mbf{v}_{k},
\end{align}
\end{subequations}
where $\mbf{x}_k \in \realset^{n_x}$ is the system state, $\mbf{w}_{k}$ is the process uncertainty, $\mbf{u}_k$ is the known input, $\mbf{y}_k$ is the measured output, and $\mbf{v}_k$ is the measurement uncertainty. The second class is a discrete-time linear descriptor system given by
\begin{subequations} \label{eq:systemdescriptor}
\begin{align}
    \mbf{E} \mbf{x}_k & = \mbf{A} \mbf{x}_{k-1} + \mbf{B}_w \mbf{w}_{k-1} + \mbf{B}_u \mbf{u}_{k-1}, \\
    \mbf{y}_k & = \mbf{C} \mbf{x}_{k} + \mbf{D}_v \mbf{v}_{k}.
\end{align}
\end{subequations}
The third class is a discrete-time system with nonlinear dynamics and nonlinear measurement equations, given by
\begin{subequations} \label{eq:systemnonlinear}
\begin{align}
    \mbf{x}_k & = \mbf{f}(\mbf{x}_{k-1},\mbf{w}_{k-1},\mbf{u}_{k-1}), \\
    \mbf{y}_k & = \mbf{g}(\mbf{x}_{k},\mbf{v}_{k}).
\end{align}
\end{subequations}

\code{DTSystem} objects can be easily created for these classes of discrete-time systems, as shown below:
\begin{itemize}
    \item \code{DTSystem('linear','A',A,'Bw',Bw,...)} creates a discrete-time linear system as in \eqref{eq:systemlinear}.%
    \item \code{DTSystem('descriptor','E',E,'A',A,...)} creates a discrete-time linear  descriptor system as in \eqref{eq:systemdescriptor}.%
    \item \code{DTSystem('nonlinear',modelname)} creates a discrete-time nonlinear  system as in \eqref{eq:systemnonlinear}, where \code{modelname} corresponds to the prefix of function names implementing $\mbf{f}$ and $\mbf{g}$.\footnote{For this syntax example, the current version of {\acron} requires that the user implements functions named \code{modelname_f.m} and \code{modelname_g.m} in the current working folder.}
\end{itemize}

A \code{DTSystem} object allows for straightforward simulation of the respective class of discrete-time system and plotting figures showing the resulting trajectory. Algorithm \ref{alg:dtsystemexample} illustrates some of the capabilities of a \code{DTSystem} object describing a linear system. Step 1 creates the object using the system matrices as inputs. Step 2 simulates the system for an initial state $\mbf{x}_0$, $N$ time steps, and uncertainties $\mbf{w}_k$ and $\mbf{v}_k$ bounded by zonotopes $W$ and $V$, respectively. Step 3 generates figures illustrating the resulting state $\mbf{x}_k$ and output $\mbf{y}_k$, whereas Steps 4 and 5 retrieve their respective values.

\begin{algorithm}[!tb] 
	\caption{Example of the capabilities of a \code{DTSystem} object with input matrices \code{A}, \code{Bw} and \code{C}, \code{Zonotope} objects \code{W} and \code{V}, and initial state \code{x0}, for \code{N} time steps}
	\label{alg:dtsystemexample}
	\scriptsize
	\begin{algorithmic}[1]
        \State \code{linearsys = DTSystem('linear','A',A,'Bw',Bw,'C',C);}
        \State \code{linearsys = simulate(linearsys,x0,N,W,V);}
        \State \code{plot(linearsys);}
        \State \code{x = linearsys.simdata.x;}
        \State \code{y = linearsys.simdata.y;}
	\end{algorithmic}
	\normalsize
\end{algorithm}	



\section{Advanced features of {\acron}} \label{sec:advanced}

\subsection{State estimation of linear systems and descriptor systems} \label{sec:linearsystems}


Our library comes with algorithms implementing a few methods for state estimation of the linear systems \eqref{eq:systemlinear} and \eqref{eq:systemdescriptor}. These are located in the \code{estimation} folder. 

{\acron} implements state estimation of linear systems using zonotopes, constrained zonotopes, and line zonotopes. For bounded uncertainties $\mbf{w}_k \in W$ and $\mbf{v}_k \in V$, state estimation of linear systems consists of recursively computing enclosures $\bar{X}_k$ for the prediction step and $\hat{X}_k$ for the update step, given by, respectively,
\begin{align}
    \bar{X}_k \supseteq \{ & \mbf{A} \mbf{x}_{k-1} + \mbf{B}_w \mbf{w}_{k-1} + \mbf{B}_u \mbf{u}_{k-1} : \nonumber \\
    & \qquad (\mbf{x}_{k-1},\mbf{w}_{k-1}) \in \hat{X}_{k-1} \times W\}, \\
    \hat{X}_k \supseteq \{ & \mbf{C} \mbf{x}_k + \mbf{D}_v \mbf{v}_k = \mbf{y}_k : (\mbf{x}_{k},\mbf{v}_{k}) \in \bar{X}_k \times V \}.
\end{align}

The file \code{zon_linear_estimator.m} implements linear state estimation based on zonotopes, with prediction step given by 
\begin{equation} \label{eq:zonlinearpred}
    \bar{X}_k = \mbf{A} \hat{X}_{k-1} \oplus \mbf{B}_w W \oplus \mbf{B}_u \mbf{u}_{k-1},
\end{equation}
and update step given by
\begin{equation} \label{eq:zonlinearupdate}
    \hat{X}_k = \bar{X}_k \cap (\cap_{j=1}^{n_y} S_j(\mbf{y}_k)), 
\end{equation}
where $S_j(\mbf{y}_k)$ is a \code{Strip} object describing the set of states consistent with $\bar{X}_k$ and the $j$th element of $\mbf{y}_k$. Each strip $S_j(\mbf{y}_k)$ and the intersections in \eqref{eq:zonlinearupdate} are computed according to \cite{Bravo2006}.

The file \code{czon_linear_estimator.m} implements linear state estimation based on constrained zonotopes, as in \cite{Scott2016}. The prediction step is given by \eqref{eq:zonlinearpred}, with the update step computed as
\begin{equation} \label{eq:czonlinearupdate}
    \hat{X}_k = \bar{X}_k \cap_\mbf{C} (\mbf{y}_k \oplus (-\mbf{D}_v V)).
\end{equation}
Finally, the file \code{lzon_linear_estimator.m} implements linear state estimation based on line zonotopes, using \eqref{eq:zonlinearpred} for the prediction step and \eqref{eq:czonlinearupdate} for the update step. All the linear state estimation algorithms in {\acron} take a linear \code{DTSystem} object as input to facilitate the usage of the system matrices in the estimation algorithms.

{\acron} also implements state estimation of linear descriptor systems, using constrained zonotopes and line zonotopes. For bounded uncertainties $\mbf{w}_k \in W$ and $\mbf{v}_k \in V$, state estimation of \eqref{eq:systemdescriptor} consists in recursively computing enclosures $\bar{X}_k$ for the prediction step and $\hat{X}_k$ for the update step, given by, respectively,
\begin{align}
    \bar{X}_k \supseteq \{ & \mbf{x}_k \in \realset^{n_x} : \mbf{E} \mbf{x}_{k} = \mbf{A} \mbf{x}_{k-1} + \mbf{B}_w \mbf{w}_{k-1} + \mbf{B}_u \mbf{u}_{k-1}, \nonumber \\
    & \qquad (\mbf{x}_{k-1},\mbf{w}_{k-1}) \in \hat{X}_{k-1} \times W\}, \\
    \hat{X}_k \supseteq \{ & \mbf{C} \mbf{x}_k + \mbf{D}_v \mbf{v}_k = \mbf{y}_k : (\mbf{x}_{k},\mbf{v}_{k}) \in \bar{X}_k \times V \}.
\end{align}

The file \code{czon_descriptor_estimator.m} implements the state estimation method proposed in \cite{Rego2020b} for the computation of $\bar{X}_k$ and $\hat{X}_k$ using constrained zonotopes, while the file \code{lzon_descriptor_estimator.m} implements the state estimation method proposed in \cite{Rego2024LineZonArxiv} using line zonotopes. Both algorithms take a descriptor \code{DTSystem} object as input to facilitate the usage of the system matrices in the estimation algorithms.
% 

\begin{remark} \rm \label{rem:faultdetection}
    The state estimation methods in {\acron} can be employed for fault detection, by verifying the inclusion of the measurement using \code{isinside} on the respective set.
\end{remark}

\subsection{Active fault diagnosis of linear systems} \label{sec:faultdiag}

The current version of {\acron} implements a method for active fault diagnosis of linear systems using zonotopes. This algorithm is located in the \code{faultdiag} folder. It addresses a system whose trajectories satisfy one of the possible models
\begin{subequations} \label{eq:systemlinearfault}
\begin{align}
    \mbf{x}_k & = \mbf{A}^{[i]} \mbf{x}_{k-1} + \mbf{B}_w^{[i]} \mbf{w}_{k-1} + \mbf{B}_u^{[i]} \mbf{u}_{k-1}, \\
    \mbf{y}_k^{[i]} & = \mbf{C}^{[i]} \mbf{x}_{k} + \mbf{D}_v^{[i]} \mbf{v}_{k}.
\end{align}
\end{subequations}

The file \code{zonAFD_inputdesign.m} implements the open-loop active fault diagnosis algorithm proposed in \cite{Scott2014}. It receives an array of linear \code{DTSystem} objects as input to describe \eqref{eq:systemlinearfault}, and allows the user to choose between solving a mixed-integer quadratic program (MIQP) or an analogous mixed-integer linear program (MILP), to design the input sequence that separates the output reachable tubes of the collection of models \eqref{eq:systemlinearfault}. An example is available in \code{demos/faultdiag}, which reproduces the first example from \cite{Scott2014} using the MIQP method (Fig.~\ref{fig:zonfaultdiagmiqp}), together with results obtained using an MILP approach.% 
