\section{Self-consistent calculations in the BdG model}\label{app:bdg}

\subsection{Self-consistent treatment on a lattice and the supercurrent}  
Assuming singlet pairing only, the gap equation for order parameter $\Delta_{ij}$ for attractive interaction potential $V_{ij}$ between sites $i$ and $j$ is given by:
\begin{equation} \label{eq:gapequation_ij-A}
    \Delta_{ij}=-V_{ij}\text{Tr}\left[\frac{\partial h}{\partial \Delta^*_{ij}}\frac{1}{\beta}\sum_{\omega_{n}}\mathcal{G}(i\omega_n)\right]
\end{equation} which can be derived as the saddle point of the path integral, as described in \cite{Can2021}. We define the unitary operator $U$ that diagonalizes the hamiltonian $H$ such that $U^\dag H U = E$ where $E$ is a diagonal matrix of eigenvalues. Using the definition of the Green's function $\frac{1}{i\omega_n - E}= U^\dag \mathcal{G}(i\omega_n) U$ we obtain
\begin{equation}
\frac{1}{\beta}\sum_n U^\dag  \mathcal{G}(i\omega_n) U e^{i\omega_n0^+} =\frac{1}{\beta}\sum_n \frac{e^{i\omega_n0^+}}{i\omega_n - E} = f(E)
\end{equation}  where multiplied the equation by convergence factor and summed over all fermionic Matsubara frequencies. Note that the RHS of this equation is the fermi factor which we denote $f(E)$ as a diagonal matrix, similar to $E$ we defined above. Inverting this expression we find that 
\begin{equation}
\frac{1}{\beta}\sum_n   \mathcal{G}_{ij}^{\alpha\beta}(i\omega_n)  e^{i\omega_n0^+} = [Uf(E)U^\dag]_{ij}^{\alpha\beta}
\end{equation} 

\subsection{Current operator}
Using the Heisenberg equation of motion 
$dN/dt=i/\hbar\left[H,N\right]$ we compute the charge flow from the degree of freedom $\mu=(r,\alpha,\sigma)$ where we packed position, orbital and spin indices together. $N=c^{\dag}_{\mu} c_{\mu}$ And the net charge flow for $\mu$ us given by 
\begin{equation*}
    \frac{dQ}{dt}=e\frac{dN}{dt}=\frac{ie}{\hbar}[H,N]
\end{equation*} 
with carriers with charge $e$ for the Hamiltonian 
\begin{equation}
    H=t_{\mu\nu}c_\mu^\dag c_\nu + H_{int}.
\end{equation} 
The quartic interaction terms commute with $H$ since they conserve particle number on a given site. Note that we derive this operator before we do the MF decoupling since pairing terms in the SC Hamiltonian will generate additional terms. Only the hopping terms in $H$ will contribute to the current:
\begin{equation}
\frac{dQ_\mu}{dt}=-\frac{ie}{\hbar}\sum_\nu\left[t_{\mu \nu}c^\dag_\mu c_\nu - t_{\nu\mu }c^\dag_\nu c_\mu \right]
\end{equation} where the first term corresponds to charge transport from orbital $\nu$ to $\mu$ and the second term corresponds to the reverse process. This we can consider as the bond current $I_{\mu \nu}$ from site $\nu$ to $\mu$:
\begin{equation}
    I_{\mu \nu}= -\frac{ie}{\hbar}\left[h_{\mu \nu}c^\dag_\mu c_\nu - h_{\nu\mu }c^\dag_\nu c_\mu \right]
\end{equation} More specifically we can write the current operator as  
\begin{equation}
    J_{ij}=\frac{ie}{\hbar}t_{ij}\left(c_{i\uparrow}^\dag c_{j\uparrow} + c_{i\downarrow}^\dag c_{j\downarrow}\right) + h.c.
\end{equation} this can be rewritten in the following form which is useful to cast our equations in particle-hole basis. 
\begin{equation}
    J_{ij}=\frac{ie}{\hbar}\left( t_{ij}c_{i\uparrow}^\dag c_{j\uparrow} + t^*_{ij} c_{i\downarrow} c_{j\downarrow}^\dag\right) + h.c.
\end{equation} Assuming $t_{ij}$ is real (and therefore symmetric), we can write the current operator defining the spinors $\Psi_i=(c_{i\uparrow}, c^\dag_{i\downarrow})$ which in turn becomes
\begin{equation}
    J_{ij}=\frac{ie}{\hbar}t_{ij}\Psi_i^\dagger \begin{pmatrix}
1 & 0 \\
0 & 1 
\end{pmatrix}
\Psi_j + h.c.
\end{equation} 
The expectation value of the current can be written 
\begin{align*}
    \langle J_{ij}\rangle &=\frac{ie}{\hbar}t_{ij}\text{Tr}\left[\Psi_i^\dagger \begin{pmatrix}
1 & 0 \\
0 & 1 
\end{pmatrix}
\Psi_j\right] + h.c. \\
& =\frac{ie}{\hbar}t_{ij}\text{Tr}\left[\Psi_j \Psi_i^\dagger 
\right] + h.c. \\ 
& =\frac{ie}{\hbar}t_{ij}\sum_\alpha \left[\langle \Psi_{j\alpha} \Psi_{i\alpha}^\dagger \rangle-\langle \Psi_{i\alpha} \Psi_{j\alpha}^\dagger \rangle \right]
\end{align*}
where we used the cyclic property of trace and rewrote it as sum over $\alpha$ which denotes the BdG degrees of freedom. Note that the expectation values we are interested in can be expressed as imaginary time Gorkov Green's functions \begin{align}
    \mathcal{G}^{\alpha\beta}_{ij}(0^+)=-\langle \Psi_{i\alpha} \Psi_{j\beta}^\dagger \rangle
\end{align} Using the imaginary time relation $\mathcal{G}(0^-)-\mathcal{G}(0^+)=1$ \cite{tremblay2008refresher} and the Matsubara frequency space representation $\mathcal{G}(\tau)=\beta^{-1}\sum_n\mathcal{G}(i\omega_n)e^{-i\omega_n\tau}$ we can show that the expectation value of the bond current is given by


\begin{equation}\label{eq:currentingreensfunctions}
    \langle J_{ij}\rangle=\frac{ie}{\hbar}t_{ij}\frac{1}{\beta}\sum_{n,\alpha}\left[\mathcal{G}_{ij}^{\alpha\alpha}(i\omega_n)e^{i\omega_n0^+}-\mathcal{G}_{ji}^{\alpha\alpha}(i\omega_n)e^{i\omega_n0^+}\right]
\end{equation}

Note that this expression appears in \ref{eq:currentingreensfunctions} and when combined we obtain the equation below that we use in our numerical calculations of current 
\begin{align}
     J_{ij} &=\frac{ie}{\hbar}t_{ij} \sum_\alpha\left[U f(E)U^\dagger\right]^{\alpha\alpha}_{ij} - \left[U f(E)U^\dagger\right]^{\alpha\alpha}_{ji}  \nonumber \\  &= -\frac{2e}{\hbar}t_{ij} \sum_\alpha \text{Im}\left[U f(E)U^\dagger\right]^{\alpha\alpha}_{ij} 
\end{align} This expression also appears in the gap equation \ref{eq:gapequation_ij} and simplifies it into a form that is suitable for numerical calculations.

