\title{\Large\bf Efficient application of the Voigt functions in the Fourier transform}

%\bigskip
\author{
\normalsize\bf Sanjar M. Abrarov, Rehan Siddiqui, Rajinder K. Jagpal \\
\normalsize\bf and Brendan M. Quine}

\date{June 24, 2025}
\maketitle
%\vspace{1cm}%\bigskip

\begin{abstract}
In this work, we develop a method for rational approximation of the Fourier transform (FT) based on the real and imaginary parts of the complex error function
\[
w(z) = e^{-z^2}(1 - {\rm{erf}}(-iz)) = K(x,y) + iL(x,y), \qquad z = x + iy,
\]
where $K(x,y)$ and $L(x,y)$ are known as the Voigt and imaginary Voigt functions, respectively. In contrast to our previous rational approximation of the FT, the expansion coefficients in this method are not dependent on the values of a sampled function. As the values of the Voigt functions remain the same, this approach can be used for rapid computation with help of look-up tables. Mathematica codes with some examples are presented.
\vspace{0.2cm}
\\
\noindent {\bf Keywords:} rational approximation; Fourier transform; Voigt function; complex error function
\\
\end{abstract}


\section{Introduction}

The forward and inverse Fourier transforms (FTs) can be defined in a symmetric form as~\cite{Hansen2014, Bracewell2000}
\begin{equation}
\label{FT1} % Fourier transform 1
{\cal F}\left\{f(t)\right\}(\nu) = \int_{-\infty}^\infty {f(t)e^{-2\pi i\nu t}dt} = {\hat f}(\nu)
\end{equation}
and
\begin{equation}
\label{IFT} % Inverse Fourier transform
{\cal F}^{-1}\left\{\hat f(\nu)\right\}(t) = \int_{-\infty}^\infty {{\hat f}(\nu)e^{2\pi i\nu t}d\nu} = f(t),
\end{equation}
respectively. In~this work, we will consider only the forward FT \eqref{FT1} since due to symmetric form the approximations for the inverse FT (IFT) \eqref{IFT} can be readily obtained from the forward FT by change of the~variables.

Equation \eqref{IFT} shows how the function $\hat{f}(\nu)$ is transformed from $\nu$-domain ({\it e.g.} frequency domain) back to its original $t$-domain ({\it e.g.} time domain). More generally, however, the~IFT is also applicable for transformation from $t$-domain to $\nu$-domain. This can be written conveniently in a shorthand notation as
\[
{\cal F}^{-1}{\Omega(t)}(\nu) = {\hat \Omega}^{-1}(\nu),
\]
where $\Omega(t)$ is an arbitrary function with $t$-domain.

There are relations between a function $f(t)$ and its even $f_{even}(t)$ and odd $f_{odd}(t)$ components. In~particular, the~even and odd functions can be readily generated by using the following relations
\begin{equation}
\label{EFI} % even function identity
f_{even}(t) = \frac{f(t) + f(-t)}{2}
\end{equation}
and
\begin{equation}
\label{OFI} % odd function identity
f_{odd}(t) = \frac{f(t) - f(-t)}{2}
\end{equation}
such that
\[
f(t) = f_{even}(t) + f_{odd}(t).
\]
Therefore, due to the linearity of the FT we can also state that
\begin{equation}
\label{FTI} % Fourier Transform identity
{\hat f(\nu)} = {\hat f_{even}}(\nu) + {\hat f_{odd}}(\nu).
\end{equation}

Using Euler’s identity
\[
e^{ix} = \cos(x) + i\sin(x),
\]
we can express Equation \eqref{FT1} as
\begin{equation}
\label{FTTF} % Fourier Transform in trigonometric form
{\cal F}\left\{f(t)\right\}(\nu) = \int_{-\infty}^\infty {f(t)\left(\cos(2\pi \nu t) - i\sin(2\pi\nu t)\right)}\,dt.
\end{equation}

Since an even function satisfies the condition
\begin{equation}
\label{I4EF} % identity for even function
f_{even}(t) = f_{even}(-t),
\end{equation}
it follows that
\[
\int_{-\infty}^\infty {f_{even}(t)\cos(2\pi\nu t)}\,dt = 2\int_0^\infty {f_{even}(t)\cos(2\pi\nu t)}\,dt
\]
and
\[
\int_{-\infty}^\infty {f_{even}(t)\sin(2\pi\nu t)}\,dt = 0.
\]

Since an odd function satisfies the condition
\begin{equation}
\label{I4OF} % identity for off function
-f_{odd}(t) = f_{odd}(-t),
\end{equation}
we have
\[
\int_{-\infty}^\infty {f_{odd}(t)\cos(2\pi\nu t)}\,dt = 0
\]
and
\[
\int_{-\infty}^\infty {f_{odd}(t)\sin(2\pi\nu t)}\,dt = 2\int_0^\infty  {f_{odd}(t)\sin(2\pi\nu t)}\,dt.
\]

Consequently, from~these relations and Equations \eqref{FTI} and \eqref{FTTF} we get the following identities
\begin{equation}
\label{FT2} % Fourier Transform 2
{\cal F}\left\{f_{even}(t)\right\}(\nu) = 2\int_0^\infty {f_{even}(t)\cos(2\pi\nu t)}\,dt = {\hat f}_{even}(\nu)
\end{equation}
and
\begin{equation}
\label{FT3} % Fourier Transform 3
{\cal F}\left\{f_{odd}(t)\right\}(\nu) = -2i\int_0^\infty {f_{odd}(t)\sin(2\pi\nu t)}\,dt = {\hat f}_{odd}(\nu).
\end{equation}

Equations \eqref{FT2} and \eqref{FT3} are of primary importance since they will be used 
in derivation of the new approximation of the~FT.

In a recent publication, we developed a new methodology providing a rational approximation of the FT~\cite{Abrarov2021}. Specifically, the~FT of a function $f(t)$ can be approximated as a rational function consisting of low-order polynomials, $3 \times 4$, 
in~form
\begin{equation}
\label{RA} % rational approximation
\begin{aligned}
{\hat f}(\nu) &\approx \sum_{m = 1}^M {\left(\frac{\alpha_m + \beta_m \nu^2}{\kappa_m + \lambda_m\nu^2 + \nu^4} - i\frac{\gamma_m\nu + \theta_m\nu^3}{\kappa_m + \lambda_m\nu^2 + \nu^4}\right)}
\\
&= \sum_{m = 1}^M {\frac{\alpha_m - i\gamma_m\nu + \beta_m\nu^2 - i\theta_m\nu^3}{\kappa_m + \lambda_m\nu ^2 + \nu^4}},
\end{aligned}
\end{equation}
where expansion coefficients are given by
\small
\[
\begin{aligned}
\alpha_m &= \frac{1}{8M\pi^4}\sum_{n = -N}^N {f_{even}(nh)e^{nh\sigma}\left(\mu_m^2 + \sigma^2\right)\left(\sigma\cos(nh\mu_m) + \mu_m\sin(nh\mu_m)\right)},
\\
\beta_m &= \frac{1}{2M\pi^2}\sum_{n = - N}^N {f_{even}(nh)e^{nh\sigma}\left(\sigma\cos(nh\mu_m) - \mu_m\sin(nh\mu_m)\right)},
\end{aligned}
\]
\[
\begin{aligned}
\gamma_m &= \frac{1}{4M\pi^3}\sum_{n = -N}^N {f_{odd}(nh)e^{nh\sigma}\left(\left(\sigma^2 - \mu_m^2\right)\cos(nh\mu_m) + 2\sigma\mu_m\sin(nh\mu_m)\right)},
\\
\theta_m &= \frac{1}{M\pi}\sum_{n = -N}^N {f_{odd}(nh)e^{nh\sigma}\cos(nh\mu_m)},
\\
\kappa_m &= \frac{1}{16\pi^4}\left(\mu_m^2 + \sigma^2\right)^2,
\\
\lambda_m &= \frac{1}{2\pi^2}\left(\sigma^2 - \mu_m^2\right),
\\
{\mu _m} &= \frac{\pi(m - 1/2)}{Mh}
\end{aligned}
\]
\normalsize
and $h$, $\sigma$ are fitting~parameters.

It should be noted that in our previous publication~\cite{Abrarov2015}, we {\it de facto} applied a rational approximation of the FT. Therefore, a~new method of rational approximation, described in our paper~\cite{Abrarov2021}, is just a generalization of a sampling and integration technique that we proposed earlier in~\cite{Abrarov2015} to derive rapid and high-accuracy rational approximations of the complex error function. Specifically, in~our earlier publication~\cite{Quine2013}, we found a very useful product-to-sum identity
\begin{equation}
\label{SFI} % sinc function identity
\prod_{n = 1}^k\cos\left(\frac{x}{2^n}\right) = \frac{1}{2^{k - 1}}\sum_{n = 1}^{2{^{k - 1}}}\cos\left(\frac{n - 1/2}{2^{k - 1}}x\right).
\end{equation}

Since according to Euler's formula for the sinc function (this formula is also attributed to Vi\`ete) \cite{Kac1959, Gearhart1990}
\[
{\rm sinc}(x) = \frac{\sin(x)}{x} = \prod_{n = 1}^\infty\cos\left(\frac{x}{2^n}\right),
\]
from Equation \eqref{SFI} it follows that~\cite{Abrarov2015}
\[
{\rm sinc}(x) = \lim_{K \to \infty}\frac{1}{K}\sum_{n = 1}^K\cos\left(\frac{n - 1/2}{K}x\right),
\]
where $K = 2^{k - 1}$. Consequently, from~this limit we can find the following approximation
\begin{equation}
\label{ICE} % incomplete cosine expansion
{\rm sinc}(x) \approx \frac{1}{K}\sum_{n = 1}^K\cos\left(\frac{n - 1/2}{K}x\right), \qquad\qquad K\gg 1
\end{equation}
that can be used efficiently as a sampling function~\cite{Abrarov2015}. Since in this approximation the integer $K$ is a finite number, we can regard this sampling function as an incomplete cosine expansion of the sinc~function.

Applying the sampling function \eqref{ICE} together with a new method of rational approximation based on integration with exponential decay multiplier that we developed in \cite{Abrarov2021,Abrarov2015}, we can obtain the rational approximation \eqref{RA} of the FT. Some examples of rational approximation \eqref{RA} of the FT are shown in our work~\cite{Abrarov2021} and can be visualized by running a provided Matlab code (Matlab code can be copy-pasted from this link: \url{https://arxiv.org/pdf/2001.07533}).

There are many methods for rational approximations such as Pad\'e approximation~\cite{Baker1961, Brezenski1996}, minimax approximation~\cite{Filip2018, Nakatsukasa2020}, Remez algorithm~\cite{Pachon2009, Hofreither2021}, and so on. However, to~the best of our knowledge, a~method of rational approximation that we developed in~\cite{Abrarov2021} is new and has never been reported in 
scientific~literature.

The small-order polynomials $3 \times 4$ in quotients of rational approximation \eqref{RA} may be advantageous for numerical analysis with any kind of computations including matrix manipulations, integrations and differentiations. However,~rational approximation \eqref{RA} requires re-computation of the four expansion coefficients $\alpha_m$, $\beta_m$, $\gamma_m$, and $\theta_m$ every time the sampled function $f(t)$ changes. In~this work, we propose a new method for rational approximation of the 
FT based on a sum of the real and imaginary parts of the complex error function~\cite{Abramowitz1972, Armstrong1972, Schreier1992}. Such a representation of rational approximation of the FT does not require re-computation when shape of the sampled function $f(t)$ changes.


\section{Preliminaries}

The complex error function, also commonly known as the Faddeeva function, can be defined as \cite{Schreier1992, Armstrong1967}

\begin{equation}
\label{CEF1} % complex error function 1
w(z) = e^{-{z^2}}\left(1 + \frac{2i}{\sqrt\pi}\int_0^z {e^{t^2}dt}\right),
\end{equation}
where $z = x + iy$. Comparing equation \eqref{CEF1} with definition of the error function \cite{Abramowitz1972}
\[
{\rm{erf}}(z) = \frac{2}{\sqrt\pi}\int_0^z {e^{-{t^2}}}dt
\]
one can see that the complex error function can be expressed as \cite{Abramowitz1972, Zaghloul2012}
\begin{equation}
\label{CEF2} % complex error function 2
w(z) = e^{-{z^2}}\left[1 - {\rm erf}(-iz)\right].
\end{equation}
Therefore, the complex error function $w(z)$ can be considered as a reformulation of the error function ${\rm erf}(z)$.

Complex error function satisfies the following relation
\begin{equation}
\label{I4CEF} % identity for comple error functon
w(-z) = 2e^{-{z^2}} - w(z).
\end{equation}

It can be shown that the complex error function is a solution of the following differential equation
\[
w'(z) + 2zw(z) = \frac{2i}{\sqrt\pi},
\]
with initial condition
\[
w(0) = 1.
\]

The complex error function $w(z)$ is closely related to the complex probability function \cite{Armstrong1972, Schreier1992}
\begin{equation}
\label{CPF} % complex probability function
W(z) = \frac{i}{\pi}\int_{-\infty}^\infty {\frac{e^{-t^2}}{z - t}}dt.
\end{equation}

There is a direct relationship between these two functions. In particular, both functions are equal to each other on the upper half of the complex plane \cite{Armstrong1972, Schreier1992}
\[
w(z) = W(z), \qquad {\rm Im}[z] > 0.
\]

Separating the real and imaginary parts of the complex probability function \eqref{CPF} as
\[
W(z) = K(x,y) + iL(x,y),
\]
results in
\begin{equation}
\label{KF} % K-function
K(x,y) = \frac{y}{\pi}\int_{-\infty}^\infty \frac{e^{-t^2}}{y^2 + (x - t)^2}dt
\end{equation}
and
\begin{equation}
\label{LF} % L-function
L(x,y) = \frac{1}{\pi}\int_{-\infty}^\infty \frac{e^{-t^2}(x - t)}{y^2 + (x - t)^2}dt,
\end{equation}
respectively. 

The real part $K(x,y)$ of the complex probability function is known as the Voigt function that is widely used in Atmospheric Physics to describe absorption and emission of atmospheric molecules \cite{Berk2017, Pliutau2017, Pliutau2021}. 

The imaginary part $L(x,y)$ is also used in various fields of Physics and Engineering \cite{Balazs1969, Chan1986}. It does not have a specific name. However, following Zaghloul and Ali \cite{Zaghloul2012}, for the convenience we will also refer to the function $L(x,y)$ as the imaginary Voigt function.

It is not difficult to show that substituting the following identity \cite{Armstrong1972}
\begin{equation}
\label{I4I} % identity for integral
\frac{y}{y^2 + (x - t)^2} = \int_0^\infty  e^{-yq}\cos\left[(x - t)q\right]\,dq, \qquad y > 0,
\end{equation}
into equation \eqref{KF}, we obtain \cite{Armstrong1972, Srivastava1987}
\[
\begin{aligned}
K(x,y) &= \frac{1}{\pi}\int_{-\infty}^\infty e^{-t^2}\frac{y}{y^2 + (x - t)^2}dt
\\
&= \frac{1}{\pi}\int_0^\infty {\int_{-\infty}^\infty e^{-t^2}e^{-yq}\cos\left[(x - t)q\right]dt\,dq}
\\
&= \frac{1}{\pi}\int_0^\infty e^{-yq}\int_{-\infty}^\infty e^{-t^2}\cos\left[(x - t)q\right]dt\,dq 
\end{aligned}
\]
and since
\[
\int_{-\infty}^\infty e^{-t^2}\cos\left[(x - t)q\right]\,dt = \sqrt\pi e^{-q^2/4}\cos(qx), 
\]
we can write
\begin{equation}
\label{VF} % Voigt function
K(x,y) = \frac{1}{\sqrt\pi}\int_0^\infty e^{-t^2/4 - yt}\cos(xt)\,dt, \qquad y > 0.
\end{equation}

Similarly, substituting the identity 
$$
\frac{x - t}{y^2 + (x - t)^2} = \int_0^\infty e^{-yq}\sin(q(x - t))\,dq, \qquad y > 0,
$$
into equation \eqref{LF} we get \cite{Srivastava1987}
\[
\begin{aligned}
L(x,y) &= \frac{1}{\pi}\int_{-\infty}^\infty e^{-t^2}\frac{x-t}{y^2 + (x - t)^2}dt
\\
&= \frac{1}{\pi}\int_0^\infty {\int_{-\infty}^\infty e^{-t^2}e^{-yq}\sin\left[(x - t)q\right]dt\,dq}
\\
&= \frac{1}{\pi}\int_0^\infty e^{-yq}\int_{-\infty}^\infty e^{-t^2}\sin\left[(x - t)q\right]dt\,dq 
\end{aligned}
\]
and since
\[
\int_{-\infty}^\infty e^{-t^2}\sin\left[(x - t)q\right]\,dt = \sqrt\pi e^{-q^2/4}\sin(qx), 
\]
we have
\begin{equation}
\label{IVF} % imaginary Voigt function
L(x,y) = \frac{1}{\sqrt\pi}\int_0^\infty e^{-{t^2}/4 - yt}\sin(xt)dt, \qquad y > 0.
\end{equation}

Sum of the equations above in terms of the real and imaginary parts yields \cite{Srivastava1987}
\[
\begin{aligned}
K(x,y) + iL(x,y) &= \frac{1}{\sqrt\pi}\int_0^\infty e^{-t^2/4 - yt}\left[\cos(xt) + i\sin(xt)\right]\,dt
\\
&= \frac{1}{\sqrt\pi}\int_0^\infty e^{-t^2/4 - yt}e^{ixt}\,dt
\\
&= \frac{1}{\sqrt\pi}\int_0^\infty e^{-t^2/4}e^{(-y - ix)t}\,dt
\\
&= e^{(y - ix)^2}\left[1 - {\rm erf}(y - ix)\right].
\end{aligned}
\]
We can see now that this equation is consistent with equation \eqref{CEF2} of the complex error function $w(z)$.


\section{Results and discussion}

\subsection{Methodology}

Consider the rectangular function (solitary rectangular function) that can be \mbox{defined as}
\[
f_r(t) = \left\{
\begin{aligned}
&1, &\quad  &-1/2 < t < 1/2,
\\
&1/2, &\quad &\left| t \right| = 1/2,
\\
&0, &\quad &{\rm{otherwise.}}
\end{aligned}
\right.
\]

This function can be expressed by the following limit:
\begin{equation}
\label{L4RF} % limit for rectangular function
f_r(t) = \lim\limits_{k \to \infty} \frac{1}{\left(2t\right)^{2k} + 1}.
\end{equation}
Consequently, we can approximate the rectangular function by taking sufficiently large value of the parameter $k$.

Figure~1 shows the rectangular function and its approximation at $k = 35$ by dashed red and light blue colors, respectively. As~we can see, at~$k = 35$ Equation \eqref{L4RF} approximates the rectangular function reasonably well. Therefore, we can use the following approximation:
\begin{equation}
\label{A4RF} % approximation for rectangular function
f_r(t) \approx \frac{1}{(2t)^{70} + 1}
\end{equation}
and apply it to perform numerically the~FT.

\begin{figure}[ht]
\begin{center}
\includegraphics[width=18pc]{fig1.png}\hspace{2pc}%
\begin{minipage}[b]{28pc}
\vspace{0.3cm}
{\sffamily {\bf{Fig. 1.}} Rectangular and sawtooth functions and their approximations. Rectangular and sawtooth functions are shown by dashed red and solid black lines. Even $1/\left(\left(2t \right)^{70}+1\right)$ and odd $t/\left(\left(2t \right)^{70}+1\right)$ functions are shown by blue and green curves.}
\end{minipage}
\end{center}
\end{figure}

Previously, we have used the following sampling function:
\begin{equation}
\label{SF} % sampling function
s(t) = \frac{h}{c\sqrt \pi}{e^{-\left(\frac{t}{c}\right)^2}},
\end{equation}
where $h$ and $c$ are small fitting parameters, for~high-accuracy approximation of the complex error function~\cite{Abrarov2016}. Thus, applying this sampling function over the points $nh$ to approximation \eqref{A4RF}, the~rectangular function can be approximated as
\begin{equation}
\label{SA4RF} % sampled approximaton for rectangular function
\begin{aligned}
f_r(t) &\approx \sum_{n = -N}^N {s(t - nh)f_r(nh)}
\\
&= \frac{h}{c\sqrt\pi}\sum_{n = -N}^N {e^{-(\frac{t - nh}{c})^2}f_r(nh)}
\\
&= \frac{h}{c\sqrt\pi}\sum_{n = -N}^N {e^{\left(2\frac{nh}{c^2}\right)t}e^{-\left(\frac{t}{c}\right)^2}e^{-\left(\frac{nh}{c}\right)^2}f_r(nh)}. 
\end{aligned}
\end{equation}

Figure~2 shows the approximations of the rectangular function at different fitting parameters $h$ and $c$. Specifically, the~green curve corresponds to $h = 0.065$, $c = 0.035$, and $N = 25$, the~red curve corresponds to $h = 0.05$, $c = 0.03$, and $N = 25$ while the light blue curve corresponds to $h = 0.02$, $c = 0.025$, and $N = 25$. The~rectangular function is also shown by black dashed~curve.

\begin{figure}[ht]
\begin{center}
\includegraphics[width=18pc]{fig2.png}\hspace{2pc}%
\begin{minipage}[b]{28pc}
\vspace{0.3cm}
{\sffamily {\bf{Fig. 2.}} The rectangular function (dashed black curve) and its approximations by sampling at $h=0.065$, $c=0.035$, $N=25$ (green curve), $h=0.05$, $c=0.03$, $N=25$ (red curve) and $h=0.02$, $c=0.025$, $N=25$ (light blue curve).}
\end{minipage}
\end{center}
\end{figure}

Since the rectangular function $f_r(t)$ is even, we can use Equation \eqref{FT2} for the FT. Thus, the~substitution of approximation \eqref{SA4RF} into Equation \eqref{FT2} leads to
\[
\begin{aligned}
{\hat f}_r(\nu) &\approx 2\frac{h}{c\sqrt\pi}\int_{0}^\infty \sum_{n = -N}^N e^{-\left(\frac{t}{c}\right)^2 + \left(2\frac{nh}{c^2}\right)t}e^{-\left(\frac{nh}{c}\right)^2}f_r(nh)\cos(2\pi\nu t)dt
\\
&= 2\frac{h}{\sqrt\pi}\int_{0}^\infty \sum_{n = -N}^N e^{-t^2 + \frac{2nh}{c}t}e^{-\left(\frac{nh}{c}\right)^2}f_r(nh)\cos(2\pi\nu ct)dt
\\
&= \frac{h}{\sqrt\pi}\int\limits_{0}^\infty \sum_{n = -N}^N e^{-\frac{t^2}{4} - \frac{nh}{c}t}e^{ - \left(\frac{nh}{c} \right)^2}f_r(nh)\cos(\pi\nu ct)dt.
\end{aligned}
\]
Comparing the  approximation above with Equation \eqref{VF}, one can see that the FT of the rectangular function \eqref{L4RF} can be expressed in terms of the Voigt function
\begin{equation}
\label{FT4RF}
{\hat f}_r(\nu) \approx h\sum_{n = -N}^N e^{-\left(\frac{nh}{c}\right)^2}f_r(nh)K\left(\pi\nu c,\frac{nh}{c}\right).
\end{equation}

As a simple example for an odd function, we can consider the sawtooth function (solitary 
sawtooth function)
\[
f_s(t) = tf_r(t) = \left\{
\begin{aligned}
&t, &\quad  &-1/2 < t < 1/2,
\\
&-1/4, &\quad & t = -1/2,
\\
&1/4, &\quad & t = 1/2,
\\
&0, &\quad &{\rm{otherwise.}}
\end{aligned}
\right.
\]
Since this function can be express though the following limit
\begin{equation}
\label{L4SF} % limit for sawtooth function
f_s(t) = t\lim_{k\to\infty} \frac{1}{(2t)^{2k} + 1},
\end{equation}
we can approximate it by multiplying $t$ with Equation \eqref{A4RF} as follows
\begin{equation}
\label{A4SF} % approximation for sawtooth function
f_s(t) \approx t\,\frac{1}{(2t)^{70} + 1}.
\end{equation}

Figure~1 shows the sawtooth function \eqref{L4SF} and its approximation \eqref{A4SF} by black and light green curves, respectively.

Applying the sampling function \eqref{SF} over the points $nh$ to approximation \eqref{A4SF}, we obtain
$$
\begin{aligned}
f_s(t) &\approx \sum_{n = -N}^N {s(t - nh)f_s(nh)}
\\
&= \frac{h}{c\sqrt\pi}\sum_{n = -N}^N e^{-(\frac{t - nh}{c})^2}f_s(nh)
\\
&= \frac{h}{c\sqrt\pi}\sum_{n = -N}^N e^{\left(2\frac{nh}{c^2}\right)t}e^{-\left(\frac{t}{c}\right)^2}e^{-\left(\frac{nh}{c}\right)^2}f_s(nh). 
\end{aligned}
$$
Consequently, the~FT of the sawtooth function \eqref{L4SF} can be approximated as
\[
\begin{aligned}
{\hat f}_s(\nu) &\approx -2i\frac{h}{c\sqrt\pi}\int_{0}^\infty\sum_{n = -N}^N e^{-\left(\frac{t}{c}\right)^2 + \left(2\frac{nh}{c^2}\right)t}e^{-\left(\frac{nh}{c}\right)^2}f_s(nh)\sin(2\pi\nu t)dt
\\
&= -2i\frac{h}{\sqrt\pi}\int_{0}^\infty\sum_{n = -N}^N e^{-t^2 + \frac{2nh}{c}t}e^{-\left(\frac{nh}{c}\right)^2}f_s(nh)\sin(2\pi\nu ct)dt
\\
&= i\frac{h}{\sqrt\pi}\int_{0}^\infty\sum_{n = -N}^N e^{-\frac{t^2}{4} - \frac{nh}{c}t}e^{-\left(\frac{nh}{c}\right)^2}f_s(nh)\sin(\pi\nu ct)dt.
\end{aligned}
\]
Comparing this equation with the imaginary Voigt function \eqref{IVF}, we can rearrange equation above as
\begin{equation}
\label{FT4SF} % Fourier transform for sawtooth function
{\hat f}_s(\nu) \approx ih\sum_{n = -N}^N e^{-\left(\frac{nh}{c}\right)^2}f_s(nh)L\left(\pi\nu c,\frac{nh}{c}\right).
\end{equation}

The applied methodology for the FTs of the rectangular and sawtooth \linebreak functions \eqref{FT4RF} and \eqref{FT4SF} can be generalized to any even or odd functions as
\begin{equation}
\label{FT4EF} % Fourier transform for even function
{\hat f}_{even}(\nu) \approx h\sum_{n = -N}^N e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)K\left(\pi\nu c,\frac{nh}{c}\right)
\end{equation}
and
\begin{equation}
\label{FT4OF} % Fourier transform for odd function
{\hat f}_{odd}(\nu) \approx ih\sum_{n = -N}^N e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)L\left(\pi\nu c,\frac{nh}{c}\right).
\end{equation}

Due to symmetric properties of the even and odd functions (see Equations \eqref{I4EF} and \eqref{I4OF}), the~number of the summation terms in these approximations can be reduced by a factor of~two.

Let us rearrange Equation \eqref{FT4EF} in the following form
\[
\begin{aligned}
{\hat f}_{even}(\nu) \approx & \, h\left[f_{even}(0)K(\pi\nu c,0) + \sum_{n = 1}^N e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)K\left(\pi\nu c,\frac{nh}{c}\right)\right.
\\
&\left. + \sum_{n = -N}^{-1} e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)K\left(\pi\nu c,\frac{nh}{c} \right)\right].
\end{aligned}
\]

Change of summation index~as
\[
\sum_{n = -N}^{- 1} e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)K\left(\pi\nu c,\frac{nh}{c}\right) = \sum_{n = 1}^N e^{-\left(\frac{-nh}{c}\right)^2}f_{even}(-nh)K\left(\pi\nu c,\frac{- nh}{c}\right) 
\]
leads to
\[
\begin{aligned}
{\hat f}_{even}(\nu) \approx &\, h\left[f_{even}(0)K(\pi\nu c,0) + \sum_{n = 1}^N e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)K\left(\pi\nu c,\frac{nh}{c}\right)\right.  
\\
&\left. + \sum_{n = 1}^N e^{-\left(\frac{-nh}{c}\right)^2}f_{even}(-nh)K\left(\pi\nu c,\frac{-nh}{c} \right)\right].
\end{aligned}
\]

Since according to Equation \eqref{I4EF}
\[
e^{-\left(\frac{-nh}{c}\right)^2} = e^{-\left(\frac{nh}{c}\right)^2},
\]
\[
f_{even}(-nh) = f_{even}(nh),
\]
and since
\[
K(x,0)=e^{-x^2} \Rightarrow K(\pi\nu c,0)=e^{-(\pi\nu c)^2},
\]
we can write
\begin{equation}
\label{FT4LT1} % Fourier Transform for look-up table 1
{\hat f}_{even}(\nu) \approx h \left(f_{even}(0)e^{-(\pi\nu c)^2} + \sum_{n = 1}^N {e^{-\left(\frac{nh}{c}\right)^2}f_{even}(nh)V_k\left(\pi\nu c,\frac{nh}{c}\right)}\right),
\end{equation}
where
\begin{equation}
\label{PVK} % parameter $V_k$
V_k\left(\pi\nu c,\frac{nh}{c}\right)=K\left(\pi\nu c,\frac{nh}{c}\right) + K\left(\pi\nu c,\frac{-nh}{c}\right)
\end{equation}
Equation \eqref{FT4OF} can be expanded as
\begin{equation}
\label{FT4OFE} % Fourier Transform for odd function expanded
\begin{aligned}
{\hat f}_{odd}(\nu) \approx &\, ih\left[f_{odd}(0)L(\pi\nu c,0) + \sum_{n = 1}^N e^{-\left(\frac{nh}{c} \right)^2}f_{odd}(nh)L\left(\pi\nu c,\frac{nh}{c}\right)\right.
\\
&+ \left.\sum_{n = -N}^{-1} e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)L\left(\pi\nu c,\frac{nh}{c} \right)\right].
\end{aligned}
\end{equation}

Taking into consideration that
\[
\sum_{n = -N}^{-1} e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)L\left(\pi\nu c,\frac{nh}{c}\right) = \sum_{n = 1}^N e^{-\left(\frac{-nh}{c}\right)^2}f_{odd}(-nh)L\left(\pi\nu c,\frac{- nh}{c}\right) 
\]
such that according to \eqref{I4OF}
\[
f_{odd}(-nh) = -f_{odd}(nh)
\]
and since
\[
L(\pi\nu c,0)=0,
\]
we can recast Equation \eqref{FT4OFE} as given by
\[
\begin{aligned}
{\hat f}_{odd}(\nu) \approx &\, ih\left[\sum_{n = 1}^N {e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)L\left(\pi\nu c,\frac{nh}{c}\right)}\right.
\\
&\left. + \sum_{n = 1}^N {e^{-\left(\frac{-nh}{c} \right)^2}f_{odd}(-nh)L\left(\pi\nu c,\frac{-nh}{c} \right)} \right]
\end{aligned}
\]
or
\[
\begin{aligned}
{\hat f}_{odd}(\nu) \approx &\, ih\Bigg[f_{odd}(0)L(\pi\nu c,0)
\\
&+ \sum_{n = 1}^N e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)\left(L\left(\pi\nu c,\frac{nh}{c}\right) - L\left(\pi\nu c,\frac{-nh}{c}\right)\right)\Bigg]
\end{aligned}
\]
or
\begin{equation}
\label{FT4LT2} % Fourier Transform for look-up table 2
{\hat f}_{odd}(\nu) \approx \, ih\sum_{n = 1}^N e^{-\left(\frac{nh}{c}\right)^2}f_{odd}(nh)V_\ell\left(\pi\nu c,\frac{nh}{c}\right),
\end{equation}
where
\begin{equation}
\label{PVL} % parameter $V_\ell$
V_\ell\left(\pi\nu c,\frac{nh}{c}\right)=L\left(\pi\nu c,\frac{nh}{c}\right) - L\left(\pi\nu c,\frac{-nh}{c}\right).
\end{equation}

At first glance, the FT Formulas \eqref{FT4LT1} and \eqref{FT4LT2} may appear computationally costly as they require user defined (external) function files. However, unlike Equation \eqref{RA}, the~expansion coefficients $V_k(\pi\nu c,nh/c)$ and $V_\ell(\pi\nu c,nh/c)$, shown by  Equations \eqref{PVK} and \eqref{PVL}, respectively, do not require re-computations every time when we change the sampled function $f(t)$ to any other function. Since the values $V_k(\pi\nu c,nh/c)$ and $V_\ell(\pi\nu c,nh/c)$ 
always remain the same regardless of the shape of the sampled function, these values can be precomputed in form of the look-up tables. Such implementation makes computation rapid as the required values $V_k(\pi\nu c,nh/c)$ and $V_\ell(\pi\nu c,nh/c)$ can be instantly picked up from the computer memory during computation of the FT. Furthermore, many algorithms, based on rational approximations, have been developed for rapid and high-accuracy computation of the Voigt/complex error function~\cite{Humlicek1979, Weideman1994, Wells1999, Letchworth2007, Schreier2011, Schreier2018, Abrarov2018a, Abrarov2018b, Azah2021, Thompson2024, Mangaldan}. Therefore, the~proposed technique can also be used as an alternative for rational approximation \eqref{RA} of the~FT.


\subsection{Numerical results}

The FT of the rectangular function can be readily found by integration as
\begin{equation}
\label{AFT1} % analitical Fourier Transform 1
{\hat f}_r(\nu) = \int_{-\infty}^\infty {f_r(t)e^{-2\pi i\nu t}dt = \int_{-1/2}^{1/2} e^{-2\pi i\nu t}dt = \, {\rm{sinc}}(\pi \nu)}.
\end{equation}
Similarly, we can find the FT of the sawtooth function as follows
\begin{equation}
\label{AFT2} % analitical Fourier Transform 2
\begin{aligned}
{\hat f}_s(\nu) &= \int_{-\infty}^\infty f_s(t)e^{- 2\pi i\nu t}dt = \int_{-\infty}^\infty tf_r(t)e^{-2\pi i\nu t}dt
\\
&= \int_{-1/2}^{1/2} te^{-2\pi i\nu t}dt = \, i\frac{\pi\nu\cos(\pi\nu) - \sin(\pi\nu)}{2\pi^2\nu^2},
\end{aligned}
\end{equation}
We can use these analytical results for comparison with numerical FTs computed by using Equations \eqref{FT4LT1} and \eqref{FT4LT2}.

Figure~3 shows numerical FTs of rectangular and the sawtooth functions by light green and magenta curves, respectively. Equations \eqref{AFT1} and \eqref{AFT2} are also shown by dashed black~curves.

