\section{Preliminaries}
First, the following local existence theory, where the initial density is strictly away from vacuum, can be shown by similar arguments as in  \cite{Ma2013}:
\begin{lemma}\label{local}
    Assume that the initial data $(\rho_0, u_0, d_0)$ satisfies the regularity condition \eqref{ia}.
  %   and the compatibility condition
  %   \begin{equation}\label{cc}
		% -\mathrm{div}\left(\mu \rho_0^\alpha \bigl(\nabla u_0+\nabla^\bot u_0\bigr)\right)+\nabla P_0=\rho_0^\frac{1}{2}g,
  %   \end{equation}
  %   for some $(P_0,g)\in H^1\times L^2$. 
    Then there exists a small time $T$ and a unique strong solution $(\rho, u, d)$ to the initial boundary value problem \eqref{ins}-\eqref{bc} such that
\begin{equation}\label{l-r}
    \left\{ \begin{array}{l}
    \rho\in C([0,T];D^{1,2}\cap D^{1,q}),\
    \nabla u\in C([0,T];H^1)\cap L^2([0,T];W^{1,q}),\\
    \rho_t \in C([0,T];L^q),\
    \sqrt{\rho}u_t\in L^\infty([0,T];L^2),\ 
    u_t\in L^2([0,T];H^1_0),\\
    d-e\in C([0,T;H^3])\cap L^2(0,T;H^4), d_t\in C([0,T;H^1])\cap L^2(0,T;H^2).
    \end{array} \right.
\end{equation}
% Furthermore, if $T^\ast$is the maximal existence time of the local strong solution $(\rho, u)$, then either
% $T^\ast=\infty$ or
% \begin{equation}\label{blow-up}
%     \sup_{0\leq t\leq T^\ast}\left(\|\nabla\rho\|_{L^q}+\|\nabla u\|_{L^2}\right)=\infty.
% \end{equation}
\end{lemma}

Next, the following well-known Gagliardo-Nirenberg inequality  will be used frequently later (see \cite{ladyzhenskaia1968linear}).
\begin{lemma}[Gagliardo-Nirenberg Inequality]\label{G-N}
Let 1 $\leq q \le  +\infty$ be a positive extended real quantity. Let $j$ and $m$  be non-negative integers such that $ j < m$. Furthermore, let $1 \leq r \leq \infty$ be a positive extended real quantity,  $p \geq 1$  be real and  $\theta \in [0,1]$  such that the relations
\begin{equation}
    \dfrac{1}{p} = \dfrac{j}{n} + \theta \left( \dfrac{1}{r} - \dfrac{m}{n} \right) + \dfrac{1-\theta}{q}, \qquad \dfrac jm \leq \theta \leq 1,
\end{equation}
hold. Then, 
\begin{equation}
    \|\nabla^j u\|_{L^p(\mathbb{R}^n)} \leq C\|\nabla^m u\|_{L^r(\mathbb{R}^n)}^\theta\|u\|_{L^q(\mathbb{R}^n)}^{1-\theta},
\end{equation}
where $u \in L^q(\mathbb{R}^n)$  such that  $\nabla^m u \in L^r(\mathbb{R}^n)$. Moreover, if $q>1$ and $r>3$,
\begin{equation}
\|u\|_{C(\overline{\mathbb{R}^n})}\leq C\|u\|^{q(r-3)/(3r+q(r-3))}_{L^q(\mathbb{R}^n)}\|\nabla u\|^{3r/(3r+q(r-3))}_{L^r(\mathbb{R}^n)},
\end{equation}
where $u \in L^q(\mathbb{R}^n)$  such that  $\nabla u \in L^r(\mathbb{R}^n)$.
The constant $C > 0$  depends on the parameters $j,\,m,\,n,\,q,\,r,\,$ and $\theta$.

\end{lemma}

