\section{A priori estimates}

For any fixed time $T>0$, $(\rho,u, d)$ is the unique local strong solution to \eqref{ins}-\eqref{bc} on $\mathbb{R}^3\times (0,T]$ with initial data $(\rho_0,u_0, d_0)$ satisfying \eqref{ia}, which is guaranteed by Lemma 
\ref{local}.






Define
\begin{gather}\label{As1}
    \mathcal{E}_d(T)\triangleq\sup_{t\in[0,T] }\|\nabla 
    d \|_{L^3},\\
    %\label{As2}\mathcal{E}_u(T) \triangleq \sup_{t\in[0,T] } \bar\rho^{\alpha}\|\nabla u \|_{L^2}^2 +\int_0^{T}  \|\sqrt{\rho} u_t \|_{L^2}^2\,dt,\\
    %\label{As3}\mathcal{E}_\rho(T) \triangleq \sup_{t\in[0,T] }\|\nabla \rho \|_{L^q}.\\
    \mathcal{E}_{\rho,1}(T) \triangleq \sup_{t\in[0,T] }\|\rho-\bar\rho \|_{L^\infty},\\
	\mathcal{E}_{\rho,2}(T) \triangleq \sup_{t\in[0,T] }\|\nabla \rho \|_{L^q}^2
	+ \bar \rho^{\gamma-\alpha} \int_0^{T}  \|\nabla \rho \|_{L^q}^2dt,\\
	\mathcal{E}_{\rho,3}(T) \triangleq \sup_{t\in[0,T] }\|\nabla \rho \|_{L^2}^2
	+ \bar \rho^{\gamma-\alpha} \int_0^{T}  \|\nabla \rho \|_{L^2}^2dt,\\
	\mathcal{E}_{u,1}(T) \triangleq \mu \frac{\bar\rho^{\alpha} }{2^{\alpha+1}} \sup_{t\in[0,T] }\|\nabla u \|_{L^2}^2
	+ \frac 12  \int_0^{T}  \|\sqrt{\rho} u_t \|_{L^2}^2dt,\\
	\mathcal{E}_{u,2}(T) \triangleq \sup_{t\in[0,T] }\|\sqrt{\rho} u_t \|_{L^2}^2
	+ \mu \frac{\bar\rho^{\alpha} }{2^{\alpha+1}}  \int_0^{T}  \|\nabla u_t \|_{L^2}^2dt.
\end{gather}


We have the following key proposition.

\begin{proposition}\label{pr}
Under the conditions of Theorem \ref{global},for 
    \begin{equation}\label{b}
        \beta=\max\{3-\gamma,0\}
    \end{equation}
there exist positive constants  $\Lambda_0$ depending on $a,\mu_1, \mu_2,\nu, \lambda,  \alpha,\gamma$,  $\|G(\rho_0)\|_{L^1}, \|\nabla\rho_0\|_{L^q}, \| u_0\|_{H^2},$ $ \|\nabla d_0\|_{H^2}$, 
and $\varepsilon_0$ depending only on the Sobolev constants, 
and $N_i=N_i(a,\mu_1,\mu_2,\nu, \lambda,  \alpha,\gamma,\|\rho_0-\bar\rho\|_{L^{\gamma}}, \|\nabla \rho_0\|_{L^q}, \|\nabla u_0\|_{H^1}, \|\nabla d_0\|_{H^2}), i=1,2,4$ $N_3=N_3(\mu_1, \mu_2, \|\nabla u_0\|_{L^2})$,  such that if $(\rho,u,d)$ is a smooth solution to the problem (\ref{ins})--(\ref{bc}) on $\mathbb{R}^3\times (0,T]$ satisfying
    \begin{equation}\label{a1}
    \begin{aligned}
        \mathcal{E}_d(T)\leq 2\delta,
        ~\mathcal{E}_{\rho,1}(T) \le \frac{\bar \rho}{2}, 
        ~\mathcal{E}_{\rho,2}(T) \le 2N_1 \bar\rho^{\beta},
        ~\mathcal{E}_{\rho,3}(T) \le 2N_2 \bar\rho^{\beta},\\
	~\mathcal{E}_{u,1}(T) \le 2^{\alpha+2}N_3 \bar\rho^{\alpha},
        ~\mathcal{E}_{u,2}(T) \le 3 N_4 \bar\rho^{2\alpha-1}, \qquad\qquad\quad 
    \end{aligned}
    \end{equation}
for some $\delta<1$ sufficiently small (defined in \eqref{delta}), then the following estimates hold:
    \begin{equation}
        \begin{aligned}
        \mathcal{E}_d(T)\leq \delta,
        ~\mathcal{E}_{\rho,1}(T) \le \frac{\bar \rho}{4}, 
        ~\mathcal{E}_{\rho,2}(T) \le N_1 \bar\rho^{\beta},
        ~\mathcal{E}_{\rho,3}(T) \le N_2 \bar\rho^{\beta},\\
	~\mathcal{E}_{u,1}(T) \le 2^{\alpha+1}N_3 \bar\rho^{\alpha},
        ~\mathcal{E}_{u,2}(T) \le 2 N_4 \bar\rho^{2\alpha-1},  \qquad\qquad\quad
    \end{aligned}
    \end{equation}
	provided 
    \begin{equation}
		\bar\rho\ge \Lambda_0,\quad \|\nabla d_0\|_{L^3}\leq  \varepsilon_0.
    \end{equation}     
\end{proposition}
First, the basic energy inequality of the system \eqref{ins} reads
\begin{lemma}
    Under the assumption $ \mathcal{E}_{\rho,1}(T) \le \frac{\bar \rho}{2}$, it holds that
    \begin{align}\label{basic-est-0}
		&\sup_{0\le t\le T} \left(\bar \rho \| u\|_{L^2}^2 + \bar \rho^{\gamma-2}\|\rho- \bar \rho \|_{L^2}^2 + \|\nabla d\|_{L^2}^2\right)   +  \int_{0}^{T} \bar\rho^{\alpha}\|\nabla u\|_{L^2}^2+\|\Delta d+|\nabla d|^2d\|_{L^2}^2 dt \nonumber\\
        &\le C(\bar\rho\|u_0\|_{L^2}^2+ \|G(\rho_0)\|_{L^1}^\gamma +\|\nabla d_0\|_{L^2}^2) \le C \bar \rho,
	\end{align}
 where $C$ depends on $\|u_0\|_{L^2},\|G(\rho_0)\|_{L^1}, \|\nabla d_0\|_{L^2}$.

    Furthermore, under the additional assumptions $\mathcal{E}_{u,1}(T) \le 2^{\alpha+2}N_3 \bar\rho^{\alpha}, \mathcal{E}_d(T)\le 2\delta$ with $\delta$ sufficiently small, we have
    %\eqref{a2} with $\delta$ sufficiently small, we have
	% \begin{equation}\label{basic-est}
	% 	\sup_{0\le t\le T} \left(\bar \rho \| u\|_{L^2}^2+\|\nabla d\|_{L^2}^2\right)   +  \int_{0}^{T} \bar\rho^{\alpha}\|\nabla u\|_{L^2}^2+\|\nabla^2 d\|_{L^2}^2 dt \le C(\bar\rho+\delta).
	% \end{equation}
    \begin{equation}\label{basic-est}
		\sup_{0\le t\le T} \|\nabla d\|_{L^2}^2  +  \int_{0}^{T} \|\nabla^2 d\|_{L^2}^2 dt \le C\|\nabla d_0\|_{L^2}^2,
    \end{equation}
    provided $\bar \rho>1$.
\end{lemma}

\begin{proof}
First, it follows from \eqref{a1} that 
    \begin{equation}\label{upbd}
        \frac{\bar \rho }{2} \le \rho \le \frac{3\bar \rho}{2}.
    \end{equation}
Multiplying \eqref{ins}$_2$ by $u$ and integrating the resultant equation, we obtain after integration by parts that 
 \begin{equation}\label{d1}
    \begin{aligned}
        &\frac{d}{dt} \left( \frac{1}{2} \|\sqrt{\rho} u\|_{L^2}^2 + \|G(\rho)\|_{L^1} \right) + \mu_1 \frac{\bar \rho^{\alpha}}{2^\alpha}\|\nabla u\|_{L^2}^2\\
        &\leq  \frac{d}{dt} \left( \frac{1}{2} \|\sqrt{\rho} u\|_{L^2}^2 + \|G(\rho)\|_{L^1} \right)+2\mu_1 \int\rho^\alpha|\mathcal{D}(u)|^2 dx + \mu_2 \int \rho^\alpha (\mathrm{div} u)^2 dx \\
        &=-\nu \int u\cdot\nabla d\cdot\Delta d\, dx,
    \end{aligned}
\end{equation}
where $G(\rho)$ is defined in \eqref{g}. 
 Multiplying \eqref{ins}$_3$ by $- (\Delta d+|\nabla d|^2d)$ and integrating the resultant equation, we obtain from integration by parts and using $|d|=1$ and \eqref{bc}  that 
	\begin{equation}\label{d-1st}
		\begin{aligned}
			&\frac{1}{2} \frac{d}{dt} \|\nabla d\|_{L^2}^2 
   +\lambda \int|\Delta d+|\nabla d|^2d|^2 dx
   =\int u\cdot\nabla d\cdot\Delta d\,dx.
		\end{aligned}
	\end{equation}
	Adding \eqref{d-1st} multiplied by $\nu$ to \eqref{d1}, integrating over $[0, T]$ and using \eqref{upbd}
    and 
    \begin{equation*}
        G(\rho) \sim \bar \rho^{\gamma-2} (\rho-\bar\rho)^2,
    \end{equation*}
    due to \eqref{upbd}, lead to \eqref{basic-est-0}.

 Furthermore, since $|d|=1$ implies $\Delta d\cdot d=-|\nabla d|^2$, one has
 \begin{equation*}
    \int|\Delta d+|\nabla d|^2d|^2\,dx=\int (|\Delta d|^2-|\nabla d|^4)\,dx. 
 \end{equation*}
 % Thus, we obtain from using Lemma \ref{G-N} with $\frac{\partial d}{\partial n}=0$ that
 % \begin{align*}
 %     \|\Delta d\|_{L^2}^2\leq\|\Delta d+|\nabla d|^2d\|_{L^2}^2+\|\nabla d\|_{L^4}^4\leq \|\Delta d+|\nabla d|^2d\|_{L^2}^2+C\|\nabla d\|_{L^3}^2\|\nabla^2 d\|_{L^2}^2
 % \end{align*}
By integration by parts and Sobolev inequality Lemma \ref{G-N}, we have 
\begin{equation}
\begin{aligned}\label{d-ell}
    \|\nabla^2 d\|_{L^2}^2 &=  \|\Delta d\|_{L^2}^2 =  \|\Delta d+|\nabla d|^2d\|_{L^2}^2 +  \|\nabla d\|_{L^4}^4\\
    &\le \|\Delta d+|\nabla d|^2d\|_{L^2}^2 +c_1 \|\nabla d\|_{L^3}^2\|\nabla^2 d\|_{L^2}^2\\
    &\leq  \|\Delta d+|\nabla d|^2d\|_{L^2}^2 + 4\delta^2 c_1 \|\nabla^2 d\|_{L^2}^2\\
    &\leq 2 \|\Delta d+|\nabla d|^2d\|_{L^2}^2,
\end{aligned}
\end{equation}
after choosing 
$$\delta<\frac{1}{2\sqrt{2 c_1}},$$
with $c_1$ depending only on Sobolev constants.
Combining the above result with \eqref{d-1st} gives 
\begin{equation}
    \begin{aligned}
      \frac{d}{dt}\|\nabla d\|_{L^2}^2+\lambda\|\nabla^2 d\|_{L^2}^2
      &\leq C\int|\nabla u||\nabla d|^2 dx
      \leq C\|\nabla u\|_{L^2}\|\nabla d\|_{L^3}\|\nabla d\|_{L^6}\\
      &\leq C\|\nabla u\|_{L^2}\|\nabla d\|_{L^2}^{\frac{1}{2}}\|\nabla^2 d\|_{L^2}^\frac{3}{2}\\
      &\leq \frac{\lambda}{2}\|\nabla^2 d\|_{L^2}^2+C\|\nabla u\|_{L^2}^4\|\nabla d\|_{L^2}^2,
    \end{aligned}
\end{equation}
where we have used 
\begin{equation*}
    \|\nabla d\|_{L^3}\leq C\|\nabla d\|_{L^2}^\frac{1}{2}\|\nabla
    ^2d\|_{L^2}^\frac{1}{2},~~\|\nabla d\|_{L^6}\leq C\|\nabla^2d\|_{L^2}.
\end{equation*}
Applying Gronwall's inequality, we obtain
\begin{equation}\label{359}
    \begin{aligned}
    &\sup_{t\in[0,T]}\|\nabla d\|_{L^2}^2 
    +\lambda \int_{0}^{T} \|\nabla^2 d\|_{L^2}^2 dt \leq \|\nabla d_0\|_{L^2}^2\cdot\exp\left\{C\int_0^T\|\nabla u\|_{L^2}^4 dt\right\}\\
    %&\leq \|\nabla d_0\|_{L^2}^2\exp\left\{\Tilde C(\|\nabla u_0\|_{L^2}, \|\nabla^2 d_0\|_{L^2})\int_0^T\|\nabla u\|_{L^2}^2 dt\right\}\\
    %&\leq C\|\nabla d_0\|_{L^2}^2 \exp\left\{C(\bar\rho^{1-\alpha}\|\nabla u_0\|_{L^2}^2+\bar\rho^{1-\alpha}\|\nabla^2 d_0\|_{L^2}^2)\right\}\\
    &\leq  \|\nabla d_0\|_{L^2}^2
    \exp\left\{C\|\nabla u_0\|_{L^2}^2\bar\rho^{1-\alpha}\right\}\\
    &\leq C\|\nabla d_0\|_{L^2}^2,
    %\leq 2 \|\nabla d_0\|_{L^2}^2, 
    \end{aligned}
\end{equation}
if $\bar \rho >1$.
%if $\bar \rho$ is big enough.
\end{proof}


Next, we can close the a prior assumption $\mathcal{E}_d(T)$.
\begin{lemma}
Under the assumptions that $\mathcal{E}_{u,1}(T) \le 2^{\alpha+2}N_3 \bar\rho^{\alpha}, \mathcal{E}_d(T)\le 2\delta$ with $\delta$ sufficiently small, there exist positive constants $\varepsilon_0$ and $\Lambda_1$ such that 
\begin{equation}
\mathcal{E}_d(T)\le \delta,
\end{equation}
provided $\|\nabla d_0\|_{L^3}\leq  \varepsilon_0\triangleq \frac{\delta}{2}$ and $\bar \rho> \Lambda_1=\Lambda_1(\mu_1,\mu_2, \| \nabla u_0\|_{L^2})$.   
\end{lemma}
\begin{proof}
    Taking the gradient of $\eqref{ins}_3$, we get that
\begin{equation}\label{dd}
    \nabla d_t- \lambda \nabla\Delta d=-\nabla(u\cdot\nabla d)+ \lambda \nabla(\vert\nabla d\vert^2 d).
\end{equation}
Multiplying \eqref{dd} by $|\nabla d| \nabla d$ and integrating the resultant equation give
\begin{equation}
    \begin{aligned}
      &\frac 13 \frac{d}{dt}\|\nabla d\|_{L^3}^3+\lambda \int |\nabla^2 d|^2 |\nabla d| dx+ \lambda \int |\nabla |\nabla d||^2 |\nabla d| dx\\
      &= \lambda \int |\nabla d|^5 dx -  \int \nabla u^i \partial_i d  : \nabla d |\nabla d| dx + \frac 13\int \dv u |\nabla d|^3 dx\\
      &\leq C \lambda \|\nabla d\|_{L^9}^{3} \|\nabla d\|_{L^3}^{2} + C\|\nabla u\|_{L^2}\|\nabla d\|_{L^3}^{\frac 34}\|\nabla d\|_{L^9}^{\frac94}\\
      & \le C \lambda \|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{2} \|\nabla d\|_{L^3}^{2} + C\|\nabla u\|_{L^2}\|\nabla d\|_{L^3}^{\frac 34}\|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{\frac32}\\
      & \le \frac{2\lambda}{9}\|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{2}+ C \lambda \|\nabla d\|_{L^3}^2 \|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{2} + C \|\nabla d\|_{L^3}^3\|\nabla u\|_{L^2}^4\\
      & \le \frac{2\lambda}{9}\|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{2}+ c_2 \lambda \delta \|\nabla |\nabla d|^{\frac 32}\|_{L^2}^{2} + C\|\nabla d\|_{L^3}^3\|\nabla u\|_{L^2}^4,
    \end{aligned}
\end{equation}
which implies 
\begin{equation}
    \begin{aligned}
        &\frac 13 \frac{d}{dt}\|\nabla d\|_{L^3}^3+\lambda \int |\nabla^2 d|^2 |\nabla d| dx+ \frac{\lambda}{9} \int |\nabla |\nabla d|^{\frac 32}|^2 dx \le  C \|\nabla d\|_{L^3}^3 \|\nabla u\|_{L^2}^4,
    \end{aligned}
\end{equation}
after choosing 
\begin{equation}
    \delta< \frac{1}{9 c_2},
\end{equation}
with $c_2$ depending only on Sobolev constants. 
Then, Gronwall inequality implies that 
\begin{equation}
\begin{aligned}
    \sup_{t\in[0,T]} \|\nabla d\|_{L^3} &\le \|\nabla d_0\|_{L^3}\exp\left\{C\int_0^T\|\nabla u\|_{L^2}^4 dt\right\} \\
    &\le \epsilon_0 \exp\left\{C\|\nabla u_0\|_{L^2}^2\bar\rho^{1-\alpha}\right\} \\
    &\le \epsilon_0 \exp\left\{C_1\bar\rho^{1-\alpha}\right\} \le \delta,
\end{aligned}
\end{equation}
after choosing 
\begin{equation}
    \epsilon_0 \triangleq \frac{\delta}{2},
\end{equation}
and 
\begin{equation}
     \bar \rho > \Lambda_1 \triangleq \max\left\{1,\left(\frac{C_1}{\ln2}\right)^{\frac{1}{\alpha-1}}\right\}.
\end{equation}
\end{proof}



\begin{lemma}\label{3d}
Under the assumption $\mathcal{E}_{u,1}(T) \le 2^{\alpha+2}N_3 \bar\rho^{\alpha}, \mathcal{E}_d(T)\le 2\delta$ with $\delta$ sufficiently small, 
we have
\begin{align}\label{d2d}
  \sup_{0\le t\le T}\|\nabla^2 d\|_{L^2}^2 
    +\int_{0}^{T}\|\nabla^3 d\|_{L^2}^2 dt\leq C\|\nabla^2d_0\|_{L^2}^2.
\end{align}
% and
% \begin{align}\label{tdd}
%  \sup_{0\le t\le T}t\|\nabla^2 d\|_{L^2}^2 
%     +\int_{0}^{T}t\|\nabla^3 d\|_{L^2}^2 dt\leq C\|\nabla d_0\|_{L^2}^2.   
% \end{align}
\end{lemma}

\begin{proof}

Multiplying \eqref{dd} by $-\nabla\Delta d $, and using integration by parts, we have 
\begin{equation}\label{d-2nd}
    \begin{aligned}
    &\frac{1}{2}\frac{d}{dt}\|\nabla^2 d\|_{L^2}^2+\lambda \|\nabla\Delta d\|_{L^2}^2=\int\nabla(u\cdot\nabla d)\cdot\nabla \Delta d\,dx-\lambda \int\nabla(|\nabla d|^2d)\nabla\Delta d\,dx\\
    &\leq C (\|\nabla u\|_{L^2}\|\nabla d\|_{L^\infty}+\|u\|_{L^6}\|\nabla^2d\|_{L^3})\|\nabla\Delta d\|_{L^2}\\
    &\quad + C\lambda ( \|\nabla d\|_{L^3}\|\nabla^2d\|_{L^6}+ \|\nabla d\|_{L^\infty}^{\frac{3}{2}}\|\nabla d\|_{L^3}^{\frac{3}{2}})\|\nabla\Delta d\|_{L^2}\\
    &\leq C \|\nabla u\|_{L^2} \|\nabla^2 d\|_{L^2}^{\frac{1}{2}} \|\nabla^3 d\|_{L^2}^{\frac{3}{2}} + C\lambda (\|\nabla d\|_{L^3}+\|\nabla d\|_{L^3}^2)\|\nabla^3d\|_{L^2}^2\\
    &\leq C(\eta+\lambda \|\nabla d\|_{L^3}+\lambda \|\nabla d\|_{L^3}^2)\|\nabla^3d\|_{L^2}^2+C_\eta\|\nabla^2 d\|_{L^2}^2 \|\nabla u\|_{L^2}^4,
\end{aligned}
\end{equation}
where we have used 
$$\|\nabla d\|_{L^\infty} + \|\nabla^2 d\|_{L^3} \le C\|\nabla^3 d\|_{L^2}^{\frac{1}{2}}\|\nabla^2 d\|_{L^2}^\frac{1}{2},$$
\begin{equation}\label{GN-d-2}
   \|\nabla^2 d\|_{L^3}\leq C\|\nabla^3 d\|_{L^2}^{\frac{2}{3}}\|\nabla d\|_{L^3}^\frac{1}{3},~~\|\nabla d\|_{L^\infty}\leq C\|\nabla d\|_{L^3}^\frac{1}{3}\|\nabla^3 d\|_{L^2}^\frac{2}{3}, 
\end{equation}
and
\begin{equation*}
-\int\partial_t\nabla d\cdot\nabla\Delta ddx=\frac{1}{2}\frac{d}{dt}\|\nabla^2 d\|_{L^2}^2.
\end{equation*}
Then choosing $\eta$ small enough, we have
\begin{equation}\label{d-2nd1}
    \begin{aligned}
    \frac{d}{dt}\|\nabla^2 d\|_{L^2}^2
    +\lambda\|\nabla^3 d\|_{L^2}^2
    \leq& \lambda c_3 \delta \|\nabla^3 d\|_{L^2}^2+C\|\nabla^2 d\|_{L^2}^2 \|\nabla u\|_{L^2}^4.
\end{aligned}
\end{equation} 
Then after choosing 
$$\delta<\frac{1}{2c_3},$$
with $c_3$ depending only on Sobolev constants. 
Gronwall's inequality implies 
\begin{equation}\label{d-2nd2}
    \begin{aligned}
    &\sup_{0\le t\le T}\|\nabla^2 d\|_{L^2}^2 
    +\frac{\lambda}{2}\int_{0}^{T}\|\nabla^3 d\|_{L^2}^2 dt
    \leq  \|\nabla^2 d_0\|_{L^2}^2 \cdot \exp{\left\{C\int_{0}^{T}\|\nabla u\|_{L^2}^4dt\right\}} \\
    \le&  \|\nabla^2 d_0\|_{L^2}^2 \cdot \exp\{C \|\nabla u_0\|_{L^2} \bar\rho^{1-\alpha}\} \le C \|\nabla^2 d_0\|_{L^2}^2 .
\end{aligned}
\end{equation}
% Multiplying \eqref{d-2nd1} by $t$, integrating the resultant equation and using \eqref{basic-est} give
% \begin{equation}\label{d-2nd2-t}
%     \begin{aligned}
