Next, we deal with the following high-order estimate of the velocities which will be used frequently.

\begin{lemma}
	Under the assumption $\mathcal{E}_{\rho,2}(T) \le 2N_1 \bar\rho^{\beta}, \mathcal{E}_{\rho,3}(T) \le 2N_2 \bar\rho^{\beta}$, it holds that 
	\begin{equation}\label{H2}
	    \| \nabla  u\|_{L^6} \leq C \left(\bar\rho^{\frac{1}{2}-\alpha}\|\sqrt{\rho} u_t\|_{L^2} +\|\nabla u\|_{L^2} 
        +\bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2}
        %+\bar \rho^{-\alpha+1 + \frac{5}{6}(\gamma-1) } \|\nabla \rho\|_{L^q}^{\frac{5}{7}} 
        +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2}\right),
	\end{equation}
		and
        \begin{equation}\label{W2p}
        \begin{aligned}
         \|\nabla u\|_{L^\infty} \le&  C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar\rho^{-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}}+\|\nabla u\|_{L^2} \right).
        \end{aligned}
        \end{equation}	
\end{lemma}
\begin{proof}
    Rewrite \eqref{ins}$_2$ as 
\begin{equation}\label{elliptic}
    \mu_1 \Delta u +(\mu_1+\mu_2) \nabla \dv u =  \nabla \mathcal{P}+H,
\end{equation}
with
\begin{equation*}
    \nabla \mathcal{P}=
        \begin{cases}
            \frac{a\gamma}{\gamma-\alpha} \nabla \rho^{\gamma-\alpha}, \quad \gamma \neq \alpha,\\
            a\gamma \nabla \ln \rho, \quad \gamma=\alpha,
        \end{cases}
\end{equation*}
and
$$H \triangleq \rho^{1-\alpha}\dot u
+\alpha\rho^{-1}\nabla\rho\cdot(2\mu \mathcal{D}u +\lambda \dv u) - \nu \rho^{-\alpha} \nabla d \cdot \Delta d .$$
Define the efficient viscous flux $F$ and vorticity $w$ respect to \eqref{elliptic} as
\begin{equation}\label{flux}
    F=(2\mu_1+\mu_2) \dv u +  \mathcal{P}(\rho)-\mathcal{P}(\bar \rho),\quad w=\nabla \times u,
\end{equation}
then \eqref{elliptic} implies
\begin{gather}
    \label{f1}-\Delta F=\dv H,\\
    -\mu \Delta w =\nabla \times H.
\end{gather}


According to the standard $L^2$-estimate of the elliptic system, one has after using \eqref{upbd}, \eqref{basic-est-0}, and Sobolev's inequality in Lemma \ref{G-N},
\begin{equation}\label{e1}
    \begin{aligned}
        &\|\nabla u\|_{L^6} \le C \|\nabla^2 u\|_{L^2}\\
        %\le& C (\|F\|_{L^6} + \|w\|_{L^6}+ \|\mathcal{P}(\rho)-\mathcal{P}(\bar \rho)\|_{L^6}) \\
        \le & C( \|\nabla F\|_{L^2} + \|\nabla w\|_{L^2}+ \bar \rho^{-\alpha}\|\nabla P(\rho)\|_{L^2} )\\
        \le & C \left(\bar\rho^{-\alpha+\frac12}\|\sqrt{\rho}u_t\|_{L^2}+ \bar\rho^{-\alpha+1} \|\nabla u\|_{L^2}^{\frac{3}{2}} \|\nabla u\|_{L^6}^{\frac{1}{2}} + \bar\rho^{-1} \|\nabla \rho \|_{L^q} \|\nabla u\|_{L^{2}}^{\frac{q-3}{q}} \|\nabla u\|_{L^6}^{\frac{3}{q}} \right) \\
        &+ C \left(\bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2} +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2} \right)\\
        \le & \frac{1}{2} \|\nabla u\|_{L^6} + C \left( \bar\rho^{-\alpha+\frac12}\|\sqrt{\rho}u_t\|_{L^2}+ \bar\rho^{-2\alpha+2} \|\nabla u\|_{L^2}^{3}  + \bar\rho^{-\frac{q}{q-3}} \|\nabla \rho \|_{L^q}^{\frac{q}{q-3}} \|\nabla u\|_{L^{2}} \right)\\
        &+ C \left(\bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2} + \bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2} \right),
    \end{aligned}
\end{equation}
where we have used  
\begin{equation}\label{e2}
    \begin{aligned}
        &\|\nabla F\|_{L^2} + \|\nabla w\|_{L^2} \le C \|H\|_{L^2}\\
        \le& C \bar\rho^{-\alpha}\|-\rho(u_t+u\cdot \nabla u)+2\mu \nabla \rho^\alpha \cdot \mathcal{D}u +\lambda \nabla \rho^{\alpha} \dv u - \nu  \nabla d \cdot \Delta d\|_{L^2}\\
        \le & C \left(\bar\rho^{-\alpha+\frac12}\|\sqrt{\rho}u_t\|_{L^2}+ \bar\rho^{-\alpha+1} \|\nabla u\|_{L^2}^{\frac{3}{2}} \|\nabla u\|_{L^6}^{\frac{1}{2}}\right)\\
        & + C \left( \bar\rho^{-1} \|\nabla \rho \|_{L^q} \|\nabla u\|_{L^{\frac{2q}{q-2}}}  + \bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2} \right)\\
        \le & C \left( \bar\rho^{-\alpha+\frac12}\|\sqrt{\rho}u_t\|_{L^2}+ \bar\rho^{-\alpha+1} \|\nabla u\|_{L^2}^{\frac{3}{2}} \|\nabla u\|_{L^6}^{\frac{1}{2}} \right)\\
        & + \left( \bar\rho^{-1} \|\nabla \rho \|_{L^q} \|\nabla u\|_{L^{2}}^{\frac{q-3}{q}} \|\nabla u\|_{L^6}^{\frac{3}{q}} +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2}\right).
    \end{aligned}
\end{equation}

Note that by Sobolev's inequality,
    \begin{equation}\label{rho1}
        \begin{aligned}
        \|\nabla u\|_{L^\infty} \le & C \|\nabla u\|_{L^2}^{\theta} \|\nabla^2 u\|_{L^q}^{1-\theta}\\
        %\le & C \|\nabla u\|_{L^2}^{\theta} \left( \bar\rho^{-\alpha}\|\rho u_t\|_{L^q} + \bar\rho^{\frac{-\alpha+1}{\theta}}  \| u\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} + \bar\rho^{-\frac{1}{\theta}} \|\nabla \rho\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q}\right)^{1-\theta}
        \end{aligned}
    \end{equation}
    where 
    \begin{equation}\label{theta}
        \theta=\frac{2(q-3)}{5q-6}.
    \end{equation}

    Similarly, the standard $L^p$-estimate of the elliptic system gives that
    \begin{equation}\label{e-p}
        \begin{aligned}
         \|\nabla^2 u\|_{L^q} \le & C( \|\nabla F\|_{L^q} + \|\nabla w\|_{L^q}  + \|\nabla \mathcal{P}\|_{L^q})\\
        %\le & C (\|H\|_{L^q} + \|\nabla \mathcal{P}\|_{L^q})\\
        %\le& C \bar\rho^{-\alpha}\|-\rho(u_t+u\cdot \nabla u)+2\mu \nabla \rho^\alpha \cdot \mathcal{D}u +\lambda \nabla \rho^{\alpha} \dv u\|_{L^q} \\
        \le& C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q} + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar \rho^{-\alpha}\|\nabla d\|_{L^{\frac{6q}{6-q}}}\|\nabla^2d\|_{L^6}\right)\\
        & +C \left( \bar\rho^{-\alpha+1}  \| u\|_{L^q} \| \nabla u\|_{L^\infty} + \bar\rho^{-1} \|\nabla \rho\|_{L^q} \| \nabla u\|_{L^\infty} \right)\\
        \le& C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q} + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar \rho^{-\alpha} \|\nabla d\|_{L^3}^{\frac{2}{q}}\|\nabla^2 d\|_{L^6}^{2-\frac{2}{q}}\right)\\
        & + C \left( \bar\rho^{-\alpha+1}  \| u\|_{L^q} \|\nabla u\|_{L^2}^{\theta} \|\nabla^2 u\|_{L^q}^{1-\theta} + \bar\rho^{-1} \|\nabla \rho\|_{L^q} \|\nabla u\|_{L^2}^{\theta} \|\nabla^2 u\|_{L^q}^{1-\theta} \right)\\
        \le & \frac{1}{2} \|\nabla^2 u\|_{L^q} + C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar\rho^{-\alpha} \|\nabla d\|_{L^3}^{\frac{2}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{2}{q}}\right)\\
         & +  C \left( \bar\rho^{\frac{-\alpha+1}{\theta}}  \| u\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} + \bar\rho^{-\frac{1}{\theta}} \|\nabla \rho\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} \right),
        \end{aligned}
    \end{equation}
    where we have used 
    \begin{equation}\label{e3}
    \begin{aligned}
        &\|\nabla F\|_{L^q} + \|\nabla w\|_{L^q} \le C \|H\|_{L^q}\\
        \le& C \bar\rho^{-\alpha}\|-\rho(u_t+u\cdot \nabla u)+2\mu \nabla \rho^\alpha \cdot \mathcal{D}u +\lambda \nabla \rho^{\alpha} \dv u - \nu  \nabla d \cdot \Delta d\|_{L^q}\\
        \le& C \left(\bar\rho^{-\alpha}\| \rho u_t\|_{L^q}  + \bar\rho^{-\alpha+1}  \| u\|_{L^q} \| \nabla u\|_{L^\infty} + \bar\rho^{-1} \|\nabla \rho\|_{L^q} \| \nabla u\|_{L^\infty} + \bar \rho^{-\alpha}\|\nabla d\|_{L^{\frac{6q}{6-q}}}\|\nabla^2d\|_{L^6}\right).
    \end{aligned}
    \end{equation}


    Finally, it follows from \eqref{e1} and \eqref{e-p} that
    \begin{equation}\label{H2}
    \begin{aligned}
        &\| \nabla  u\|_{L^6} \\
        \leq & C \bigg(\bar\rho^{\frac{1}{2}-\alpha}\|\sqrt{\rho} u_t\|_{L^2} +\bar\rho^{2-2\alpha}\|\nabla u\|_{L^2}^3 + \bar\rho^{-\frac{q}{q-3}} \|\nabla \rho \|_{L^q}^{\frac{q}{q-3}} \|\nabla u\|_{L^{2}} \\
        &+ \bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2} +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2} \bigg)\\
        %\le C (\bar\rho^{\frac{1}{2}-\alpha}\|\sqrt{\rho} u_t\|_{L^2} +\|\nabla u\|_{L^2} +\bar \rho^{-\alpha + \gamma } \|\nabla \rho\|_{L^q}^{\frac{5q}{2(4q-3)}} +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2})\\
        \le & C \left(\bar\rho^{\frac{1}{2}-\alpha}\|\sqrt{\rho} u_t\|_{L^2} +\|\nabla u\|_{L^2} 
        +\bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2} + \bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2} \right),
    \end{aligned}
    \end{equation}
    and 
    \begin{equation}\label{W2p}
        \begin{aligned}
         \|\nabla^2 u\|_{L^q} \le&  C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar\rho^{-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}}\right)\\
         & +  C \left( \bar\rho^{\frac{-\alpha+1}{\theta}}  \| u\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} + \bar\rho^{-\frac{1}{\theta}} \|\nabla \rho\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} \right)\\
         \le&  C \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar\rho^{-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}}+\|\nabla u\|_{L^2} \right),
        \end{aligned}
        \end{equation}
        due to $\alpha>1$ , $\beta<2$ and $q\in(3,6)$.
