Now we are ready to deal with an estimate of $\mathcal{E}_{u,1}(T)$.
\begin{lemma}\label{L_2}
Under the assumption \eqref{a1}, and 
\begin{equation}
    \alpha>\frac{\gamma+1}{2}, \alpha\ge \gamma-1,
\end{equation}
then there exists a positive constant $\Lambda_2$ such that 
\begin{equation}
\mathcal{E}_{u,1}(T)\le 2^{\alpha+1}N_3 \bar\rho^{\alpha},
\end{equation}
% and
% \begin{equation}\label{tdu}
% \sup_{t\in[0,T]}t\bar\rho^{\alpha}\|\nabla u \|_{L^2}^2
% +\int_0^{T}t \|\sqrt{\rho} u_t \|_{L^2}^2 dt \leq C\bar\rho ,
% \end{equation}
% \begin{equation}\label{tdd}
% \sup_{t\in[0,T]}t \|\nabla^2d\|_{L^2}^2
% +\int_0^{T}t \|\nabla^3d\|_{L^2}^2 dt \leq C \|\nabla d_0\|_{L^3}^2,
% \end{equation}
with $N_3$ defined in \eqref{m1}, provided $\bar \rho\ge \Lambda_2= \Lambda_2(\mu_1,\mu_2,\nu, \lambda, \alpha,a, \|\nabla \rho_0\|_{L^q}, \| u_0\|_{H^1}, \|\nabla^2 d_0\|_{L^2})$.
\end{lemma}
\begin{proof}
	Multiplying \eqref{ins}$_2$ by $u_t$, and integrating by parts, we have that 
	\begin{equation}\label{51}
		\begin{aligned}
			&\frac{d}{dt}\int (\mu_1 \rho^\alpha |\mathcal{D}(u)|^2 + \mu_2 \rho^\alpha |\dv u|^2 )dx -\frac{d}{dt}\int  (P(\rho)-P(\bar\rho)) \dv u  dx +  \int\rho |u_t|^2dx \\
			&= -\int  \rho u \cdot \nabla u \cdot u_t dx+ \int  \mu_1(\rho^\alpha)_t |\mathcal{D}(u)|^2 dx + \int \mu_2 (\rho^\alpha)_t|\dv u|^2 dx - \int P_t \dv u dx\\
            &\quad -\nu \int u_t \cdot  \nabla d \cdot \Delta d  dx.
		\end{aligned}
	\end{equation}
	It follows from H\"older and Sobolev inequalities that 
	\begin{equation}\label{52}
        \begin{aligned}
		&\int  \rho u \cdot \nabla u \cdot u_t dx\\
        &\leq C\bar\rho^\frac{1}{2}\|\sqrt{\rho} u_t\|_{L^2}\|u\|_{L^6}\|\nabla u\|_{L^3} \\
        &\leq \frac{1}{16}\|\sqrt{\rho} u_t\|_{L^2}^2+C \bar\rho \|\nabla u\|_{L^2}^3\|\nabla u\|_{L^6}.\\        
        %&\leq \frac{1}{16}\|\sqrt{\rho} u_t\|_{L^2}^2+ C\bar \rho \|\nabla u\|_{L^2}^3 (\bar\rho^{\frac{1}{2}-\alpha}\|\sqrt{\rho} u_t\|_{L^2} +\|\nabla u\|_{L^2} + \bar \rho^{-\alpha + \gamma } \|\nabla \rho\|_{L^q}^{\frac{5q}{2(4q-3)}} +\bar\rho^{-\alpha}\|\nabla d\|_{L^3}\|\nabla^3d\|_{L^2})\\
        %&\leq \frac{1}{8}\|\sqrt{\rho} u_t\|_{L^2}^2 +C(\bar\rho^{3-2\alpha}+\bar\rho^{2-2\alpha})\|\nabla u\|_{L^2}^6 + C\bar \rho \|\nabla u\|_{L^2}^4 + C \bar \rho^{\gamma+1-\alpha}\|\nabla u\|_{L^2}^3 +C\|\nabla d\|_{L^3}^2\|\nabla^3d\|_{L^2}^2\\
        %&\leq \frac{1}{8}\|\sqrt{\rho} u_t\|_{L^2}^2 +C\bar\rho^{\alpha}\|\nabla u\|_{L^2}^2 +C\|\nabla d\|_{L^3}^2\|\nabla^3d\|_{L^2}^2.
        \end{aligned}
	\end{equation}
Using 
% \begin{equation}\label{rhoat}
%     \partial_t(\rho^\alpha)+u\cdot\nabla\rho^\alpha + \alpha \rho^\alpha \dv u=0,
% \end{equation}
\eqref{ins}$_1$, which together with Sobolev inequalities yields
\begin{equation}\label{53}
\begin{aligned}
&\int\mu_1(\rho^\alpha)_t |\mathcal{D}(u)|^2 dx + \int \mu_2 (\rho^\alpha)_t|\dv u|^2 dx\\
&\le C \bar \rho^{\alpha-1} \int  \left|\rho\dv u+\nabla \rho \cdot u\right||\nabla u|^2 dx\\
&\le C\bar\rho^\alpha  \|\nabla u\|_{L^3}^3 + C \bar \rho^{\alpha-1} \|\nabla \rho \|_{L^q}\|u\|_{L^6} \|\nabla u\|_{L^{\frac{12q}{5q-6}}}^2\\
&\le C \bar \rho^\alpha \|\nabla u\|_{L^2}^{\frac{3}{2}} \|\nabla u\|_{L^6}^{\frac{3}{2}} + C\bar{\rho}^{\alpha-1} \|\nabla \rho \|_{L^q}\|\nabla u\|_{L^2}^{\frac{5q-6}{2q}} \|\nabla u\|_{L^6}^{\frac{q+6}{2q}}\\
