            &+  \nu \int (2\mathcal{D}_{ij}(u_t)\partial_id\cdot\partial_jd_t + \nabla d : \nabla d_t \dv u_t )dx\\
            =&\sum_{i=1}^{6} I_i.
    \end{aligned}
\end{equation}

It follows from H\"older and Sobolev inequalities that
\begin{equation}
    \begin{aligned}
        I_1+I_2\le& C \int  (\bar\rho| \nabla u| +| \nabla \rho \cdot u|) |u_t|^2 dx  \\
            \le &C \left( \bar \rho  \|\nabla u\|_{L^2} +  \|\nabla \rho\|_{L^q} \|u \|_{L^{\frac{2q}{q-2}}}  \right) \| u_t \|_{L^4}^{2} \\
            \le &C \left( \bar \rho^{\frac34}  \|\nabla u\|_{L^2} +  \bar \rho^{-\frac14} \|\nabla \rho\|_{L^q} \|u \|_{L^{2}}^{\frac{q-3}{q}} \|\nabla u \|_{L^{2}}^{\frac{3}{q}} \right) \|\sqrt{\rho} u_t \|_{L^2}^{\frac12} \|\nabla u_t \|_{L^2}^{\frac32} \\
            \le & \frac{\mu}{2^{\alpha+3}} \bar \rho^{\alpha} \|\nabla u_t\|_{L^2}^2 + C\left(\bar \rho^{3-3\alpha} \|\nabla u\|_{L^2}^4  +   \bar \rho^{-3\alpha-1} \|\nabla \rho\|_{L^q}^4  \|\nabla u \|_{L^{2}}^{\frac{12}{q}}  \right) \|\sqrt{\rho} u_t \|_{L^2}^2 \\
            \le & \frac{\mu}{2^{\alpha+3}} \bar \rho^{\alpha} \|\nabla u_t\|_{L^2}^2 + C\left(\bar \rho^{3-3\alpha} \|\nabla u\|_{L^2}^2  +   \bar \rho^{-3\alpha-1+2b}   \|\nabla u \|_{L^{2}}^{2}  \right) \|\sqrt{\rho} u_t \|_{L^2}^2\\
            \le & \frac{\mu}{2^{\alpha+3}} \bar \rho^{\alpha} \|\nabla u_t\|_{L^2}^2 + C \bar \rho^{2-\alpha} \|\nabla u\|_{L^2}^2, 
    \end{aligned}
\end{equation}
