Operating $\partial_t$ to $\eqref{ins}_3$, and multiplying it by $-\Delta d_t$, by integrating the resulting equality
by parts, we get
\begin{equation}\label{ddt}
    \begin{aligned}
    &\frac{1}{2}\frac{d}{dt}\|\nabla d_t\|_{L^2}^2
    +\lambda \|\nabla^2 d_t\|_{L^2}^2\\
    &=\int u_t\cdot\nabla d\cdot \Delta d_t dx -\lambda \int(|\nabla d|^2d)_t\cdot \Delta d_t dx\\
    &\quad-\int \nabla u:\nabla d_t\odot\nabla d_t dx -\frac 12\int \dv u |\nabla d_t|^2 dx\\
    &\leq C (\|u_t\|_{L^6}\|\nabla d\|_{L^3}+\|\nabla d_t\|_{L^6}\|\nabla d\|_{L^3}+\|\nabla d\|_{L^6}^2\|d_t\|_{L^6})\|\Delta d_t\|_{L^2}\\
    &\quad+C\|\nabla u\|_{L^2}\|\nabla d_t\|_{L^4}^2\\
    &\leq C (\|\nabla u_t\|_{L^2}\|\nabla d\|_{L^3}+\|\nabla^2 d_t\|_{L^2}\|\nabla d\|_{L^3}+\|\nabla^2 d\|_{L^2}^2\|\nabla d_t\|_{L^2})\|\Delta d_t\|_{L^2}
    \\
    &\quad +C\|\nabla u\|_{L^2}\|\nabla d_t\|_{L^2}^{\frac{1}{2}}\|\nabla^2d_t\|_{L^2}^\frac{3}{2}\\
    &\leq \frac{\lambda }{4}\| \nabla^2 d_{t}\|_{L^2}^2+C\|\nabla d\|_{L^3}^2\|\nabla u_t\|_{L^2}^2
    +c_4 \lambda \|\nabla d\|_{L^3}^2\|\nabla^2 d_t\|_{L^2}^2 \\
    &\quad+C(\|\nabla u\|_{L^2}^4+\|\nabla^2 d\|_{L^2}^4)\|\nabla d_t\|_{L^2}^2,
\end{aligned}
\end{equation}
