\begin{align*}
    \int u\cdot\nabla d_t\cdot\Delta d_t dx&=-\int\partial_j u_i\partial_id_t\cdot\partial_j d_t dx-\int (u\cdot \nabla) \partial_j d_t\cdot \partial_j d_t dx\\
    &=-\int \nabla u:\nabla d_t\odot\nabla d_t dx-\frac 12\int \dv u |\nabla d_t|^2 dx.
\end{align*}
