Taking advantage of \eqref{a1}, \eqref{basic-est}, and \eqref{e1}, we obtain
\begin{equation}\label{k3}
    \begin{aligned}
        &\int_{0}^{T} \|\nabla u\|_{L^2} \|\nabla u\|_{L^6}^{3}  dt\\
        \le & C\int_{0}^{T} \|\nabla u\|_{L^2} \left(\bar\rho^{\frac{1}{2}-\alpha} \|\sqrt{\rho} u_t\|_{L^2} +\|\nabla u\|_{L^2} + \bar \rho^{-\alpha+\gamma-1}\|\nabla \rho\|_{L^2}  \right)^{3} dt\\
        & + C\int_{0}^{T} \|\nabla u\|_{L^2} \left(\bar\rho^{-\alpha}\|\nabla^2 d\|_{L^2}^{\frac 32}\|\nabla^3 d\|_{L^2}^{\frac 12} \right)^{3} dt\\
        \le & C \int_{0}^{T} \left(\bar \rho^{1-2\alpha} \|\sqrt{\rho} u_t\|_{L^2}^2 + \|\nabla u\|_{L^2}^2 + \bar \rho^{-3\alpha+3\gamma-3 +\beta } \|\nabla u\|_{L^2} \|\nabla \rho\|_{L^2}  \right) dt\\
        & + C \int_{0}^{T}  \bar \rho^{-3\alpha} \|\nabla u\|_{L^2}^{\frac 12}\|\nabla^3d\|_{L^2}^{\frac{3}{2}}  dt\\
        \le & C \left(\bar \rho^{1-\alpha}+ \bar \rho^{-3\alpha+3\gamma-3 +\beta  + (1-\alpha) \frac{1}{2} + \frac 12 (\alpha-\gamma + \beta)} + \bar \rho^{-3\alpha+ \frac 14(1-\alpha)}\right) \\
        \le & C \left(\bar \rho^{1-\alpha}+ \bar \rho^{-3\alpha + \frac 32 \beta  + \frac 52 (\gamma-1 )} + \bar \rho^{-3\alpha+ \frac 14(1-\alpha)}\right) \\
        \le & 
        \begin{cases}
            C (\bar \rho^{1-\alpha} + \bar \rho^{-3\alpha+\frac 52 (\gamma-1)  }  ), \quad \gamma>3,\\
            C (\bar \rho^{1-\alpha}  + \bar \rho^{-3\alpha + 2+\gamma} ), \quad 1<\gamma\le 3,
        \end{cases}\\
        \le &  
        \begin{cases}
            C (\bar \rho^{1-\alpha} + \bar \rho^{-\frac 12 \alpha-5  }  ), \quad \gamma>3,\\
            C (\bar \rho^{1-\alpha}  + \bar \rho^{-3\alpha + 2+\gamma} ), \quad 1<\gamma\le 3,
        \end{cases}\\
        \le &  C (\bar \rho^{\frac12(1-\alpha)}  + \bar \rho^{-3\alpha + 2+\gamma} ),
    \end{aligned}
\end{equation}
due to $\gamma\le \alpha-1$.
Substitute \eqref{k1} and \eqref{k3} into \eqref{k33}, one gets
\begin{equation}\label{trut1}
\begin{aligned}
    &\sup_{0\le t\le T}  \left(\|\sqrt{\rho} u_t \|_{L^2}^2
    + \|\nabla d_t\|_{L^2}^2\right) 
    +\int_{0}^{T} \left(\bar\rho^\alpha\|\nabla u_t\|^2_{L^2}
    + \|\Delta d_t\|_{L^2}^2\right) dt\\
    &\leq \left(\|\sqrt{\rho} u_t \|_{L^2}^2+ \|\nabla d_t\|_{L^2}^2\right)|_{t=0} \\
    &\quad+  C(\bar\rho^{3-2\alpha}+\bar\rho^{2\gamma-2\alpha+1} + \bar \rho + \bar \rho^{\gamma-\alpha+1} + \bar \rho^{\frac12(1+\alpha)}  + \bar \rho^{-2\alpha + 2+\gamma} )\cdot
    \exp{\{C\bar\rho^{1-\alpha}+\tilde{C}\}}.
\end{aligned}
\end{equation}


Define 
    \begin{align*}
        \rho_0^{1/2} u_{t0} \triangleq \rho_0^{-1/2}\left(-\rho_0 u_0\cdot \nabla u_0 - \nabla P(\rho_0) +2\mu \dv( \rho_0^{\alpha}\mathcal{D} u_0)+\lambda\nabla( \rho_0^{\alpha} \dv u_0)\right)\\
        -\nu \rho_0^{-1/2} \left(\mathrm{div}(\nabla d_0\odot\nabla d_0)-\frac{1}{2} |\nabla d_0|^2 \mathbb{I}_3)\right),
    \end{align*}
    and 
    \begin{equation*}
    \nabla d_{t0}\triangleq \lambda \nabla\Delta d_0-\nabla(u_0\cdot\nabla d_0)+ \lambda \nabla(\vert\nabla d_0\vert^2 d_0),
    \end{equation*}
    then it follows from \eqref{ia} that 
    \begin{equation}\label{ki}
    \begin{aligned}
        \|\sqrt{\rho_0} u_{t0}\|_{L^2} \le& C 
        \left(\bar \rho^{\frac12} \|\nabla u_0\|_{L^2}^{\frac{3}{2}} \|\nabla u_0\|_{L^6}^{\frac{1}{2}} + \bar \rho^{-\frac{1}{2}}\|\nabla P(\rho_0)\|_{L^2} + \bar \rho^{\alpha-\frac{1}{2}}\|\nabla^2 u_0\|_{L^2} \right) \\
        &+ C \left( \bar \rho^{\alpha-\frac{3}{2}} \|\nabla \rho_0\|_{L^q} \|\nabla u_0\|_{L^{\frac{2q}{q-2}}} + C\bar \rho^{-\frac12} \|\nabla d_0\|_{L^6}\|\nabla^2 d_0\|_{L^3} \right)\\
        \le& C  \left(\bar \rho^{\gamma-\frac{3}{2}} \|\nabla \rho_0\|_{L^2}+ \bar \rho^{\alpha-\frac{1}{2}}\right)\\
        \le & C\left(\bar \rho^{\gamma-\frac 32}+ \bar \rho^{\alpha-\frac{1}{2}}\right)\\
        \le & C_2 \bar \rho^{\alpha-\frac{1}{2}},
    \end{aligned}
    \end{equation}
    due to 
    $\gamma-1\le \alpha$, and 
    \begin{equation}
    \begin{aligned}
        \|\nabla d_{t0}\|_{L^2} \le& C 
        \left( \| \nabla \Delta  d_0\|_{L^2} + \|\nabla u_0\|_{L^6} \|\nabla d_0\|_{L^3} + \| u_0\|_{L^6} \|\nabla^2 d_0\|_{L^3}\right) \\
        &+ C \left( \|\nabla d_0\|_{L^6}^3 +  \|\nabla^2 d_0\|_{L^3} \|\nabla d_0\|_{L^{6}}  \right)\\
        \le & C_3.
    \end{aligned}
    \end{equation}
    By combining \eqref{k3} with \eqref{ki}, we obtain
    \begin{equation}
        \begin{aligned}
            &\sup_{0\le t\le T}  \|\sqrt{\rho} u_t \|_{L^2}^2 +   \mu \frac{\bar \rho^\alpha}{2^{\alpha+1}} \int_{0}^{T} \|\nabla u_t\|^2_{L^2} dt\\
            \le &  N_4 \bar \rho^{2\alpha-1}  +  C_4 \left( \bar \rho^{\alpha} + \bar \rho^{2\gamma-2\alpha +1} + \bar \rho^{\gamma} \right) \\
            \le & 2 N_4 \bar \rho^{2\alpha-1},  
        \end{aligned}
    \end{equation}
    after defining
    \begin{equation}\label{m2}
       N_4=N_4(a,\mu_1,\mu_2,\lambda, \alpha, \gamma, \|\rho_0-\bar \rho\|_{L^\gamma}, \|\nabla \rho_0\|_{L^q}, \|\nabla u_0\|_{H^1}, \|\nabla d_0\|_{H^2}) \triangleq C_2^2 + C_3^2, 
    \end{equation}
    and choosing 
    $$\bar \rho \ge \Lambda_3 \triangleq \max\left\{\Lambda_2, \left(\frac{3C_4}{ N_4}\right)^{\frac{1}{\alpha-1}}, \left(\frac{3C_4}{ N_4}\right)^{\frac{1}{2(2\alpha-\gamma-1)}}, \left(\frac{3C_4}{ N_4}\right)^{\frac{1}{2\alpha-\gamma-1}}, (4c_{5})^\frac{1}{{\alpha}} \right\},$$
    as long as $\alpha>\max\left\{1,\frac{\gamma+1}{2}\right\}$.
