Finally, we are able to finish the bound of  $\mathcal{E}_\rho$.
\begin{lemma}\label{L_1}
	There exists a positive constant $\Lambda_4$ such that 
	\begin{equation}
		\mathcal{E}_{\rho,2}(T) \le N_1 \bar\rho^{\beta},
        ~\mathcal{E}_{\rho,3}(T) \le N_2 \bar\rho^{\beta},
	\end{equation}
	provided $\bar\rho>\Lambda_4=\Lambda_4(\mu_1,\mu_2,\nu,\lambda, \alpha,a,\|\nabla\rho_0\|_{L^q}, \| u_0\|_{H^2}, \|\nabla d_0\|_{H^1})$.
    As a consequence, 
    \begin{equation}
		\mathcal{E}_{\rho,1}(T) \le \frac{\bar \rho}{4}.
	\end{equation}
\end{lemma}
\begin{proof}
	It follows from \eqref{ins}$_1$ and \eqref{flux} that  
    \begin{equation}
        \nabla \rho_t + u \cdot \nabla^2 \rho + \nabla u \cdot \nabla \rho + \nabla \rho \dv u+ \frac{1}{2\mu+\lambda} \rho \left(\nabla F + \nabla \mathcal{P} \right)=0.
    \end{equation}
    Multiplying the above equation by $|\nabla \rho|^{q-2}\nabla \rho$ and then integrating by parts, we have 
    \begin{equation}
        \begin{aligned}
            &\frac{1}{p}\frac{d}{dt} \|\nabla \rho\|_{L^q}^q + \frac{a \gamma }{2\mu+\lambda}\int  \rho^{\gamma-\alpha}|\nabla \rho|^qdx \\
            =& \frac{1-q}{q}\int \dv u |\nabla \rho |^qdx - \int \nabla \rho \cdot \nabla u \cdot \nabla \rho |\nabla \rho|^{q-2} dx - \frac{ 1 }{2\mu+\lambda} \int \rho \nabla F \cdot \nabla \rho |\nabla \rho|^{p-2} dx \\
            \le & C \|\nabla u\|_{L^\infty} \|\nabla \rho \|_{L^q}^q + C \bar \rho \|\nabla F\|_{L^q} \|\nabla \rho \|_{L^q}^{q-1}.
        \end{aligned}
    \end{equation}
    Then, we have
    \begin{equation}
        \frac{d}{dt} \|\nabla \rho\|_{L^q}^2 + \bar \rho^{\gamma-\alpha}   \|\nabla \rho\|_{L^q}^2  \le C \|\nabla u\|_{L^\infty} \|\nabla \rho \|_{L^q}^2 + C \bar \rho \|\nabla F\|_{L^q} \|\nabla \rho \|_{L^q},
    \end{equation}
    which together with \eqref{e3} and \eqref{W2p} gives that 
    \begin{equation}
    \begin{aligned}
        &\frac{d}{dt} \|\nabla \rho\|_{L^q}^2 + \bar \rho^{\gamma-\alpha}   \|\nabla \rho\|_{L^q}^2\\
        \le& C \|\nabla u\|_{L^\infty} \|\nabla \rho \|_{L^q}^2 + C \bar\rho^{-\alpha+1} \|\rho u_t\|_{L^q} \|\nabla \rho \|_{L^q} + C \bar\rho^{-\alpha+2}  \| u\|_{L^q} \| \nabla u\|_{L^\infty} \|\nabla \rho \|_{L^q} \\
        &+ C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q}\\
        \le& C \bar\rho \|\nabla u\|_{L^\infty} \|\nabla \rho \|_{L^q} + C \bar\rho^{-\alpha+1} \|\rho u_t\|_{L^q} \|\nabla \rho \|_{L^q}  + C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q}\\
        \le& C \bar\rho \left(\bar\rho^{-\alpha}\|\rho u_t\|_{L^q}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} + \bar\rho^{-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}}+\|\nabla u\|_{L^2} \right) \|\nabla \rho \|_{L^q} \\
        &+ C \bar\rho^{-\alpha+1} \|\rho u_t\|_{L^q} \|\nabla \rho \|_{L^q}  + C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q}\\
        \le& C \bar\rho \left( \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q} +\|\nabla u\|_{L^2} \right) \|\nabla \rho \|_{L^q} \\
        &+ C \bar\rho^{-\alpha+1} \|\rho u_t\|_{L^q} \|\nabla \rho \|_{L^q}  + C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q}\\
        \le & \frac12 \bar \rho^{\gamma-\alpha}   \|\nabla \rho\|_{L^q}^2  + C \bar\rho^{2-\alpha-\gamma} \|\rho u_t\|_{L^q}^2 + C \bar \rho^{2+\alpha-\gamma} \|\nabla  u\|_{L^2}^2 \\
        &+ C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q}.
    \end{aligned}
    \end{equation}


    Next, it follows from \eqref{a1} and \eqref{e-p} that 
    \begin{equation}\label{ep1}
        \begin{aligned}
            \int_{0}^{T}  \|\rho u_t\|_{L^q}^2 dt \le & \int_{0}^{T}  \bar\rho^{\frac{5q-6}{2q}}\|\sqrt{\rho}u_t\|_{L^2}^{\frac{6-q}{q}} \|\nabla u_t\|_{L^2}^{\frac{3(q-2)}{q}} dt\\
            \le & C \bar\rho^{\frac{5q-6}{2q}} \left(\int_{0}^{T} \|\sqrt{\rho}u_t\|_{L^2}^2 dt\right)^{\frac{6-q}{2q}} \left( \int_{0}^{T}\|\nabla u_t\|_{L^2}^2 dt \right)^{\frac{3(q-2)}{2q}}\\
            \le & C \bar\rho^{\frac{5q-6}{2q}+ \alpha \frac{6-q}{2q} + (\alpha-1)  \frac{3(q-2)}{2q}} = C \bar\rho^{1+\alpha},
        \end{aligned}
    \end{equation}
    and that 
    \begin{equation}\label{ddd}
        \begin{aligned}
            \int_{0}^{T} \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} dt \le C.
        \end{aligned}
    \end{equation}
    % \begin{equation}\label{ep2}
    %     \begin{aligned}
    %         \int_{0}^{T}  \|\nabla u\|_{L^\infty}^2 dt 
    %         \le & C \int_{0}^{T} \|\nabla u\|_{L^2}^{\theta} \|\nabla^2 u\|_{L^q}^{1-\theta} dt\\
    %         %\le& C \int_{0}^{T} \|\nabla u\|_{L^2}^{2 \theta} \left( \bar\rho^{-\alpha}\|\rho u_t\|_{L^q} + \bar\rho^{\frac{-\alpha+1}{\theta}}  \| u\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2} + \bar\rho^{-\frac{1}{\theta}} \|\nabla \rho\|_{L^q}^{\frac{1}{\theta}} \|\nabla u\|_{L^2}  + \bar \rho^{\gamma-\alpha-1}\|\nabla \rho \|_{L^q}\right)^{2(1-\theta)} dt \\
    %         \le & C \int_{0}^{T}  \biggl( \|\nabla u\|_{L^2}^{2 } 
    %         + \bar\rho^{-2\alpha}\|\rho u_t\|_{L^q}^2 + \bar\rho^{\frac{-2\alpha+2}{\theta}}  \| u\|_{L^q}^{\frac{2}{\theta}} \|\nabla u\|_{L^2}^2 \\
    %         & +\bar\rho^{-\frac{2}{\theta}} \|\nabla \rho\|_{L^q}^{\frac{2}{\theta}} \|\nabla u\|_{L^2}^2  
    %         + \bar \rho^{2\gamma-2\alpha-2}\|\nabla \rho \|_{L^q}^2 + \bar \rho^{2-2\alpha} \|\nabla^2 d\|_{L^2}^{\frac{6}{q}}\|\nabla^3 d\|_{L^2}^{4-\frac{6}{q}}\biggr) dt\\
    %         \le & C \int_{0}^{T}  \left( \|\nabla u\|_{L^2}^{2 } 
    %         + \bar\rho^{-2\alpha}\|\rho u_t\|_{L^q}^2  + \bar \rho^{2\gamma-2\alpha-2}\|\nabla \rho \|_{L^q}^2 \right) dt \\
    %         \le & C  \bar\rho^{1-\alpha} 
    %         + C\bar \rho^{\gamma-\alpha-2 + b}\\
    %         \le & C \bar \rho^{\gamma-\alpha},
    %     \end{aligned}
    % \end{equation}
    % with $\theta$ defined in \eqref{theta}.

    Finally, applying the Gronwall inequality to \eqref{rho1} and using \eqref{ep1}, \eqref{ddd}, we have 
    \begin{equation}
    \begin{aligned}
        &\sup_{0\le t\le T} \|\nabla \rho\|_{L^q}^2 + \frac{1}{2} \bar \rho^{\gamma-\alpha}   \int_{0}^{T} \|\nabla \rho\|_{L^q}^2 dt \\
        %\le& \exp{\left\{\int_{0}^{T} C \bar \rho^{\alpha-\gamma} \|\nabla u\|_{L^\infty}^2 dt \right\}}\\
        \le & C\left(\|\nabla \rho_0\|_{L^q}^2 + C \bar\rho^{2-\alpha-\gamma} \int_{0}^{T}\|\rho u_t\|_{L^q}^2 dt + C \bar\rho^{2+\alpha-\gamma}  \int_{0}^{T} \| \nabla u\|_{L^2}^2 dt \right)\\
        & + C \bar \rho^{1-\alpha} \int_0^T \|\nabla^2 d\|_{L^2}^{\frac{3}{q}}\|\nabla^3 d\|_{L^2}^{2-\frac{3}{q}} \|\nabla \rho\|_{L^q} dt\\
        \le & C \left(\|\nabla \rho_0\|_{L^q}^2 + \bar\rho^{3-\gamma} +  \bar\rho^{1-\alpha + \frac{\beta}{2}}  \right)\\
        \le & C_4 \left(\|\nabla \rho_0\|_{L^q}^2 +  \bar\rho^{3-\gamma} \right)\\
        \le & N_1 \bar \rho^{\beta},
    \end{aligned}
    \end{equation}
    where 
    \begin{equation}\label{m3}
        N_1 \triangleq C_4 \left(\|\nabla \rho_0\|_{L^q}^2 + 1\right).
    \end{equation}

        Similarly, we have
    \begin{equation}
    \begin{aligned}
        &\frac{d}{dt} \|\nabla \rho\|_{L^2}^2 + \bar \rho^{\gamma-\alpha}   \|\nabla \rho\|_{L^2}^2\\
        \le & C \bar\rho^{2-\alpha-\gamma} \|\rho u_t\|_{L^2}^2 + C \bar \rho^{2+\alpha-\gamma} \|\nabla  u\|_{L^2}^2 + C \bar \rho^{1-\alpha} \|\nabla^2 d\|_{L^2}^{\frac{3}{2}}\|\nabla^3 d\|_{L^2}^{\frac{1}{2}} \|\nabla \rho\|_{L^2},
    \end{aligned}
    \end{equation}
    which together with \eqref{ddd} gives
    \begin{equation}
    \begin{aligned}
        &\sup_{0\le t\le T} \|\nabla \rho\|_{L^2}^2 +  \bar \rho^{\gamma-\alpha}   \int_{0}^{T} \|\nabla \rho\|_{L^2}^2 dt \\
        \le & C\left(\|\nabla \rho_0\|_{L^2}^2 + C \bar\rho^{2-\alpha-\gamma} \int_{0}^{T}\|\rho u_t\|_{L^2}^2 dt + C \bar\rho^{2+\alpha-\gamma}  \int_{0}^{T} \| \nabla u\|_{L^2}^2 dt \right)\\
        & + C \bar \rho^{1-\alpha} \int_0^T \|\nabla^2 d\|_{L^2}^{\frac{3}{2}}\|\nabla^3 d\|_{L^2}^{\frac{1}{2}} \|\nabla \rho\|_{L^2} dt\\
        \le & C \left(\|\nabla \rho_0\|_{L^q}^2 + \bar\rho^{3-\gamma} +  \bar\rho^{1-\alpha + \frac{\beta}{2}}  \right)\\
        \le & C_5 \left(\|\nabla \rho_0\|_{L^2}^2 +  \bar\rho^{3-\gamma} \right)\\
        \le & N_2 \bar \rho^{\beta},
    \end{aligned}
    \end{equation}
    where 
    \begin{equation}\label{m33}
        N_2 \triangleq C_5 \left(\|\nabla \rho_0\|_{L^2}^2 + 1\right).
    \end{equation}

    Finally,   
    \begin{equation}
    \begin{aligned}
        \mathcal{E}_{\rho,1}(T)=\sup_{t\in[0,T] }\|\rho-\bar\rho \|_{L^\infty}\le &C \sup_{t\in[0,T] }\|\rho-\bar\rho \|_{L^2}^{\frac{2(q-3) }{5q-6}} \|\nabla \rho \|_{L^q}^{\frac{3q }{5q-6}}\\
        \le& C \bar \rho^{\frac{2(q-3) }{5q-6} \frac{3-\gamma}{2}+ \frac{\beta}{2} \frac{3q }{5q-6} } \\
        \le& C_6 \bar \rho^{\frac{2(q-3) }{5q-6} + \frac{\beta}{2} \frac{3q }{5q-6} }\le \frac{\bar \rho}{4}, 
    \end{aligned}
    \end{equation}
    provided that 
    \begin{equation}\label{lambda}
        \bar \rho \ge \Lambda_4 \triangleq \max \left\{\Lambda_3, (4C_6)^{\frac{2(5q-6)}{3q(2-\beta)}} \right\}.
    \end{equation}
