\textbf{Proof of Prosition \ref{pr}}
    Proposition \ref{pr} is a direct consequence of Lemmas \ref{3d}, \ref{L_2} and \ref{L_1} after choosing
    \begin{equation}\label{delta}
        \delta < \min\left\{\frac{1}{2\sqrt{2 c_1}}, \frac{1}{9 c_2}, \frac{1}{2c_3}, \frac{1}{4c_4}\right\},
    \end{equation}
    with constants $c_1,c_2,c_3,c_4$ depending only on the Sobolev constants and elliptic constants,
    and 
    $$\Lambda_0\triangleq\Lambda_4.$$

\section{Proof of Theorem \ref{global}}
According to Theorem \ref{local}, there exists a $\Tilde{T}>0$ such that the compressible simplified Ericksen-Leslie system \eqref{ins}-\eqref{bc} has a unique local strong solution $(\rho, u, d)$ on $[0, \Tilde{T}]$. We use the a priori estimates, Proposition \ref{pr} to extend the local strong solution to all time.

Due to 
\begin{equation}
    \|\nabla \rho_0\|_{L^q}=\mathcal{E}_\rho(0)<3\mathcal{E}_\rho(0), \ 
    \|\nabla u_0\|_{L^2}^2=M<3M,\
    \|\nabla d_0\|_{L^3}=\mathcal{E}_d(0)<2\delta,
\end{equation}
and the local regularity results \eqref{l-r}, there exists a $T_1\in(0, \Tilde{T})$ such that
\begin{equation}
    \sup_{0\le t\le T_1} \|\nabla \rho\|_{L^q}\leq 3\mathcal{E}_\rho(0),\ 
    \sup_{0\le t\le T_1} \|\nabla u_0\|_{L^2}^2 \leq 3M,\
    \sup_{0\le t\le T_1} \|\nabla d_0\|_{L^3} \leq 2\delta.
\end{equation}
Set
\begin{equation}
    T^\ast=\sup\{T| (\rho, u, d)\ \mathrm{is}\ \mathrm{a}\ \mathrm{strong}\ \mathrm{solution}\ \mathrm{to}\ \eqref{ins}-\eqref{bc}\ \mathrm{on}\ [0,T]\},
\end{equation}
\begin{equation}
T_1^\ast=\sup\left\{T\bigg| 
\begin{array}{l}
(\rho, u, d)\ \mathrm{is}\ \mathrm{a}\ \mathrm{strong}\ \mathrm{solution}\ \mathrm{to}\ \eqref{ins}-\eqref{bc}\ \mathrm{on}\ [0,T],\\
\sup_{0\le t\le T_1} \|\nabla \rho\|_{L^q}\leq 3\mathcal{E}_\rho(0),\ 
\sup_{0\le t\le T_1} \|\nabla u_0\|_{L^2}^2 \leq 3M,\\
\sup_{0\le t\le T_1} \|\nabla d_0\|_{L^3} \leq 2\delta.
\end{array} \right\}.
\end{equation}
Then $T^\ast_1\geq T_1>0$. Recalling Proposition \ref{pr}, it’s easy to verify
\begin{equation}
    T^\ast=T^\ast_1.
\end{equation}
provided that $\bar\rho>\Lambda_0$ and $\|\nabla d_0\|_{L^3}\leq  \varepsilon_0$ as assumed. 

We claim that $T^\ast=\infty$. Otherwise, assume that
$T^\ast<\infty$. By virtue of Proposition \ref{pr}, for every $t\in[0, T^\ast)$, it holds that
\begin{equation}
     \|\nabla \rho\|_{L^q}\leq 2\mathcal{E}_\rho(0),\ 
     \|\nabla u_0\|_{L^2}^2 \leq 2M,\
     \|\nabla d_0\|_{L^3} \leq \delta,
\end{equation}
therefore we can extend the solution to $T^{\ast\ast}>T^\ast$ due to Lemma \ref{local}, which contradicts with the defination of $T^\ast$. Hence we finish the proof of Theorem \ref{global}.

