\red{\appendix 
\section{Appendix. On the implied volatility smiles from call an put options with IM correction}

\noindent We analyse more in detail the behavior of the implied volatility smiles obtained from the non-linear call and put option prices in Figures \ref{fig:callNL} and \ref{fig:putNL}.
As already pointed out at the end of Section \ref{s:fin_diff}, theses prices do not satisfy put-call parity, which explains why the implied volatilities from calls and puts do not coincide.

Under the non-linear pricing rule $V^{NL}$, the price of a call option is
\[
\begin{aligned}
V_0^{NL} = C(T,K) &:= 
\esp \Bigl[
e^{-rT}
\left( S_0 e^{rT - \int_0^T d^{\mathrm{Call}}(t)dt + \sigma \sqrt T G - \frac 12 \sigma^2 T} - K \right)^+
\Bigr]
\\
&=
F^T(r,\dC) e^{-rT} 
\esp \left[
\left( e^{\sigma \sqrt T G - \frac 12 \sigma^2 T} - \frac{K}{F^T(r,\dC) } \right)^+
\right]\\
&:= 
F^T(r,\dC) e^{-rT} C_{\mathrm{BS}} \left(\frac K{F^T(r,\dC)}, \sigma \sqrt T \right)
\end{aligned}
\]
where $F^T(r,d) = S_0 e^{rT - \int_0^T d(t)\dt}$ is the usual forward price of $S$ with interest rate $r$ and dividend rate $d(t)$, and we denote $C_{\mathrm{BS}}(X,v)$ the normalized BS call price with moneyness $X$ and total implied volatility $v$ (so that $C_{\mathrm{BS}}(0,v) = 1$).
In our case,
\[
\begin{aligned}
&d^{\mathrm{Call}}(t) = - C_{\alpha} R \, \sigma \sqrt{(t+\Delta) \wedge T - t},
\\
&d^{\mathrm{Put}}(t) = C_{\alpha} R \, \sigma \sqrt{(t+\Delta) \wedge T - t}.
\end{aligned}
\]
How do we imply the implied volatility $\sigC$? Using the same reference Black-Scholes price that leads to a constant smile when $R=0$ (as in Figures \ref{fig:callNL}-\ref{fig:putNL}): that is, we impose
\begin{multline} \label{e:def_implVol}
C(T,K) =
F^T(r,\dC) e^{-rT} C_{\mathrm{BS}} \left(\frac K{F^T(r,\dC)}, \sigma \sqrt T \right)
\\
=
F^T(r,d=0) e^{-rT} C_{\mathrm{BS}} \left(\frac K{F^T(r,d=0)}, \sigC(K) \sqrt T \right)
=
\mathrm{RefCallPrice}(T,K)
\end{multline}
and analogously for $\sigP(\cdot)$. Equation \eqref{e:def_implVol} is of the form
\[
C_{\mathrm{BS}} \left(X, \sigC(X F_1) \sqrt T \right)
 = \frac{F_2}{F_1} C_{\mathrm{BS}} \left(X \frac{F_1}{F_2}, \sigma \sqrt T \right)
= \esp \left[\left(\frac{F_2}{F_1}e^{\sigma \sqrt T -\frac12 \sigma^2 T}- X\right)^+ \right],
\qquad X \ge 0,
\]
with $F_2 = F^T(r,\dC) \maj F_1 = F^T(r,0)$.
This already shows that: 
\begin{enumerate}
\item There is a smile: $\sigC(\cdot)$ is not constant.
\item $\sigC(K) \ge \sigma$ for all $K$, since $F_2 \ge F_1$.
\end{enumerate}
The same conclusions (1) and (2) also hold for $\sigP(\cdot)$, for which we have $\dP \ge0$, hence $F^T(r,\dP) \mino F^T(r,0)$.

Why are the implied volatilities of calls and puts with IM different?
Because the reference price satisfies the following parity relation
\[
\mathrm{RefCallPrice}(T,K) -
\mathrm{RefPutPrice}(T,K) 
= e^{-rT} \left( F^T(r,0) - K \right)
\]
while the call and put prices with IM satisfy 
\[
\begin{aligned}
C(T,K) - P(T,K)
&=
e^{-rT} \biggl[
F(\dC)  
C_{\mathrm{BS}}(\dC)  
- 
F(\dP)
P_{\mathrm{BS}}(\dP)  
\biggr]
\\
&= e^{-rT} \left(F(\dC) - K \right)
\\
&\quad
+ e^{-rT} \biggl[
F(\dC) \left(P_{\mathrm{BS}}(\dC) - P_{\mathrm{BS}}(\dP) \right)
\\
&\quad 
+ P_{\mathrm{BS}}(\dP) \left( F(\dC) - F(\dP) \right)
\biggr],
\end{aligned}
\]
where we have slightly simplified notations by setting $F(\dC) = F^T(r,\dC)$, $F(\dP) = F^T(r,\dP)$, and $C_{\mathrm{BS}}(d) = C_{\mathrm{BS}} \left(\frac K{F^T(r,d)}, \sigma \sqrt T \right)$, $P_{\mathrm{BS}}(d) = P_{\mathrm{BS}} \left(\frac K{F^T(r,d)}, \sigma \sqrt T \right)$.
Note that the right hand side is not an affine function of $K$.

We can now assess the sign of the ATMF skew $\partial_K \sigma(K)|_{K = F^T(r,0)}$.
Taking derivatives with respect to $K$ in \eqref{e:def_implVol}, we get
\[
\begin{aligned}
\Prob \left(S_T^{r, \dC, \sigma} \maj K\right)
&=
F^T(r,0) 
\left[
\partial_K C_{\mathrm{BS}} \biggl(\frac K{F^T(r,0)}, \sigC(K) \sqrt T \biggr)
+
\partial_\sigma C_{\mathrm{BS}} \biggl(\frac K{F^T(r,0)}, \sigC(K) \sqrt T \biggr)
\partial_K \sigC(K)
\right]
\\
&=
-\Prob \left(S_T^{r,d=0, \sigC(K)} \maj K\right)
+
K \sqrt{T} \phi
\biggl(
d_2
\biggl(
\frac K{F^T(r,0)}, \sigC(K) \sqrt T
\biggr)
\biggr)
\partial_K \sigC(K),
\end{aligned}
\]
or yet
\begin{equation} \label{e:implVolSkew}
\sqrt T \partial_K \sigC(K)
=
\frac
{-\Prob \left(S_T^{r, \dC, \sigma} \maj K\right) + \Prob \left(S_T^{r,d=0, \sigC(K)} \maj K\right)}
{K \phi
\biggl(
d_2
\biggl(
\frac K{F^T(r,0)}, \sigC(K) \sqrt T
\biggr)
\biggr)}
\end{equation}
where $\phi(\cdot)$ is the standard normal density.
Note that $\partial_K \sigC(K)$ has the sign of the numerator $\mathrm{Num^{CallSkew}}$ in \eqref{e:implVolSkew}.
Setting
\[
q(d,\sigma)
:= \Prob \left(S_T^{r, d, \sigma} \maj K\right)
= N \biggl(
d_2 \biggl(
\frac K{F^T(r,d)}, \sigma \sqrt T
\biggr)
\biggr)
= 
N \biggl(
\frac{\ln \frac{F^T(r,d)} K}{\sigma \sqrt T}
- \frac 12 \sigma \sqrt T
\biggr)
\]
we have
\[
\partial_\sigma q(d,\sigma)
= \sqrt T \phi(d_2) 
\biggl(
-\frac{\ln \frac{F^T(r,d)} K}{\sigma^2 T}
- \frac 12
\biggr),
\qquad
\partial_d q(d,\sigma)
= \frac 1{\sigma \sqrt T}
\phi(d_2) 
\frac{\partial_d F^T(r,d)}{F^T(r,d)}
=
- \frac T{\sigma \sqrt T}
\phi(d_2) 
\]
the last derivative being taken in the case of a constant dividend rate $d$ (which is our case up to time $t \le T-\Delta$).
We can write the numerator in \eqref{e:implVolSkew} as 
\[
\begin{aligned}
\mathrm{Num^{CallSkew}}
&=
q(d=0, \sigC(K)) - q(\dC, \sigma)
\\
&=
q(d=0, \sigC(K)) - q(d=0, \sigma)
+ q(d=0, \sigma) - q(\dC, \sigma)
=: 
\mathrm{Num_1^{CallSkew}}
+
\mathrm{Num_2^{CallSkew}}.
\end{aligned}
\]
We now consider the ATMF point, that is $K=F^T(r,0)$. 
Since, in this case,
\[
\partial_\sigma q(d=0,\sigma)
= - \frac 12 \sqrt T \phi(d_2) \mino 0,
\]
we have $\mathrm{Num_1^{CallSkew}} \mino 0$, recalling that $\sigC(K) \maj \sigma$.
Moreover, since $\partial_d q(d,\sigma) \mino 0$, we also have $\mathrm{Num_2^{CallSkew}} \mino 0$, recalling that $0 \maj \dC$.
Overall, we have obtained
\[
\sqrt T \partial_K \sigC(K)|_{K = F^T(r,0)}
\mino 0.
\]
}

