\end{equation*}
Then we have that for all $1 \leq j \leq r$ and the estimators in (\ref{eq_generalestimateone}) and (\ref{eq_generalestimatetwo}) {\vspace*{-5pt}  
\begin{align}\label{eq_rate}
\sup_{t \in [0,1],x \in \mathbb{R}}\left | m_j(t,x)-\widehat{m}_{j}(t,x) \right|&=\OO_{\mathbb{P}}\Big(\xi \varsigma( \gamma  \iota+\zeta) \sqrt{\frac{\mathsf{p}}{n}}+c_j^{-\mathsf{m}_{1j}}+d_j^{-\mathsf{m}_{2j}}+\gamma \sqrt{\mathfrak{F}_j} \Big), 
