\begin{theorem}\label{thm_asymptoticdistribution}
Suppose Assumptions \ref{assum_models}--\ref{assum_debiasassumption} as well as the assumptions of Theorem \ref{thm_consistency} hold.  For $\Theta$ in (\ref{eq_controlparameter}), we assume that 
\begin{equation}\label{eq_onebound}
\Theta=\oo(1). 
\end{equation}
Moreover, we assume that the basis functions are selected such that $|\bm{r}|$, as defined in (\ref{eq_verctorconstruction}), is uniformly bounded from below for all $t \in [0,1]$ and $x \in \mathbb{R}$. {Then we have that when $n$ is sufficiently large, for all $(t,x) \in [0,1] \times \mathbb{R}$ and $\mathsf{T}_j(t,x)$ in (\ref{eq_definitiont1})   
\begin{equation}\label{eq_thmonepartone}
\frac{\sqrt{n} \mathsf{T}_{j}(t,x)}{h_j(t,x)} \simeq \mathcal{N}(0,1),
\end{equation}
where $h_j(t,x)$ is defined in (\ref{eq_defhtx}) and $\simeq$ means convergence in distribution.}    
\end{theorem}


Theorem \ref{thm_asymptoticdistribution} establishes the {point-wise} asymptotic normality of $\mathsf{T}_j$ under the assumption (\ref{eq_onebound}) which can be easily satisfied. In particular, combining with the discussion in Remark \ref{rmk_minimaxoptimal}, it is not hard to see that when $\tau>0$ is large enough so that the temporal relation decays fast enough, the basis functions are chosen so that $\xi, \varsigma=\mathrm{O}(1)$ and $\zeta=\mathrm{O}(1),$ in order to guarantee that $\Theta=\mathrm{o}(1),$ we can allow $\mathsf{p}$ to be as large as $\mathrm{O}(n^{2/7-\delta})$ for some sufficiently small constant $\delta>0.$  This matches with the 
dimension setting for high dimensional convex Gaussian approximation \cite{MR3571252}. Moreover, for many commonly used sieve basis functions—such as Fourier basis functions, orthogonal polynomials, and wavelet basis functions—the quantity $|\bm{r}|$ typically diverges with $\mathsf{p}$, allowing it to be uniformly bounded from below. For further details, see \cite{CHEN2015447}.

{In addition to the pointwise convergence results, we also establish uniform convergence results for the statistics. In particular, to construct the SCRs in (\ref{eq_SCRformaldefinition}), it is essential to understand the asymptotic behavior of $c_\alpha$ in (\ref{eq_calpha}).} Recall (\ref{eq_xbasisbound}), (\ref{eq_defnxic}) and $\mathfrak{m}$ and $\mathrm{h}$ in (\ref{eq_controlparameter}). Denote the control parameter $\Theta^*$ as
\begin{align}\label{eq_thetastar}
\Theta^*:=&n^{-1/2} \mathsf{p}^{7/4} \mathrm{h}^3  \mathfrak{m}^2+\sqrt{\mathsf{p}n} \mathrm{h}^{-2} \varsigma \xi \mathfrak{m}^{-\tau-1/2}+n \mathsf{p}^{-1/2} \xi^2 \varsigma \mathfrak{m}^{-3/2} \mathrm{h}^{-q-1} \nonumber  \\
&+n^{1/2} \mathsf{p}^{-1/2} \mathrm{h}^{-2} \mathfrak{m}^{-3/2} \varsigma^2 \left( \mathsf{p} \xi^2 \fm^{-\tau+1}+ \mathsf{p}n \xi^4 \hd^{-(q-2)} \right).  
\end{align}
{As can be seen in Theorem \ref{thm_uniformconvergencegaussian} of our supplement \cite{suppl}, $\Theta^*$ is used to control the error rates of the uniform Gaussian approximation.}

Recall (\ref{eq_betaolsform}), (\ref{eq_proposedestimator}) and (\ref{eq_longruncovariancematrix}). We further denote 
\begin{equation}\label{eq_ljdefinition}
l_j(t,x):=n^{-1}\overline{\bm{r}}^\top \overline{\mathsf{I}}_j  \overline{\Pi}^{-1}.
\end{equation} 
For $x \in \mathbb{R},$ using the mappings in Definition \ref{defn_mappings}, we write
\begin{equation}\label{eq_ll}
\widetilde{l}_j(t,\widetilde{x}):=l_j(t,g(2\widetilde{x}-1;s)) \equiv l_j(t,x), \ \widetilde{x} \in [0,1], 
\end{equation}  
and $\widetilde{\bm{r}} \equiv \widetilde{\bm{r}}(t, \widetilde{x})=\bm{r}(t, g(2\widetilde{x}-1);s) \equiv \bm{r}(t,x). $
Recall $\bm{\epsilon}=(\epsilon_i)_{1 \leq i \leq n} \in \mathbb{R}^{n}.$ Denote 
%$T_j(t,\widetilde{x})$ 
\begin{equation}\label{eq_defntdefn}
T_j(t, \widetilde{x}):=\frac{\sqrt{n} \widetilde{l}_j(t,\widetilde{x}) \sqrt{\operatorname{Cov}(W^\top \bm{\epsilon})}}{\widetilde{h}_j(t, \widetilde{x})}, \  \widetilde{h}_j(t,\widetilde{x}):=h_j(t,g(2\widetilde{x}-1);s). 
\end{equation} 
Armed with the above notations, let the manifold $\mathcal{M}_j, 1 \leq j \leq r,$ be defined as follows
\begin{equation}\label{eq_manifolddefinition}
\mathcal{M}_j=:\left\{ T_j(t, \widetilde{x}): (t,\widetilde{x}) \in [0,1] \times [0,1]  \right\}.
\end{equation}


\begin{theorem}\label{thm_uniformdistribution} {Suppose the assumptions of Theorem \ref{thm_asymptoticdistribution} hold with (\ref{eq_onebound}) replaced by $\Theta^*=\oo(1).$} Then critical value $\cf_{\alpha}$ in (\ref{eq_calpha}) satisfies the following expansion
\begin{align}\label{eq_expansionformula}
\alpha=\frac{\cf_{\alpha} \kappa_0}{\sqrt{2} \pi^{3/2}} \exp\left(-\frac{\cf_{\alpha}^2}{2} \right)+\frac{\eta_0}{2 \pi} \exp\left(-\frac{\cf_{\alpha}^2}{2} \right)&+2(1-\Phi(\cf_{\alpha})) +\oo\left( \exp\left(-\frac{\cf^2_{\alpha}}{2} \right)\right),
\end{align}
where $\kappa_0 \equiv \kappa_0(n), \eta_0 \equiv \eta_0(n)$ are the area and the length of the boundary of $\mathcal{M}_j$ in (\ref{eq_manifolddefinition}) and $\Phi(\cdot)$ is the cumulative distribution function of a standard Gaussian random variable. Moreover, suppose $c_j,d_j,$ are chosen according to (\ref{eq_cdchoice}), and there exist some constants $\alpha_1, \alpha_2 \geq 0$ so that
\begin{equation}\label{eq_assumptionbasisderivative}
\int \frac{\| \nabla_t \widetilde{\bm{r}} \|_2}{\| \widetilde{\bm{r}} \|_2} \mathrm{d}t \dd \widetilde{x} \asymp n^{\alpha_1}, \ \int \frac{\| \nabla_{\widetilde{x}} \widetilde{\bm{r}} \|_2}{\| \widetilde{\bm{r}} \|_2} \mathrm{d}t \dd \widetilde{x} \asymp n^{\alpha_2}, \ 
\end{equation}
then we have 
\begin{equation}\label{eq_quantitiesbound}
\cf_{\alpha} \asymp  \log^{1/2} n.
\end{equation}
\end{theorem}

\begin{remark}\label{rem_remaftertheorem41}
Two remarks are in order. First, Theorem \ref{thm_uniformdistribution} provides an accurate representation for the critical value $\cf_{\alpha}$ as in (\ref{eq_expansionformula}). Especially, under the condition of (\ref{eq_assumptionbasisderivative}), we obtain the exact rate of $\cf_\alpha$ in (\ref{eq_quantitiesbound}). Inserting this back into (\ref{eq_expansionformula}), we can see that the error term can be made sufficiently small so that solving (\ref{eq_expansionformula}) will yield an accurate estimation for $\cf_{\alpha}.$ 
We note that the commonly used sieve basis functions can easily satisfy (\ref{eq_assumptionbasisderivative}). For further details, please refer to Assumption 4 in \cite{CHEN2015447}.
%We point out that (\ref{eq_assumptionbasisderivative}) can be easily satisfied by the commonly used sieve basis functions like Fourier basis functions, orthogonal polynomials and wavelet basis functions. For more details, we refer the readers to 
% Assumption 4 of \cite{CHEN2015447}. 

Second, based on Theorems \ref{thm_asymptoticdistribution} and \ref{thm_uniformdistribution}, we observe that the approach of using SCRs for various tests, as illustrated in Examples \ref{exam_exactform}--\ref{exam_seperabletest}, can achieve asymptotic power of one, provided the alternative deviates from the null hypothesis at a rate greater than the order of the SCR width, i.e., $\mathrm{O}(n^{-1/2} \cf_{\alpha} h_j(t,x))$. From the definition in (\ref{eq_defhtx}), it is evident that {$h_j(t,x) \asymp \sqrt{c_j d_j}$.} Thus, the proposed tests will achieve asymptotic power of one if the width of the SCRs is much larger than {$\sqrt{c_j d_j \log n/n}$}.



