\begin{algorithm}[!ht]
%\small
\caption{\bf Multiplier bootstrap for constructing SCR}
\label{alg:boostrapping}
\vspace{1pt}
\normalsize
\begin{flushleft}
\noindent{\bf Inputs:} Coverage probability $1-\alpha,$ the function index $1 \leq j \leq r,$  the tuning parameters $c_0, c_j$, $d_j$ and $m$ chosen by the data-driven procedure demonstrated in Section \ref{sec_parameterchoice} of the supplement \cite{suppl}, time series $\{X_{j,i}\}$ and $\{Y_i\},$ and sieve basis functions.
\vspace{2pt}

\noindent{\bf Step one:} Compute $\widehat{\overline{\Pi}}^{-1}$ as in (\ref{eq_defnt1k}), the estimate $\widehat{m}_{j}(t,x)$ as in (\ref{eq_generalestimatetwo}), and the residuals $\{\widehat{\epsilon}_i\}$ according to (\ref{eq_defnresidual}).
\vspace{2pt}

%\noindent{\bf Step two:} For each given pair $(t,x),$ 
%\vspace{2pt}

\noindent{\bf Step two:} Construct a sequence of uniform grids of $[0,1] \times [0,1],$ denoted as $(t_i, y_l)$, $1 \leq i$ $\leq C_1$, $1 \leq l \leq C_2,$ where $C_1$ and $C_2$ are some large integers (say $C_1=C_2=2,000$). Using the mappings in Definition \ref{defn_mappings} and calculate $x_l=g(2y_l-1;s).$  
\vspace{2pt}

\noindent{\bf Step three:} For each pair of $(t_i, x_l),$ calculate the associated s.t.d. following the discussions above (\ref{eq_hahahahahahhaha}) and denote them as $\widehat{h}_j(t_i, x_l).$ 
\vspace{2pt}

\noindent{\bf Step four:} For each pair of $(t_i, x_l),$  generate $M$ (say 1,000) i.i.d. copies of  $\{\widehat{\mathsf{T}}_{j,k}(t_i, x_l)\}$, $1 \leq$ $k \leq M.$ For each $k,$ calculate $\mathcal{T}_k$ as follows
\begin{equation*}
\mathcal{T}_k:=\sup_{i,l}\left| \frac{\widehat{\mathsf{T}}_{j,k}(t_i, x_l)}{\widehat{h}_j(t_i, x_l)} \right|.
\end{equation*}
Let $\mathcal{T}_{(1)} \leq \mathcal{T}_{(2)} \leq \cdots \leq \mathcal{T}_{(M)}$ be the order statistics of $\{\mathcal{T}_k\}.$ Calculate $\widehat{\cf}_{\alpha}$ as
\begin{equation*}
\widehat{\cf}_{\alpha}=\mathcal{T}_{\lfloor M(1-\alpha) \rfloor},
\end{equation*}
where $\lfloor x \rfloor$ denotes the largest integer smaller or equal to $x.$
\vspace{2pt}

\noindent{\bf Output:} The SCR can be represented as $\widehat{m}_{j,c,d}(t,x) \pm \frac{\widehat{\cf}_{\alpha}}{\sqrt{n}} \widehat{h}_j(t,x).$
\end{flushleft}

\end{algorithm}
