\section{A brief summary of sieve spaces approximation theory}\label{sec_sieves}
In this section, we give a brief overview on the sieve approximation theory \cite{CXH} for compact domain and the mapped sieve approximation theory for the unbounded domain \cite{MR1874071,MR2486453,unboundeddomain}.  We start with introducing some commonly used sieve basis functions. 


\begin{example}[Trigonometric and mapped trigonometric polynomials]\label{examplebasis_fourier} For $x \in [0,1],$ we consider the following trigonometric polynomials 
\begin{equation*}
\left\{1, \sqrt{2} \cos(2 k \pi x), \sqrt{2} \sin (2k\pi x), \cdots \right\}, \ k \in \mathbb{N}.
\end{equation*}
The above basis functions form an orthonormal basis 
of $L_2([0,1]).$ Note that the classic trigonometric basis function is well suited for approximating periodic functions on $[0,1].$ 

When $x \in \mathbb{R},$ let $u(x): \mathbb{R} \rightarrow [0,1]$ be constructed following Example \ref{example_mappings}. Since $u(x)$ in Example \ref{example_mappings} satisfies that $u'(x) \in L_2(\mathbb{R})$, the following mapped trigonometric polynomials form an orthonomal basis for $L_2(\mathbb{R})$ 
\begin{equation*}
\left\{ \sqrt{u'(x)}, \ \sqrt{2 u'(x) } \cos(2 k \pi u(x)), \ \sqrt{2 u'(x)} \sin(2 k \pi u(x)),\cdots \right\}, \ k \in \mathbb{N}, 
\end{equation*}
where we used inverse function theorem. 
\end{example}


% {\color{red} start from here, the conclusion section, section 7 of \cite{unboundeddomain}}
\begin{example}[Jacobi and mapped Jacobi polynomials]\label{exam_jacobibasis} For $I=(-1,1)$ and some constants $\alpha, \beta>-1,$ denote the Jacobi weight function as
\begin{equation*}
\omega^{\alpha,\beta}(y)=(1-y)^{\alpha}(1+y)^{\beta},
\end{equation*}
and associated weighted $\mathcal{L}^2$ space as $\mathcal{L}^2_{\omega^{\alpha,\beta}}(I).$ With the above notations, the Jacobi polynomials are the orthogonal polynomials $\{J_n^{\alpha,\beta}(y)\}$ such that 
\begin{equation*}
\int_I J_n^{\alpha, \beta}(y) J_m^{\alpha,\beta}(y) \omega^{\alpha,\beta}(y) \dd y=\gamma_n^{\alpha,\beta} \delta_{n,m}, 
\end{equation*}
where $\delta_{n,m}$ is the Kronecker function, and 
\begin{equation*}
\gamma_n^{\alpha,\beta}=\frac{2^{\alpha+\beta+1} \Gamma(n+\alpha+1) \Gamma(n+\beta+1)}{(2n+\alpha+\beta+1) \Gamma(n+1) \Gamma(n+\alpha+\beta+1)}.
\end{equation*}
More explicitly, the Jacobi polynomials can be characterized using the  Rodrigues' formula \cite{MR0000077} 
\begin{equation*}
J_n^{\alpha,\beta}(x)=\frac{(-1)^n }{2^n n!}(1-x)^{-\alpha}(1+x)^{-\beta} \frac{\dd^n }{\dd x^n} \left( (1-x)^\alpha(1+x)^\beta(1-x^2)^n \right).
\end{equation*}
Then for $x \in [0,1],$ the following sequence forms an orthonormal basis for $L_2([0,1])$ 
\begin{equation*}
\left\{ \mathsf{J}^{\alpha,\beta}_k(x):= \sqrt{\frac{2 \omega^{\alpha, \beta}(2x-1)}{\gamma_k^{\alpha,\beta}} } J_k^{\alpha,\beta}(2x-1)  \right\}, \ k \in \mathbb{N}. 
\end{equation*}
We mention that when $\alpha=\beta=0,$ the Jacobi polynomial reduces to the Legendre polynomial and when $\alpha=\beta=-0.5,$ the Jacobi polynomial reduces to the Chebyshev polynomial of the first kind. 

When $x \in \mathbb{R},$ let $u(x)$ be the mapping as in Example \ref{examplebasis_fourier}. Then the following sequence provides an orthonormal basis for $L_2(\mathbb{R})$ (see \cite[Section 2.3]{unboundeddomain}) 
\begin{equation*}
\left\{ \sqrt{u'(x)}\mathsf{J}_k^{\alpha,\beta}(u(x)) \right\}.
\end{equation*}

