\section{Additional simulation results and real data analysis}\label{addtional_numerical} In this section, we provide some additional simulation results and an additional financial real data analysis.
\subsection{Simulation setup for $\epsilon_i$ used in Section \ref{sec_simulationsettup}}\label{sec_simulationsetupepsilon}
For the locally stationary time series $\{\epsilon_i\}$ used in Section \ref{sec_simulationsettup}, let $a_1(i/n) \equiv 0.3, \ a_2(i/n)=0.3 \sin(2 \pi i/n),$ and $\eta_i, i=1,2,\cdots,n,$ be i.i.d. standard Gaussian random variables,  we consider the following settings
\begin{enumerate}
\item[(a).] Time-varying linear AR(2) model  
\begin{equation*}
\epsilon_i=\sum_{j=1}^2 a_j(\frac{i}{n}) \epsilon_{i-j}+\eta_i.
\end{equation*} 
\item[(b).] Self-exciting threshold auto-regressive (SETAR) model
\begin{equation*}
\epsilon_i=
\begin{cases}
a_1(\frac{i}{n}) \epsilon_{i-1}+\eta_i, & \epsilon_{i-1} \geq 0, \\
a_2(\frac{i}{n}) \epsilon_{i-1}+\eta_i, & \epsilon_{i-1}<0.
\end{cases}
\end{equation*}
\item[(c).] First order bilinear model 
\begin{equation*}
\epsilon_i=\left(a_1(\frac{i}{n}) \eta_{i-1}+a_2(\frac{i}{n}) \right)\epsilon_{i-1}+\eta_i.
\end{equation*}
\end{enumerate}

