\subsection{Uniform consistency of the proposed estimators: proof of Theorem \ref{thm_consistency}}\label{sec_consistencyproof}

In this subsection, we prove Theorem \ref{thm_consistency}. Till the end of the paper, for a positive definite $H,$ we denote $\|H \|_{\op}$ as the operator norm of $H,$ i.e., the largest eigenvalue of $H.$ 

\begin{proof}[\bf Proof of Theorem \ref{thm_consistency}] Since $r$ is finite, without loss of generality, we assume $r=1.$ For general $r,$ the proof can be modified verbatim with only additional notional complicatedness. Consequently, we can omit the subscript $j,$ so that $m \equiv m_{1}, X_i \equiv X_{1,i}, c \equiv c_1, d \equiv d_1, \chi(t) \equiv \chi_1(t)$ and $\widehat{m} \equiv \widehat{m}_{1}.$ In light of the identifiability assumption (\ref{eq_identiassum}) and the treatment above (\ref{eq_meanchisquare}),   the starting point of our proof is the following decomposition {
\begin{align}\label{eq_initialdecomposition}
|\widehat{m}(t,x)-m(t,x)| & \leq |\widehat{m}^*_{c,d}(t,x)-m_{c,d}(t,x)|+|\chi(t)-\widehat{\chi}(t)| \\
&+|m_{c,d}(t,x)-m(t,x)|.  \nonumber
\end{align} }  
Since the last term of the right-hand side of (\ref{eq_initialdecomposition}) can be bounded using Proposition \ref{thm_approximation}, it suffices to control the first two terms. We start with the first one. 


Using the definitions of  (\ref{eq_firststeptruncation1}), (\ref{eq_firststeptruncation}) and (\ref{eq_proposedestimator}), by Cauchy-Schwarz inequality, we have that {
\begin{equation}\label{eq_ll1}
|\widehat{m}^*_{c,d}(t,x)-m_{c,d}(t,x)| \leq  | \widehat{\bm{\beta}}_1-\bm{\beta}_1 | \zeta,  
\end{equation}}
where $\zeta$ is defined in (\ref{eq_defnxic}).
Since $| \widehat{\bm{\beta}}_1-\bm{\beta}_1| \leq | \widehat{\bm{\beta}}-\bm{\beta} |,$ the rest of the proof leaves to control $\widehat{\bm{\beta}}-\bm{\beta}.$ Note that we denote $\bm{Y}=(Y_i)_{1 \leq i \leq n} \in \mathbb{R}^{n}$ and $\bm{\epsilon}=(\epsilon_i)_{1 \leq i \leq n} \in \mathbb{R}^{n}.$  Recall the notations around (\ref{eq_designmatrix}) and (\ref{eq_betaolsform}) and that
\begin{equation}\label{eq_betadifferenceexpression}
\widehat{\bm{\beta}}-\bm{\beta}=(W^\top W)^{-1} W^\top \bm{\epsilon}. 
\end{equation}
Therefore, we need to control $| \widehat{\bm{\beta}}-\bm{\beta} |$ which satisfies {
\begin{equation}\label{eq_betabound1}
| \widehat{\bm{\beta}}-\bm{\beta} | \leq \left| \frac{1}{\lambda_{\mathsf{p}}((n^{-1} W^\top W))} \right| | n^{-1} W^\top \bm{\epsilon} |, 
\end{equation} 
where we recall the notation (\ref{eq_defnp}). }

%and $\bm{I} \in \mathbb{R}^{r},  \ \widehat{m}_j-m_j=(\widehat{\bm{\beta}}-\bm{\beta}) \mathbf{I}_j (\bm{b}  \otimes \mathbf{1}_r).$
% Denote the $i$th row of $W$ as $W_i.$ 
%where $\xb_i$ is defined similarly as in (\ref{eq_ddd}) except that $\xb_{ik}=\varphi_{\ell_2(k)}(X_{i-\ell_i(k)}).$ 

First, we establish the convergence results for the matrix $W^\top W. $ Recall that $W$ contains two parts $W_0$ and $W_1.$ Denote $W_{0(1)}(i)$ as the $i$th column of $W_{0(1)}.$ It suffices to analyze the terms $W_0(i)^\top W_0(j), W_0(i)^\top W_1(j)$ and $W_1(i)^\top W_1(j).$  Without loss of generality, we focus our discussion on the terms $$ W_1(1)^\top W_1(1) ,W_1(1)^\top W_2(1), W_0(1)^\top W_0(1), W_0(1)^\top W_0(2), W_0(1)^\top W_1(1). $$ 
The general cases of $i,j$ can be handled similarly.

We start with the term $W_1^\top(1) W_1(1).$ Let $W_1(1)=(\mathsf{w}_{12}, \cdots, \mathsf{w}_{1n})^\top.$ Recall (\ref{eq_designmatrix}). We have 
\begin{equation*}
\mathsf{w}_{1k}=\phi_1(t_k) \varphi_1(X_{k}), \ 1 \leq k \leq n.
\end{equation*}
Consequently, we have that
\begin{equation*}
\frac{1}{n} W_1(1)^\top W_1(1)=\frac{1}{n} \sum_{k=1}^n \phi_1(t_k)^2 \varphi_1(X_{k})^2.  
\end{equation*}
Note that by a discussion similar to Lemma \ref{lem_locallystationaryform}, we can show that $\mathfrak{h}_k:=\phi_1(t_k)^2 \varphi_1(X_{k})^2, 1 \leq k \leq n,$ is a sequence of locally stationary time series whose physical dependence measure satisfies that 
\begin{equation*}
\delta_{\mathfrak{h}}(j,q) \leq C \xi^2 \varsigma^2 j^{-\tau}, \ \text{for some constant} \ C>0,
\end{equation*}
where we again recall the notations in (\ref{eq_defnxic}).

Together with (1) of Lemma \ref{lem_concentration}, we obtain that
\begin{equation}\label{eq_firstusedimportantequation}
\left\|\frac{1}{n} W_1^\top(1) W_1(1)-\frac{1}{n}\sum_{k=1}^n \phi_1(t_k)^2 \mathbb{E} \varphi_1(X_{k})^2  \right\|_q \leq \frac{C \xi^2 \varsigma^2}{\sqrt{n}},
\end{equation}
where we used the assumption that $q>2.$ 
Moreover, by (2) of Lemma \ref{lem_concentration}, we have that 
\begin{equation}\label{eq_cccc}
\left| \frac{1}{n}\sum_{k=1}^n \phi_1(t_k)^2 \mathbb{E} \varphi_1(X_{k})^2 -\frac{1}{n} \sum_{k=1}^n \Pi_{11}(t_k) \right| \leq C \xi^2 \varsigma^2 n^{-1+\frac{2}{\tau+1}},
\end{equation}
where $\Pi_{11}(t)$ is the first entry of $\Pi(t)$ defined in (\ref{eq_longrunwitht}).
Further, by Lemma \ref{lem_intergralappoximation}, we 
have that
\begin{equation}\label{eq_ccc2}
\left|\frac{1}{n} \sum_{k=1}^n  \Pi_{11}(t_k)-\int_0^1  \Pi_{11}(t) \dd t \right|=\OO(n^{-2}). 
\end{equation}
We point out that $\int_0^1 \Pi_{11}(t)\dd t=\Pi_{11}$ which is the first entry of $\Pi$ as in (\ref{eq_longruncovariancematrix}). Combining with the above arguments, we conclude that 
\begin{equation*}
\left\| \frac{1}{n} W_1^\top(1) W_1(1)- \Pi_{11} \right\|_q \leq C \left( \frac{\varsigma^2\xi^2}{\sqrt{n}}+\frac{\varsigma^2 \xi^2 n^{\frac{2}{\tau+1}}}{n}\right).
\end{equation*}
Similarly, we can show that 
\begin{equation*}
\left\| \frac{1}{n} W_1^\top(1) W_2(1)- \Pi_{12} \right\|_q \leq C \left( \frac{\varsigma^2 \xi^2}{\sqrt{n}}+\frac{\varsigma^2 \xi^2 n^{\frac{2}{\tau+1}}}{n}\right).
\end{equation*}

Moreover, for $W_0(1)^\top W_0(1),$ we recall that $W_0(1)=(\phi_1(t_1), \cdots, \phi_1(t_n)).$ Consequently, we have that 
\begin{equation*}
\frac{1}{n} W_0(1)^\top W_0(1)=\frac{1}{n} \sum_{k=1}^n \phi_1^2(t_k).
\end{equation*}
By the orthonormality of the basis functions and Lemma \ref{lem_intergralappoximation}, we obtain that 
\begin{equation*}
\left|\frac{1}{n} W_0(1)^\top W_0(1)-1 \right|=\mathrm{O}(n^{-2}). 
\end{equation*}
Similarly, we can prove that 
\begin{equation*}
\left|\frac{1}{n} W_0(1)^\top W_0(2) \right|=\mathrm{O}(n^{-2}). 
\end{equation*}

Finally, we discuss $W_0(1)^\top W_1(1).$ By definition, we have that
\begin{equation*}
\frac{1}{n} W_0(1)^\top W_1(1)=\frac{1}{n} \sum_{k=1}^n \phi_1^2(t_k) \varphi_1(X_k). 
\end{equation*}
Then according to a discussion similar to (\ref{eq_firstusedimportantequation})--(\ref{eq_ccc2}), we readily obtain that 
\begin{equation*}
\left\| \frac{1}{n} W_0(1)^\top W_1(1)-\overline{\Pi}_{1 (c_0+1)} \right\|_q \leq C \left(\frac{ \xi^2 \varsigma}{\sqrt{n}}+\xi^2 \varsigma n^{-1+\frac{2}{\tau+1}} \right). 
\end{equation*} 


Recall (\ref{eq_Pibar}). 
%{\color{blue}[from here]}
Together the above results with Lemma \ref{lem_circle}, we conclude that 
\begin{equation}\label{eq_consistencyconvergency}
\left\| \frac{1}{n} W^\top W-\overline{\Pi} \right\|_{\op} =\OO_{\mathbb{P}} \left( \mathsf{p}\left( \frac{\varsigma^2 \xi^2}{\sqrt{n}}+\frac{\xi^2 \varsigma^2 n^{\frac{2}{\tau+1}}}{n}\right) \right),
\end{equation}
where we used the fact that $q>2$ and recall that $\mathsf{p}$ is defined in (\ref{eq_defnp}). Together with Assumption \ref{assum_updc} and (\ref{eq_parameterassumption}), we find that {
\begin{equation}\label{eq_boundone}
\left | \frac{1}{\lambda_{\min}(n(W^\top W)^{-1})} \right |=\OO_{\mathbb{P}}(1). 
\end{equation}}



Second, we control the error term $\frac{W^\top \bm{\epsilon}}{n}.$ {Without loss of generality, we focus on the first entry of the matrix $\frac{W_1^\top \bm{\epsilon}}{n}$ as follows
\begin{equation}\label{eq_entrywiseexpansion}
\frac{\left[W_1^\top \bm{\epsilon} \right]_{1}}{n}=\frac{1}{n}\sum_{k=1}^n \phi_1(t_k) \varphi_1(X_{k}) \epsilon_{k}.
\end{equation}} 
By Lemma \ref{lem_locallystationaryform}, (1) of Lemma \ref{lem_concentration} and $q>2$, we conclude that 
\begin{equation*}
\left \|\frac{\left[W_1^\top \bm{\epsilon} \right]_{1}}{n} \right \|^2 \leq \frac{C\xi^2 \varsigma^2 }{n}.
\end{equation*} 
Consequently, for some constant $C>0,$ we have that 
\begin{equation}\label{eq_boundtwo}
\left \|\frac{W^\top \bm{\epsilon}}{n} \right \| \leq  \frac{C \xi \varsigma \sqrt{\mathsf{p}}}{\sqrt{n}}.   
\end{equation}
In summary,  by (\ref{eq_boundone}) and (\ref{eq_boundtwo}), in view of (\ref{eq_betabound1}), we obtain that {
\begin{equation}\label{eq_betabound}
|\widehat{\bm{\beta}}-\bm{\beta} |=\OO_{\mathbb{P}}(\xi \varsigma \sqrt{\frac{\mathsf{p}}{n}}). 
\end{equation} }
Together with (\ref{eq_ll1}), we have completed the proof of the control of the first part of the right-hand side of (\ref{eq_initialdecomposition}) . 

Then we proceed to control $|\chi(t)-\widehat{\chi}(t) |.$  Recall (\ref{eq_definitionvartheta}) and  $\bm{f}=\{\phi_{\ell_1}(t)\}_{\ell_1 \leq i \leq c} \otimes \{\vartheta_{\ell_2}(t)\}_{1 \leq \ell_2 \leq d}  \in \mathbb{R}^{cd}.$ Moreover, for the estimators $\{\widehat{\vartheta}_{\ell_2}(t)\},$ we denote
$\widehat{\bm{f}}=\{\phi_{\ell_1}(t)\}_{1 \leq \ell_1 \leq c} \otimes \{\widehat{\vartheta}_{\ell_2}(t)\}_{1 \leq \ell_2 \leq d}  \in \mathbb{R}^{cd}.$ By definition, we have that 
\begin{equation}\label{eq_widehatfnotation}
\chi(t)-\widehat{\chi}(t)=\bm{f}^\top (\bm{\beta}_1-\widehat{\bm{\beta}}_1)+\widehat{\bm{\beta}}_1^\top(\bm{f}-\widehat{\bm{f}}). 
\end{equation}



On the one hand, for some constant $C>0,$ using (\ref{eq_betabound}), we have that {
\begin{equation*}
| \bm{f}^\top (\bm{\beta}_1-\widehat{\bm{\beta}}_1) | \leq |\bm{f}| | \bm{\beta}-\widehat{\bm{\beta}}|=\OO_{\mathbb{P}}(|\bm{f}| \xi \varsigma \sqrt{\frac{\mathsf{p}}{n}}).  
\end{equation*}}
Recall $\phib(t)=\{\phi_{\ell_1}(t)\} \in \mathbb{R}^c.$ For $|\bm{f}|,$ using the property of Kronecker product, we have that
\begin{align}\label{eq_bbbbbb}
|\bm{f}|=|\phib| |\bm{\vartheta}(t)  | \leq \gamma  \iota,
\end{align}
where $\bm{\vartheta}(t) \in \mathbb{R}^d$ is the collection of $\{\vartheta_{\ell_2}\}$ and we recall (\ref{eq_defnxic}) again. Consequently, we have that{ 
\begin{equation*}
| \bm{f}^\top (\bm{\beta}_1-\widehat{\bm{\beta}}_1) | =\OO_{\mathbb{P}}(\xi \varsigma \gamma \iota \sqrt{\frac{\mathsf{p}}{n}}).  
\end{equation*}}

On the other hand, when $n$ is sufficiently large, together with (\ref{eq_betabound}),   we have that {
\begin{equation*}
|\widehat{\bm{\beta}}_1^\top(\bm{f}-\widehat{\bm{f}})|=\OO_{\mathbb{P}}(| \bm{\beta}_1| | \bm{f}-\widehat{\bm{f}}|).   
\end{equation*} }
Using the property of Kronecker product, we have that 
\begin{equation*}
| \bm{f}-\widehat{\bm{f}} |=|\phib| | \bm{\vartheta}-\widehat{\bm{\vartheta}} | \leq \gamma \sqrt{\sum_{\ell=1}^d \|\vartheta_\ell-\widehat{\vartheta}_\ell\|^2}. 
\end{equation*}
Using Lemma \ref{lem_locallystationaryform}, by a discussion similar to (\ref{eq_betabound}) (see \cite{DZ, DZ2} for more details), we readily have that { 
\begin{equation*}
|\vartheta_{\ell}(t)-\widehat{\vartheta}_{\ell}(t)|=\OO_{\mathbb{P}}\left(c_\ell^{-\mathsf{n}_{\ell}}+\gamma_\ell \xi \varsigma \sqrt{\frac{c_\ell}{n}}  \right). 
\end{equation*}}
This yields that {
\begin{equation}\label{eq_bbbbbb11111}
| \bm{f}-\widehat{\bm{f}} |=\OO_{\mathbb{P}}\left(\gamma \sqrt{\sum_{\ell=1}^d \left( c_\ell^{-n_\ell}+\gamma_\ell \xi \varsigma \sqrt{\frac{c_\ell}{n}} \right)^2} \right). 
\end{equation} }


Combining all the above results, one can readily obtain that {
\begin{equation}\label{eq_boundnnnnnn}
| \chi(t)-\widehat{\chi}(t) |=\mathrm{O}_{\mathbb{P}} \left( \xi \varsigma \gamma \iota \sqrt{\frac{\mathsf{p}}{n}} +\gamma \sqrt{\sum_{\ell=1}^d \left( c_\ell^{-n_\ell}+\gamma_\ell \xi \varsigma \sqrt{\frac{c_\ell}{n}} \right)^2}\right).
\end{equation}}
This concludes our proof of (\ref{eq_rate}). 

Finally, we deal with the time-varying intercept part. Similar to (\ref{eq_initialdecomposition}), we have that {
\begin{align*}
| \widehat{m}_0(t)-m_0(t) | \leq | \widehat{m}_{0,c}^*(t)-m_{0,c}(t) |+\left|  \widehat{\chi}(t)- \chi(t) \right|+|m_0(t)-m_{0,c}(t)|. 
\end{align*}}
Using (\ref{eq_betabound}) and a discussion similar to (\ref{eq_ll1}), we readily have that {
\begin{equation}\label{eq_adddadada}
 | \widehat{m}_{0,c}^*(t)-m_{0,c}(t) |=\mathrm{O}_{\mathbb{P}}\left( \gamma \xi \varsigma \sqrt{\frac{\mathsf{p}}{n}} \right). 
\end{equation} }
Together with (\ref{eq_boundnnnnnn}), we can then conclude the proof. 

\end{proof}




\subsection{{High dimensional point-wise Gaussian approximation and proof of Theorem \ref{thm_asymptoticdistribution}}}\label{sec_gassuianapproximation}
In this subsection, we prove Theorem \ref{thm_asymptoticdistribution}. The key ingredient is to establish the Gaussian approximation for the statistics $\mathsf{T}_{j}$ . The starting point is to rewrite the statistics $\mathsf{T}_{j}$ more explicitly in an affine form. We first prepare some notations. Without loss of generality, we only explain the proof for $r=1$ as  discussed in the beginning of the proof of Theorem \ref{thm_consistency} and omit the subscript $j$ in the sequel. Additionally, since our focus is on the regression functions, we assume $m_0(t) \equiv 0$. The general case can be handled in a similar manner; see Remark \ref{rem_meanzerodiscussions} below for more discussions. 

Recall (\ref{eq_widehatfnotation}). Denote 
\begin{equation*}
\widehat{\bm{r}}=\bm{b}-\widehat{\bm{f}}. 
\end{equation*} 
According to (\ref{eq_initialdecomposition}), under the assumption of (\ref{eq_parameterassumption}), Assumption \ref{assum_debiasassumption} and mean-zero assumption,
\begin{align} \label{eq_fundementalexpression}
\widehat{m}(t,x)-m(t,x)&= \bm{r}^\top (\widehat{\bm{\beta}}-\bm{\beta})+(\widehat{\bm{r}}^\top-\bm{r}^\top) \widehat{\bm{\beta}} \nonumber \\
& =\frac{1}{\sqrt{n}}\bm{r}^\top \Pi^{-1} (\frac{1}{\sqrt{n}} W^\top \bm{\epsilon})\left(1+\oo_{\mathbb{P}}(1)  \right),
\end{align}
where we recall (\ref{eq_verctorconstruction}), and we used (\ref{eq_betadifferenceexpression}) and  (\ref{eq_consistencyconvergency}). 
\begin{remark}\label{rem_meanzerodiscussions}
We note that if the mean is nonzero, (\ref{eq_fundementalexpression}) can be easily modified such that the arguments and discussions remain valid. More specifically, we have that  
\begin{align*} 
\widehat{m}(t,x)-m(t,x)&= \bm{r}^\top (\widehat{\bm{\beta}}_1-\bm{\beta}_1) \nonumber \\
& =\frac{1}{\sqrt{n}}\overline{\bm{r}}^\top \overline{\Pi}^{-1} (\frac{1}{\sqrt{n}} W^\top \bm{\epsilon})\left(1+\oo_{\mathbb{P}}(1)  \right),
\end{align*}
where $\overline{\Pi}$ is defined in (\ref{eq_Pibar}) and $\overline{\bm{r}}=(\bm{0}^\top_c \ \bm{r}^\top)^\top.$  Consequently, we can further write  
\begin{align*} 
\widehat{m}(t,x)-m(t,x)& =\frac{1}{\sqrt{n}}\overline{\bm{r}}^\top \overline{\Pi}^{-1} (\frac{1}{\sqrt{n}} W^\top \bm{\epsilon})\left(1+\oo_{\mathbb{P}}(1)  \right). 
\end{align*}
Then all the discussions below still apply. 
\end{remark}


Based on Remark \ref{rem_meanzerodiscussions}, in what follows, without loss of generality, we assume the time-varying intercept is always zero; see Remark \ref{rem_meannotzero} for more discussions on this point. Recall that the deterministic vector $\bm{l}$ and random vector $\bm{z}$ are defined as
\begin{equation}\label{eq_originaldefinition}
\bm{l}=\Pi^{-1} \bm{r}, \ \bm{z}=\frac{1}{\sqrt{n}} W^\top \bm{\epsilon}.
\end{equation}
In what follows, recall (\ref{eq_realU}), we denote $\bm{y}_i \in \mathbb{R}^p$ such that 
\begin{equation}\label{eq_decompositionkronecker}
\bm{y}_i=\widetilde{\mathbf{U}}(t_i, \mathcal{F}_i).
\end{equation}
Using (\ref{eq_designmatrix}), it is easy to see that  
\begin{equation}\label{eq_bmzgreatform}
\bm{z}=\frac{1}{\sqrt{n}}\sum_{i=1}^n \bm{y}_i.
\end{equation}
Therefore, in view of (\ref{eq_originaldefinition}),  the analysis of $\mathsf{T}$ reduces to study $\bm{l}^\top \bm{z}$ using (\ref{eq_bmzgreatform}) and (\ref{eq_decompositionkronecker}). 


Based on the above discussion, we have seen that it suffices to establish the Gaussian approximation theory for the affine form $\bm{l}^\top \bm{z}.$ Before stating the Gaussian approximation results,  we first pause to record the covariance structure of $\bm{z}$ in Lemma \ref{lem_covarianceofz} below. It indicates that $\operatorname{Cov}(\bm{z})$ is close to $\Omega$ defined in (\ref{eq_longruncovariancematrix}). 
%{\color{red}[from here]}
\begin{lemma}\label{lem_covarianceofz}
Let $\operatorname{Cov}(\bm{z})$ be the covariance matrix of $\bm{z}.$ Suppose the assumptions of Theorem \ref{thm_consistency} hold. Then we have that
\begin{equation*}
\|\operatorname{Cov}(\bm{z})-\Omega \|_{\op}=\OO\left(\frac{p\xi^2 \varsigma^2 n^{2/\tau}}{\sqrt{n}} +p\xi^2 \varsigma^2 n^{-1+\frac{2}{\tau+1}}\right).
\end{equation*}
\end{lemma}
\begin{proof}
Denote $\bm{z}=(z_1, \cdots, z_p)^\top.$ We control the error entrywisely and focus on $[\operatorname{Cov}(\bm{z})]_{11}=\operatorname{Var}(z_1)$. Recall (\ref{eq_ddd}).  Note that 
%\begin{equation*}
%z_1=\sum_{j=1}^r \sum_{k=1}^n \phi_1(t_k) \varphi_1(X_{k-j}) \epsilon_{k}
%\end{equation*}
\begin{equation}\label{eq_z1form}
z_1=\frac{1}{\sqrt{n}}\sum_{k=1}^n \phi_1(t_k) \varphi_1(X_{k}) \epsilon_{k}.
\end{equation}
Using the notation (\ref{eq_ddd}) and Lemma \ref{lem_locallystationaryform}, we conclude that 
\begin{align}\label{eq_decompositionvariance}
\operatorname{Var}(z_1) &=\frac{1}{n} \sum_{k_1, k_2=1}^n \phi_1(t_{k_1}) \phi_1(t_{k_2}) \mathbb{E} u_{k_1 1} u_{k_2 1} \nonumber \\
&=\frac{1}{n}\sum_{k=1}^n \phi_1(t_{k})^2 \mathbb{E} u^2_{k 1}+\frac{1}{n} \sum_{k_1 \neq k_2}^n \phi_1(t_{k_1}) \phi_1(t_{k_2}) \mathbb{E} u_{k_1 1} u_{k_2 1}:=\mathsf{E}_1+\mathsf{E}_2,
\end{align}

First, by a discussion similar to (\ref{eq_cccc}) and (\ref{eq_ccc2}), we  find that
\begin{equation}\label{eq_e1finalerror}
\left| \mathsf{E}_1-\Omega_{11}\right|=\OO\left(\xi^2 \varsigma^2 n^{-1+\frac{2}{\tau+1}}\right).
\end{equation}
Second, for $\mathsf{E}_2,$ by Lemma \ref{lem_locallystationaryform} and (3) of Lemma \ref{lem_concentration}, we find that for some constant $C>0$ 
\begin{equation}\label{eq_hhahahahahhaha}
|\mathbb{E} u_{k_1 1} u_{k_2 1}| \leq C \varsigma |k_1-k_2|^{-\tau}. 
\end{equation}
Consequently, we obtain that for some constant $C>0$ {
\begin{align}\label{eq_e2part}
\left| \mathsf{E}_2 \right| &= \frac{1}{n} \left(  \sum_{k_1=1}^n \phi_1(t_{k_1}) \sum_{|k_1-k_2| > n^{2/\tau}}  \phi_1(t_{k_2})  \mathbb{E} u_{k_1 1} u_{k_2 1} + \sum_{k_1=1}^n \phi_1(t_{k_1}) \sum_{|k_1-k_2| \leq n^{2/\tau}, k_1 \neq k_2}  \phi_1(t_{k_2})  \mathbb{E} u_{k_1 1} u_{k_2 1}\right) \nonumber \\
&\leq C\frac{ \varsigma \xi^2}{n}+C\left|\frac{1}{n} \sum_{k_1=1}^n \phi_1(t_{k_1}) \sum_{|k_1-k_2| \leq n^{2/\tau}, k_1 \neq k_2}  \phi_1(t_{k_2})  \mathbb{E} u_{k_1 1} u_{k_2 1} \right|,
\end{align}
where in the second step we used (\ref{eq_hhahahahahhaha}).} For each fixed $k_2,$ by a discussion similar to Lemma \ref{lem_locallystationaryform}, we see that $\{u_{k_1 1} u_{k_2 1}\}$ is a locally stationary time series whose physical dependence measure satisfies that $\delta(i,q) \leq C \varsigma^2 i^{-\tau}.$ {Recall that $\phi_1(t_{k_2})=\mathrm{O}(\xi).$ Similarly, for fixed $k_1,$ $\{\sum_{|k_1-k_2| \leq n^{2/\tau}, k_1 \neq k_2}  \phi_1(t_{k_2}) u_{k_1 1} u_{k_2 1} \}$ is also a locally stationary time series whose dependence measure $\delta'(i,q)$ can be bounded by  $C \xi n^{2/\tau} \varsigma^2 i^{-\tau}.$} As $q>2,$ applying (1) of Lemma \ref{lem_concentration}, we readily see that 
%\begin{equation*}
%\left| \frac{1}{n} \sum_{k_1=1}^n \phi_1(t_{k_1}) \mathbb{E} u_{k_1 1} u_{k_2 1} \right| \leq \frac{C \varsigma^2 \xi}{\sqrt{n}}.
%\end{equation*}
{ 
\begin{align*}
\left|\frac{1}{n} \sum_{k_1=1}^n \phi_1(t_{k_1}) \sum_{|k_1-k_2| \leq n^{2/\tau}, k_1 \neq k_2}  \phi_1(t_{k_2})  \mathbb{E} u_{k_1 1} u_{k_2 1} \right| \leq \frac{C \varsigma^2 \xi^2 n^{2/\tau}}{\sqrt{n}}.
\end{align*}
}
Together with (\ref{eq_e2part}), we arrive at
\begin{equation}\label{eq_e2finalerror}
|\mathsf{E}_2| \leq C \left( \varsigma \frac{\xi^2}{n} +\frac{ \varsigma^2 \xi^2 n^{2/\tau}}{\sqrt{n}}\right).
\end{equation} 
By (\ref{eq_decompositionvariance}), (\ref{eq_e1finalerror}) and (\ref{eq_e2finalerror}), we obtain that 
\begin{equation*}
|\operatorname{Var}(z_1)-\Omega_{11}|=\OO\left( \frac{\varsigma \xi^2}{n} +\frac{ \varsigma^2 \xi^2 n^{2/\tau}}{\sqrt{n}} +\xi^2 \varsigma^2 n^{-1+\frac{2}{\tau+1}}\right).
\end{equation*}
The general term $\operatorname{Cov}(z_i, z_j)$ can be analyzed similarly. We can therefore conclude our proof using Lemma \ref{lem_circle}. 
\end{proof} 

\begin{remark}\label{rem_meannotzero}
When the intercept is nonzero, we should construct $\bm{y}_i \in \mathbb{R}^{c_0+p}$ as follows 
\begin{equation*}
\bm{y}_i=(D(t_i,\mathcal{F}_i) \otimes \phib_0(t_i)^\top, \widetilde{\mathbf{U}}(t_i, \mathcal{F}_i)^\top)^\top. 
\end{equation*}
Then all the discussion will follow. Especially, one has $\bm{z}=(z_{01}, \cdots, z_{0c_0}, z_1, \cdots, z_p)^\top.$ Note that 
\begin{equation*}
z_{01}=\frac{1}{\sqrt{n}}\sum_{k=1}^n \phi_1(t_k) \epsilon_k.
\end{equation*}  
Based on this, we can obtain a similar similar to Lemma \ref{lem_covarianceofz} by replacing $\Omega$ with $\overline{\Omega},$ and $p$ with $\mathsf{p}$ in the error bound, as well as the fact that 
\begin{equation*}
\operatorname{Cov}(z_{01}, z_1)=\frac{1}{n} \sum_{k_1=1}^n \sum_{k_2=1}^n \phi_1(t_{k_1}) \phi_1(t_{k_2}) \operatorname{Cov}(\varphi_1(X_k),\epsilon_k)=0,
\end{equation*}  
where we used the assumption below (\ref{eq:model}) that $\mathbb{E}(\epsilon_k|X_k)=0.$
\end{remark}



Next, we state the Gaussian approximation results for the affine form of $\bm{z}$. Consider a sequence of centered Gaussian random vectors $\{\bm{g}_i\}_{i=1}^n$ in $\mathbb{R}^p$ which preserve the covariance structure of $\{\widetilde{\mathbf{U}}(t_i, \mathcal{F}_i)\}$ and denote
