%z_1= \frac{1}{\sqrt{n}} \sum_{k=1}^n \phi_1(t_k) \varphi_1(X_{k-1}) \epsilon_{k}. 
%\end{equation*}
%Based on the above expression,
we readily obtain that for some constant $C>0,$
\begin{equation*}
\mathbb{E}(|z_i-z_i^\Mt|^q)^{2/q} \leq C \xi^2 \Theta^2_{\fm,q} \leq C \xi^2 \varsigma^2 \fm^{-2\tau+2},  
\end{equation*} 
where $\Theta_{\fm,q}=\sum_{k=\fm}^{\infty} \delta_u(k,q)$ (recall (\ref{eq_deltaxdefinition})). Consequently, as $q>2,$ by (1) of Lemma \ref{lem_collectionprobineq}, we readily obtain that for some constant $C_1>0$
\begin{equation}\label{eq_control}
\mathbb{E}|z_i-z^\Mt_i| \leq C_1 \xi \Theta_{\fm,q}, \  \mathbb{E}|z_i-z^\Mt_i|^2 \leq C_1 \xi^2 \Theta^2_{\fm,q}.
\end{equation} 
Note that (\ref{eq_variancedecomposition}) implies that 
\begin{equation}\label{eq_decompositionv}
\left| \operatorname{Var}(z_i)-\operatorname{Var}(z_i^\Mt)\right| \leq \sqrt{\mathbb{E}|z_i-z_i^\Mt|^2 \mathbb{E}|z_i+z_i^\Mt|^2}+\mathbb{E}|z_i-z_i^\Mt| \mathbb{E}|z_i+z_i^\Mt|,
\end{equation}
where we used (2) of Lemma \ref{lem_collectionprobineq}. Moreover, by Lemmas \ref{lem_locallystationaryform} and \ref{lem_concentration}, using the definition (\ref{eq_z1form}), we find that for some constant $C_2>0$
\begin{equation}\label{eq_bound}
\mathbb{E}|z_i|< C_2 \xi \varsigma, \ \mathbb{E}|z_i|^2< C_2 \xi^2 \varsigma^2.
\end{equation} 
Together with (\ref{eq_control}), we see that
\begin{equation*}
\mathbb{E}|z_i+z_i^\Mt| \leq C_2 \xi \varsigma+ C_1 \xi \Theta_{\fm,q}.
\end{equation*}
Furthermore, using (\ref{eq_bound}), we see that
\begin{align*}
 \mathbb{E}|z_i+z_i^\Mt|^2 & \leq 2 \mathbb{E}|z_i|^2+2 \mathbb{E}|z_i^\Mt|^2 \\
 & \leq 2C_2 \xi^2 \varsigma^2 +2\mathbb{E}|z_i|^2+2\mathbb{E}|z_i-z_i^\Mt| \mathbb{E} |z_i+z_i^\Mt| \\
 & \leq 4 C_2 \xi^2 \varsigma^2+2 C_1 \xi\Theta_{\fm,q}(C_2\xi \varsigma+C_1 \Theta_{\fm,q}).
\end{align*}
Together (\ref{eq_control}) and (\ref{eq_decompositionv}), we conclude that for some constant $C>0,$
\begin{equation*}
\left| \operatorname{Var}(z_i)-\operatorname{Var}(z_i^\Mt)\right| \leq C \xi^2 \varsigma \Theta_{\fm,q}. 
\end{equation*}
Similarly, we can show that for all $1 \leq i,j \leq p$
\begin{equation*}
\left| \operatorname{Cov}(z_i, z_j)-\operatorname{Cov}(z_i^\Mt, z_j^\Mt) \right| \leq C \xi^2 \varsigma \Theta_{\fm,q}. 
\end{equation*}
Consequently, by Lemma \ref{lem_circle}, we obtain that for some constant $C_1>0$
\begin{equation}\label{eq_partonecontrol}
\left\| \operatorname{Cov}(\zb)-\operatorname{Cov}(\zb^\Mt)  \right\|_{\op} \leq C p \xi^2 \varsigma \Theta_{\fm,q} \leq C_1 p \xi^2 \varsigma^2 \fm^{-\tau+1}, 
\end{equation}
where in the second inequality we used (\ref{eq_transferbound}). 

Second, we control the second term on the right-hand side of (\ref{eq_tridecomposition}). Recall (\ref{eq_truncation}). We point out that $\bar{z}^\Mt_i \neq z_i^\Mt \mathbf{1}(z_i \leq \hd)$ in general. For notational simplicity, we denote $\mathbf{U}^\Mt(t_i, \mathcal{F}_i)=(u_{i1}^\Mt, \cdots, u_{i,d}^\Mt).$ Using the construction (\ref{eq_dependencesequence}), with an argument similar to Lemma \ref{lem_locallystationaryform}, we can show that $\{\mathbf{U}^\Mt(t_i, \mathcal{F}_i)\}$ is a locally stationary time series whose physical dependence measure also satisfies $\delta(j,q) \leq C \varsigma j^{-\tau},$ for some constant $C>0$. Analogous to the discussion for the first term, we focus on the case $i=1$ and keep the subscript $i.$ Observe that
\begin{equation}\label{eq_firstorder}
|\mathbb{E}z_i^\Mt-\mathbb{E}\bar{z}_i^\Mt|=\left|\frac{1}{\sqrt{n}} \sum_{k=1}^n \phi_1(t_k) \mathbb{E}(u^\Mt_{k,i} \mathbf{1}(|u_{k,i}^\Mt|>\hd)) \right|.
\end{equation} 
Moreover, using Chebyshev's inequality (c.f. (3) of Lemma \ref{lem_collectionprobineq}), a discussion similar to (\ref{eq_bound}),  and the fact that 
\begin{equation*}
\mathbf{1}(|u_{k,i}^\Mt|>\hd) \leq \frac{|u_{k,i}^\Mt|^{q-1}}{\hd^{q-1}},
\end{equation*}
we find that for some constant $C>0,$
\begin{equation*}
|\mathbb{E}(u^\Mt_{k,i} \mathbf{1}(|u_{k,i}^\Mt|>\hd))| \leq C \xi \varsigma \hd^{-(q-1)}.  
\end{equation*}
Consequently, we see that 
\begin{equation}\label{eq_expectationcontrolone}
|\mathbb{E}z_i^\Mt-\mathbb{E}\bar{z}_i^\Mt| \leq C \sqrt{n} \xi^2 \varsigma  \hd^{-(q-1)}.
\end{equation}
Similarly, we can show that 
\begin{equation}\label{eq_secondorder}
\left| \mathbb{E}(z_1^\Mt)^2-\mathbb{E} (\bar{z}_1^\Mt)^2 \right| \leq C n \xi^4 \varsigma^2  \hd^{-(q-2)}.
\end{equation}
By (\ref{eq_firstorder}), (\ref{eq_secondorder}) and the fact $|\bar{u}_{k,i}^\Mt| \leq \hd,$ using a decomposition similar to (\ref{eq_variancedecomposition}), we conclude that for some
constant $C>0,$
\begin{equation*}
\left| \operatorname{Var}(\bar{z}^\Mt_i)-\operatorname{Var}(z_i^\Mt)\right| \leq C n \xi^4 \varsigma^2 \hd^{-(q-2)}. 
\end{equation*}
Similarly, we can show that for all $1 \leq i,j \leq p$
\begin{equation*}
\left| \operatorname{Cov}(\bar{z}^\Mt_i, \bar{z}^\Mt_j)-\operatorname{Cov}(z_i^\Mt, z_j^\Mt) \right| \leq  C n \xi^4 \varsigma^2 \hd^{-(q-2)}. 
\end{equation*}
Consequently, by Lemma \ref{lem_circle}, we obtain that
\begin{equation}\label{eq_parttwocontrol}
\left\| \operatorname{Cov}(\bar{\zb}^\Mt)-\operatorname{Cov}(\zb^\Mt)  \right\|_{\op} \leq C pn \xi^4 \varsigma^2 \hd^{-(q-2)}. 
\end{equation}

In summary, by (\ref{eq_tridecomposition}), (\ref{eq_partonecontrol}) and (\ref{eq_parttwocontrol}), we find that for some constant $C>0$
\begin{equation}\label{eq_covarianceclose}
\left\|\operatorname{Cov}(\bm{z})-\operatorname{Cov}(\bar{\zb}^\Mt) \right\|_{\op}  \leq C \varsigma^2 \left( p \xi^2 \fm^{-\tau+1}+ pn \xi^4 \hd^{-(q-2)} \right). 
\end{equation}
This completes Step one. Furthermore, since the assumption (\ref{eq_onebound}) ensures that the right-hand side of (\ref{eq_covarianceclose}) is of order $\mathrm{o}(1),$ we can conclude that the covariance matrices are close. 

