{The rest of the work focuses on proving Theorem \ref{thm_uniformconvergencegaussian}. }
The key idea for controlling (\ref{eq_uniformGaussianneedtobebounded}) is to employ the smoothing technique proposed in \cite{bentkus2003dependence}, the convex Gaussian approximation trick in \cite{MR3571252,FangRollin2015} and the crucial bounds obtained in the proofs of Theorem \ref{thm_gaussianapproximationcase}.



\begin{proof}[\bf Proof of Theorem \ref{thm_uniformconvergencegaussian}]
For the purpose of smoothing, we introduce the following function as in \cite{bentkus2003dependence}. For the collection of convex sets $\mathcal{A}$ in $\mathbb{R}^p$ and $\mathsf{A} \in \mathcal{A},$ given some small $\epsilon_1>0,$ we denote 
\begin{equation*}
h_{\mathsf{A}, \epsilon_1}(\bm{q})=\eta\left( \frac{\operatorname{dist}(\bm{q},\mathsf{A})}{\epsilon_1} \right),
\end{equation*} 
where $\operatorname{dist}(\bm{q},\mathsf{A})=\inf_{\bm{w} \in \mathsf{A}}|\bm{q}-\bm{w}|$ and 
\begin{equation*}
\eta(x)=
\begin{cases}
1, & x<0, \\
1-2x^2, & 0 \leq x<\frac{1}{2}, \\
2(1-x)^2, & \frac{1}{2} \leq x<1, \\
0, & x \geq 1. 
\end{cases}
\end{equation*}
According to (iv) of Lemma 2.3 of \cite{bentkus2003dependence}, we have that 
\begin{equation}\label{eq_derivativebound}
|\nabla h_{\mathsf{A}, \epsilon_1} | \leq \frac{2}{\epsilon_1}.
\end{equation}

Recall the convention in (\ref{eq_ddddd}), we have that $\bm{v}=\Sigma_0^{1/2}\mathbf{f}$ with $\mathbf{f}$ being a standard Gaussian random vector. Similar, for notional simplify, we also write $\bm{z}=\Sigma_0^{1/2} \mathbf{x},$ where $\mathbf{x}=\Sigma_0^{-1/2} \bm{z}.$ Denote $\bm{l}_1=\Sigma_0^{1/2} \bm{l}.$ We can then rewrite (\ref{eq_uniformGaussianneedtobebounded}) as follows 
\begin{equation}\label{eq_fffafafearaefaef}
\mathcal{K}^*(\bm{z}, \bm{v}) \equiv \mathcal{K}^*(\xb, \fb):=\sup_{\mathsf{x} \geq 0} \left| \mathbb{P}( \sup_{t \in [0,1], x \in \mathbb{R}} |\xb^\top \bm{l}_1| \leq \mathsf{x})-\mathbb{P}( \sup_{t \in [0,1], x \in \mathbb{R}}  |\fb^\top \bm{l}_1| \leq \mathsf{x}) \right|. 
\end{equation}
For $\mathsf{x} \in \mathbb{R},$ denote
\begin{equation*}
\mathsf{A}_{\mathsf{x}} \equiv \mathsf{A}_{\mathsf{x}}(t,x):=\left\{ \bm{q} \in \mathbb{R}^p: |\bm{q}^\top \bm{l}_1| \leq \mathsf{x}   \right\}, \ \ \text{and} \ \ \mathsf{A}_{\mathsf{x}}:=\bigcap_{t \in [0,1] \\ x \in \mathbb{R}}\mathsf{A}_{\mathsf{x}}(t,x). 
\end{equation*}
Similar to the discussions below (\ref{eq_defnset}), we have that 
\begin{equation*}
\mathcal{K}^*(\xb, \fb) \leq \sup_{\mathsf{A} \in \mathcal{A}} |\mathbb{P}(\xb \in \mathsf{A})-\mathbb{P}(\fb \in \mathsf{A})|.  
\end{equation*} 
Consequently, according to Lemma 4.2 of \cite{FangRollin2015}, we can control
\begin{equation}\label{eq_reducednorm}
\mathcal{K}^*(\xb, \fb) \leq 4 p^{1/4} \epsilon_1+\sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\xb)- h_{\mathsf{A}, \epsilon_1}(\fb)\right] \right|. 
\end{equation} 
Therefore, the rest of the proof leaves to control the right-hand side of (\ref{eq_reducednorm}). For notional simplicity, for the quantities in (\ref{eq_decomposition}), we denote 
\begin{equation*}
\xb^{\Mt}=\Sigma_0^{-1/2} \bm{z}^{\Mt}, \ \overline{\xb}^{\Mt}=\Sigma_0^{-1/2} \overline{\bm{z}}^{\Mt}, \  \ \overline{\fb}^{\Mt}=\Sigma_0^{-1/2} \overline{\bm{v}}^{\Mt}.
\end{equation*} 
Note that according to Lemma \ref{lem_covarianceofz}, the assumption of (\ref{eq_parameterassumption}), as well as Assumption \ref{assum_updc}, we have that $\Sigma_0^{-1/2}$ is bounded from above (in operator norm), i.e., 
\begin{equation}\label{eq_operatornormbound}
\| \Sigma_0^{-1/2} \|_{\operatorname{op}}=\mathrm{O}(1). 
\end{equation} 


By triangular inequality, we can write 
\begin{align}\label{eq_decompose}
\sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\xb)- h_{\mathsf{A}, \epsilon_1}(\fb)\right] \right| & \leq \sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\xb)- h_{\mathsf{A}, \epsilon_1}(\xb^{\Mt})\right] \right|+ \sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\xb^\Mt)- h_{\mathsf{A}, \epsilon_1}(\overline{\xb}^\Mt)\right] \right| \nonumber \\
&+ \sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\overline{\xb}^\Mt)- h_{\mathsf{A}, \epsilon_1}(\overline{\fb}^\Mt)\right] \right|+\sup_{\mathsf{A} \in \mathcal{A}} \left| \mathbb{E}\left[h_{\mathsf{A}, \epsilon_1}(\overline{\fb}^\Mt)- h_{\mathsf{A}, \epsilon_1}(\fb)\right] \right| \nonumber \\
&:=L_1+L_2+L_3+L_4. 
\end{align}


Then we bound them term by term. For $L_1,$ using (\ref{eq_derivativebound}), we find that for some constant $C>0,$
\begin{equation*}
L_1 \leq \frac{C}{\epsilon_1}\| \xb-\xb^{\Mt} \|=\mathrm{O} \left( \epsilon_1^{-1} p^{3/2} \xi \varsigma \mathfrak{m}^{-\tau+1} \right), 
\end{equation*}
where we used (\ref{eq_boundneedone}) and (\ref{eq_operatornormbound}). Similarly, using (\ref{eq_needboundtwo}), we can control that
\begin{equation*}
L_2=\mathrm{O} \left( \epsilon_1^{-1}\sqrt{p n} \xi^2 \varsigma \hd^{-(q-1)} \right), 
\end{equation*}  
and using (\ref{eq_covarianceclose}) and (\ref{oldb1}), we can control that 
\begin{equation*}
L_4=\mathrm{O}\left( \epsilon_1^{-1} \sqrt{p} \varsigma^2 \left( p \xi^2 \fm^{-\tau+1}+ pn \xi^4 \hd^{-(q-2)} \right) \right). 
\end{equation*}
Finally, for $L_3,$ following the proof of Lemma \ref{lem_mvnapp}, especially equation (4.24) of \cite{MR3571252}, using the setup as in (\ref{eq_setup}), we have that for some constant $C>0$
\begin{equation*}
L_3 \leq 4 p^{1/4} \epsilon_1+C n^{-1/2}(\sqrt{p} \mathrm{h})^3 \mathfrak{m}^2 \epsilon_1^{-1} \left[p^{1/4}(\epsilon_1+\mathfrak{m}  n^{-1/2}\sqrt{p} \mathrm{h}) +L_3\right]. 
\end{equation*}
This yields that 
\begin{equation*}
L_3 \leq 4 p^{1/4} \epsilon_1+ C n^{-1/2} p^{7/4} \mathrm{h}^3  \mathfrak{m}^2+C n^{-1} p^{9/4} \epsilon_1^{-1} \mathrm{h}^4 \mathrm{m}^3+n^{-1/2}p^{3/2} \epsilon_1^{-1} \mathrm{h}^3 \mathrm{m}^2 L_3.  
\end{equation*}
Note that we can choose $\epsilon_1=n^{-1/2}p \mathrm{h}^2 \mathfrak{m}^{3/2}$ to optimize the control of $L_3$ so that 
\begin{equation*}
L_3=\mathrm{O} \left( n^{-1/2} p^{7/4} \mathrm{h}^3  \mathfrak{m}^2\right). 
\end{equation*}
Moreover, with  $\epsilon_1=n^{-1/2}p \mathrm{h}^2 \mathfrak{m}^{3/2}$, we readily obtain that 
\begin{align*}
L_1+L_2+L_4 & =\mathrm{O}\Big( \sqrt{pn} \mathrm{h}^{-2} \varsigma \xi \mathfrak{m}^{-\tau-1/2}+n p^{-1/2} \xi^2 \varsigma \mathfrak{m}^{-3/2} \mathrm{h}^{-q-1}  \\
&+n^{1/2} p^{-1/2} \mathrm{h}^{-2} \mathfrak{m}^{-3/2} \varsigma^2 \left( p \xi^2 \fm^{-\tau+1}+ pn \xi^4 \hd^{-(q-2)} \right) \Big).
\end{align*}
Combining all the above discussions with (\ref{eq_decompose}), (\ref{eq_reducednorm}) and (\ref{eq_fffafafearaefaef}), we have completed our proof. 
\end{proof}
