Then we prove that both the high-dimensional time series $\{\bm{w}_j(i)\}$ in (\ref{eq_desigmatrixform}) and $\{\bm{u}_j(i)\}$ in (\ref{eq_ddd}) can be regarded as short-range dependent locally stationary time series in the physical representation form. 



\begin{lemma}\label{lem_locallystationaryform}
Suppose  Assumptions \ref{assum_models} and \ref{assum_physical} hold. For $1 \leq j \leq r,$ there exist measurable functions $\mathbf{W}_j(t, \cdot)=(W_{j1}(t,\cdot), \cdots, W_{jd_j}(t, \cdot)), \ \mathbf{U}_j(t, \cdot)=(U_{j1}(t,\cdot), \cdots, U_{jd_j}(t,\cdot)) \in \mathbb{R}^{d_j}$ satisfying the stochastic Lipschitz continuity as in (\ref{eq_slc}) such that $\{\bm{u}_j(i)\}$ is mean zero and (\ref{eq_locallystationaryform}) holds.  Moreover, denote their physical dependence measures as
\begin{equation}\label{eq_deltaxdefinition}
\begin{gathered}
\delta_{w,j}(\mathsf{s},q)=\sup_{1 \leq k \leq d_j} \sup_t\| W_{jk}(t, \mathcal{F}_0)- W_{jk}(t, \mathcal{F}_{0,\mathsf{s}})\|_q, \\ 
 \delta_{u,j}(\mathsf{s},q)=\sup_{1 \leq k \leq d_j} \sup_t\| U_{jk}(t, \mathcal{F}_0)- U_{jk}(t, \mathcal{F}_{0,\mathsf{s}})\|_q.
\end{gathered}
\end{equation} 
Then we have that for $\varsigma_j$ defined in (\ref{eq_xbasisbound}) and some constant $C>0$
\begin{equation}\label{eq_transferbound}
\max\{\delta_{w,j}(\mathsf{s},q),\delta_{u,j}(\mathsf{s},q) \} \leq C \varsigma_j \mathsf{s}^{-\tau}, \ \ \text{for all} \ \mathsf{s} \geq 1. 
\end{equation}
\end{lemma}

\begin{proof}[\bf Proof of Lemma \ref{lem_locallystationaryform}]
Due to similarity, we only prove the results for $\{\bm{u}_i\}$.  First of all, under Assumption \ref{assum_models}, for $w_{ik}$ defined in (\ref{eq_desigmatrixform}), we have that 
\begin{equation}\label{eq_meanzero}
\mathbb{E}(\varphi_{\el_2(k)}(X_{\el_1(k)+1,i} \epsilon_i)=\mathbb{E}(\mathbb{E}(\varphi_{\el_2(k)}(X_{\el_1(k)+1,i}) \epsilon_i| X_{\el_1(k)+1,i}))=0. 
\end{equation}
This shows that $\{\bm{u}_i\}$ is mean zero. Second, for any $1 \leq k \leq rd,$ by (\ref{eq_ddd}) and (\ref{eq_desigmatrixform}), we have that 
\begin{equation}\label{eq_exactform}
u_{ik}=\varphi_{\el_2(k)}(X_{\el_1(k)+1,i})\epsilon_i.
\end{equation}
Under the assumption of (\ref{eq_setting2}), it is clear that for some measurable function $U_k(t,\cdot),$ we can write
\begin{equation*}
u_{ik}=U_k\left(\frac{i}{n}, \mathcal{F}_i\right).
\end{equation*} 
Third, for $s,t \in [0,1],$ using (\ref{eq_exactform}), the smoothness of the basis functions and the assumption (\ref{eq_slc}), we have that for some constant $C>0$
\begin{equation*}
\sup_i \| U_k(s, \mathcal{F}_i)-U_k(t, \mathcal{F}_i) \|_q \leq C|t-s|.
\end{equation*}
Finally, for any $1 \leq k \leq rd,$ using (\ref{eq_exactform}) and (\ref{eq_setting2}), we have that for some constant $C>0$
\begin{align*}
\sup_t \| U_k(t, \mathcal{F}_0)&-U_{k}(t, \mathcal{F}_{0,\mathsf{s}}) \|_q  \leq  \sup_t \| \varphi_{\ell_2(k)}(G_{\ell_1(k)+1}(t,\mathcal{F}_0)) D(t, \mathcal{F}_0)-\varphi_{\ell_2(k)}(G_{\ell_1(k)+1}(t,\mathcal{F}_0)) D(t, \mathcal{F}_{0,\mathsf{s}}) \|_q \\
& + \sup_t \|\varphi_{\ell_2(k)}(G_{\ell_1(k)+1}(t,\mathcal{F}_0)) D(t, \mathcal{F}_{0,\mathsf{s}})-\varphi_{\ell_2(k)}(G_{\ell_1(k)+1}(t,\mathcal{F}_{0,\mathsf{s}})) D(t, \mathcal{F}_{0,\mathsf{s}}) \|_q  \\
& \leq C \varsigma \mathsf{s}^{-\tau},
\end{align*}
where we recall (\ref{eq_xbasisbound}) and in the last inequality we used Assumption \ref{assum_physical}, the smoothness of the basis function and mean value theorem.  $\{\bm{w}_i\}$ can be proved similarly and we omit the details. This finishes our proof. 
