\section{Some auxiliary lemmas}\label{sec_auxililarylemma}
In this section, we collect some useful auxiliary lemmas. The first lemma, Lemma \ref{lem_mvnapp} will be used in the proof of Gaussian approximation, i.e., Theorem \ref{thm_gaussianapproximationcase}. 
\begin{lemma}[Multivariate Gaussian approximation]\label{lem_mvnapp}
Denote $[n]:=\{1,\cdots, n\}$ and $X_N:=\sum_{i \in N} X_i$ for some index set $N.$ Let $X_i \in \mathbb{R}^d$ and $W=\sum_{i=1}^n X_i.$ Moreover, we assume that 
\begin{equation*}
\mathbb{E} X_i=0, \ \operatorname{Cov}(W)=\Sigma.
\end{equation*}
For a standard $d$-dimensional Gaussian random vector $Z$, denote 
\begin{equation*}
\mathtt{d}_c(\mathcal{L}(W), \mathcal{L}(\Sigma^{1/2}Z)):=\sup_{A \in \mathcal{A}}\left| \mathbb{P}(W \in A)-\mathbb{P}(\Sigma^{1/2}Z \in A) \right|,
\end{equation*}
where $\mathcal{A}$ denotes the collection of all the convex sets in $\mathbb{R}^d.$  Suppose that $W$ can be decomposed as follows
\begin{itemize}
\item $\forall i \in [n], \exists i \in N_i \subset [n] $ such that $W-X_{N_i}$ is independent of $X_i;$ 
\item $\forall i \in [n], j \in N_i, \exists N_i \subset N_{ij} \subset [n]$ such that   $W-X_{N_{ij}}$ is independent of $\{X_i, X_j\};$
\item $\forall i \in [n], j \in  N_i, k \in N_{ij}, \exists N_{ij} \subset N_{ijk} \subset [n]$ such that $W-X_{N_{ijk}}$ is independent of $\{X_i,X_j, X_k\}.$
\end{itemize}
Suppose further that for each $i \in [n], j \in N_i$ and $k \in N_{ij},$
\begin{equation*}
\|X_i\|_2 \leq \beta, \ |N_i| \leq n_1, \ |N_{ij}| \leq n_2, \ |N_{ijk}| \leq n_3. 
\end{equation*}
Then there exists a universal constant $C>0$ such that 
\begin{equation*}
\mathtt{d}_c(\mathcal{L}(W), \mathcal{L}(\Sigma^{1/2}Z)) \leq C d^{1/4} n \| \Sigma^{-1/2} \|^3  \beta^3 n_1 \left( n_2+\frac{n_3}{d} \right). 
\end{equation*}
\end{lemma}
\begin{proof}
See Theorem 2.1 and Remark 2.2 of \cite{MR3571252}.
\end{proof}

In the following two lemmas, we consider that $x_i=G_i(\mathcal{F}_i),$ where $G_i(\cdot)$ is some measurable function and $\mathcal{F}_i=(\cdots, \eta_{i-1}, \eta_i)$ and $\eta_i$ are i.i.d. random variables. Suppose that $\mathbb{E} x_i=0$ and $\max_i \mathbb{E} |x_i|^q<\infty$ for some $q>1.$ For any integer $k>0,$ denote $\theta_{k,q}=\max_{1 \leq i \leq n}\| G_i(\mathcal{F}_i)-G_i(\mathcal{F}_{i,i-k}) \|_q,$ where $\mathcal{F}_{i,i-k}=(\cdots, \eta_{i-k-1}, \eta'_{i-k}, \eta_{i-k+1}, \eta_i)$ and $\{\eta_i'\}$ are i.i.d. copies of $\{\eta_i\}.$ Let $\Theta_{k,q}=\sum_{i=k}^{\infty} \theta_{i,q}$ and $\Lambda_{k,q}=\sum_{i=0}^k \theta_{i,q},$ where we use the convention that $\theta_{i,q}=0, i<0.$ 

\begin{lemma}[Concentration inequalities for locally stationary time series]\label{lem_concentration} Let $S_n=\sum_{i=1}^n x_i$ and $q'=\min(2,q).$ Then: \\
(1). We have that for some constant $C>0$ 
\begin{equation*}
\|S_n\|_q^{q'}  \leq C \sum_{i=-n}^{\infty} (\Lambda_{i+n}-\Lambda_{i,q})^{q'}. 
\end{equation*}
Moreover, we have that
\begin{equation*}
\| \max_{1 \leq i \leq n} |S_i| \|_q \leq C n^{1/{q'}} \Theta_{0,q}. 
\end{equation*}
(2). Suppose $x_i=G(i/n, \mathcal{F}_i)$ and $\Theta_{k,q}=\OO(k^{-\gamma}), \gamma>0,$ then we have that
\begin{equation*}
\sum_{i=1}^n \left|\mathbb{E} x_i^2-\sigma\left(\frac{i}{n}\right)\right|=\OO\left(n^{1-\frac{\gamma}{2+\gamma}}\right), 
\end{equation*}
where $\sigma(\cdot)$ is the long run covariance matrix defined as 
\begin{equation*}
\sigma(t)=\sum_{k=-\infty}^{\infty} \operatorname{Cov}\left( G(t, \mathcal{F}_0), G(t, \mathcal{F}_k) \right). 
\end{equation*}
(3). For some constant $C>0,$ we have that 
\begin{equation*}
|\operatorname{Cov}(x_i, x_j)| \leq  C \theta_{|i-j|,q}.
\end{equation*}
\end{lemma}
\begin{proof}
The first part can be found in Theorem 1 of \cite{WUAOP}; also see Lemma 6 of \cite{MR3174655}; the second part of the proof follows directly from Corollary 2 of \cite{MR2827528}; see the last equation in the end of the proof of Corollary 2 therein; the third part can be found in Lemma 6 of \cite{MR3161462} or Lemma 2.6 of \cite{DZ}. 
\end{proof}


\begin{lemma}[$m$-dependent approximation]\label{lem_mdependent} Let $S_n'=\sum_{i=1}^n x_i'$, where $x_i'=\mathbb{E}(x_i| \mathcal{F}_\fm(i)), \mathcal{F}_\fm(i)=\sigma(\eta_{i-\fm}, \cdots, \eta_i)$ is the sigma-algebra generated by  $(\eta_{i-\fm}, \cdots, \eta_i).$ Here $\fm \geq 0.$ Define $R_n=S_n-S_n'$ and $R_n^*=\max_{1 \leq i \leq n} |R_i|.$  Then for some constant $C>0,$ we have
\begin{equation*}
\| R_n \|_q^{q'} \leq C n \Theta_{\fm,q}^{q'}, 
\end{equation*}
and
\begin{equation*}
\| R_n^* \|_q^{q'} \leq C 
\begin{cases}
n \Theta_{\fm,q}^2, & q>2;\\
n (\log n)^q   \Theta_{\fm,q}^2, & 1 <q \leq 2. 
\end{cases}
\end{equation*}
\end{lemma}
\begin{proof}
See Lemma A.1 \cite{MR2485027}. 
\end{proof}
