The next lemma provides a deterministic control for the Riemann summation. 
\begin{lemma}\label{lem_intergralappoximation}
Suppose that $f$ is twice differentiable and $f^{''}$ is bounded and almost everywhere continuous on a compact set $[a,b].$ Let $\Delta: a=s_0 \leq s_1 \leq \cdots \leq s_{n-1} \leq s_n=b$ and $s_{i-1} \leq \xi_i \leq s_i.$ Denote the Riemann sum as
\begin{equation*}
\mathcal{R} \equiv \mathcal{R}(f; \Delta, \xi_i):=\sum_{i=1}^n (s_i-s_{i-1}) f(\xi_i).
\end{equation*}
Then we have that for $s_i=a+i(b-a)/n$
\begin{equation*}
\int_a^b f(x) \dd x =\mathcal{R}+\OO(n^{-2}). 
\end{equation*}
\end{lemma}
\begin{proof}
See Theorem 1.1 of \cite{TASAKI2009477}. 
\end{proof}

Then we collect some elementary probability inequalities. 
\begin{lemma}\label{lem_collectionprobineq}
(1). If $\mathbb{E}|X|^k<\infty,$ then for $0<j<k,$ $\mathbb{E}|X|^j<\infty$ and
\begin{equation*}
\mathbb{E}|X|^j \leq (\mathbb{E}|X|^k)^{j/k}. 
\end{equation*}
(2). (Holder's inequality) For $p,q \in [1, \infty)$ with $1/p+1/q=1,$
\begin{equation*}
\mathbb{E}|XY| \leq \| X\|_p \| Y\|_q. 
\end{equation*}
(3). (Chebyshev’s inequality) If $g(x)$ is a  monotonically increasing nonnegative function for the nonnegative reals, then we have that 
\begin{equation*}
\mathbb{P}(|X|>a) \leq \frac{E(g(|X|))}{g(a)}. 
\end{equation*}
(4). (Bernstein’s concentration inequality) Let $\{x_i\}$ be i.i.d. standard Gaussian random variables. Then for every $0<t<1,$ we have that
\begin{equation*}
\mathbb{P}\left(\left|\frac{1}{n} \sum_{k=1}^n x_k^2-1 \right| \geq t \right) \leq 2 e^{-nt^2/8}. 
\end{equation*}
{(5). (Probability control for Gaussian random vector on convex set) Let $A$ be a convex set on $\mathbb{R}^p$ and $\mathbf{z} \in \mathbb{R}^p$ be a Gaussian random vector. For some $\epsilon>0,$ denote the set
\begin{equation*}
A^\epsilon:=\{x \in \mathbb{R}^p: \operatorname{dist}(x, A) \leq \epsilon\},
\end{equation*}
where $\operatorname{dist}(x, A) :=\inf_{v \in A}|x-v|.$ Let $\mathcal{A}$ be the collection of all the convex sets on $\mathbb{R}^p.$ We have that 
\begin{equation*}
\sup_{A \in \mathcal{A}} \mathbb{P}(\mathbf{z} \in A^\epsilon \backslash A) \leq 4 p^{1/4} \epsilon.
\end{equation*} 
}
\end{lemma}
\begin{proof}
(1) follows from Exercise 1.6.11 of \cite{probbook}; (2) is Theorem 1.6.3 of \cite{probbook}; (3) follows from Theorem 1.6.4 of \cite{probbook}; (4) is in Example 2.11 of \cite{MR3967104}; (5) in in equation (4.10) of \cite{FangRollin2015}.   
\end{proof}

The following lemma provides a deterministic control  for the norm of a symmetric matrix. 
\begin{lemma}[Gershgorin circle theorem]\label{lem_circle}
 Let  $A=(a_{ij})$ be a complex $ n\times n$ matrix. For  $1 \leq i \leq n,$ let  $R_{i}=\sum _{{j\neq {i}}}\left|a_{{ij}}\right| $ be the sum of the absolute values of the non-diagonal entries in the  $i$-th row. Let  $ D(a_{ii},R_{i})\subseteq \mathbb {C} $ be a closed disc centered at $a_{ii}$ with radius  $R_{i}$. Such a disc is called a \emph{Gershgorin disc.} The every eigenvalue of $ A=(a_{ij})$ lies within at least one of the Gershgorin discs  $D(a_{ii},R_{i})$, where $R_i=\sum_{j\ne i}|a_{ij}|$.
\end{lemma}
\begin{proof}
See Theorem 7.2.1 of \cite{MR3024913}. 
\end{proof}
Finally, we collect some approximation formulas for the tail probabilities of the maxima of a two-dimensional Gaussian random field in the setting of simutaneous confidence bands. Assuming that 
$Y_i=f(x_i)+\epsilon_i, \ 1 \leq i \leq n, \ x_i \in \mathbb{R}^2$ and $\epsilon_i$ are i.i.d. $\mathcal{N}(0, \sigma^2)$ random variables. Let $\widehat{f}(x)$ be an unbiased estimator of $f(x)$ such that
\begin{equation*}
\widehat{f}(x)=l(x)^\top Y, \ l(x)=(l_1(x), \cdots, l_n(x))^\top, \ Y=(Y_1, \cdots, Y_n)^\top. 
\end{equation*}  
For some constant $\mathsf{c}_{\alpha}>0,$ the simultaneous coverage probability of the confidence bands is 
\begin{equation*}
1-\alpha=\mathbb{P}\left(\left|f(x)-\widehat{f}(x) \right| \leq \mathsf{c}_{\alpha} \sqrt{\operatorname{Var}(\widehat{f}(x))}, \ x \in \mathcal{X} \right). 
\end{equation*} 
Moreover, according to equation (1.4) of \cite{MR1311978}, we have that
\begin{equation}\label{eq_alphatheortrep}
\alpha=\p \left( \sup_{x \in \mathcal{X}} \left| l(x)^\top \epsilon /\sqrt{\operatorname{Var}(\widehat{f}(x))} \right| \geq \mathsf{c}_{\alpha} \sigma \right). 
\end{equation}
\begin{lemma}\label{lem_volumeoftube} Suppose $\mathcal{X}$ is a rectangle in $\mathbb{R}^2.$ Assume the manifold $\mathcal{M}:=\left\{l(x)/\sqrt{\operatorname{Var}(\widehat{f}(x))}: x \in \mathcal{X} \right\}$ is $C^3$ with a positive radius. Let $\kappa_0$ be the area of $\mathcal{M}$ and $\zeta_0$ be the length of the boundary of $\mathcal{M},$ then  (\ref{eq_expansionformula}) holds true. 
\end{lemma}
\begin{proof}
The proof follows from Proposition 2 of \cite{MR1311978} by replacing $\|l(x) \|$ with $\sqrt{\operatorname{Var}(\widehat{f}(x))}.$ 
\end{proof}

