          \tau_{33}=\tau_{\infty}(0)(1+kt)\sin\theta+\frac{1}{\sqrt{p_1^2-4p_2}}\left[\frac{E_{\alpha}\left(-\lambda_1t^{\alpha}\right)}{\lambda_1}-\frac{E_{\alpha}\left(-\lambda_2t^{\alpha}\right)}{\lambda_2}\right]\cr\hspace{9mm}\left\{{(\tau_{33})}_0-{\tau_{\infty}}(0)\sin\theta\right\}+2V\Psi_4H(t_1)\Big[q_1+\frac{q_1p_2-p_1q_2}{p_2\sqrt{p_1^2-4p_2}}\cr\hspace{9mm}\left\{\frac{E_{\alpha}(-\lambda_1t_1^{\alpha})}{-\lambda_1}+\frac{E_{\alpha}(-\lambda_2t_1^{\alpha})}{\lambda_2}\right\}-\frac{q_2}{p_2\sqrt{p_1^2-4p_2}}\left\{\frac{E_{\alpha}(-\lambda_1t_1^{\alpha})}{\lambda_1^2}-\frac{E_{\alpha}(-\lambda_2t_1^{\alpha})}{\lambda_2^2}\right\}\Big] 
