\title {Modeling the g-factors, hyperfine interaction and optical properties of semiconductor QDs: the atomistic and eight-band $\kp$ approaches}

    \author{Krzysztof Gawarecki\,\orcidlink{0000-0001-7400-2197}}
    \email{Krzysztof.Gawarecki@pwr.edu.pl}
