\title{Heterogeneous model for superdiffusive movement of dense-core vesicles in {\it C. elegans}}



\author[1,2]{Anna Gavrilova}
\author[2]{Nickolay Korabel}
\author[1]{Victoria J. Allan}
\author[2,*]{Sergei Fedotov}
\affil[1]{School of Biological Sciences, Faculty of Biology, Medicine and Health, University of Manchester, The Michael Smith Building, Rumford St, Manchester, UK, M13 9PT. }
