\title{Ultracategories via Kan extensions of relative monads}
\author{Umberto Tarantino}
\author{Joshua Wrigley}

\date{}

\keywords{
	Relative 2-monad, ultracategory, ultracompletion.
}

\thanks{\emph{2020 MSC}: Primary: 18N15; secondary: 18C15, 18C20, 03G30, 03C20. \\ The research is supported by the Agence Nationale de la Recherche (ANR), project ANR-23-CE48-0012-01.}

