	\section{Relative monads and their algebras}\label{sec:prelims}

	We begin by reviewing the relevant notions from the theory of relative monads and their algebras, both for the convenience of the reader and so as to fix notations.

	\subsection{2-categories}
	We will assume basic knowledge of 2-category theory.  By \emph{2-category}, \emph{2-functor}, \emph{2-monad} etc., we mean the strictest 2-categorical notion, e.g.\ a 2-functor preserves identity and composition on the nose.  In particular, by a \emph{2-fully faithful} 2-functor $J \colon \Bcat\to \Acat$ we mean a 2-functor inducing {isomorphisms} $\Hom {\Bcat} {b}{b'} \iso \Hom{\Acat}{Jb}{Jb'}$ between hom-categories, rather than equivalences.  We write $\CAT$ for the 2-category of (large) categories, with $[C,D]$ denoting the category of functors $C \to D$.  We refer the reader to, e.g., \cite{2dimensionalcategories} for more details. For a category $C$, we will systematically abuse notation by writing $c\in C$ and $f \colon c\to c' \in C$ in place of $c \in \operatorname{Ob} (C)$ and $f \colon c \to c' \in \operatorname{Arr}(C)$ respectively.

	\subsection{Relative 2-monads}Recall from \cite{manes,marmolejo-wood} that a monad on a category $C$ can be equivalently described as an \emph{extension system} $\braket{T,\eta,(-)^\ast}$, that is:
	\begin{enumerate}
		\item for each $c \in C$, an object $T c \in C$ and a \emph{unit arrow} $\eta_c \colon c \to T c \in C$,
		\item for each pair $d,c \in C$, an \emph{extension function} $(-)^\ast \colon \Hom C d {Tc}  \to \Hom C {Td} {Tc}$, 
	\end{enumerate}
	satisfying equational axioms (see Definition \ref{def:relative-2-monad} below).	In particular, we recover the usual description in terms of an endofunctor $T \colon C \to C$ by letting $T f \coloneqq ( \eta_{c'} \circ f )^*$ for an arrow $f \colon c \to c' \in C$.

	In \cite{ACU-relative}, this definition is extended to that of a \emph{relative monad}, which allows for an underlying functor between different categories. The \emph{relative pseudomonads} of \cite{pseudomonads-fiore} are then a further 2-dimensional generalisation, which we here recall in the particular case which will be used in this paper: namely, that of a \emph{relative 2-monad} in the sense of \cite{arkor-relative-monads} -- i.e.\ where the root pseudofunctor is a 2-functor and where all structure isomorphisms are taken to be the identity.

	\begin{definition}\label{def:relative-2-monad}
		Let $J \colon \Bcat \to \Acat$ be a 2-functor between 2-categories, which we will refer to as the \emph{root}.  A \emph{$J$-relative 2-monad} $\braket{T,\eta,(-)^\ast}$ is the datum of:
		\begin{enumerate}
			\item for each $b \in \Bcat$, an object $Tb \in \Acat$ and a \emph{unit 1-cell} $\eta_b \colon Jb \to Tb \in \Acat$;
			\item for each pair $a,b \in \Bcat$, an \emph{extension functor} $(-)^\ast \colon \Hom \Acat {Ja} {Tb} \to \Hom\Acat {Ta}{Tb}$,
		\end{enumerate}
		satisfying:
		\begin{enumerate}
			\item[(a)] $\eta_b^* = \id_{ T b }$ for each object $b\in \Bcat$;
			\item[(b)] $f^* \circ \eta_c = f $ for each 1-cell $ f \colon Jc \to Tb \in \Acat$;
			\item[(c)] $(f^*\circ g)^* = f^*\circ g^* $ for each pair of 1-cells $ f \colon  Jc \to Tb, g \colon J d \to T c\in \Acat$.
		\end{enumerate}

		Under this definition, $T$ can be extended to a 2-functor $\Bcat\to \Acat$, where the action on an arrow $f \colon b \to b' \in \Bcat$ is given by $(\eta_{b'} \circ Jf)^* \colon Tb \to Tb'$, while $\eta$ and $(-)^*$ become 2-natural transformations $J \implies T$ and $\Hom{\Acat} {J-} {T-} \implies \Hom{\Acat} {T-} {T-}$ respectively (cf.\ \cite[Proposition 4.7]{pseudomonads-fiore}).
	\end{definition}

	\begin{example}\label{ex:relative_over_identity}
		Relative 2-monads over the identity 2-functor $\id \colon \Acat\to\Acat$ coincide with 2-monads on $\Acat$ in the usual sense (cf.\ \cite[Remarks 3.4, 3.5]{arkor-saville-slattery}).
	\end{example}
	\begin{example}\label{ex:Jff-and-monad-yields-relative}
		For a 2-monad $\braket{T,\eta,(-)^\ast}$ on $\Bcat$ and a 2-fully faithful 2-functor $J \colon \Bcat \to \Acat$, the 2-functor $J T \colon \Bcat\to \Acat$ carries the structure of a $J$-relative 2-monad where:
		\begin{enumerate}
			\item for $b \in \Bcat$, the unit is given by $J \eta_b \colon J b \to J T b$ ;
			\item for $b,c\in \Bcat$, the extension functor is given by 
			\[\begin{tikzcd}
				{\Hom{\Acat}{Jc}{J T b}} \iso {\Hom{\Bcat}{c}{T b}} & {\Hom{\Bcat}{Tc}{Tb}} \iso {\Hom{\Bcat}{JTc}{JTb}}
				\arrow["{(-)^*}", from=1-1, to=1-2]
			\end{tikzcd}\]
			which we still denote as $(-)^*$, so that for a 1-cell $f \colon c \to Tb$ in $\Bcat$ we can unambiguously write $J f^*$ for $(Jf)^* = J(f^*)$.
		\end{enumerate}
		We omit the routine verification that these data satisfy Definition \ref{def:relative-2-monad}.
	\end{example}

	\subsection{Algebras for a relative 2-monad}
	Relative 2-monads admit notions of algebras which extend the usual notion of algebra for a (2-)monad. The 2-dimensional setting, in particular, allows us to distinguish between \emph{lax}, \emph{colax}, \emph{pseudo} and \emph{strict} algebras depending on the 2-cells involved in the definitions, and similarly for their morphisms. We recall here the definitions that we will use in this paper, namely those regarding \emph{colax algebras}; for a more extensive treatment, we refer the reader to \cite{arkor-saville-slattery}.

	The construction of the 2-category of colax algebras given in Definition \ref{def:colax-algebra} below is not concocted in a vacuum.  It is intended to capture a 2-dimensional generalisation of the universal property of the category of algebras for a relative monad amongst all resolutions \cite[Theorem 2.12]{ACU-relative}, itself a generalisation of the universal property of the category of Eilenberg-Moore algebras for a monad (see \cite[Theorem 2.2]{eilenberg-moore}). However, the necessary literature regarding `colax-resolutions' of relative 2-monads is not yet extant, the closest parallel being given for pseudo-resolutions in \cite[\S 6]{arkor-saville-slattery}.  We hope that the example of weak ultracategories (Definition \ref{def:ultracategory}) serves as the catalyst for further research generalising \cite{ACU-relative,arkor-saville-slattery} to the colax setting -- see also Example \ref{ex:free_algebras} and \cite[Remark 3.4]{arkor-saville-slattery}.


	\begin{definition}\label{def:colax-algebra}
		Let $J \colon  \Bcat\to \Acat$ be a 2-functor and let $\braket{T,\eta,(-)^\ast}$ be a $J$-relative 2-monad, which we abbreviate to $T$.  

		A \emph{colax algebra} for $T$ is a tuple $\braket{A,(-)^A, \Gamma,\Delta}$ consisting of:
		\begin{enumerate}
			\item an object $A \in \Acat$;
			\item for each $b\in \Bcat$, a functor $(-)^A \colon \Hom{\Acat}{Jb}{A} \to \Hom{\Acat}{Tb}{A}$, called the \emph{extension operator};
			\item a family of 2-cells $ \Gamma_{h} \colon \kl h A \circ \eta_b \implies h$ for each $h \colon Jb \to A \in \Acat$, natural in $h$;
			\item a family of 2-cells $\Delta_{h,k} \colon \kl h A \circ k^\ast \implies (\kl h A \circ k)^A $ for each $ h \colon J b \to A, k \colon Jc \to Tb \in \Acat $, natural in $h$ and $k$,
		\end{enumerate}
		satisfying the commutativity equations
		\[(a) \begin{tikzcd}[sep = large]
			{\kl h A \eta_b^*} & {\kl {(\kl h A \eta_b)} A} \\
			& {\kl h A}
			\arrow["{{\Delta_{h,\eta_b}}}", from=1-1, to=1-2]
			\arrow[equals, from=1-1, to=2-2]
			\arrow["{{\kl {(\Gamma_h)}A}}", from=1-2, to=2-2]
		\end{tikzcd} \qquad (b) \begin{tikzcd}[sep = large]
			{\kl h A k^* \eta_c} & {\kl { ( \kl h A k ) } A \eta_c} \\
			& {\kl h A k}
			\arrow["{{\Delta_{h,k}*\eta_c}}", from=1-1, to=1-2]
			\arrow[equals, from=1-1, to=2-2]
			\arrow["{{\Gamma_{\kl h A k}}}", from=1-2, to=2-2]
		\end{tikzcd}\]
		\[ (c) \quad \begin{tikzcd}[sep = large]
			{\kl h A (k^* l)^*} & {\kl h A k^* l^*} & {\kl {(\kl h A k)} A l^*} \\
			{\kl {(\kl h A k^*l)} A} && {\kl{( \kl{( \kl h A k)}A l)}A}
			\arrow[equals, from=1-1, to=1-2]
			\arrow["{{\Delta_{h,k^*l}}}"', from=1-1, to=2-1]
			\arrow["{{\Delta_{h,k}*l^*}}", from=1-2, to=1-3]
			\arrow["{{\Delta_{\kl h A k, l}}}", from=1-3, to=2-3]
			\arrow["{{\kl{(\Delta_{h,k}*l)}A}}"', from=2-1, to=2-3]
		\end{tikzcd}\]
		for every $h \colon J b \to A, k \colon J c \to T b, l \colon Jd \to T c \in \Acat$.  We say that $A$ is \emph{strict} if each 2-cell $\Gamma_h$ and each 2-cell $\Delta_{h,k}$ is the identity.

		A \emph{colax morphism} $\braket{U, \upsilon} \colon {\braket{A,(-)^A, \Gamma, \Delta} \to\braket{A',(-)^{A'}, \Gamma', \Delta'}}$ of colax algebras for $T$ consists of:
		\begin{enumerate}
			\item a 1-cell $U \colon A \to A' \in \Acat$;
			\item a family of $2$-cells $\upsilon_h \colon  U\kl h A \implies \kl {(Uh)} {A'}$ for each $h \colon Jb \to A \in \Acat$, natural in $h$,
		\end{enumerate}
		satisfying the commutativity equations
		\[(a)\begin{tikzcd}[sep = large]
			{U \kl h A \eta_b} & {\kl{(Uh)} {A'} \eta_b} \\
			& Uh
			\arrow["{\upsilon_h*\eta_b}", from=1-1, to=1-2]
			\arrow["{U*\Gamma_h}"', from=1-1, to=2-2]
			\arrow["{\Gamma'_{Uh}}", from=1-2, to=2-2]
		\end{tikzcd} \quad  (b)\begin{tikzcd}[row sep = large]
			{U \kl h A k^*} && {\kl{(Uh)}{A'} k^*} \\
			{U\kl{(\kl h A k)}{A}} & {\kl{(U\kl h A k)}{A'}} & {\kl{ (\kl{(Uh)}{A'} k) }{A'}}
			\arrow["{\upsilon_h*k^*}", from=1-1, to=1-3]
			\arrow["{U*\Delta_{h,k}}"', from=1-1, to=2-1]
			\arrow["{\Delta'_{Uh,k}}", from=1-3, to=2-3]
			\arrow["{\upsilon_{\kl h A k}}"', from=2-1, to=2-2]
			\arrow["{\kl{(\upsilon_h*k)}{A'}}"', from=2-2, to=2-3]
		\end{tikzcd}\] 
		for every $h \colon  J b \to A, k \colon J c \to T b \in \Acat$. A \emph{lax morphism} is defined analogously, reversing the direction of each 2-cell $\upsilon_h$. In particular, a (co)lax morphism $\braket{U,\upsilon}$ is a \emph{pseudomorphism} if each $\upsilon_h$ is invertible, and it is a \emph{strict morphism} if each $\upsilon_h$ is the identity. 

		Let $\braket{U, \upsilon}, \braket{U', \upsilon'} \colon {\braket{A,(-)^A, \Gamma, \Delta} \to\braket{A',(-)^{A'}, \Gamma', \Delta'}}$ be colax morphisms of colax algebras for $T$. A \emph{transformation} $\braket{ U, \upsilon}\implies \braket{U', \upsilon'}$ is a 2-cell $\alpha \colon U \implies U'$ such that, for each $h \colon J b \to A \in \Acat$, the square
		\[\begin{tikzcd}
			{U \kl h A } & {U' \kl h A} \\
			{\kl{(Uh)}{A'}} & {\kl{(U'h)}{A'}}
			\arrow["{\alpha*\kl h A }", from=1-1, to=1-2]
			\arrow["{\upsilon_h}"', from=1-1, to=2-1]
			\arrow["{\upsilon'_h}", from=1-2, to=2-2]
			\arrow["{\kl{(\alpha*h)}{A'}}"', from=2-1, to=2-2]
		\end{tikzcd}\]
		commutes. Transformations between lax morphisms are defined analogously.
	\end{definition}

	\begin{proposition}[\protect{\cite[\S 3.9-11]{arkor-saville-slattery}}]
		Colax algebras, their morphisms and transformations form 2-categories:
		\begin{enumerate}
			\item $\CoLaxAlg_{co}^J(T)$, with colax morphisms;
			\item $\CoLaxAlg_{lax}^J(T)$, with lax morphisms;
			\item $\CoLaxAlg^J_{ps}(T)$, with pseudomorphisms;
			\item $\CoLaxAlg_{str}^J(T)$, with strict morphisms.
		\end{enumerate} 
	\end{proposition}

	% \begin{remark}
		%     We obtain 2-categories of algebras, rather than bicategories, since $\Bcat$ is a 2-category (cf.\ \cite[Remark 3.11]{arkor-saville-slattery}).
	% \end{remark}

	\begin{notation}\label{nota:omit_morphisms}
		For $\star \in \set{ co, lax, ps, str}$, we will write $\CoLaxAlg^J_\star(T)$ to refer to any of the above 2-categories.
	\end{notation}

	\begin{example}\label{ex:free_algebras}
		Let $J \colon  \Bcat\to \Acat$ be a 2-functor and let $\braket{T,\eta,(-)^\ast}$ be a $J$-relative 2-monad. For each object $b \in \Bcat$, the object $Tb\in \Acat$ admits a (strict) algebra structure determined by the extension functors $(-)^* \colon \Hom\Acat{Ja}{Tb} \to \Hom\Acat{Ta}{Tb}$. The assignment $b \mapsto \braket{Tb,(-)^\ast,\id,\id}$ extends to a 2-functor $T' \colon \Bcat \to \CoLaxAlg^J_\star(T)$ which acts as $T$ on the underlying objects, 1-cells and 2-cells of $\Bcat$.  That is to say, post-composing $T'$ with the evident forgetful 2-functor $F \colon \CoLaxAlg^J_\star(T) \to \Acat$, that sends a colax algebra $\braket{A,(-)^A,\Gamma,\Delta}$ to $A$, returns the 2-functor $T$.

		Moreover, the 2-functor $T'$ yields a \emph{$J$-relative colax 2-adjunction}
		\[\begin{tikzcd}
			& {\CoLaxAlg_{co}^J(T)} \\
			\Bcat && {\Acat\ .}
			\arrow[""{name=0, anchor=center, inner sep=0}, "F", from=1-2, to=2-3]
			\arrow[""{name=1, anchor=center, inner sep=0}, "{T'}", from=2-1, to=1-2]
			\arrow["J"', from=2-1, to=2-3]
			\arrow["\dashv"{anchor=center}, draw=none, from=1, to=0]
		\end{tikzcd}\]
		By this we mean that, for each $b \in \Bcat$ and each colax algebra $\braket{A,(-)^A,\Gamma,\Delta}$ for $T$, there is a suitably natural adjunction
		\[\begin{tikzcd}
			{\Acat(Jb,A)} && \CoLaxAlg_{co}^J(T)\big(\braket{Tb,(-)^\ast,\id,\id},\braket{A,(-)^A,\Gamma,\Delta}\big)
			\arrow[""{name=0, anchor=center, inner sep=0}, "{(-)^A}"', shift right=2, from=1-1, to=1-3]
			\arrow[""{name=1, anchor=center, inner sep=0}, "{F(-) \circ \eta_b}"', shift right=2, from=1-3, to=1-1]
			\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
		\end{tikzcd}.\]
		The counit of the adjunction, at a 1-cell $h \colon Jb \to A$, is given by $\Gamma_h \colon h^A \circ \eta_b \Rightarrow h$, while the unit, at a  colax morphism $\braket{U,\upsilon} \colon \braket{Tb,(-)^\ast,\id,\id} \to \braket{A,(-)^A,\Gamma,\Delta}$, is the transformation defined by the 2-cell
		\[
		\begin{tikzcd}
			{U = U\circ \eta^*_b} & {(U\circ \eta_b)^A \ .}
			\arrow["{{\upsilon_{\eta_b}}}", from=1-1, to=1-2]
		\end{tikzcd}
		\]
		In this sense, $\CoLaxAlg_{co}^J(T)$ is a \emph{colax-resolution} for the relative 2-monad $\braket{T,\eta,(-)^*}$.
	\end{example}

	\begin{example}\label{ex:Jff-and-monad-colax-algebras-embed}
		Let $T$ be a 2-monad on $\Bcat$ and $J \colon \Bcat \to \Acat$ a 2-fully faithful 2-functor, so that $JT$ is a $J$-relative 2-monad as in Example \ref{ex:Jff-and-monad-yields-relative}. Then, by the 2-fully faithfulness of $J$, we have evident 2-fully faithful embeddings $\CoLaxAlg^{\id}_\star ( T )\hookrightarrow \CoLaxAlg^J_\star ( J T )$ whose images are spanned by those algebras having their carrier object in the essential image of $J$.
	\end{example}



