					\arrow["{c_j}"{description}, from=1-3, to=2-2]
					\arrow["{c_j}", from=1-3, to=2-3]
					\arrow["g"', from=2-2, to=3-2]
					\arrow["{\beta_j}", Rightarrow, from=2-3, to=2-2]
					\arrow["h", curve={height=-6pt}, from=2-3, to=3-2]
					\arrow["{\lambda_m}"', shift left=5, shorten >=5pt, Rightarrow, from=0, to=1]
				\end{tikzcd}
				\qquad \begin{tikzcd}[column sep=small]
					Fi && Fj \\
					\ell & \ell \\
					& {\ell'}
					\arrow[""{name=0, anchor=center, inner sep=0}, "Fm", from=1-1, to=1-3]
					\arrow["{c_i}"', from=1-1, to=2-1]
					\arrow[""{name=1, anchor=center, inner sep=0}, "{c_i}"{description}, from=1-1, to=2-2]
					\arrow["{c_j}", from=1-3, to=2-2]
					\arrow["g"', curve={height=6pt}, from=2-1, to=3-2]
