				coincide for each $m \colon i \to j \in I$, then there exists a unique 2-cell $\beta \colon h \Rightarrow g$ such that $\beta_i = \beta \ast c_i$.
			\end{enumerate}
		\end{enumerate}
	\end{definition}

	\begin{remark}\label{rem:iso between oplax colimits}
		As with ordinary colimits, note that if $k \in \Acat$ is (the vertex of) an oplax cocone for a diagram $F \colon I \to \Acat$ for which $\ell_0,\ell_1 \in \Acat$ are both (vertices of) oplax colimits, so that in particular there exists a canonical isomorphism $f \colon \ell_0 \to \ell_1$, then the uniquely determined 1-cells $g_0 \colon \ell_0 \to k$, $g_1 \colon \ell_1 \to k$ satisfy $g_1\circ f = g_0$. 
	\end{remark}
	\begin{example}\label{ex:oplax-colimit-of-itself}
		Let $I$ be a category, and let $R \colon \op{I} \to \CAT$ be the functor that sends each object of $I$ to the terminal category $1_\CAT$ and each morphism of $I$ to the identity on $1_\CAT$.  In this case, the oplax colimit is given by $I$ itself, with the corresponding 1-cell of the cocone $c_i \colon 1_\CAT \to I$ at an object $i \in \op{I}$ given by the functor that picks out the object $i \in I$, while the 2-cell $\lambda_m \colon c_j \circ \id_{1_\CAT} \Rightarrow c_i$ at an arrow $m \colon i \to j \in \op{I}$ is the natural transformation whose (only) component is $m \colon j \to i \in I$. 
	\end{example}

	\subsection{Skew-monoidal structure}\label{ssec:structure-on-Bcat-to-CAT}

	We define the \emph{$J$-relative composition} operation
	\[ \circ^J \colon {\mathbf{Oplax}}\funcat {\Bcat}\CAT \times {\mathbf{Oplax}}\funcat {\Bcat}\CAT \to {\mathbf{Oplax}}\funcat {\Bcat}\CAT \]
	by letting, on objects, $F \circ^J G \coloneqq \tilde F \circ G$, which clearly extends to a functor making use of Remark \ref{rem:tilde-is-functorial}. This operation can be endowed with the following structural maps.
	\begin{enumerate}
		\item We define a \emph{left unit}, a family of oplax transformations $\mathfrak{l}_F \colon J \circ^J F \implies F$ for each 2-functor $F \colon \Bcat\to\CAT$, natural in $F$, as follows.

		First, consider the strict transformation $\id_{J} \colon J \implies J$. By the universal property of $\tilde J$, it uniquely factors through $\zeta^J \colon J \implies \tilde J \circ J$ via a strict transformation $\bar{\mathfrak{l}} \colon \tilde J \implies \id_{\CAT}$, from which we define $\mathfrak{l}_F \coloneq \bar{\mathfrak{l}} * F$. Explicitly, this means that for each object $c \in \Bcat$, the component $(\mathfrak{l}_F)_c \colon \tilde J(C) \to C$ is the functor:
		\[ \begin{tikzcd}
			{(b, h \colon J b \to Fc, x \in J b)} & {h(x)} \\
			{(b', h'\colon J b' \to Fc, x' \in J b')} & {h'(x')}
			\arrow[maps to, from=1-1, to=1-2]
			\arrow["{(f,\alpha,g)}"', from=1-1, to=2-1]
			\arrow["{\alpha_{x'}\circ h(g)}", from=1-2, to=2-2]
			\arrow[maps to, from=2-1, to=2-2]
		\end{tikzcd} \]

		\item We define a \emph{right unit}, a family of oplax transformations $\mathfrak{r}_F \colon F \implies F \circ^J J$ for each 2-functor $F \colon \Bcat\to\CAT$, natural in $F$, by considering for each $b\in \Bcat$ the functor
		\[ (\mathfrak{r}_F)_b \coloneqq (\iota_{F, J b})_b (\id_{Jb}) \colon F b \to \tilde F ( J b ) \]
		explicitly defined as
		\[ \begin{tikzcd}
			\nu & {(b , \id_{Jb}\colon J b \to J b, \nu \in F b)} \\
			{\nu'} & {(b , \id_{Jb}\colon J b \to J b, \nu' \in F b)}
			\arrow[maps to, from=1-1, to=1-2]
			\arrow["\phi"', from=1-1, to=2-1]
			\arrow["{(\id_b, \id, \phi)}", from=1-2, to=2-2]
			\arrow[maps to, from=2-1, to=2-2]
		\end{tikzcd}\]
		and, for each 1-cell $f \colon b' \to b\in\Bcat$, the natural transformation $(\mathfrak{r}_F)_f \colon (\mathfrak{r}_F)_b \circ Ff \implies \tilde F J f \circ (\mathfrak{r}_F)_{b'}$ defined at an object $\nu'\in F b'$ by the arrow
		\[ ((\mathfrak{r}_F)_f)_{\nu'} \coloneqq ( f, \id, \id) \colon (b, \id_{Jb}, Ff(\nu')) \to (b', J f, \nu')\]
		in $\tilde F (Jb)$.


		\item We define an \emph{associator}, a family of oplax transformations $\mathfrak{a}_{F,G,H} \colon (F \circ^J G)\circ^J H \implies F \circ^J ( G \circ^J H )$ for each triple of 2-functors $F,G,H \colon \Bcat\to\CAT$, natural in $F$, $G$ and $H$, as follows.

		First, consider the oplax transformation $\tilde F * \zeta^G \colon \tilde F \circ G \implies \tilde F \circ \tilde G \circ J$. By the universal property of $\tilde{ \tilde F \circ G }$, it uniquely factors through $\zeta^{\tilde F \circ G} \colon \tilde F \circ G \implies \tilde {( \tilde F \circ G)} \circ J$ via a strict transformation $\bar{\mathfrak{a}}_{F,G} \colon \tilde { \tilde F \circ G }  \implies \tilde F \circ \tilde G$, from which we define $\mathfrak{a}_{F,G,H} \coloneqq \bar{\mathfrak{a}}_{F,G} * H$. Explicitly, this means that for each object $c \in \Bcat$, the component $({\mathfrak{a}}_{F,G,H})_c \colon \tilde { \tilde F \circ G } (H c) \to \tilde F(\tilde G(H c))$ is the functor defined:
		\begin{enumerate}
			\item on objects, by mapping $(b, h \colon J b \to H c, ( d , k \colon J d \to Gb, \nu \in Fd))$ to the triple $(d , K \colon J d \to \tilde G (Hc), \nu \in F d)$ where $K$ is the functor
			\[ \begin{tikzcd}[column sep = 30pt]
				Jd & Gb & {\tilde G(Jb)} & {\tilde G (H c)}
				\arrow["k", from=1-1, to=1-2]
				\arrow["{\zeta^G_b}", from=1-2, to=1-3]
				\arrow["{\tilde G(h)}", from=1-3, to=1-4]
			\end{tikzcd} \]
			i.e.\ such that $K(x) \coloneqq ( b , h \colon J b \to Hc, k(x) \in G b)$;

			\item on arrows, by mapping $(f,\alpha, ( g, \beta, \psi ) ) \colon ( b , h , ( d, k , \nu)) \to (b', h', (d', k', \nu') )$ to the triple of $g \colon d'\to d\in \Bcat$, the natural transformation $J g \circ K \implies K'$ given by the composite
			\[ \begin{tikzcd}[column sep = 1.75 em, row sep = 1em]
				Jd && Gb && {\tilde G (Jb)} \\
				&&&&&& {\tilde G (H c)} \\
				{Jd'} && {Gb'} && {\tilde G ( J b')}
				\arrow["k", from=1-1, to=1-3]
				\arrow["\beta", shorten <=11pt, shorten >=11pt, Rightarrow, from=1-1, to=3-3]
				\arrow["{\zeta^G_b}", from=1-3, to=1-5]
				\arrow["{\zeta^G_f}", shorten <=11pt, shorten >=11pt, Rightarrow, from=1-3, to=3-5]
				\arrow["{\tilde G (h)}", curve={height=-12pt}, from=1-5, to=2-7]
				\arrow["Jg", from=3-1, to=1-1]
				\arrow["{k'}"', from=3-1, to=3-3]
				\arrow["Gf"{description}, from=3-3, to=1-3]
				\arrow["{\zeta^G_{b'}}"', from=3-3, to=3-5]
				\arrow["{\tilde G (Jf)}"{description}, from=3-5, to=1-5]
				\arrow[""{name=0, anchor=center, inner sep=0}, "{\tilde G (h')}"', curve={height=12pt}, from=3-5, to=2-7]
				\arrow["{\tilde G ( \alpha)}", shorten <=9pt, shorten >=9pt, Rightarrow, from=1-5, to=0]
			\end{tikzcd} \]
			and $\psi \colon \nu \to Fg(\nu') \in F d$.

		\end{enumerate}

		\todo{check naturality in arguments}
	\end{enumerate}

	\begin{remark}
		Note how the transformations $\mathfrak{l}_F$ and $\mathfrak{a}_{F,G,H}$ are actually strict rather than merely oplax.
	\end{remark}

	\begin{proposition}
		The category $\mathbf{Oplax}\funcat{\Bcat}{\CAT}$, together with the composition $\circ^J$ and the families $\mathfrak{l},\mathfrak{r}, \mathfrak{a}$, is a skew-monoidal category.
		\begin{proof}
			The proof follows exactly as in \cite[Theorem 3.1]{ACU-relative}.
		\end{proof}
	\end{proposition}

	\begin{remark}\label{rem:comparison-with-ACU}
		In \cite{ACU-relative}, the hypotheses of ``well-behavedness'' on the root functor ensures that the families $\mathfrak{l},\mathfrak{r}, \mathfrak{a}$ are invertible, i.e.\ that the skew-monoidal structure is monoidal. If our assumptions on the root 2-functor were to imply the same, our motivating example of weak ultracategories would be left out. For instance, it is easy to see that $\bar{\mathfrak{l}}$ is not invertible for $J \colon \Set \hookrightarrow \CAT$ being the inclusion of sets as discrete categories: in other words, the left oplax Kan extension of $J$ along itself is not (isomorphic to) the identity. In a way, our assumptions on $J$ are intended to do without these inverses.
	\end{remark}

	In light of the previous remark, we now use our assumptions on $\Bcat$ and on the root $J \colon \Bcat \to \CAT$ to define additional structure for the $J$-relative composition.
	\begin{enumerate}
		\item[(4)]    We define a strict transformation $\mathfrak{d} \colon \id_{\CAT} \implies \tilde J$ by setting $\mathfrak{d}_C \colon C \to \tilde J (C)$, for each category $C$, to be the functor:
		\[ \begin{tikzcd}
			c & {(1_{\Bcat}, c \colon 1_{\CAT} \to C, \bullet)} \\
			{c'} & {(1_{\Bcat}, c ' \colon 1_{\CAT} \to C, \bullet)}
			\arrow[maps to, from=1-1, to=1-2]
			\arrow["f"', from=1-1, to=2-1]
			\arrow["{(\id, f, \id)}", from=1-2, to=2-2]
			\arrow[maps to, from=2-1, to=2-2]
		\end{tikzcd}
		\] 
		where by assumption $J 1_{\Bcat} = 1_{\CAT}$ is the terminal category.     Clearly, $\bar{\mathfrak {l}} \circ \mathfrak{d} = \id$.

		\item[(5)] For each pair of 2-functors $F, G \colon \Bcat \to \CAT$ and for each category $C$, let
		\[ (\mathfrak{s}_{F,G})_C \colon \tilde F ( \tilde G (C)) \to \tilde {\tilde F \circ G}(C) \]
		be the functor defined as follows.\todo{maybe it needs to be explained more in detail? i wrote less than what we had in the first draft}

		Consider an object  $( b, h \colon J b \to \tilde G C, \nu \in Fb) \in \tilde F ( \tilde G C)$. For each object $x \in Jb$ and each arrow $g \colon x \to y\in J b$, we will use the following notation to denote their image under $h$:
		\[
		{h(x) \coloneqq ( Rx , a_x \colon J Rx \to C , \nu_x \in G R x )} , \quad {{h(g) \coloneqq \left( Rg , \gamma_g , \psi_g \right)}}.
		\]
		Note that this yields a functor $R \coloneqq \pi\circ \op h\colon \op{(Jb)} \to \Bcat$. Then, we define the action of $(\mathfrak{s}_{F,G})_C$ on $(b, h, \nu)$ as the tuple $(\ell, a \colon J \ell \to C, (b, Q \colon Jb \to G \ell, \nu \in Fb ) )$ where:
		\begin{enumerate}
			\item $\ell \in \Bcat$ is the oplax colimit of the diagram $R$, witnessed by families
			\[ \set{ c_x \colon Rx \to \ell | x \in J b } \mbox{ and } \set{ \lambda_g \colon c_x \circ R g \implies c_y | g \colon x \to y \in J b },\]
			\item $a \colon J \ell \to C$ is the functor uniquely induced by seeing $C$ as an oplax cocone on the diagram $J \circ R$ through the families
			\[ \set{ a_x \colon J Rx \to C | x \in J b } \mbox{ and } \set{ \gamma_g \colon a_x \circ J R g \implies a_y | g \colon x \to y \in J b },\]
			\item and $Q \colon J b \to G\ell$ is the functor extending $x \mapsto Gc_x(\nu_x)$ by setting $Qg$, for an arrow $g \colon x \to y \in J b$, to be the composite:
			\[ \begin{tikzcd}
