				\arrow["{Gc_x(\psi_x)}", from=1-1, to=1-3]
				\arrow["{G(\lambda_g)_{\nu_y}}", from=1-3, to=1-5]
			\end{tikzcd} \]
		\end{enumerate}

		Now consider an arrow $(f, \alpha,\phi) \colon ( b, h , \nu ) \to ( b', h' , \nu' ) \in \tilde F (\tilde G C)$. Building on the previous notation, we will denote the component of $\alpha \colon h\circ J f \implies h'$ at $x \in Jb'$ as the triple
		\[
		\left( w_x , \delta_x, \chi_x\right) \colon { h ( Jf(x))  =( RJf(x) , a_{Jf(x)} , \nu_{Jf(x)} )} \to {( R'x , a_x'  , \nu_x' ) = h'(x)}.
		\]
		Then, we define the action of $(\mathfrak{s}_{F,G})_C$ on $( f , \alpha, \phi )$ as the tuple $\left( \bar f , \bar \alpha , ( f, \theta, \phi ) \right)$ where:
