				QJf(x) = Gc_{Jf(x)}(\nu_{Jf(x)}) \ar{rr}{G c_{Jf(x)}(\chi_x)}  && {G c_{Jf(x)} ( G w_x (\nu_x')) } = {G \bar f ( G c_x'(\nu_x'))} = { G\bar f (Q' x).}
