	\begin{proposition}\label{prop:structure-on-Bcat-to-CAT}
		For each 2-functor $F \colon \Bcat\to\CAT$, the following diagrams of strict transformations commute up to a canonical invertible modification:
		\[(a) \quad \begin{tikzcd}
			{\tilde J\circ \tilde F } && {\tilde { \tilde J \circ F }} \\
			& {\tilde F }
			\arrow["{\mathfrak{s}_{J,F}}", from=1-1, to=1-3]
			\arrow["{\mathfrak{d}*\tilde F }", from=2-2, to=1-1]
			\arrow["{\tilde{\mathfrak{d}*F}}"', from=2-2, to=1-3]
		\end{tikzcd} \qquad (b)\quad  \begin{tikzcd}
			{\tilde F \circ \tilde J } && {\tilde {\tilde F \circ J }} \\
			& {\tilde F }
			\arrow["{\mathfrak{s}_{F,J}}", from=1-1, to=1-3]
			\arrow["{\tilde F * \mathfrak{d}}", from=2-2, to=1-1]
			\arrow["{\tilde {\mathfrak{r}_F}}"', from=2-2, to=1-3]
		\end{tikzcd}\]
		\[ (c)\quad  \begin{tikzcd}
			{\tilde F ^3} &&&& {\tilde F \circ \widetilde{\widetilde F \circ F}} \\
			{\widetilde {\widetilde F \circ F} \circ \tilde F} && {\widetilde {\widetilde {\widetilde F \circ F} \circ F}} && {\widetilde{ \tilde F ^2 \circ F}}
			\arrow["{\tilde F *\mathfrak{s}_{F,F}}", from=1-1, to=1-5]
			\arrow["{\mathfrak{s}_{F,F}* \tilde F }"', from=1-1, to=2-1]
			\arrow["{\mathfrak{s}_{F, \tilde F \circ F}}", from=1-5, to=2-5]
			\arrow["{\mathfrak{s}_{\tilde F \circ F, F}}"', from=2-1, to=2-3]
			\arrow["{\widetilde{\bar{{{\mathfrak{a}}}}_{F,F}* F}}"', from=2-3, to=2-5]
		\end{tikzcd}\]
		\begin{proof}
			We consider each diagram in turn.

			\begin{enumerate}
				\item[(a)] Let $C$ be a category and let $(b, h\colon J b \to C, \nu \in F b) \in \tilde F C$, which $(\tilde {\mathfrak{d} * F})_C$ maps to the triple $(b, h , \mathfrak{d}_{F b}(\nu))$ i.e.\ $(b , h , (1_{\Bcat}, \nu \colon 1_{\CAT}\to F b , \bullet))$. On the other side, $\mathfrak{d}_{\tilde F C}$ maps $(b,h,\nu)$ to the tuple $(1_{\Bcat}, (b,h , \nu) \colon 1_{\CAT} \to \tilde F C, \bullet)$, which is then sent by $(\mathfrak{s}_{J,F})_C$ to a tuple $( \ell, a \colon J \ell \to C , ( 1_{\Bcat}, Q \colon 1_{\CAT} \to F \ell , \bullet ) )$, where by definition $\ell \in \Bcat$ is the oplax colimit of the diagram $R \colon \op{(1_{\CAT})} \to \Bcat$ that picks out the object $b\in \Bcat$. Evidently, $b$ itself is an oplax colimit of $R$, so there is a canonically induced invertible 1-cell $u\colon b \to \ell \in \Bcat$ yielding the invertible arrow:
				\[ ( u , \id, \id ) \colon ( \ell , a, (1_{\Bcat}, Q, \bullet)) \to ( b , h , ( 1_{\Bcat}, \nu , \bullet))\] 
				in $(\tilde{\tilde J \circ F})(C)$, which is the component of an invertible modification $\mathfrak{s}_{J,F} \circ (\mathfrak{d}*\tilde F) \Rrightarrow \tilde{\mathfrak{d}*F}$. \todo{check}

				\item[(b)]  Let $C$ be a category and let $(b, h\colon J b \to C, \nu \in F b) \in \tilde F C$, which $(\tilde {\mathfrak{r}_F})_C$ maps to the triple $(b, h , (\mathfrak{r}_F)_b(\nu))$ i.e.\ $(b , h , ( b, \id_{Jb} , \nu ))$. On the other side, $\tilde F (\mathfrak{d}_C)$ maps $(b,h, \nu)$ to the triple $(b , \mathfrak{d}_C \circ h , \nu)$, which $(\mathfrak{s}_{F,J})_C$ then maps to a tuple $(\ell, a \colon J \ell \to C , ( b, Q \colon J b \to J \ell , \nu ))$ where by definition $\ell \in \Bcat$ is the oplax colimit of the constant diagram $R \colon \op{(Jb)} \to \Bcat$ of value $1_{\Bcat}$. By Example \ref{ex:oplax-colimit-of-itself} and 2-fully-faithfulness of $J$, $b\in\Bcat$ is also an oplax colimit of $R$, so there is a canonically induced invertible 1-cell $v\colon b \to \ell \in \Bcat$ yielding the invertible arrow:
				\[ ( v , \id, \id ) \colon ( \ell , a, (b, Q, \nu)) \to ( b , h , ( b, \id_{Jb} , \nu))\] 
				in $(\tilde{\tilde F \circ J})(C)$, which is the component of an invertible modification $\mathfrak{s}_{F,J} \circ (\tilde F * \mathfrak{d}) \Rrightarrow \tilde{\mathfrak{r}_F}$. \todo{check}

				\item[(c)]Let $C$ be a category and let $(b , h \colon J b \to \tilde F^2 C, \nu \in F b) \in \tilde F ^ 3 C$. By definition, $\tilde F ((\mathfrak{s}_{F,F})_C)$ maps it to the triple $( b , (\mathfrak{s}_{F,F})_C\circ h , \nu )$, which $(\mathfrak{s}_{F, \tilde F \circ F})_C$ then maps to a tuple $(\bar\ell, \bar a \colon J \bar \ell \to C, ( b , \bar Q \colon J b \to \tilde F (F \bar \ell ), \nu))$ where
				\[ \bar \ell \coloneqq \opcolim_{x \in \op{(Jb)}} \left( \opcolim_{y \in \op{(JRx)}} \left( \pi a_x(y)\right) \right) \]
				Since oplax colimits commute with oplax colimits (cf.\ \cite{bonart2024}), there is a canonical isomorphism: 
				\[ \opcolim_{x \in \op{(Jb)}} \left( \opcolim_{y \in \op{(J R x)}} \left( \pi a_x (y) \right) \right) \iso \opcolim_{(x,y) \in \op{ \left(\opcolim_{x' \in \op{(J b)} } (J R x') \right) }} \left( \pi a_x (y) \right) \]
				where, in the right-hand side, $(x,y)$ denotes the image of $y \in J R x$ along the coprojection functor $J R x \to \opcolim_{x' \in \op{(J b)} } (J R x' )$. 
				Chasing $(b, h ,\nu)$ along the other side of the diagram, instead, we have that:
				\begin{enumerate}
					\item[(1)] $(\mathfrak{s}_{F,F})_{\tilde F C}$ maps it to the tuple 
					\[(\ell, a \colon J \ell \to \tilde F C, ( b , Q \colon J b \to F \ell , \nu))\] 
					where $\ell \in \Bcat$ is the oplax colimit of the diagram $R \colon \op{(Jb)}\to \Bcat$ -- with coprojections $\set{ c_x \colon Rx \to \ell | x \in J b}$; 

					\item[(2)] $(\mathfrak{s}_{\tilde F \circ F , F})_C$ maps (1) to the tuple 
					\[ ( \ell' , a ' \colon J \ell ' \to C, ( \ell , Q ' \colon J \ell \to F \ell' , ( b , Q \colon J b \to F \ell , \nu ))) \] 
					where $\ell' \in \Bcat$ is the oplax colimit of the diagram $\pi \circ \op{a} \colon \op{(J\ell)} \to \Bcat$;

					\item[(3)] $(\tilde{\bar{{\mathfrak{a}}}_{F,F} * F})_C$ maps (2) to the tuple
					\[ ( \ell' , a ' \colon J \ell ' \to C, (\bar{{\mathfrak{a}}}_{F,F})_{F\ell'} ( \ell , Q ' \colon J \ell \to F \ell' , ( b , Q \colon J b \to F \ell , \nu ))) \] 
					i.e.\ $( \ell' , a ' \colon J \ell ' \to C, ( b , K \colon J b \to \tilde F (F\ell'), \nu ))$, where $K \coloneqq \tilde F ( Q' ) \circ \zeta_{\ell'} \circ Q$. 
				\end{enumerate}
				Note therefore that, by our assumptions, $J \ell$ is the oplax colimit of $J \circ R$, with coprojections $\set{ J c_x \colon J R x \to J \ell | x \in J b }$. Therefore, recalling also that $a \circ J c_x = a_x$ by definition of $a \colon J \ell \to \tilde F C$, we have that:
				\begin{align*}
					\opcolim_{(x,y) \in \op{ \left(\opcolim_{x' \in \op{(J b)} } (J R x') \right) }} \left( \pi a_x (y) \right) & = \opcolim_{z = J c_x (y)  \in \op{ ( J \ell ) }} \left( \pi a_x (y) \right)\\
					&= \opcolim_{z = J c_x (y)  \in \op{ ( J \ell ) }} \left( \pi a (Jc_x (y)) \right)\\
					&= \opcolim_{z \in \op{ ( J \ell ) }} \left( \pi a (z) \right) = \ell' ,
				\end{align*}
				and hence there is a canonically induced invertible 1-cell $w \colon \ell'\to \bar \ell \in \Bcat$ yielding the invertible arrow:
				\[ ( w, \id, \id ) \colon (\bar\ell, \bar a , ( b , \bar Q , \nu)) \to ( \ell' , a' , ( b, K, \nu)) .\]
				in $(\tilde{\tilde F^2\circ F})(C)$, which is the component of an invertible modification \[\mathfrak{s}_{F,\tilde F \circ F} \circ (\tilde F * \mathfrak{s}_{F,F}) \Rrightarrow \tilde{\bar{{\mathfrak{a}}}_{F,F} * F} \circ \mathfrak{s}_{\tilde F \circ F , F } \circ (\mathfrak{s}_{F,F}*\tilde F).\]%\todo{check}
			\end{enumerate}
		\end{proof}
	\end{proposition}

	\begin{remark}
		Given 2-functors $F, G , H \colon \Bcat \to \CAT$, the same proof of (c) can be generalised to show that a similar diagram going from $\tilde F \circ \tilde G \circ \tilde H$ to $\tilde{\tilde F \circ \tilde G \circ H}$ also commutes up to a canonical invertible modification, but we will not need this in the rest of the paper.
	\end{remark}


	\subsection{Pseudomonad structure}We are finally ready to endow $\tilde T$ with the structure of a pseudomonad on $\CAT$, that is, a unit $\eta^\sharp$ and a multiplication $\mu^\sharp$ together with appropriate coherent invertible modifications expressing unitality and associativity. Following \cite{ACU-relative}, we first define a `$J$-relative multiplication' for $T$ -- i.e.\ a strict transformation $\mu \colon T \circ^J T \implies T$ -- by considering, for each $b\in B$, the functor $\mu_b \colon \tilde T (T b) \to T b$ uniquely corresponding to the strict transformation $(-)^* \colon \funcat{J-}{ Tb} \implies \funcat{T-}{Tb}$ by the universal property of the left oplax Kan extension. Explicitly, $\mu_b$ acts as follows:
	\[ \begin{tikzcd}
		{(d, k \colon J d \to Tb, \nu \in T d)} & {k^*(\nu)} \\
		{(d', k' \colon J d' \to Tb', \nu' \in T d')} & {k'^*(\nu').}
		\arrow[maps to, from=1-1, to=1-2]
		\arrow["{(f,\alpha,\phi)}"', from=1-1, to=2-1]
		\arrow["{\alpha^*_{\nu'}\circ k^*(\phi)}", from=1-2, to=2-2]
		\arrow[maps to, from=2-1, to=2-2]
	\end{tikzcd} \]

	\begin{proposition}
		The following diagrams of oplax transformations commute:
		\[ (a)\quad \begin{tikzcd}[cramped]
			{\tilde J \circ T } && {\tilde T \circ T} \\
			\\
			T && T
			\arrow["{\tilde \eta*T}", from=1-1, to=1-3]
			\arrow["\mu", from=1-3, to=3-3]
			\arrow["{\mathfrak{d}*T}", from=3-1, to=1-1]
			\arrow[equals, from=3-1, to=3-3]
		\end{tikzcd} \qquad (b)\quad \begin{tikzcd}[cramped]
			{\tilde T \circ J} && {\tilde T \circ T} \\
			\\
			T && T
			\arrow["{\tilde T * \eta}", from=1-1, to=1-3]
			\arrow["\mu", from=1-3, to=3-3]
			\arrow["{\mathfrak{r}_T}", from=3-1, to=1-1]
			\arrow[equals, from=3-1, to=3-3]
		\end{tikzcd}  \]
		\[ (c) \quad \begin{tikzcd}
			& {\tilde T \circ \tilde T \circ T} & {\tilde T \circ T } \\
			{\tilde{\tilde T \circ T }\circ T} \\
			{\tilde T \circ T} && T
			\arrow["{{\tilde T *\mu}}", from=1-2, to=1-3]
			\arrow["\mu", from=1-3, to=3-3]
			\arrow["{{\bar{\mathfrak{a}}_{T,T}*T}}", from=2-1, to=1-2]
			\arrow["{{\tilde \mu * T }}"', from=2-1, to=3-1]
			\arrow["\mu"', from=3-1, to=3-3]
		\end{tikzcd} \] 
		\begin{proof}
			The proof carries over from that of \cite[Theorem 3.4]{ACU-relative} -- for diagram (a), also making use of the fact that $\mathfrak{l}_T \circ (\mathfrak{d}* T) = \id$. % For diagram (b), the only one where a non-strict transformation appears, it follows by direct inspection that the composite $\mu \circ (\tilde T * \eta) \circ \mathfrak{r}_T$ is strict.
		\end{proof}
	\end{proposition}

	\begin{definition}
		We endow $\tilde T \colon \CAT \to \CAT$ with the following pseudomonad structure.
		\begin{enumerate}
			\item First, we define a unit $\eta^\sharp \colon \id_{\CAT} \implies \tilde T$ as the strict transformation:
			\[ \begin{tikzcd}
				{\id_{\CAT}} & {\tilde J} & {\tilde T}
				\arrow["\mathfrak{d}", from=1-1, to=1-2]
				\arrow["{\tilde \eta}", from=1-2, to=1-3]
			\end{tikzcd} \]

			\item Second, we define a multiplication $\mu^\sharp \colon \tilde T \circ \tilde T \implies \tilde T$ as the strict transformation:
			\[ \begin{tikzcd}
				{\tilde T \circ\tilde T} & {\tilde{\tilde T \circ T}} & {\tilde T}
				\arrow["{\mathfrak{s}_{T,T}}", from=1-1, to=1-2]
				\arrow["{\tilde\mu}", from=1-2, to=1-3]
			\end{tikzcd} \]

			\item We define a \emph{left unit} $\mathfrak{p} \colon \mu^\sharp \circ (\eta^\sharp * \tilde T) \Rrightarrow \id$ as the invertible modification obtained by pasting:
			\[\begin{tikzcd}[cramped, column sep = small, row sep = small]
				&&& {\tilde T \circ \tilde T} \\
				& {\tilde J \circ \tilde T} &&&& {\tilde {\tilde T \circ T}} \\
