				\arrow["\iso"', shorten <=3pt, shorten >=6pt, Rightarrow, from=2-2, to=0]
			\end{tikzcd}\]

			\item We define a \emph{right unit} $\mathfrak{q} \colon \id \Rrightarrow \mu^\sharp \circ ( \tilde T * \eta^\sharp)$ as the invertible modification obtained by pasting:
			\[ \begin{tikzcd}[cramped, column sep = small, row sep = small]
				&&& {\tilde T \circ \tilde T } \\
				& {\tilde T \circ \tilde J } &&&& {\tilde {\tilde T \circ T}} \\
				&&& {\tilde {\tilde T \circ J}} \\
				{\tilde T } &&&&&& {\tilde T }
				\arrow["{{\mathfrak{s}_{T,T}}}", from=1-4, to=2-6]
				\arrow["{{\tilde T * \tilde \eta}}", from=2-2, to=1-4]
				\arrow["{{\mathfrak{s}_{T,J}}}", from=2-2, to=3-4]
				\arrow["{{\tilde \mu}}", from=2-6, to=4-7]
				\arrow["{{\tilde{\tilde T *\eta}}}"', from=3-4, to=2-6]
				\arrow["{{\tilde T * \mathfrak{d}}}", from=4-1, to=2-2]
				\arrow[""{name=0, anchor=center, inner sep=0}, "{{\tilde{\mathfrak{r}_T}}}"{description}, from=4-1, to=3-4]
