			\[ 
			\begin{tikzcd}
				{\tilde T \circ \tilde T\circ \tilde T} && {\tilde T\circ \tilde{\tilde T \circ T }} &&& {\tilde T\circ \tilde T} \\
				{\tilde{\tilde T \circ T}\circ \tilde T } &&& {\tilde{\tilde T \circ \tilde T \circ T}} \\
