				\arrow["{\tilde T*\mathfrak{s}_{T,T}}", from=1-1, to=1-3]
				\arrow["{\mathfrak{s}_{T,T}*\tilde T}"', from=1-1, to=2-1]
				\arrow["{\tilde T*\tilde \mu}", from=1-3, to=1-6]
				\arrow["{\mathfrak{s}_{T, \tilde T\circ T}}", from=1-3, to=2-4]
				\arrow["{\mathfrak{s}_{T,T}}", from=1-6, to=3-6]
				\arrow[""{name=0, anchor=center, inner sep=0}, "{\mathfrak{s}_{\tilde T \circ T , T }}"', from=2-1, to=3-3]
				\arrow["{\tilde \mu*\tilde T}"', from=2-1, to=4-1]
				\arrow["{\tilde{\tilde T * \mu}}", from=2-4, to=3-6]
				\arrow["{\tilde{\bar{\mathfrak{a}}_{T,T}*T}}"', from=3-3, to=2-4]
