				\arrow["{\tilde\mu}", from=3-6, to=4-6]
				\arrow["{\mathfrak{s}_{T,T}}"', from=4-1, to=4-4]
				\arrow["{\tilde\mu}"', from=4-4, to=4-6]
				\arrow["\iso", shorten <=8pt, shorten >=8pt, Rightarrow, from=1-3, to=0]
			\end{tikzcd}
			\]
		\end{enumerate}
	\end{definition}

	\begin{theorem}\label{thm:tilde-t-is-a-pseudomonad}
		The triple $\braket{\tilde T , \eta^\sharp, \mu^\sharp}$, together with the modifications $\mathfrak{p}$, $\mathfrak{q}$, and $\mathfrak{x}$, is a pseudomonad on $\CAT$.
		\begin{proof}
			The two coherence conditions spelled out in \cite{lack-pseudomonads} are satisfied since all arrows describing them are uniquely induced by the universal properties of oplax colimits.
		\end{proof}
	\end{theorem}

	\section{Preservation of algebras}\label{sec:algebras}
	In the previous section, we constructed the pseudomonad $\braket{\tilde T,\eta^\sharp,\mu^\sharp}$ obtained by unrelativising a $J$-relative 2-monad $\braket{T , \eta, (-)^*}$. This section is dedicated to proving that their colax algebras coincide. Before formally stating the theorem, we here recall the definitions regarding colax algebras for a pseudomonad on $\CAT$. For practical purposes, we restrict ourselves to the context of the pseudomonad $\tilde T$: that is, in the equational axioms, we will assume that the underlying pseudofunctor is actually a 2-functor rather than a pseudofunctor, and that the unit and the multiplication are strict transformations rather than pseudonatural transformations. For a more general treatment, we refer the reader to \cite{stepan-thesis}.

	\begin{definition}[\protect{\cite[\S 2]{street74}, \cite[\S 2.4]{stepan-thesis}}]\label{def:colax-algebras-for-pseudomonad}
