			\end{tikzcd}\]
			\item[(b)]the following pastings coincide:
			\[ \begin{tikzcd}[column sep = 14pt, row sep = 20 pt]
				& {\tilde T C} && C \\
				{\tilde T^2 C} && {\tilde T C} && {C',} \\
				& {\tilde T^2 C'} && {\tilde T C'}
				\arrow["\Phi", from=1-2, to=1-4]
