			\arrow["{{\mathfrak{u}}}"', shorten <=15pt, shorten >=15pt, Rightarrow, from=3-1, to=1-3, shift right=3pt]
			\arrow["U"', from=3-1, to=3-3]
			\arrow["{{\tilde T \alpha}}", shorten <=4pt, shorten >=4pt, Rightarrow, from=0, to=1]
		\end{tikzcd} \qquad \begin{tikzcd}
			{\tilde T C} && {\tilde T C'} \\
			\\
			C && {C'}
			\arrow["{{\tilde T U'}}", from=1-1, to=1-3]
			\arrow["\Phi"', from=1-1, to=3-1]
			\arrow["{{\Phi'}}", from=1-3, to=3-3]
			\arrow["{{\mathfrak{u}'}}", shorten <=15pt, shorten >=15pt, Rightarrow, from=3-1, to=1-3, shift left = 3pt]
			\arrow[""{name=0, anchor=center, inner sep=0}, "{{U'}}"{description}, curve={height=-18pt}, from=3-1, to=3-3]
			\arrow[""{name=1, anchor=center, inner sep=0}, "U"', curve={height=18pt}, from=3-1, to=3-3]
			\arrow["\alpha", shorten <=5pt, shorten >=5pt, Rightarrow, from=1, to=0]
		\end{tikzcd} \]
		Transformations between lax morphisms are defined analogously. 

		% the square
		% \[ \begin{tikzcd}[ sep = 24 pt]
			%     {U \circ \Phi} & {U' \circ \Phi} \\
			%     {\Phi'\circ \tilde T U } & {\Phi'\circ \tilde T U '}
			%     \arrow["{\alpha * \Phi}", from=1-1, to=1-2]
			%     \arrow["{\mathfrak{u}}"', from=1-1, to=2-1]
			%     \arrow["{\mathfrak{u}'}", from=1-2, to=2-2]
			%     \arrow["{\Phi'*\tilde T \alpha}"', from=2-1, to=2-2]
			% \end{tikzcd}\] 
		% commutes. 

		Colax algebras, their morphisms and transformations form 2-categories:
		\begin{enumerate}
			\item $\CoLaxAlg_{co}(\tilde T)$, with colax morphisms;
			\item $\CoLaxAlg_{lax}(\tilde T)$, with lax morphisms;
			\item $\CoLaxAlg_{ps}(\tilde T)$, with pseudomorphisms;
			\item $\CoLaxAlg_{str}(\tilde T)$, with strict morphisms.
		\end{enumerate} 
	\end{definition}

	\begin{notation}
		As in Notation \ref{nota:omit_morphisms}, we will write $\CoLaxAlg_\star(\tilde T)$ for $\star \in \set{co , lax, ps, str}$ to refer to any of the above 2-categories.
	\end{notation}

	\begin{remark}
            Analogous to Example \ref{ex:relative_over_identity}, the pseudomonad $\braket{\tilde T, \eta^\sharp, \mu^\sharp}$ can be viewed as a relative pseudomonad over the identity $\id_\CAT$ in the sense of \cite{pseudomonads-fiore}.  Thus, there is another notion for the colax algebras of $\tilde T$ given by generalising Definition \ref{def:colax-algebra} to the relative pseudomonad setting, (see \cite{arkor-saville-slattery} or \cite[\S 4]{marmolejo-wood-pseudomonads}).  The resultant 2-category of colax algebras is, however, bi-equivalent to the 2-category $\CoLaxAlg(\tilde T)$ described above (cfr. \cite[Theorem 5.1]{marmolejo-wood-pseudomonads}).
	\end{remark}

	\begin{theorem}[Unrelativisation preserves colax algebras]\label{thm:algebras_preserved}
		Given a $J$-relative 2-monad $T$ on $\CAT$ satisfying the assumptions of Section \ref{sec:absolution}, for each $\star \in \set{co , lax, ps, str}$ the 2-categories $\CoLaxAlg^J_\star(T)$ and $\CoLaxAlg_\star(\tilde T)$ are isomorphic.
	\end{theorem}

	To prove Theorem \ref{thm:algebras_preserved}, we will make extensive use of the universal property of $\tilde T$ as a left oplax Kan extension. In particular, we will show that the datum of a colax algebra for $\braket{T , \eta, (-)^*}$ on a category $C$ coincides with that of a colax algebra for $\braket{\tilde T,\eta^\sharp,\mu^\sharp}$ on the same category $C$. Indeed -- recalling Example \ref{ex:extension-operators-define-lax-trans} and the discussion before Definition \ref{def:left-oplax-kan-extension} -- the former consists of a lax transformation $\funcat{ J - }{C} \implies \funcat{ T -}{C}$ with extra structure, while the latter consists of a functor $\tilde T C \to C$ with extra structure.  By Proposition \ref{prop:left-oplax-Kan-extension-in-CAT}, such lax transformations and such functors are in bijection, hence Theorem \ref{thm:algebras_preserved} will follow by showing that the rest of the structure is also interdefinable.  We present the construction for colax morphisms, but this is easily adapted.



	\subsection{ \texorpdfstring{From $T$-algebras to $\tilde T$-algebras}{From relative algebras to algebras for the pseudomonad} }To witness the isomorphisms in Theorem \ref{thm:algebras_preserved}, we first build a 2-functor $\Theta \colon \CoLaxAlg_{co}^J(T) \to \CoLaxAlg_{co}(\tilde T)$.

	\subsubsection{On algebras}\label{sssec:rel-to-abs_on-algebras}Let $\braket{ C, (-)^C, \Gamma, \Delta}$ be a colax algebra for the $J$-relative 2-monad $\braket{T, \eta, (-)^*}$. We define a colax algebra 
	\[ \Theta (\braket{ C, (-)^C, \Gamma, \Delta}) \coloneqq \braket{C, \Phi, \mathfrak{i}, \mathfrak{m} }\]
	for the pseudomonad $\braket{\tilde T , \eta^\sharp, \mu^\sharp}$ as follows.

	By Example \ref{ex:extension-operators-define-lax-trans}, recall that the family of extension operators defines a lax transformation $(-)^C \colon \funcat{ J - }{C} \implies \funcat{ T -}{C}$, so we let the structure functor $\Phi \colon \tilde T C \to C$ be the uniquely induced functor by Proposition \ref{prop:left-oplax-Kan-extension-in-CAT}. Explicitly, this means that $\Phi$ is defined
	\begin{enumerate}
		\item on objects by mapping $(b,h \colon J b \to C, \nu)\in\tilde T C$ to $h^C(\nu)$,
		\item and on arrows by mapping $(f,\alpha,\phi) \colon ( b , h , \nu) \to (b', h',\nu') \in \tilde T C$ to the composite
		\[ \begin{tikzcd}[column sep = 18 pt]
			{h^C(\nu)} & {h^CTf(\nu')} && {(h^C\eta_bJf)^C(\nu')} && {(hJf)^C(\nu')} & {h'^C(\nu') . }
			\arrow["{{h^C(\phi)}}", from=1-1, to=1-2]
			\arrow["{{(\Delta_{h, \eta_bJf})_{\nu'}}}", from=1-2, to=1-4]
			\arrow["{{(\Gamma_h*Jf)^C_{\nu'}}}", from=1-4, to=1-6]
			\arrow["{{\alpha^C_{\nu'}}}", from=1-6, to=1-7]
		\end{tikzcd} \]
	\end{enumerate}

	Next we define the counitor $\mathfrak{i} \colon \Phi \circ \eta_C^\sharp \implies \id_C$. First note that $\Phi \circ \eta_C^\sharp \colon C \to C$ is the functor
	\[ \begin{tikzcd}
		c & {c^C(\eta_{1_{\Bcat}}(\bullet))} \\
		{c'} & {c'^C(\eta_{1_{\Bcat}}(\bullet))}
		\arrow[maps to, from=1-1, to=1-2]
		\arrow["f"', from=1-1, to=2-1]
		\arrow["{f^C_{\eta_{1_{\Bcat}}(\bullet)}}", from=1-2, to=2-2]
		\arrow[maps to, from=2-1, to=2-2]
	\end{tikzcd} \]
	where we identify $c,c'\in C$ with functors $J 1_{\Bcat} = 1_{\CAT} \to C$ and hence $f \colon c \to c' \in C$ with a natural transformation $c \implies c'$. Therefore, we define the component of $\mathfrak{i}$ at an object $c \in C$ as the arrow 
	\[ \begin{tikzcd}
		{(\Phi\circ \eta_C^\sharp)(c)  = c^C(\eta_{1_{\Bcat}}(\bullet))} && c
		\arrow["{(\Gamma_c)_\bullet}", from=1-1, to=1-3]
	\end{tikzcd} \]
	in $C$. Naturality of $\mathfrak{i}$ follows immediately by that of the family $\set{ \Gamma }$.

	Finally, we define the coassociator $\mathfrak{m} \colon \Phi \circ \mu^\sharp_C \implies \Phi \circ \tilde T \Phi $. First note that the functor $\Phi \circ \mu^\sharp_C \colon \tilde T ^2 C \to C$ acts:
	\begin{enumerate}
		\item on objects, by mapping $(b, h \colon J b \to \tilde T C, \nu) \in \tilde T^2 C$ to $a^C Q^* (\nu) \in C$, where we let $(\ell, a \colon J \ell \to C, ( b , Q \colon J b \to T \ell, \nu)) \coloneqq \mathfrak{s}_{T,T}(b,h,\nu)$ as in \ref{ssec:structure-on-Bcat-to-CAT}; 
		\item on arrows, by mapping $(f , \alpha , \phi ) \colon ( b ,h , \nu) \to (b', h', \nu') \in \tilde T ^2 C$ to the composite 
		\[ \begin{tikzcd}[column sep = large]
			{a^CQ^*(\nu)} \\
			{a^CT \bar f (Q'^*\nu')} && {(a^C\eta_\ell J \bar f )^C(Q'^*\nu')} && {(a J \bar f )^C(Q'^*\nu')} \\
			&&&& {a'^CQ'^*(\nu') , }
			\arrow["{{a^C(\theta^*_{\nu'}\circ Q^*(\phi))}}", from=1-1, to=2-1]
			\arrow["{{(\Delta_{a, \eta J \bar f }*Q'^*)_{\nu'}}}", from=2-1, to=2-3]
			\arrow["{{((\Gamma_a*J\bar f )^C*Q'^*)_{\nu'}}}", from=2-3, to=2-5]
			\arrow["{{(\bar \alpha ^C*Q'^*)_{\nu'}}}", from=2-5, to=3-5]
		\end{tikzcd} \]
		where again we let $(\bar f , \bar \alpha, ( f, \theta, \phi)) \coloneqq \mathfrak{s}_{T,T} ( f, \alpha, \phi)$ as in \ref{ssec:structure-on-Bcat-to-CAT}.
	\end{enumerate}
	Moreover, note that for each object $(b , h \colon J b \to \tilde T C, \nu) \in \tilde T ^2 C$, the family of arrows
	\[ \begin{tikzcd}[column sep = 18 pt]
		{a^CQ(x) = a^CTc_x(\nu_x)} && {(a^C\eta_{\ell}Jc_x)^C(\nu_x)} && {(aJc_x)^C(\nu_x) = a_x^C(\nu_x)}
		\arrow["{{(\Delta_{a, \eta J c_x})_{\nu_x}}}", from=1-1, to=1-3]
		\arrow["{{(\Gamma_a*Jc_x)^C_{\nu_x}}}", from=1-3, to=1-5]
	\end{tikzcd} \]
	for $x \in Jb$ defines a natural transformation $\tau \colon a^C \circ Q \implies \Phi \circ h$, where as usual we denote $h(x)$ as $(Rx, a_x\colon J R x \to C, \nu_x) $ and hence $\Phi ( h ( x) ) = a_x^C(\nu_x)$. Therefore, we define the component of $\mathfrak{m}$ at $(b,h,\nu)$ as the composite
	\[ \begin{tikzcd}[column sep = 10pt]
		{(\Phi\circ \mu^\sharp_C)(b,h,\nu) = a^CQ^*(\nu)} && {(a^CQ)^C(\nu)} && {(\Phi h )^C(\nu) = (\Phi\circ \tilde T \Phi)(b,h,\nu)}
		\arrow["{{(\Delta_{a,Q})_\nu}}", from=1-1, to=1-3]
		\arrow["{{\tau^C_\nu}}", from=1-3, to=1-5]
	\end{tikzcd} \]
	in $C$. We omit the routine proof of the naturality of $\mathfrak{m}$. The proof of the fact that $\braket{C, \Phi, \mathfrak{i},\mathfrak{m}}$ is a colax algebra for $\tilde T$ is postponed to Lemma \ref{lem:rel-to-abs_is-algebra}.

	\subsubsection{On morphisms}\label{sssec:rel-to-abs_on-morphisms}
	Let $\braket{U, \upsilon}\colon \braket{C,(-)^C, \Gamma, \Delta} \to \braket{C',(-)^{C'}, \Gamma', \Delta'}$ be a colax morphism of colax algebras for $\braket{T, \eta, (-)^*}$. The same underlying functor $U \colon C \to C'$ yields a colax morphism
	\[ \Theta ( \braket{U, \upsilon} ) \coloneqq \braket{U, \mathfrak{u} } \colon \braket{C, \Phi, \mathfrak{i},\mathfrak{m} } \to \braket{C',\Phi', \mathfrak{i}',\mathfrak{m}' }  \]
	of colax algebras for $\braket{\tilde T , \eta^\sharp,\mu^\sharp}$ by taking the natural transformation $\mathfrak{u} \colon U \circ \Phi \implies \Phi' \circ \tilde T U$ defined at an object $(b,h\colon J b \to C,\nu) \in \tilde T C$ by the arrow
	\[ \begin{tikzcd}
		{(U\circ \Phi) ( b, h ,\nu) = U(h^C(\nu))} & {(Uh)^C(\nu) = (\Phi'\circ \tilde T U)(b,h,\nu)}
		\arrow["{{(\upsilon_h)_\nu}}", from=1-1, to=1-2]
	\end{tikzcd} \]
	in $C'$. Naturality of $\mathfrak{u}$ follows immediately by that of the family $\set{ \upsilon }$. A proof of the fact that $\braket{U, \mathfrak{u}}$ is a colax morphism is given in Lemma \ref{lem:rel-to-abs_is-morphism}. With this definition, $\Theta$ is clearly a functor $\CoLaxAlg_{co}^J(T) \to \CoLaxAlg_{co}(\tilde T)$. 

	\subsubsection{On transformations}Let $\braket{U, \upsilon}, \braket{U', \upsilon'}\colon \braket{C,(-)^C, \Gamma, \Delta} \to \braket{C',(-)^{C'}, \Gamma', \Delta}$ be colax morphisms of colax algebras for $\braket{T, \eta, (-)^*}$ and let $\alpha \colon \braket{U, \upsilon} \implies \braket{U', \upsilon'}$ be a transformation. Let us show that $\alpha$ is also a transformation $\braket{U, \mathfrak{u}}\implies \braket{U', \mathfrak{u}'}$, i.e.\ that the diagram of natural transformations
	\[ \begin{tikzcd}[column sep = large]
		{U \circ \Phi} & {U' \circ \Phi} \\
		{\Phi'\circ \tilde T U} & {\Phi'\circ \tilde T U '}
		\arrow["{\alpha * \Phi}", from=1-1, to=1-2]
		\arrow["{\mathfrak{u}}"', from=1-1, to=2-1]
		\arrow["{\mathfrak{u}'}", from=1-2, to=2-2]
		\arrow["{\Phi'*\tilde T \alpha}"', from=2-1, to=2-2]
	\end{tikzcd} \] 
	commutes. Instantiated at an object $(b,h\colon J b \to C, \nu) \in \tilde T C$, this yields the diagram
	\[ \begin{tikzcd}[column sep = large]
		{Uh^C(\nu)} & {U'h^C(\nu)} \\
		{(Uh)^{C'}(\nu)} & {(U'h)^{C'}(\nu)}
		\arrow["{(\alpha*h^C)_\nu}", from=1-1, to=1-2]
		\arrow["{(\upsilon_h)_\nu}"', from=1-1, to=2-1]
		\arrow["{(\upsilon'_h)_\nu}", from=1-2, to=2-2]
		\arrow["{(\alpha*h)^{C'}_\nu}"', from=2-1, to=2-2]
	\end{tikzcd} \] 
	in $C'$, which commutes since $\alpha$ is a transformation $ \braket{U, \upsilon} \implies \braket{U', \upsilon'}$. Therefore, we can extend $\Theta$ to a 2-functor $\CoLaxAlg_{co}^J(T) \to \CoLaxAlg_{co}(\tilde T)$ simply by setting:
	\[ \Theta ( \alpha ) \coloneqq \alpha \colon \braket{U, \mathfrak{u}}\implies \braket{U', \mathfrak{u}'}\]

	\begin{remark}\label{rem:theta_respects_lax_morphisms}
		It is evident how to define $\Theta$ on lax morphisms and their transformations, and moreover that it preserves pseudomorphisms and strict morphisms. Therefore, we have defined a 2-functor $\Theta \colon \CoLaxAlg_\star^J(T) \to \CoLaxAlg_\star(\tilde T)$ for each $\star \in \set{ co, lax, ps, str}$.
	\end{remark}

	\subsection{ \texorpdfstring{From $\tilde T$-algebras to $T$-algebras}{From algebras for the pseudomonad to relative algebras} }We now build a 2-functor $\Sigma \colon \CoLaxAlg_{co}(\tilde T )\to \CoLaxAlg_{co}^J(T)$. Although we will not make use of this intuition, $\Sigma$ can be thought of as being induced by $\zeta \colon T \implies \tilde T \circ S$ acting as a `morphism of relative pseudomonads' where we allow the root 2-functor to change -- a notion which does not yet appear in the literature.

	\subsubsection{On algebras}\label{sssec:abs-to-rel_on-algebras}Let $\braket{C, \Phi, \mathfrak{i}, \mathfrak{m}}$ be a colax algebra for the pseudomonad $\braket{\tilde T , \eta^\sharp, \mu^\sharp}$. We define a colax algebra
	\[ \Sigma ( \braket{C, \Phi, \mathfrak{i}, \mathfrak{m}} ) \coloneqq \braket{C, (-)^C, \Gamma,\Delta} \]
	for the $J$-relative 2-monad $\braket{T,\eta,(-)^*}$ as follows.

	We define the extension operator $(-)^C \colon \funcat{J-}{C} \implies \funcat{T-}{C}$ as the unique lax transformation corresponding to the functor $\Phi \colon \tilde T C \to C$, that is:
	\[ \begin{tikzcd}
		{\funcat{J-}{C}} && {\funcat{T-}{\tilde T C}} && {\funcat{T-}{C} .}
		\arrow["{\iota_{T,C}}", from=1-1, to=1-3]
		\arrow["{\Phi \circ-}", from=1-3, to=1-5]
	\end{tikzcd} \]

	Next we define a natural transformation $\Gamma_h \colon h^C \circ \eta_b \implies h$ for each functor $h \colon J b \to C$. First note that $h^C \circ \eta_b \colon J b \to C$ is the functor
	\[ \begin{tikzcd}
		x & {(b, h \colon J b \to C, \eta_b(x))} \\
		{x'} & {(b, h\colon J b \to C, \eta_b(x')) \ . }
		\arrow[maps to, from=1-1, to=1-2]
		\arrow["g"', from=1-1, to=2-1]
		\arrow["{(\id_b,\id,\eta_b(g))}", from=1-2, to=2-2]
		\arrow[maps to, from=2-1, to=2-2]
	\end{tikzcd} \] 
	Therefore, we define $\Gamma_h$ on an object $x \in Jb$ -- identified with a functor $1_{\CAT} \to Jb$ -- as the composite
	\[\begin{tikzcd}
		{\Phi (b,h\colon J b \to C, \eta_b(x))} && {\Phi(1_{\Bcat},hx \colon 1_{\CAT}\to C, \eta_{1_{\Bcat}}(\bullet))} && {h(x)}
		\arrow["{{\Phi(\dot x, \id, \id)}}", from=1-1, to=1-3]
		\arrow["{\mathfrak{i}_{h(x)}}", from=1-3, to=1-5]
	\end{tikzcd} \] 
	in $C$, where $\dot x \colon 1_{\Bcat} \to b$ is the unique 1-cell in $\Bcat$ such that $J \dot x = x$, by assumption of 2-fully-faithfulness of $J$. We omit the routine proofs of the naturality of each $\Gamma_h$ and of the family $\set{\Gamma}$.

	Finally, we define a natural transformation $\Delta_{h,k}\colon h^C \circ k^* \implies ( h^C \circ k )^C$ for each pair of functors $h\colon J b\to C$ and $k \colon J c \to T b$. First note that $h^C \circ k^*$ and $(h^C\circ k)^C $ are the functors $T c \to C$ respectively given by
	\[ \begin{tikzcd}
		\nu & {\Phi(b, h \colon J b \to C, k^*(\nu))} \\
		{\nu'} & {\Phi(b, h \colon J b \to C , k^*(\nu'))}
		\arrow[maps to, from=1-1, to=1-2]
		\arrow["\phi"', from=1-1, to=2-1]
		\arrow["{\Phi(\id,\id,k^*(\phi))}", from=1-2, to=2-2]
		\arrow[maps to, from=2-1, to=2-2]
	\end{tikzcd} \mbox{ and } \begin{tikzcd}
		\nu & {\Phi(c, h^Ck\colon J c \to C, \nu)} \\
		{\nu'} & {\Phi(c, h^Ck\colon J c \to C, \nu') \ .}
		\arrow[maps to, from=1-1, to=1-2]
		\arrow["\phi"', from=1-1, to=2-1]
		\arrow["{\Phi(\id,\id,\phi)}", from=1-2, to=2-2]
		\arrow[maps to, from=2-1, to=2-2]
	\end{tikzcd}\]
	Therefore, we define $\Delta_{h,k}$ on an object $\nu\in T c$ as the composite:
	\[ \begin{tikzcd}[column sep = small]
		{\Phi(b, h \colon J b \to C, k^*(\nu))} \\
		{\Phi(\ell, a \colon J \ell \to C, Q^*(\nu))} &[-19pt] {=(\Phi\circ \mu^\sharp_C)(c, \iota_b(h)k\colon J c \to \tilde T C, \nu)} \\
		& {(\Phi\circ\tilde T \Phi) (c, \iota_b(h)k\colon J c \to \tilde T C, \nu)} &[-22pt] {=\Phi ( c, h^Ck\colon J c \to C, \nu)}
		\arrow["{\Phi(t, \id,\id)}", from=1-1, to=2-1]
		\arrow["{\mathfrak{m}_{(c,\iota_b(h)k,\nu)}}", from=2-2, to=3-2]
	\end{tikzcd} \] 
	in $C$, where we let $(\ell, a \colon J \ell \to C, (c , Q \colon J c \to T \ell, \nu)) \coloneqq \mathfrak{s}_{T,T} ( c, \iota_b(h)k , \nu)$ as in \ref{ssec:structure-on-Bcat-to-CAT} and use $t \colon \ell \to b \in \Bcat$ to denote the canonical 1-cell induced being $b$ an oplax cocone on the constant diagram $\op{(Jc)}\to\Bcat$ of value $b$, of which $\ell$ is the oplax colimit. We omit the routine proofs of the naturality of each $\Delta_{h,k}$ and of the family $\set{\Delta}$. The proof of the fact that $\braket{C, (-)^C, \Gamma,\Delta}$ is a colax algebra for $T$ is postponed to Lemma \ref{lem:abs-to-rel_is-algebra}.

	\subsubsection{On morphisms}\label{sssec:abs-to-rel_on-morphisms}Let $\braket{U, \mathfrak{u}}\colon \braket{C,\Phi, \mathfrak{i}, \mathfrak{m}} \to \braket{C',\Phi', \mathfrak{i}', \mathfrak{m}'}$ be a colax morphism of colax algebras for $\braket{\tilde T, \eta^\sharp, \mu^\sharp}$. The same underlying functor $U \colon C \to C'$ yields a colax morphism
	\[ \Sigma ( \braket{U, \mathfrak{u}} ) \coloneqq \braket{U, \upsilon } \colon \braket{C, (-)^C, \Gamma, \Delta } \to \braket{C',(-)^{C'}, \Gamma', \Delta'}  \]
	of colax algebras for $\braket{ T , \eta ,(-)^*}$ by taking, for a functor $h \colon J b \to C$, the natural transformation $\upsilon_h \colon U h^C \implies (Uh)^{C'}$ defined at an object $\nu \in T b$ by the arrow
	\[ \begin{tikzcd}[column sep = 20pt]
		{Uh^C(\nu)} &[-27pt] {=(U\circ \Phi)(b,h\colon J b \to C, \nu)} \\
		& {(\Phi \circ \tilde T U )(b, h \colon J b \to C,\nu)} &[-29pt] {=\Phi (b, U h \colon J b \to C',\nu)=(Uh)^{C'}(\nu)}
		\arrow["{{\mathfrak{u}_{(b,h,\nu)}}}", from=1-2, to=2-2]
	\end{tikzcd} \] 
	in $C'$. Naturality of $\upsilon_h$ and of the family $\set{\upsilon}$ follow immediately by that of $\mathfrak{u}$. A proof of the fact that $\braket{U, \upsilon}$ is a colax morphism is given in Lemma \ref{lem:abs-to-rel_is-morphism}. With this definition, $\Sigma$ is clearly a functor $\CoLaxAlg_{co}(\tilde T) \to \CoLaxAlg_{co}^J(T)$. 

	\subsubsection{On transformations}Let $\braket{U, \mathfrak{u}}, \braket{U', \mathfrak{u}'} \colon \braket{C,\Phi, \mathfrak{i}, \mathfrak{m}} \to \braket{C',\Phi', \mathfrak{i}', \mathfrak{m}'}$ be colax morphisms of colax algebras for $\braket{\tilde T , \eta^\sharp, \mu^\sharp}$ and let $\alpha \colon \braket{U, \mathfrak{u}} \implies \braket{U', \mathfrak{u}'}$ be a transformation. Let us show that $\alpha$ is also a transformation $\braket{U, \upsilon}\implies \braket{U', \upsilon'}$, i.e.\ that the diagram of natural transformations
	\[ \begin{tikzcd}[column sep = large]
		{Uh^C} & {U'h^C} \\
		{(Uh)^{C'}} & {(U'h)^{C'}}
		\arrow["{\alpha*h^C}", from=1-1, to=1-2]
		\arrow["{\upsilon_h}"', from=1-1, to=2-1]
		\arrow["{\upsilon'_h}", from=1-2, to=2-2]
		\arrow["{(\alpha*h)^C}"', from=2-1, to=2-2]
	\end{tikzcd} \] 
	commutes for each functor $h \colon J b \to C$. Instantiated at an object $\nu \in T b$, this yields the diagram:
	\[ \begin{tikzcd}[column sep = 60pt]
		{(U\circ\Phi)(b,h,\nu)} & {(U'\circ\Phi)(b,h,\nu)} \\
		{(\Phi\circ\tilde T U)(b,h,\nu)} & {(\Phi\circ\tilde T U')(b,h,\nu)}
		\arrow["{(\alpha*\Phi)_{(b,h,\nu)}}", from=1-1, to=1-2]
		\arrow["{\mathfrak{u}_{(b,h,\nu)}}"', from=1-1, to=2-1]
		\arrow["{\mathfrak{u}'_{(b,h,\nu)}}", from=1-2, to=2-2]
		\arrow["{(\Phi*\tilde T \alpha)_{(b,h,\nu)}}"', from=2-1, to=2-2]
	\end{tikzcd}
	\] 
	which commutes since $\alpha$ is a transformation $ \braket{U, \mathfrak{u}} \implies \braket{U', \mathfrak{u}'}$. Therefore, we can extend $\Sigma$ to a 2-functor $\CoLaxAlg_{co}(\tilde T) \to \CoLaxAlg_{co}^J( T)$ simply by setting:
	\[ \Sigma ( \alpha ) \coloneqq \alpha \colon \braket{U, \upsilon}\implies \braket{U', \upsilon'}\]

	\begin{remark}\label{rem:sigma_respects_lax_morphisms}
		As for $\Theta$, it is evident how to define $\Sigma$ on lax morphisms and their transformations, and moreover that it preserves pseudomorphisms and strict morphisms. Therefore, we have defined a 2-functor $\Sigma \colon  \CoLaxAlg_\star(\tilde T)\to \CoLaxAlg_\star^J(T)$ for each $\star \in \set{ co , lax, ps, str}$
	\end{remark}

	\subsection{There and back again}Finally, we complete the proof of Theorem \ref{thm:algebras_preserved} by showing that $\Theta$ and $\Sigma$ are each other's inverse. First, consider the composite $\Sigma \circ \Theta$.

	\begin{lemma}
		Let $\braket{C, (-)^C, \Gamma,\Delta}$ be a colax algebra for $\braket{T, \eta, (-)^*}$. Then 
		\[ \Sigma\Theta ( \braket{C, (-)^C, \Gamma,\Delta} ) = ( \braket{C, (-)^C, \Gamma,\Delta} ).\] 
		\begin{proof}
			Denote $\Sigma\Theta ( \braket{C, (-)^C, \Gamma,\Delta} )$ as $\braket{C, (-)^{\bar C}, \bar\Gamma,\bar\Delta}$. Clearly $(-)^{\bar C} = (-)^C$ as they are both the unique lax transformation corresponding to the functor $\Phi \colon \tilde T C \to C$ defining $\braket{C , \Phi, \mathfrak{i}, \mathfrak{m}}\coloneqq \Theta (\braket{C, (-)^C, \Gamma,\Delta})$. 

			For a functor $h \colon J b \to C$, the natural transformation $\bar \Gamma_h$ is defined at an object $x\in J b$ as the composite
			\[ \begin{tikzcd}
				{\Phi(b,h, \eta_b(x))} && {\Phi(1_{\Bcat},hx, \eta_{1_{\Bcat}}(\bullet))} && {h(x)}
