			\end{tikzcd} \] 
			which, using the description of $\Phi$ and $\mathfrak{i}$, is explicitly the composite:
			\[ \begin{tikzcd}[cramped, sep = 16pt]
				{h^C(\eta_b  (x) ) = h^CT\dot x(\eta_{1_{\Bcat}}(\bullet))} && {(h^C\eta_b x )^C(\eta_{1_{\Bcat}}(\bullet))} && {(hx)^C(\eta_{1_{\Bcat}}(\bullet))} & {h(x) .}
