				\arrow["{{{{(\Gamma_{hx})_\bullet}}}}", from=1-5, to=1-6]
			\end{tikzcd} \] 
			Note then that the diagram:
			\[ \begin{tikzcd}[sep = 22pt]
				{h^C(\eta_b  (x) )= h^CT\dot x(\eta_{1_{\Bcat}}(\bullet))} && {(h^C\eta_b x )^C(\eta_{1_{\Bcat}}(\bullet))} && {(hx)^C(\eta_{1_{\Bcat}}(\bullet))} \\
				&& {(h^C\eta_b x )(\bullet)} && {hx(\bullet)}
				\arrow["{{{{(\Delta_{h,\eta_b x} * \eta_{1_{\Bcat}})_\bullet}}}}", from=1-1, to=1-3]
