	\begin{corollary}\label{cor:sigmatheta-identity}
		The composite $\Sigma \circ \Theta$ is the identity 2-functor on $\CoLaxAlg_\star^J(T)$.
		\begin{proof}
			It is immediate to see that $\Sigma \circ \Theta$ acts as the identity on morphisms of colax algebras for $\braket{T, \eta, (-)^*}$. As both $\Theta$ and $\Sigma$ act as the identity on transformations,  we conclude that $\Sigma\circ \Theta = \id$ as 2-functors on $\CoLaxAlg_\star^J(T)$.
		\end{proof}
	\end{corollary}

	On the other hand, consider now the composite $\Theta \circ \Sigma$.

	\begin{lemma}
		Let $\braket{C, \Phi, \mathfrak{i}, \mathfrak{m}}$ be a colax algebra for $\braket{\tilde T , \eta^\sharp, \mu^\sharp}$. Then
		\[ \Theta\Sigma \braket{C, \Phi, \mathfrak{i}, \mathfrak{m}} = \braket{C, \Phi, \mathfrak{i}, \mathfrak{m}}.\]
		\begin{proof}
			Denote $\Theta\Sigma \braket{C, \Phi, \mathfrak{i}, \mathfrak{m}}$ as $\braket{C, \bar \Phi, \bar{\mathfrak{i}}, \bar{\mathfrak{m}}}$. Clearly $\bar \Phi = \Phi$ as they are both the unique functor corresponding to the lax transformation $(-)^C \colon \funcat{J-}{C} \implies \funcat{T-}{C}$ defining $\braket{C, (-)^C, \Gamma,\Delta} \coloneqq \Sigma (\braket{C, \Phi, \mathfrak{i},\mathfrak{m}})$. Moreover, it is immediate to see that $\bar{\mathfrak{i}} = \mathfrak{i}$.

			It remains to show that $\bar{\mathfrak{m}} = \mathfrak{m}$. The natural transformation $\bar{\mathfrak{m}}$ is defined at an object $(b, h \colon J b \to \tilde T C, \nu) \in \tilde T^2 C$ as the composite:
			\[ \begin{tikzcd}[sep = 14 pt]
				{(\Phi\circ \mu^\sharp_C)(b,h,\nu) = a^CQ^*(\nu)} && {(a^CQ)^C(\nu)} && {(\Phi h )^C(\nu) = (\Phi\circ \tilde T \Phi)(b,h,\nu)}
				\arrow["{{{(\Delta_{a,Q})_\nu}}}", from=1-1, to=1-3]
				\arrow["{{{\tau^C_\nu}}}", from=1-3, to=1-5]
			\end{tikzcd} \]
			where we let $(\ell, a \colon J \ell \to C, (b, Q \colon J b \to T \ell, \nu)) \coloneqq \mathfrak{s}_{T,T} ( b, h , \nu)$ as in \ref{sssec:rel-to-abs_on-algebras}, and where $\tau \colon a^C Q \implies \Phi \circ h$ is the natural transformation defined also in \ref{sssec:rel-to-abs_on-algebras}. Unwrapping the definition of $(-)^C$, the previous composite is equal to
			\[ \begin{tikzcd}
				{\Phi \iota_\ell( a) (Q^*(\nu))} && {(\Phi \circ \iota_b(\Phi \iota_{\ell}(a)Q) )(\nu)} && {(\Phi\circ  \iota_b(\Phi h))(\nu)}
				\arrow["{{(\Delta_{a,Q})_\nu}}", from=1-1, to=1-3]
				\arrow["{(\Phi*\iota_b(\tau))_\nu}", from=1-3, to=1-5]
			\end{tikzcd} \] 
			and hence, unwrapping the definition of $\Delta_{a,Q}$, also equal to
			\[ \begin{tikzcd}[column sep = 20pt, row sep = 12pt]
				{\Phi(\ell, a , Q^*(\nu))} \\
				{\Phi(\bar \ell, \bar a , \bar Q^*(\nu))} &[-27pt] {=(\Phi\circ\mu^\sharp_C)(b,\iota_\ell(a)Q, \nu)} \\
				& {(\Phi\circ\tilde T \Phi)(b,\iota_\ell(a)Q, \nu)} &[-31pt] {=\Phi( b, a^CQ, \nu)} && {\Phi(b, \Phi h , \nu) , }
				\arrow["{\Phi(t, \id,\id)}", from=1-1, to=2-1]
				\arrow["{\mathfrak{m}_{(b, \iota_\ell (a) Q, \nu)}}", from=2-2, to=3-2]
				\arrow["{\Phi(\id, \tau, \id)}", from=3-3, to=3-5]
			\end{tikzcd} \] 
			where we let $(\bar \ell, \bar a \colon J \bar \ell \to C , (b, \bar Q \colon J b \to T \bar \ell, \nu ))\coloneqq \mathfrak{s}_{T,T}(b,\iota_\ell(a) Q , \nu )$ and where $t \colon \bar\ell \to \ell \in \Bcat$ is the canonical 1-cell induced being $\ell$ an oplax cocone on the diagram of which $\bar\ell$ is the oplax colimit. Note then that $\tau = \Phi * \tau'$ where $\tau ' \colon \iota_\ell(a) Q \implies h$ is the natural transformation defined at an object $x \in J b$ by the arrow
			\[ (c_x, \id, \id ) \colon \iota_\ell(a) (Q(x)) = ( \ell, a , Tc_x(\nu_x)) \to (Rx, a_x, \nu_x) = h(x)  \] 
			in $\tilde T C$. Therefore, $\Phi (\id,\tau,\id)$ coincides with $(\Phi \circ \tilde T \Phi) (\id,\tau',\id)$ by definition of $\tilde T \Phi$, and hence by naturality of $\mathfrak{m}$ we have that the diagram
			\[ \begin{tikzcd}[column sep = 18pt]
				{(\Phi\circ\mu^\sharp_C)(b,\iota_\ell(a)Q, \nu)} &[-25pt]& {(\Phi\circ \mu^\sharp_C)(b,h , \nu)} & {(\Phi\circ \tilde T \Phi)(b,h , \nu)} \\
				{(\Phi\circ\tilde T \Phi)(b,\iota_\ell(a)Q, \nu)} &[-25pt] {=\Phi( b, a^CQ, \nu)} && {\Phi(b, \Phi h , \nu)}
				\arrow["{(\Phi\circ \mu^\sharp_C)(\id, \tau', \id)}", from=1-1, to=1-3]
				\arrow["{\mathfrak{m}_{(b, \iota_\ell (a) Q, \nu)}}"', from=1-1, to=2-1]
				\arrow["{\mathfrak{m}_{(b, h, \nu)}}", from=1-3, to=1-4]
				\arrow[equals, from=1-4, to=2-4]
				\arrow["{\Phi(\id, \tau, \id)}"', from=2-2, to=2-4]
			\end{tikzcd} \] 
			commutes. Moreover, by the universal properties of oplax colimits (and by functoriality of $\Phi$), the diagram
			\[ \begin{tikzcd}
				{\Phi(\ell, a, Q^*(\nu))} \\
				{\Phi(\bar \ell, \bar a , \bar Q^*(\nu))} &[-30pt] {=(\Phi\circ\mu^\sharp_C)(b,\iota_\ell(a)Q, \nu)} && {(\Phi\circ \mu^\sharp_C)(b,h , \nu)}
				\arrow["{\Phi(t, \id,\id)}"', from=1-1, to=2-1]
				\arrow[curve={height=-12pt}, equals, from=1-1, to=2-4]
