\section{Appendix}
\label{sec: appendix}

\subsection*{Transition probabilities for punishment incentives and hybrid incentives}
\label{sec: fundamental matrices punishment/hybrid}

In this subsection, we present the computation of the transition probabilities for punishment and hybrid incentives, which differ slightly from those computed for reward in Section \ref{sec: asymptotic limits}. Once the transition probabilities are obtained, the fundamental matrix of the Markov chain for these types of incentive is identical to the one for reward. 

\noindent For punishment, we have:
\begin{equation} 
\label{eq: transition probabilities punishment General 2x2 Games}
\begin{split} 
u_{i,i\pm k} &= 0 \qquad \text{ for all } k \geq 2, \\
u_{i,i\pm1} &= \frac{N-i}{N} \frac{i}{N} \left(1 + e^{\mp\beta[\delta_i +\theta_i/(N-i)]}\right)^{-1},\\
u_{i,i} &= 1 - u_{i,i+1} -u_{i,i-1}.
\end{split} 
\end{equation}
We normalise $b=1$ for simplicity and obtain (recalling that $\Pi_C(i)-\Pi_D (i)=\delta_i$ and that $\theta_i/(N-i)=\frac{\theta}{b}=\theta$ for $1\leq i\leq N-1$):
\begin{equation} 
\label{eq: transition probabilities punishment General 2x2 Games normalised}
\begin{split} 
u_{i,i\pm k} &= 0 \qquad \text{ for all } k \geq 2, \\
u_{i,i\pm1} &= \frac{N-i}{N} \frac{i}{N} \left(1 + e^{\mp\beta[\delta_i +\theta]}\right)^{-1},\\
u_{i,i} &= 1 - u_{i,i+1} -u_{i,i-1}.
\end{split} 
\end{equation}

We then proceed exactly the same as in the case of reward.\\

\noindent For hybrid incentives, we have:
\begin{equation} 
\label{eq: transition probabilities hybrid General 2x2 Games}
\begin{split} 
u_{i,i\pm k} &= 0 \qquad \text{ for all } k \geq 2, \\
u_{i,i\pm1} &= \frac{N-i}{N} \frac{i}{N} \left(1 + e^{\mp\beta[\delta_i +\theta_i/\min(i/a, (N-i)/b)]}\right)^{-1},\\
u_{i,i} &= 1 - u_{i,i+1} -u_{i,i-1}.
\end{split} 
\end{equation}
We normalise $a=b=1$ for simplicity and obtain (recalling that $\Pi_C(i)-\Pi_D (i)=\delta_i$ and that $\theta_i/\min(i/a, (N-i)/b)=\theta$ for $1\leq i\leq N-1$):
\begin{equation} 
\label{eq: transition probabilities hybrid General 2x2 Games normalised}
\begin{split} 
u_{i,i\pm k} &= 0 \qquad \text{ for all } k \geq 2, \\
u_{i,i\pm1} &= \frac{N-i}{N} \frac{i}{N} \left(1 + e^{\mp\beta[\delta_i +\theta]}\right)^{-1},\\
u_{i,i} &= 1 - u_{i,i+1} -u_{i,i-1}.
\end{split} 
\end{equation}

We then proceed exactly the same as in the case of reward.

\subsection*{Neutral drift limit for punishment and hybrid incentives}
\label{sec: appendix neutral drift}

\begin{lemma}(Neutral drift limit)
For both a general $2\times 2$ game and the Collective Risk Game, we have
$$\lim_{\beta\to 0}E(\theta)= \begin{cases}
    N^2\theta H_N \hspace{0.3cm} \textit{(Punishment)} \\
    N^2\theta H_{N,a,b} \hspace{0.3cm} \textit{(Hybrid)},
\end{cases}$$
where $H_N$ is the harmonic number
\[
H_N=\sum_{i=1}^{N-1}\frac{1}{j}
\]
and $H_{N,a,b}$ is defined by
\[
H_{N,a,b}=\sum_{k=1}^{N-1} \frac{1}{j(N-j)}\min\Big(\frac{j}{a},\frac{N-j}{b}\Big).
\]
\end{lemma}
\begin{proof}
\noindent It follows from the formula of the entries of the fundamental matrix $W$ given in \eqref{eq: matrix W General 2x2 Games} that, in the limit of neutral drift, i.e. when $\beta\rightarrow0$, we have $\lim_{\beta\rightarrow 0} W=\bar W$, where

\begin{align}
\bar W= \frac{1}{2}\begin{pmatrix} 
2&-1&&&&&\\
-1&2&-1&&&&&\\
&\ddots&\ddots&\ddots&&&\\
&&-1&2&-1&&&\\
&&&-1&2&-1&&&\\
&&&&\ddots&\ddots&\ddots&\\
&&&&&-1&2&-1\\
&&&&&&-1&2
\end{pmatrix}.
\end{align}
The tridiagonal matrix above is the well-known Cartan matrix. It follows from \cite{wei2017inverses} that $(\bar{W}^{-1})_{i,j}= 2\Big[\min(i,j)-\frac{ij}{N}\Big]$, for $1\leq i,j\leq N-1.$

Then, noting that  $\lim\limits_{\beta\to 0} f_C = \lim\limits_{\beta\to 0} f_D = \frac{1}{2}$, we have
\begin{equation}
\label{eq: neutral drift limit}
    \lim_{\beta\to 0}E(\theta)= \lim_{\beta\to 0}\sum_{j=1}^{N-1} (f_Dn_{1,j} + f_Cn_{N-1,j} )\theta_j = \frac{N^2}{2}\sum_{j=1}^{N-1} \frac{(\bar W^{-1}_{1,j} + \bar W^{-1}_{N-1,j})}{j(N-j)}\theta_j.
\end{equation}

Therefore, assuming without loss of generality that $b = 1$ and substituting $\theta_j=(N-j)\theta$ in Equation \eqref{eq: neutral drift limit}, we get 

$$
 \lim_{\beta\to 0}E_p(\theta) = N^2\theta H_N.
$$

In the case of hybrid incentives, where $\theta_j=\theta\min(\frac{j}{a},\frac{N-j}{b})$, and assuming without loss of generality that $a=b=1$, we have

\begin{align*}
    \lim_{\beta\to 0}E_{mix}(\theta) &= \frac{N^2}{2}\Big[\sum_{j=1}^{N-1} \frac{\bar W^{-1}_{1,j} + \bar W^{-1}_{N-1,j}}{N-j} \theta_j\Big] \\
    &= \frac{N^2}{2}\Big[\sum_{j=1}^{N-1} \frac{2(N-j)}{jN(N-j)} \theta \min(\frac{j}{a},\frac{N-j}{b}) + \sum_{j=1}^{N-1} \frac{2j}{jN(N-j)} \theta \min(\frac{j}{a},\frac{N-j}{b})\Big] \\
    &= N\theta \Big[ \sum_{j=1}^{N-1} \frac{1}{j}\min(\frac{j}{a},\frac{N-j}{b}) + \sum_{j=1}^{N-1} \frac{1}{N-j}\min(\frac{j}{a},\frac{N-j}{b}) \Big] \\
    &= N\theta \Big[ \sum_{k=1}^{N-1} \Big(\frac{1}{j}+\frac{1}{N-j}\Big)\min(\frac{j}{a},\frac{N-j}{b}) \Big] \\
    &= N^2\theta\Big[ \sum_{k=1}^{N-1} (\frac{1}{j(N-j)})\min(\frac{j}{a},\frac{N-j}{b}) \Big] \\
    &= N^2 \theta H_{N,a,b}.
\end{align*}
\end{proof}

