\subsection*{Strong selection limit for punishment and hybrid incentives}

\begin{lemma}(Strong selection limit)
\begin{enumerate}
    \item \label{lem: ssl part 1 appendix} Defective Prisoner's Dilemma - Recall that, for the defective Prisoner's Dilemma, $\delta_j < 0$ for all $j$. Assume that $\theta$ is sufficiently small so that $\delta_j + \theta < 0$ for all $j$. Then, in the limit of strong selection, 
\[
\lim_{\beta \to \infty} E(\theta) =
\begin{cases}
\displaystyle N^2 \theta & \text{(Punishment)} \\
\displaystyle \frac{N^2 \theta}{a(N-1)} & \text{(Hybrid)}.
\end{cases}
\]
\item \label{lem: ssl part 2 appendix} Cooperative and defective Prisoner's Dilemma, the Collective Risk Game - Recall that, for the cooperative Prisoner's Dilemma, $\delta_j > 0$ for all $j$. Assume that $\theta$ is sufficiently large so that $\delta_j + \theta > 0$ for all $j$ also holds in the defective Prisoner's Dilemma and in the Collective Risk Game. Then, in the limit of strong selection,
\[
\lim_{\beta \to \infty} E(\theta) =
\begin{cases}
\displaystyle \frac{N^2 \theta}{N-1}  & \text{(Punishment)} \\
\displaystyle \frac{N^2 \theta}{b(N-1)} & \text{(Hybrid)}.
\end{cases}
\]
\end{enumerate}
\end{lemma}

\begin{proof}
The fundamental matrix $W$ transforms as following in the limit of strong selection, i.e. when $\beta\rightarrow\infty$, in part \ref{lem: ssl part 1 appendix} and part \ref{lem: ssl part 2 appendix} of the lemma:
\begin{equation}
\label{eq: matrix W in beta infy limit for delta <= 0 appendix}
\hat W=\begin{pmatrix}
1&0&&&&&\\
-1&1&0&&&&&\\
&\ddots&\ddots&\ddots&&&\\
&&-1&1&0&&&\\
&&&-1&1&0&&&\\
&&&&\ddots&\ddots&\ddots&\\
&&&&&-1&1&0\\
&&&&&&-1&1
\end{pmatrix},
\end{equation}
and
\begin{equation}
\label{eq: matrix W in beta infy limit for delta > 0 appendix}
\overline{W}=\begin{pmatrix}
1&-1&&&&&\\
0&1&-1&&&&&\\
&\ddots&\ddots&\ddots&&&\\
&&0&1&-1&&&\\
&&&0&1&-1&&&\\
&&&&\ddots&\ddots&\ddots&\\
&&&&&0&1&-1\\
&&&&&&0&1
\end{pmatrix}.
\end{equation}

Using Lemma \ref{lem: Toeplitz inverse}, we can compute the matrix inverse for both \eqref{eq: matrix W in beta infy limit for delta <= 0 appendix} and \eqref{eq: matrix W in beta infy limit for delta > 0 appendix} as follows.\\

For \eqref{eq: matrix W in beta infy limit for delta <= 0 appendix}, $\lambda_+=1$ and $\lambda_-=0$, thus
\begin{equation*}
\hat W^{-1}_{i,j} = 
\begin{cases}
     0 \hspace{0.5cm} i<j \quad \\
     1 \hspace{0.5cm} i\geq j 
\end{cases}    
\end{equation*}

Therefore, $\hat W^{-1} =\begin{pmatrix}
1      & 0      & 0      & \cdots & 0 \\
1      & 1      & 0      & \cdots & 0 \\
1      & 1      & 1      & \cdots & 0 \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
1      & 1      & 1      & \cdots & 1 \\
\end{pmatrix}.$\\

For \eqref{eq: matrix W in beta infy limit for delta > 0 appendix}, $\lambda_+=1$ and $\lambda_-=0$, thus
\begin{equation*}
\overline{W}^{-1}_{i,j} = 
\begin{cases}
     1 \hspace{0.5cm} i\leq j \quad \\
     0 \hspace{0.5cm} i> j 
\end{cases}    
\end{equation*}

Therefore, $\overline{W}^{-1} =\begin{pmatrix}
1 & 1 & 1 & \cdots & 1 \\
0 & 1 & 1 & \cdots & 1 \\
0 & 0 & 1 & \cdots & 1 \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
0 & 0 & 0 & \cdots & 1 \\
\end{pmatrix}.$\\

In the limit of strong selection, $f_D = \frac{1}{e^{\beta (N-1)(\Delta + \theta)}+1}$ and $f_C = \frac{e^{\beta (N-1)(\Delta +  \theta)}}{e^{\beta (N-1)(\Delta +  \theta)}+1}$ transform as follows.

Recall $\Delta=
\frac{1}{N-1}\sum_{j=1}^{N-1}\delta_j$. Then
$$
\Delta+\theta= \frac{1}{N-1}\sum_{j=1}^{N-1}\delta_j + \theta = \frac{1}{N-1}\sum_{j=1}^{N-1}\Big(\delta_j+\theta\Big).
$$

In part \ref{lem: ssl part 1 appendix}, as $\delta_j+\theta<0$, we have $\Delta+\theta<0$. Similarly, in part \ref{lem: ssl part 2 appendix}, since $\delta_j+\theta>0$, we get that $\Delta+\theta>0$. Thus,

\[
\lim_{\beta \to \infty} f_C =
\begin{cases}
0 & \text{for } \text{part \ref{lem: ssl part 1 appendix}}\\
1 & \text{for } \text{part \ref{lem: ssl part 2 appendix}}
\end{cases}
\quad
\lim_{\beta \to \infty} f_D =
\begin{cases}
1 & \text{for } \text{part \ref{lem: ssl part 1 appendix}} \\
0 & \text{for } \text{part \ref{lem: ssl part 2 appendix}}.
\end{cases}
\]

Therefore, by rewriting the cost function $E(\theta)$ from Equation \eqref{eq: cost function with fC and fD}, we get:

\[
\lim_{\beta \to \infty} E(\theta) =
\begin{cases}
N^2 \sum_{j=1}^{N-1} \frac{\overline{W}_{N-1,j}}{j(N-j)}\theta_j & \text{for part \ref{lem: ssl part 1 appendix}} \\
N^2 \sum_{j=1}^{N-1} \frac{\hat W_{1,j}}{j(N-j)}\theta_j & \text{for part \ref{lem: ssl part 2 appendix}} .
\end{cases}
\]

Substituting the values of $\hat W_{i,j}$ and $\overline{W} _{i,j}$ computed in \eqref{eq: matrix W in beta infy limit for delta <= 0 appendix} and \eqref{eq: matrix W in beta infy limit for delta > 0 appendix}, respectively, as well as the definition of $\theta_j$ from Equation \eqref{eq: incentives per generation}, we get 

\[
\lim_{\beta \to \infty} E(\theta) =
\begin{cases}
\displaystyle
\begin{aligned}
&\text{part \ref{lem: ssl part 1 appendix}:}
\begin{cases}
N^2 \theta & \text{(Punishment)} \\
\displaystyle \frac{N^2 \theta}{a(N-1)} & \text{(Hybrid)}
\end{cases}\\[3ex]
&\text{part \ref{lem: ssl part 2 appendix}:}
\begin{cases}
\displaystyle \frac{N^2 \theta}{N-1} & \text{(Punishment)} \\
\displaystyle \frac{N^2 \theta}{b(N-1)} & \text{(Hybrid)}.
\end{cases}
\end{aligned}
\end{cases}
\]
\end{proof}

