\centering
\hspace*{-0.5cm}  
\includegraphics[width=\textwidth]{strong_selection_limit_punishment.png}
\caption{The dashed blue line represents the strong selection limit of the punishment cost function. The three figures correspond to: (i) a defective Prisoner's Dilemma (left; $R = 2$, $S = 0$, $T = 4$, $P = 1$; restricted such that $\delta + \theta < 0$), (ii) a cooperative Prisoner's Dilemma (centre; $R = 1$, $S = 4$, $T = 0$, $P = 2$), and (iii) the Collective Risk Game (right; $B = 1$, $c = 0.1$, $r = 0.9$, $n = 5$, $m = 2$; restricted such that $\delta + \theta > 0$). As the intensity of selection $\beta$ increases, the punishment cost function asymptotically approaches the strong selection limit.} 
\label{fig: strong selection limit PD}
\end{figure}

\begin{figure}[H]
\centering
\hspace*{-0.5cm}  
\includegraphics[width=\textwidth]{strong_selection_limit_hybrid.png}
\caption{The dashed blue line represents the strong selection limit of the hybrid cost function. The three figures correspond to: (i) a defective Prisoner's Dilemma (left; $R = 2$, $S = 0$, $T = 4$, $P = 1$; restricted such that $\delta + \theta < 0$), shown for the regime $\delta_j + \theta < 0$ for tractability; (ii) a cooperative Prisoner's Dilemma (centre; $R = 1$, $S = 4$, $T = 0$, $P = 2$); and (iii) the Collective Risk Game (right; $B = 1$, $c = 0.1$, $r = 0.9$, $n = 5$, $m = 2$; restricted such that $\delta + \theta > 0$). As the intensity of selection $\beta$ increases, the hybrid cost function converges towards the strong selection limit.} 
\label{fig: strong selection limit PD}
\end{figure}

