\subsection{Harmonic measure of subarcs}

Consider the arc
\[ A_{L,t} = \{ Le^{i\theta} : 0 \leq \theta \leq t \}, \quad t < \pi/2.\] 
This is a subarc of $A_L$ of length $|A_{L,t}| = Lt$ lying in the semicircular part of the boundary of $\Omega_L$, with right end-point at $L \in \R \cap \partial \Omega_L$. See the red markings in Figure~\ref{F:Figure1}. We are interested in the harmonic measure of this arc with respect to the point $i \in \Omega_L$. Since the arc $A_{L,t}$ lies near a corner of $\Omega_L$, the harmonic measure $\omega(\Omega_L, A_{L,t}, i)$ should be significantly smaller than the length of the arc. We will prove the following estimate.

\begin{lem}
    \thlabel{L:ArcHarmMeasEst}
    In the notation as above, we have
    \[ \omega(\Omega_L, A_{L,t}, i) \leq (1-\cos(t))\frac{2L}{\pi(1-L^2)}.\]
\end{lem}

\begin{proof}
Since the mapping $\phi_L$ introduced above is conformal and satisfies $\phi_L(i) = i$, we know by invariance of harmonic measure that 
\[ \omega(\Omega_L, A_{L,t}, i) = \omega( \mathbb{H}, \phi_L(A_{L,t}), i).\] Here
\[ \phi_L(A_{L,t}) = \{x \in \partial \mathbb{H} = \R : x = \phi_L(z), z \in A_{L,t} \}\] is an interval in $\R$ with right endpoint at $\phi_L(L) = \frac{2L}{1 - L^2}$. The left endpoint is given by 
\[ \phi_L(Le^{it}) = \frac{L}{1-L^2}\bigg( \frac{Le^{it}}{L} + \frac{L}{Le^{it}}\bigg) = \frac{2L \cos (t)}{1-L^2}.\] The well-known upper half-plane harmonic measure formula
\[ \omega( \mathbb{H}, B, i) = \frac{1}{\pi}\int_B \frac{1}{t^2+1} \, dt\] which holds for Borel subsets $B \subset \R$, readily implies the desired estimate:
\begin{align*}
    \omega(\Omega_L, A_{L,t}, i) &= \frac{1}{\pi}\int^{\frac{2L}{1-L^2}}_{\frac{2L \cos (t)}{1-L^2}} \frac{1}{t^2 + 1} \, dt \\
    &\leq \frac{1}{\pi}\int^{\frac{2L}{1-L^2}}_{\frac{2L \cos (t)}{1-L^2}} 1 \, dt \\ 
    &= (1-\cos(t))\frac{2L}{\pi(1-L^2)}.    
\end{align*} 
\end{proof}

\section{Integrability properties of harmonic measure in Joukowski-Privalov domains}

\label{S:Section3}

\subsection{A Joukowski-Privalov domain} \label{S:JoukowskiPrivalovDefSubsec} 

\begin{figure}
    \centering
    \includestandalone{Joukowski-Privalov}
    \caption{An example of a domain $\D_E$, with the set $E$ marked in blue.}
    \label{F:Figure2}
\end{figure}

Let $E$ be a closed subset of $\T$ and $\C(E)$ be the family of maximal open intervals complementary to $E$ on $\T$. By adding a finite number of points to $E$, we may assume that all intervals in $\C(E)$ have length bounded above by any small a priori chosen constant (such a transformation of $E$ does not change its membership in any of the $h$-Beurling-Carleson classes, and it does not change its measure, so all our results can be translated back and forth between any two sets differing by a finite number of points). Then to every $\ell \in \C(E)$ corresponds a unique hyperbolic geodesic $\gamma_\ell \subset \D$ which connects the two endpoints of $\ell$. The curve $\gamma_\ell$ is a circular arc which meets $\T$ in two orthogonal angles. The interval $\ell$ and the curve $\gamma_\ell$ enclose a small region $T_\ell \subset \D$. We define the domain $\D_E$ as the difference between the unit disk $\D$ and the union of closures of $T_\ell$, namely \[ \D_E := \D - \big( \bigcup_{\ell \in \C(E)} \conj{T_\ell} \big). \] 
See Figure~\ref{F:Figure2} for a picture of an example domain $\D_E$. 

For each $e^{it} \in \T$, there exist a largest $r = r(t) \in (0, 1]$ for which we have $re^{it} \in \partial \D_E$. The mapping $e^{it} \to re^{it}$ is easily seen to be continuous, so $\partial \D_E$ is a Jordan curve. The lengths of $\gamma_\ell$ and $\ell$ are comparable, and it follows easily that $\partial \D_E$ is a rectifiable curve. 

\subsection{Majorant integrated against the harmonic measure}

Let $h$ be an increasing function which defines a majorant as in \eqref{E:LessThanExpGrowth}. We assume that $h$ satisfies the regularity hypotheses stated in \eqref{E:RegCond} in Section~\ref{S:MainResultSec}.

\begin{prop}
    \thlabel{P:IntegrMajorantHarmMeas}
    Let \[\omega = \omega(\D_E, \cdot, 0)\] denote the harmonic measure at $0$ for the domain $\D_E$ introduced above. Assume that $E$ is a subset of $\T$ which is closed, and satisfies the $h$-Beurling-Carleson condition in \eqref{E:CarlesonCondDef}. Then we have
    \[ \int_{\partial \D_E \cap \D} \frac{h(1-|z|^2)}{1-|z|^2} d\omega(z) < \infty.\]
\end{prop}

Note that \eqref{E:RegCond} implies 
\[ \frac{h(1-|z|^2)}{1-|z|^2} \leq \frac{h(1-|z|)}{1-|z|} \leq 2\frac{h(1-|z|^2)}{1-|z|^2}. \]

To prove \thref{P:IntegrMajorantHarmMeas}, we will use the well-known subordination principle for harmonic measure.

\begin{lem}
    \thlabel{L:SubOrdHarmMeasure}
    Let $\ell \in \C(E)$ be one of the intervals complementary to $E$. Denote by $\ell^c = \T \setminus \ell$ its closed complement in $\T$, and by $\D_{\ell^c} = \D \setminus T_\ell$ the corresponding Joukowski-Privalov domain which has only one removed region. If $B$ is a Borel subset of $\gamma_\ell \subset \partial \D_E \cap \partial \D_{\ell^c}$, then 
    \[ \omega(B) = \omega(\D_E, B, 0) \leq \omega(\D_{\ell^c}, B, 0).\]
\end{lem}

The lemma is a consequence of the containment $\D_E \subset \D_{\ell^c}$ and the maximum principle for harmonic functions. We refer to \cite[Corollary 4.3.9]{ransford1995potential} for a proof.

We will also use a very simple distortion estimate. 

\begin{lem}
    \thlabel{L:DistEst}
    Let $\psi(z) = i \frac{1-z}{1+z}$, $z \in \D$. For every $z_1,z_2 \in \D$, $\Re z_1 \geq 0$, $\Re z_2 \geq 0$, we have the inequalities
    \[ \frac{|z_1 - z_2|}{2} \leq |\psi(z_1) - \psi(z_2)| \leq 2|z_1 - z_2|\]
\end{lem}

The result follows easily by a direct computation and/or elementary estimation of the derivative of $\phi$ and its inverse. We leave out a proof.

%\begin{proof}
%    The derivative satisfies \[ |\psi'(z)| = \frac{2}{|1+z|^2} \leq 2\] where the inequality holds for $\Re z \geq 0$, since then $|1+z| \geq 1$. Thus \[ |\psi(z_1) - \psi(z_2)| \leq \int_{z_2}^{z_1} |\psi'(z)| |dz| \leq 2|z_1 - z_2|. \] To establish the other inequality, set $w_1 = \psi(z_1)$, $w_2 = \psi(z_2)$. The inverse mapping
%    \[ \psi^{-1}(w) = \frac{i-w}{i+w}\] satisfies 
%    \[|(\psi^{-1})'(w)| = \frac{2}{|i+w|^2} \leq 2,\] since $|i+w| \geq 1$ by virtue of $w \in \H$. Thus, arguing as before,
%    \[ |\psi^{-1}(w_1)-\psi^{-1}(w_2)| \leq 2|w_1 - w_2|\] which translates into \[ |z_1 - z_2| \leq 2|\psi(z_1)- \psi(z_2)|.\]
%\end{proof}



\begin{proof}[Proof of \thref{P:IntegrMajorantHarmMeas}]
    Since 
    \[ \int_{\partial \D_E \cap \D} \frac{h(1-|z|^2)}{1-|z|^2} d\omega(z) = \sum_{\ell \in \C(E)} \int_{\gamma_\ell} \frac{h(1-|z|^2)}{1-|z|^2} d\omega(z),\] by our assumption of finiteness of $\sum_{\ell \in \C(E)} h(|\ell|)$ it will suffice to show that
    \begin{equation}
        \label{E:SuffIntEstimate}
        \int_{\gamma_\ell} \frac{h(1-|z|^2)}{1-|z|^2} d\omega(z) \leq C h(|\ell|) 
    \end{equation} where the constant $C > 0$ does not depend on the complementary interval $\ell$. Fix one of the intervals $\ell$ for the remainder of the proof. Using \thref{L:SubOrdHarmMeasure} we conclude that 
    \begin{equation}
        \label{E:FirstEstimate}
        \int_{\gamma_\ell} \frac{h(1-|z|^2)}{1-|z|^2} d\omega(z) \leq \int_{\gamma_\ell} \frac{h(1-|z|^2)}{1-|z|^2} d\omega_\ell(z) 
    \end{equation} where $\omega_\ell = \omega(\D_{\ell^c}, \cdot, 0)$ denotes the harmonic measure in $\D_{\ell^c}$. By a rotation of the domain $\D_{\ell^c}$ and the radial symmetry of the integrand above, may suppose that the interval $\ell$ has $z = 1$ as its midpoint. The conformal mapping \[ \psi(z) = i \frac{1-z}{1+z}, \quad z \in \D,\] which we considered in \thref{L:DistEst}, maps the domain $\D_{\ell^c}$ bijectively onto a subdomain of the upper half-plane $\H$, and it satisfies $\psi(0) = i$, $\psi(1) = 0$. Since $\psi$ is a linear fractional transformation, it transforms the circular arc $\gamma_\ell$ into a circular arc $\psi(\gamma_\ell)$ which is symmetric with respect to the imaginary axis, and meets the real axis in two orthogonal angles. We conclude that $\psi(\D_{\ell^c})$ is one of the earlier introduced domains $\Omega_L$ (recall the definition in \eqref{E:OmegaLDef}). The interval $[-L, L]$ is the image of $\ell$ under $\psi$. Since we made arrangements for $\ell$ to be short, the arc $\gamma_\ell$, and the domain it encloses together with $\ell$, are located well within the right half-plane. Therefore, by the distortion estimates in \thref{L:DistEst}, the lengths of the intervals $[-L,L]$ and $\ell$ are comparable. More precisely, we have 
    \begin{equation}
        \label{E:ellLcompare}
        |\ell|/2 \leq 2L \leq 2|\ell|.
    \end{equation} Changing variables conformally, we obtain
    \begin{equation}
        \label{E:VariableChange}
        \int_{\gamma_\ell} \frac{h(1-|z|^2)}{1-|z|^2)} d\omega_\ell(z) = \int_{A_L} \frac{h(1-|\psi^{-1}(w)|^2)}{1-|\psi^{-1}(w)|^2} d\omega_L(w) 
    \end{equation} where now \[\omega_L := \omega(\Omega_L, \cdot, i)\] is the harmonic measure in $\Omega_L$, and as before,\[ A_L = \{ z \in \H : |z| = L, \Im z > 0 \}\] is the circular part of the boundary of $\Omega_L$. Decompose the part of $A_L$ lying in the right half-plane as 
    \[ A_L \cap \{ z \in \mathbb{C} : \Re z \geq 0\} = \bigcup_{n=0}^\infty B_{L,n}\] where 
    \[ B_{L,n} = \big\{ z = Le^{it} \in A_L : t_{n+1} < t \leq t_n \big\}\] and
    \[ t_n := \frac{\pi}{2}2^{-n}, \quad n \geq 0.\]
    Since $B_{L,n} \subset A_{L,t_n}$, we obtain by \thref{L:ArcHarmMeasEst} the estimation
    \begin{align*}
        \omega_L(B_{L,n}) &\leq (1-\cos(t_n)) \frac{2L}{\pi(1-L^2)} \leq t_n^2 L
    \end{align*} where we have used the inequality \[ 1-\cos(t) \leq t^2/2, \quad t > 0\] and implicitly assumed that $|\ell|$, and therefore $L$, are sufficiently small to have $\frac{1}{\pi(1-L^2)} \leq 1$ (recall the discussion at the beginning of Section~\ref{S:JoukowskiPrivalovDefSubsec}).

    Let us now compute 
    \[ \sup_{w \in B_{L,n}} \frac{h(1-|\psi^{-1}(w)|^2)}{1-|\psi^{-1}(w)|^2}.\]
    Since 
    \[ \psi^{-1}(w) = \frac{i-w}{i+w}\]
    we obtain, for $w \in B_{L,n}$, that
      \[  1- |\psi^{-1}(w)|^2 = \frac{4 \Im w}{|i+w|^2} \geq \Im w.\] The inequality above is a consequence of
      \[ |i+w| \leq 1+|w| = 1+L < 2\] (recall that we arranged for $i \in \Omega_L$, so $L < 1$). Using that $\sin(t) \geq t/2$ for $t \in [0, \pi/2]$, we obtain \[\inf_{w \in B_{L,n}} \Im w = L\sin(t_{n+1}) \geq L \frac{t_{t+1}}{2} = L \frac{t_n}{4}. \] Thus
      \[ \inf_{w \in B_{L,n}} 1- |\psi^{-1}(w)|^2 \geq L \frac{t_n}{4}, \] and since $h(x)/x$ is assumed decreasing by \eqref{E:RegCond}, we obtain finally that
      \[ \sup_{w \in B_{L,n}} \frac{h(1-|\psi^{-1}(w)|^2)}{1-|\psi^{-1}(w)|^2} \leq \frac{h(Lt_n/4)}{Lt_n/4}.\] By combining this estimate with our earlier estimate for $\omega_L(B_{L,n})$, it follows that
      \[ \int_{B_{L,n}} \frac{h(1-|\psi^{-1}(w)|^2)}{1-|\psi^{-1}(w)|^2} d\omega_L(w) \leq 4 h(Lt_n/4) t_n \leq 2 \pi h(|\ell|) 2^{-n}.\] In the last inequality we used that $h$ is increasing and that $Lt_n/4 \leq L$ for every $n \geq 0$ (recall \eqref{E:ellLcompare}). Summing over $n$, and employing a similar argument for the part of $A_L$ contained in the left half-plane, we obtain
      \[ \int_{A_L} \frac{h(1-|\psi^{-1}(w)|^2)}{1-|\psi^{-1}(w)|^2} d\omega_L(w) \leq 8 \pi h(|\ell|).\]
      This last estimate combined with \eqref{E:SuffIntEstimate}, \eqref{E:FirstEstimate} and \eqref{E:VariableChange} proves the desired result. 
\end{proof}

As explained in Section~\ref{S:TechniqueSection}, Khrushchev's technique combined with \thref{P:IntegrMajorantHarmMeas} immediately implies \thref{T:MainTheorem1}.

\section{Sharpness of the local Jensen-type inequality}
\label{S:Section4}

Here, we prove \thref{T:LocalJensenSharpnessTheorem}.

\subsection{Lemmas on estimation of moments}

To establish the theorem, we will need to go through a rather tedious but fairly standard sequence of lemmas related to estimation of moments of weights related to the majorants in \eqref{E:LessThanExpGrowth}.

Note first that \thref{T:LocalJensenSharpnessTheorem} holds for $(c_n)_n$ if it holds for some larger sequence $(\widetilde{c}_n)_n$, i.e, one satisfying $c_n \leq \widetilde{c}_n$ for all $n$. Thus we may replace $(c_n)_n$ by any larger sequence which satisfies some additional useful regularity properties.

\begin{lem} \thlabel{L:SequenceReplacementLemma}
    Let $(c_n)_n$ be a sequence of positive reals which satisfies $\lim_{n \to \infty} c_n = 0$. There exists a sequence of positive reals $(\widetilde{c}_n)_n$ that satisfies $\lim_{n \to \infty} \widetilde{c}_n = 0$ and the following three additional conditions:
    \begin{enumerate}[(i)]
        \item $c_n \leq \widetilde{c}_n$ for all $n$,
        \item $(\widetilde{c}_n)_n$ is decreasing,
        \item $\widetilde{c}_n \leq \sqrt{\frac{n+1}{n}} \widetilde{c}_{n+1}$ for all $n$.
    \end{enumerate}
\end{lem}

\begin{proof}
We define the desired sequence recursively by setting $\widetilde{c}_1 = c_1$ and then 
\[ \widetilde{c}_{n+1} = \max\Bigg(  \max_{m \geq n+1} c_m , \sqrt{\frac{n}{n+1}} \widetilde{c}_n \Bigg).\]
A minute of reflection shows that the conditions $(i)$, $(ii)$ and $(iii)$ hold for $(\widetilde{c}_n)_n$. To see that this sequence decays to $0$, we use $(ii)$ to conclude that if $\widetilde{c}_{n+1} = \max_{m \geq n+1} c_m$ for infinitely many $n$, then the claim holds, since $\lim_{n \to \infty} \max_{m \geq n+1} c_m = 0$ by hypothesis. In the contrary case, we have $\widetilde{c}_{n+1} = \sqrt{\frac{n}{n+1}}\widetilde{c}_n$ for all $n \geq n_0$, say. In that case, we obtain recursively that
\[ \widetilde{c}_{n_0+m} \leq \sqrt{\frac{n_0}{n_0+m}} \widetilde{c}_{n_0}\] and so $\widetilde{c}_{n_0+m} \to 0$ as $m \to \infty$.    
\end{proof}

An elementary calculus argument, which we skip, establishes the following formula.

\begin{lem} \thlabel{L:LegendreTransformOneOverX}
Let $c > 0$. For large positive integers $n$, we have
\[ \inf_{x \in (0, 1)} nx + \frac{c^2}{x} = 2c \sqrt{n},\] and the infimum is attained at the point $x_n = \frac{c}{\sqrt{n}} \in (0,1)$.    
\end{lem}

By \thref{L:SequenceReplacementLemma}, we may assume that $(c_n)_n$ satisfies the three conditions appearing in the statement of the lemma. Clearly, the sequence $\big( \frac{c_n}{\sqrt{n}}\big)_{n \geq 1}$ is decreasing to $0$, and we may assume that $c_1 < 1$. Define a function $h(x)$ by
\begin{equation}
    \label{E:hDefForCseq}
    h(x) = c_n^2, \quad x \in \Big( \frac{c_{n+1}}{\sqrt{n+1}}, \frac{c_{n}}{\sqrt{n}}\Big].
\end{equation}
For definiteness, we may set $h(x) = c_1^2$ for $x > c_1$. 

\begin{lem} \thlabel{L:MainEstimate}
Let $h$ be defined as above. For large positive integers $n$, we have 
\[ \inf_{x \in (0, 1)} nx + \frac{h(x)}{x} \geq c_n\sqrt{n}.\]
\end{lem}

\begin{proof}
    Consider first the interval \[ I_n := [ c_n/\sqrt{n}, 1]. \] Since $(c_n)_n$ is decreasing, by our definition of $h$ we have the inequality
    \[ c_n^2 \leq h(x), \quad x \in I_n.\]
    Using \thref{L:LegendreTransformOneOverX}, we obtain
    \begin{align*}
        \inf_{x \in I_n} nx + \frac{h(x)}{x} \geq \inf_{x \in I_n} nx + \frac{c_n^2}{x} \geq c_n\sqrt{n}.
    \end{align*} Now consider the interval \[J_m := \Big( \frac{c_{m+1}}{\sqrt{m+1}}, \frac{c_{m}}{\sqrt{m}}\Big], \quad m \geq n.\] By \eqref{E:hDefForCseq}, $h \equiv c_m^2$ on $J_m$. An elementary calculus argument reveals that $nx + \frac{h(x)}{x}$ attains its infimum over $J_m$ at the right endpoint of the interval. Indeed, in the interior of $J_m$, the derivative of the expression equals
    \[ n - \frac{c_m^2}{x^2}\] and this quantity is negative if \[ x < \frac{c_m}{\sqrt{n}},\] so certainly it is negative for $x$ in the interior of $J_m$, since $m \geq n$. We conclude that $x \mapsto nx + \frac{h(x)}{x}$ is decreasing in the interval $J_m$ and thus
    \[ \inf_{x \in J_m} nx + \frac{h(x)}{x} = n \frac{c_m}{\sqrt{m}} + c_m \sqrt{m}.\] We claim that
    \[ n \frac{c_m}{\sqrt{m}} + c_m \sqrt{m} \geq c_n \sqrt{n}.\] If this inequality holds, then our proof is complete. Dividing through by $\sqrt{n}$, we see that the inequality is equivalent to
    \[ \bigg(\sqrt{\frac{n}{m}} + \sqrt{\frac{m}{n}} \bigg) c_m \geq c_n.\] The inequality will hold if the stronger inequality
    \[ \sqrt{\frac{m}{n}} c_m \geq c_n\] is satisfied. Since $m \geq n$, this last inequality just the iterated version of part $(iii)$ of \thref{L:SequenceReplacementLemma}. 
\end{proof}

The function $h$ defined above is not continuous. Replacing $h$ by its least concave majorant, we conclude that given any sequence of positive reals $(c_n)_n$ which satisfies $\lim_{n \to \infty} c_n = 0$, there exists a continuous function $h$ satisfying $h(0) = 0$ and the regularity hypotheses in \eqref{E:RegCond} of Section~\ref{S:MainResultSec} for which the inequality 
\begin{equation}
    \label{E:hLegendreDominateMoments} \inf_{x \in (0,1)} nx + \frac{h(x)}{x} \geq c_n \sqrt{n}
\end{equation} holds for large positive integers $n$.

\begin{lem} \thlabel{L:MomentEstimate}
Assume that $h$ satisfies \eqref{E:hLegendreDominateMoments}. Then for large positive integers $n$ we have the inequality
\[ \int_0^1 x^n \exp\bigg(-\frac{h(1-x)}{1-x}\bigg) \, dx \leq \exp(-c_n\sqrt{n}).\]
\end{lem}

\begin{proof}
    Since the integration interval is of length $1$, it suffices to establish that the integrand is pointwise bounded by $\exp( -c_n \sqrt{n})$. To do so, we use the inequality $\log x \leq x-1$ which holds for all $x > 0$, and the change of variable $1-x = s$:
    \begin{align*}
        x^n \exp\bigg(-\frac{h(1-x)}{1-x}\bigg) &= \exp\bigg(n \log x  -\frac{h(1-x)}{1-x}\bigg) \\ 
        &\leq \exp\bigg(n(x-1) -\frac{h(1-x)}{1-x}\bigg) \\
        &=  \exp\bigg( - ns - \frac{h(s)}{s}\bigg) \\
        &\leq \exp( -c_n \sqrt{n}).
    \end{align*}
    In the last step we used \eqref{E:hLegendreDominateMoments}.
\end{proof}

\subsection{Proof of \thref{T:LocalJensenSharpnessTheorem}}
Let $(c_n)_n$ be any sequence satisfying $\lim_{n \to \infty} c_n = 0$ and $h$ be a corresponding function satisfying \eqref{E:RegCond} and the inequalities in \eqref{E:hLegendreDominateMoments}. Let \[ G(x) = \exp\bigg(-\frac{h(1-x)}{1-x} \bigg), \quad x \in [0,1])\] and $\Po^2_G$ be the weighted Bergman space consisting of analytic functions in $\D$ that satisfy
\[ \| f\|^2_G := \int_\D |f(z)|^2 G(|z|) dA(|z|) < \infty.\] The space $\Po^2_G$ is the closure of analytic polynomials in the corresponding weighted Lebesgue space $L^2(G\, dA)$. A short computation involving a subharmonicity argument and \eqref{E:RegCond} shows that for $z \in \D$ we have 
\begin{align*}
    |f(z)|^2 &\leq  \frac{4}{\pi (1-|z|)^2} \int_{ w: |z-w| < (1-|z|)/2} |f(w)|^2 dA(w) \\
    &\leq \frac{C_1 \|f\|^2_G}{(1-|z|)^2} \exp \bigg( C_2 \frac{h(1-|z|)}{1-|z|} \bigg) 
\end{align*}
i.e, any bounded sequence in $\Po^2_G$ is controlled pointwise in $\D$ by a majorant $\lambda_h$ from the class \eqref{E:LessThanExpGrowth} (after a replacement $C_2 h \to h$) if $h$ decays slow enough to subsume the term $(1-|z|)^{-2} = \exp \big(- 2\log(1-|z|) \big)$ into the exponent by increasing $C_2$ slightly. Should $h$ decay too fast we may always replace $h$ by a larger function which dominates $x \log(1/x)$ and for which the above subsumption is valid (for instance, we may replace $h(x)$ by $h(x) + x\log(1/x)$). The inequality \eqref{E:hLegendreDominateMoments} still holds for this larger $h$.

Let $E$ be an $h$-Beurling-Carleson set of positive measure which contains no intervals, and consider the diagonal 
\[ \mathcal{D} := \{ p \in \Po : (p,p) \} \subset \Po^2_G \oplus L^1(E),\] the second factor being the usual Lebesgue space on $E \subset \T$, defined using the arclength measure $|dz|$ restricted to $E$. The diagonal $\mathcal{D}$ is not norm-dense in the product space. Indeed, by \thref{T:MainTheorem1} and the pointwise estimate above, no tuple of the form $(F, 0)$, $F \neq 0$ is a norm-limit of a sequence in $\mathcal{D}$. A non-zero functional therefore annihilates $\mathcal{D}$. This functional is represented in the usual way by a tuple of functions $g \in \Po^2_G$, $f \in L^\infty(E)$. Since $(z^n, z^n) \in \mathcal{D}$ and $f$ lives only on $E$, we have
\[ \widehat{f}(n) = \int_E f(z) \conj{z}^n \, |dz| = -\int_\D g(z)\conj{z^n} G(|z|) dA(z), \quad n \geq 0.\] The function $f$ is non-zero: were it zero, then the above relation shows that Taylor coefficients around the origin of the analytic function $g$ vanish, and then so does $g$, which is contrary to hypothesis of the functional being non-zero. Cauchy-Schwarz inequality applied to $|g(z)|\sqrt{|z|^nG(|z|)}$ and $\sqrt{|z|^nG(|z|)}$, and the moment estimate in \thref{L:MomentEstimate} show that
\[ |\widehat{f}(n)| \leq \|g\|_G \cdot \exp\big(-(c_n/2) \sqrt{n} \big).\] Since $(c_n)_n$ is an arbitrary positive sequence satisfying $\lim_{n \to \infty} c_n = 0$, our \thref{T:LocalJensenSharpnessTheorem} follows.

