  \centerline{\includegraphics[width=.99\columnwidth]{FIG1__rescaled_correlators_fit_3moms_kin_fac_letter.pdf}}
  \vspace*{-8mm}
  \caption[]{\label{fig:corrs}
    Examples of timeslice fitting and correlator averaging procedure at three values of $Q^2$ for $J/\psi \to \gamma\,\eta\,$ as described in the text.
  }
