         \hline
        \textbf{Prob. seller trades when} $\mathbf{\quality = H}$ & 1 & 1 & 0.96 \tablefootnote{This is the probability that at least one buyer will receive the high signal $0.8$ when the seller has High quality: $1 - p_H^2(0.2) = 0.96$. For a seller of Low quality, this probability is: $1 - p_L^2(0.2) = 0.36$.} & 1 \\
        \hline
