\subsection{Useful Definitions and Notation}
\label{section:useful_definitions}

In what follows, I occasionally operate with the likelihood ratios of beliefs for convenience. The reader can easily verify the identities:
%
\begin{align*}
    \frac{\interim}{1 - \interim} &=
    \frac{\prior}{1 - \prior} 
    \times
    \frac{ 
        \nu_{H}\left( \strat; \experiment \right) 
    }{
        \nu_{L}\left( \strat; \experiment \right) 
    }
    &
    \frac{
        \Prob_{\interim} \left( \quality = H \mid  s_i \right)
    }{
        1 - \Prob_{\interim} \left( \quality = H \mid  s_i \right)
    }
    &=
    \frac{\interim}{1 - \interim} \times
    \frac{s_i}{1 - s_i}
\end{align*}
%
Through similar reasoning, the reader can verify that it is optimal for a buyer to accept trade when:
%
\begin{equation*}
    \frac{
        \Prob_{\interim} \left( \quality = H \mid s_i \right)
    }{
        1 - \Prob_{\interim} \left( \quality = H \mid s_i \right)
    }
    >
    \frac{c}{1-c}
\end{equation*}


Some strategies require buyers to randomise upon observing a particular outcome. To facilitate technical discussion, where it is warranted I assume that each buyer observes the realisation of a \textit{tie-breaking signal} $u \sim U[0,1]$ alongside the outcome of her experiment. This signal is not informative about the asset's quality: it is distributed independently from it conditional on the experiment's outcome. 
I denote the outcome of buyer $i$'s experiment as $s^i$ and her tie-breaking signal as $u^i$. Without loss, buyer $i$ accepts trade if and only if $\strat (s^i) \leq u^i$; where $\strat$ is her strategy. I call the pair  $(s^i, u^i)$ the \textit{score} buyer $i$ observes for the seller. 

%
\begin{defn}
    \label{defn:score}
    The tuple $Z^i = (\typesig^i, u^i)$, where $u^i \overset{IID}{\sim} U[0,1]$
    is the \textit{score} buyer $i$ observes for the seller. The seller's \textit{score profile} $\mathbf{z}$ is the set of scores each buyer observes; $\mathbf{z} = \{ (\typesig^i, u^i) \}_{i=1}^{n}$. Analogously, the seller's \textit{signal profile} $\mathbf{s} = \{ s^i \}_{i=1}^{n}$ is the set of outcomes of each buyer's experiment.
\end{defn}
%

Some proofs in Section \ref{section:omitted_proofs} require comparing interim beliefs across pairs of strategies and experiments; $(\strat, \experiment)$. For convenience, I define the mapping from such a pair to the interim belief consistent with them as 
%
$\Psi (.; \experiment): [0,1]^n \to [0,1]$:
    %
    \begin{equation*}
        \Psi \left( \strat; \experiment \right) 
        :=
        \frac{
            \prior \times \nu_H \left( \strat; \experiment \right)
        }{
            \prior \times \nu_H \left( \strat; \experiment \right)
            +
            ( 1 - \prior ) \times \nu_L \left( \strat; \experiment \right)
        }
    \end{equation*}
    %

    Wherever necessary, I treat each strategy $\strat: \signalset \to [0,1]$ for an experiment $\experiment$ as a vector in the compact set $[0,1]^m \subset \mathbb{R}^n$. This is a finite dimensional vector space, so I endow it with the metric induced by the taxicab norm without loss of generality (see \textcite{kreyszig_functionalanalysis} Theorem 2.4-5):
    %
    \begin{align*}
        \lvert \lvert \strat' - \strat \rvert \rvert &= \sum\limits_{j=1}^{m} \lvert \strat' (s_j) - \strat (s_j) \rvert
        &
        \textrm{for any two strategies } \strat' \textrm{ and } \strat
    \end{align*}
    %
    Note that the interim belief function $\Psi(.;\experiment)$ is thus a continuous function of buyers' strategies\footnote{$r_{\quality}$ is a continuous function of $\strat$, thus both the nominator and denominator are strictly positive continuous functions of $\strat$.}. 


\begin{defn}
    \label{defn:mute}
    Where the experiment $\experiment$ is binary, $s_L^{\textrm{mute}}$ is the \textit{strongest} level of bad news for which there is an equilibrium where a buyer trades regardless of her signal:
	%
	    \begin{equation*}
    	    \frac{\prior}{1 - \prior} \times 
        		\frac{s_L^{\textrm{mute}}}{1 - s_L^{\textrm{mute}}}
	        =
    	    \frac{c}{1-c}
	    		\end{equation*}
\end{defn}



\subsection{Omitted Results}
\label{section:omitted_results}

\begin{restatable}{lem}{lemselectivebetter}
        \label{lem:selectivebetter}
        Let $\strat^*$ and $\strat$ be two monotone strategies such that (i) $\strat^*$ is more selective than $\strat$, and (ii) $\strat^*$ is an equilibrium strategy. Then, total surplus is higher under $\strat^*$: $\sumpayoff (\strat^*; \signalstr) \geq \sumpayoff (\strat; \signalstr)$.
\end{restatable}

\begin{proof}
    \label{proof:prop_selectivebetter}
    Let $\mathbf{z}$ be the seller's \textit{score profile}. Take an equilibrium strategy $\strat^*$ and a less selective strategy $\strat$ such that:
    %
    \begin{equation*}
        \strat(s) - \strat^*(s) =
        \begin{cases}
            \varepsilon & s =  \underaccent{\bar}{s} \\
            0 & \textrm{otherwise}
        \end{cases}
    \end{equation*}
    %
    for some $\varepsilon > 0$, where $\underaccent{\bar}{s} := \min \{ s \in S: \strat^*(s) < 1 \}$. I show that:
    %
    \begin{equation*}
        \lim\limits_{\varepsilon \to 0} 
        \sumpayoff \left( \strat; \varepsilon \right) - \sumpayoff \left( \strat^*; \varepsilon \right) \leq 0
    \end{equation*}
    %
    By Lemma \ref{lem:overapprove}, this establishes the result. 

    Now, let $Z \subset (S \times [0,1])^n$ be the set of score profiles under which some buyer trades under $\strat$, but all buyers reject the seller under $\strat^*$:
    %
    \begin{equation*}
        \mathbf{z} \in Z \iff \hspace{0.3cm}
        \begin{aligned}
            \strat^*(s^i) > u^i \quad &\text{for all } i \in \{1, 2, \ldots, n\}, \\
            &\text{and} \\
            \strat(s^i) \leq u^i \quad &\text{for some } i \in \{1, 2, \ldots, n\}.
        \end{aligned}
    \end{equation*}
    %
    Furthermore, for a given score profile $\mathbf{z}$, 
    let $\#$ be the number of buyers whose observed scores are such that $\strat (s^i) \geq u^i > \strat^* (s^i)$. These buyers would accept trade under the strategy $\strat$, but not under $\strat^*$. 

    The seller's eventual outcome differs between the strategy profiles $\strat$ and $\strat^*$ if and only if his score profile $\mathbf{z}$ lies in $Z$. Furthermore, his eventual outcome can only change from a rejection by all buyers in $\strat^*$ to an approval by some buyer in $\strat$. Thus:
    %
    \begin{align*}
        \sumpayoff (\strat; \signalstr) - \sumpayoff (\strat^*; \signalstr) 
        &= \left[ \Prob ( \quality = H \mid \mathbf{z} \in Z ) - c \right] \times \Prob ( \mathbf{z} \in Z )
        \\
        &\propto \Prob ( \quality = H \mid \mathbf{z} \in Z ) - c
    \end{align*}
    %
    Focus therefore, on the probability that $\quality = H$ given the seller's signal profile lies in $Z$:
    %
    \begin{equation*}
        \Prob \left( \quality = H \mid \mathbf{z} \in Z \right) = 
        \sum\limits_{i=1}^{n}
        \Prob \left( \quality = H \mid \# = i \right) \times 
        \frac{
            \Prob \left( \# = i \right)
        }{
            \Prob (\mathbf{z} \in Z)
        }
    \end{equation*}
    %
    Now note:
    %
    \begin{equation*}
        \Prob \left( \# = i \mid \quality \right) = \left( p_{\quality}(\underaccent{\bar}{s}) \right)^i \times \left( 1 - p_{\quality}(\underaccent{\bar}{s}) \right)^{n-i} \times \varepsilon^i
    \end{equation*}
    %
    and thus $\Prob \left( \# = i \right) \propto \varepsilon^i$. Since $\Prob (\mathbf{z} \in A) = \sum\limits_{i=1}^{n} \Prob \left( \# = i \right)$, we have $\lim\limits_{\varepsilon \to 0} \frac{
        \Prob \left( \# = i \right)
    }{
        \Prob (\mathbf{z} \in A)
    } = 0$ for any $i > 1$. Thus:
    %
    \begin{equation*}
        \lim\limits_{\varepsilon \to 0} \Prob \left( \quality = H \mid \mathbf{z} \in A \right) - \Prob \left( \quality = H \mid \# = 1 \right) = 0
    \end{equation*}
    %
    I conclude the proof by showing that $\Prob \left( \quality = H \mid \# = 1 \right) \leq c$ as $\varepsilon \to 0$:
    %
    \begin{align*}
        \lim\limits_{\varepsilon \to 0}
        \frac{
            \Prob \left( \quality = H \mid \# = 1 \right)
        }{
            \Prob \left( \quality = L \mid \# = 1 \right)
        }
        &=
        \lim\limits_{\varepsilon \to 0}
        \frac{ \Prob \left( \quality = H \right) }{ \Prob \left( \quality = L \right) } \times
        \frac{
            \Prob \left( \# = 1 \mid \quality = H \right)
        }{
            \Prob \left( \# = 1 \mid \quality = L \right)
        }
        %\\[0.5pt]
        \\
        &=
        \lim\limits_{\varepsilon \to 0}
        \frac{ \Prob \left( \quality = H \right) }{ \Prob \left( \quality = L \right) } \times
        \left( 
            \frac{
                r_H ( \strat; \signalstr )
            }{
                r_L ( \strat; \signalstr )
            }
        \right)^{n-1}
        \times
        \frac{ p_H (\underaccent{\bar}{s}) }{ p_L (\underaccent{\bar}{s}) }
        %\\[0.5pt]
        \\
        &=
        \frac{ \Prob \left( \quality = H \right) }{ \Prob \left( \quality = L \right) } \times
        \left( 
            \frac{
                r_H ( \strat^*; \signalstr )
            }{
                r_L ( \strat^*; \signalstr )
            }
        \right)^{n-1}
        \times
        \frac{ p_H (\underaccent{\bar}{s}) }{ p_L (\underaccent{\bar}{s}) }
        %\\[0.5pt]
        \\
        &\leq
        \frac{ \interim^* }{ 1 - \interim^* } \times \frac{ p_H (\underaccent{\bar}{s}) }{ p_L (\underaccent{\bar}{s}) }
        \leq
        \frac{c}{1-c}
    \end{align*}
    %
    where $\interim^* = \interimfcn ( \strat^*; \signalstr )$ is the interim belief consistent with $\strat^*$. The penultimate inequality holds due to the straightforward fact that:
    %
    \begin{equation*}
        \frac{
            \interim^*
        }{
            1 - \interim^*
        }
        =
        \frac{\prior}{1 - \prior}
        \times
        \frac{
            1 + r_H^* + ... + (r_H^*)^{n-1}
        }{
            1 + r_L^* + ... + (r_L^*)^{n-1}
        }
        \leq
        \frac{\prior}{1 - \prior} \times
        \left( 
            \frac{r_H^*}{r_L^*}
        \right)^{n-1}
    \end{equation*}
    %
    where $r_{\quality}^* := r_{\quality} (\strat^*; \signalstr)$. The last inequality is due to the fact that $\underaccent{\bar}{s} \in S$ is optimally rejected under $\strat^*$.

\end{proof}

\begin{lem}
    \label{lemma:blackwell_necessity}
    Suppose there is a single buyer, $n = 1$. Equilibrium total surplus under experiment $\experiment'$ exceeds that under $\experiment$ \textit{regardless of the seller's reservation value} $c \in [0,1]$ \textit{and buyer's prior belief} $\prior \in [0,1]$ if and only if $\experiment'$ is (Blackwell) more informative than $\experiment$.
\end{lem}

\begin{proof}
    The sufficiency part of this Lemma follows from Blackwell's Theorem (\textcite{blackwell_girshick}, Theorem 12.2.2). To show necessity, I fix an arbitrary prior belief $\prior$ for the evaluator. 

    Let $q_j$ be the posterior belief the buyer forms about the asset's quality upon observing the outcome $s_j \in \signalset$:
    %
    \begin{equation*}
        q_j = 
        \frac{
            \prior \times s_j
        }{
            \prior \times s_j + (1 - \prior) \times (1 - s_j)
        }
    \end{equation*}
    %
    Furthermore, let $F(.)$ and $F'(.)$ be the CDFs of the posterior beliefs $\experiment$ and $\experiment'$ induce, respectively, for this prior belief $\prior$:
    %
    \begin{align*}
        F (q) &= (1 - \prior) \times \sum\limits_{s \in \signalset: s \leq q} p_L(s)
        +
        \prior \times \sum\limits_{s \in \signalset: s \leq x} p_H(s)
        \\
        F'( q ) &= (1 - \prior) \times \sum\limits_{s \in \signalset: s \leq q} p_L'(s)
        +
        \prior \times \sum\limits_{s \in \signalset: s \leq x} p_H'(s)
    \end{align*}
    %
    Equilibrium total surplus (and the buyer's expected payoff) under $\experiment$ is given by:
    %
    \begin{align*}
        \int\limits_{c}^{1} ( q - c ) dF( q ) = \int\limits_{c}^{1} q dF( q ) - c \times \left( 1 - F(c) \right) = ( 1 - c ) - \int\limits_{c}^{1} F( q ) d q
    \end{align*}
    %
    An analogous expression gives equilibrium total surplus under $\experiment'$. For the former to exceed the latter for any $c \in [0,1]$, we must have:
    %
    \begin{equation*}
        \int\limits_{c}^{1} \left( F(q) - F'(q) \right) d q 
        \geq 0
    \end{equation*}
    %
    which is equivalent to $\experiment'$ being Blackwell more informative than $\experiment$\footnote{See \textcite{muller_stoyan_comparison}, Theorem 1.5.7. The Blackwell order between signal structures is equivalent to the convex order between the posterior belief distributions they induce; see \textcite{gentzkow_kamenica_2016}.}.

\end{proof}

Lemma \ref{lem:eqm_algorithm} proves useful when proving Theorem \ref{thm:intensive}, the main result of Section \ref{section:finite}. This Lemma can also be used towards an alternative and direct proof for the equilibrium existence claim of Proposition \ref{prop:eqmexist}.

\begin{lem}
    \label{lem:eqm_algorithm}
    For each $j \in \{ 1,2,...,m \}$, let $\strat_j$ be the strategy defined as:
    %
    \begin{equation*}
        \strat_j (s) = 
        \begin{cases}
            0 & s < s_j \\
            1 & s \geq s_j
        \end{cases}
    \end{equation*}
    %
    and $\interim_j$ be the interim belief consistent with this strategy. Unless $\strat_j$ is itself an equilibrium strategy:
    %
    \begin{enumerate}[label = \roman*]
        \item There is an equilibrium strategy $\strat^*$ that is \textit{more selective than} $\strat_j$ if $\Prob_{\interim_j} \left( \quality = H \mid s_j \right) < c$.
        \item There is an equilibrium strategy $\strat^*$ that is \textit{less selective than} $\strat_j$ if $\Prob_{\interim_j} \left( \quality = H \mid s_{j-1} \right) > c$.
    \end{enumerate}
\end{lem}

\begin{proof}
    Abusing notation slightly, I add two fully revealing outcomes $s_0$ and $s_{m+1}$ to the set $\signalset$ (duplicating $s_1$ and $s_m$ if either of them are already fully revealing), and denote the strategy which \textit{never} accepts trade as  $\strat_{m+1}$:
    %
    \begin{align*}
        \frac{ s_{m+1} }{ 1 - s_{m+1} } &= \infty
        &
        \frac{s_0}{ 1 - s_0 } &= 0
        &
        \frac{ \interim_{m+1} }{ 1 - \interim_{m+1} } = 
        %\frac{ \interim_0 }{ 1 - \interim_0 } = 
        \frac{\prior}{1 - \prior}
    \end{align*}

    \begin{enumerate}[label = \textbf{Claim \roman*.}]
        \item 
    \end{enumerate}

    \noindent
    The strategy $\strat_{m+1}$ is the most selective strategy buyers can adopt, and is an equilibrium strategy unless:
    %
    \begin{equation*}
        \frac{
            s_m
        }{
            1 - s_m
        } \times
        \frac{\interim_{m+1}}{ 1 - \interim_{m+1}} > \frac{c}{1-c}
    \end{equation*}
    %
    So, assume this condition is satisfied. Likewise, the strategy $\strat_k$ for $k \geq j$ is an equilibrium if the following inequality is satisfied:
    %
    \begin{equation}
        \label{eqn:algorithm_ineq1}
        \frac{s_k}{1 - s_k} \times \frac{\interim_k}{1 - \interim_k} \geq \frac{c}{1-c} \geq \frac{s_{k-1}}{ 1 - s_{k-1} } \times \frac{\interim_k}{1 - \interim_k}
    \end{equation}
    %
    So, assume inequality \ref{eqn:algorithm_ineq1} is violated for every $k \geq j$. This gives us:
    %
    \begin{equation}
        \label{eqn:algorithm_ineq2}
        \frac{s_{m+1}}{1 - s_{m+1}} \times
        \frac{\interim_{m+1}}{ 1 - \interim_{m+1}} > \frac{c}{1-c} > \frac{s_j}{1 - s_j} \times \frac{\interim_j}{1 - \interim_j}
    \end{equation}
    %
    where the last part of this inequality is by hypothesis. 
    %

    Now, let $k^* \in \{ j, j+1, ..., m \}$ be the first index for which the following inequality is satisfied:
    %
    \begin{equation*}
        \frac{s_{k^*+1}}{1 - s_{k^*+1}} \times
        \frac{\interim_{{k^*}+1}}{ 1 - \interim_{{k^*}+1}} \geq \frac{c}{1-c} \geq \frac{s_{k^*}}{1 - s_{k^*}} \times \frac{\interim_{k^*}}{1 - \interim_{k^*}}
    \end{equation*}
    %
    such a $k^*$ must exist due to inequality \ref{eqn:algorithm_ineq2}. 
    But since inequality \ref{eqn:algorithm_ineq1} is violated, we must have:
    %
    \begin{equation*}
        \frac{s_{k^*}}{1 - s_{k^*}} \times \frac{\interim_{k^* +1}
        }{1 - \interim_{k^* +1}}
        >
        \frac{c}{1-c}
        \geq
        \frac{s_{k^*}}{1 - s_{k^*}} \times
        \frac{\interim_{k^*}}{1 - \interim_{k^*}}
    \end{equation*}
    %
    But since the function $\interimfcn (\strat; \experiment)$ is continuous in buyers' strategy $\strat$,
    %
    we can then find some strategy $\strat^*$:
    %
    \begin{equation*}
        \strat^* (s) =
        \begin{cases}
            1 & s > s_{k^*}  \\
            \in [0,1] & s = s_{k^*} \\
            0 & s < s_{k^*}
        \end{cases}
    \end{equation*}
    %
    such that:
    %
    \begin{equation*}
        \frac{s_{k^*+1}}{1 - s_{k^*+1}} \times \frac{\interimfcn (\strat^*; \experiment)
        }{1 - \interimfcn (\strat^*; \experiment)}
        \geq
        \frac{c}{1-c}
        =
        \frac{s_{k^*}}{1 - s_{k^*}} \times
        \frac{\interimfcn (\strat^*; \experiment)}{1 - \interimfcn (\strat^*; \experiment)}
    \end{equation*}
    %

    The strategy $\strat^*$ is thus an equilibrium strategy. It is clearly more selective than $\strat_j$; since it is more selective than $\strat_{k^*}$, where $k^* \geq j$.



    \begin{enumerate}[label = \textbf{Claim \roman*.}]
        \setcounter{enumi}{1}
        \item 
    \end{enumerate}

    \noindent
    For any $k \in \{ 1,2,...,j \}$, the strategy $\strat_k$ is an equilibrium if the inequality \ref{eqn:algorithm_ineq1} is satisfied. So, as earlier, assume \ref{eqn:algorithm_ineq1} is violated for every such $k$. Then, we get:
    %
    \begin{equation*}
        \frac{s_j}{1 - s_j}
        \times
        \frac{\interim_j}{1 - \interim_j} 
        \geq
        \frac{s_{j-1}}{1 - s_{j-1}} \times \frac{\interim_j}{1 - \interim_j}
        >
        \frac{c}{1-c}
        >
        \frac{s_1}{1 - s_1}
        \times
        \frac{\interim_1}{1 - \interim_1}
    \end{equation*}
    %
    where the second inequality in the chain follows by hypothesis
    %
    and the last inequality follows from the violation of inequality \ref{eqn:algorithm_ineq1} for $k = 1$. We can now repeat the argument we constructed after inequality \ref{eqn:algorithm_ineq2} to prove Claim i, to prove the existence of an equilibrium strategy $\strat^*$ that is less selective than $\strat_j$.


\end{proof}


\subsection{Omitted Proofs}
\label{section:omitted_proofs}

\propeqmexist*

\begin{proof}
    \label{proof:prop_eqmexist}

    In what follows, I treat each strategy $\strat: \signalset \to [0,1]$ as a vector in the compact set $[0,1]^m \subset \mathbb{R}^n$, endowed with the taxicab metric (see the end of Section \ref{section:useful_definitions}).
    %
    I start by proving that any equilibrium strategy must be monotone and all equilibria exhibit adverse selection. Using these observations, I prove that the set of equilibrium strategies is non-empty and compact. 

    \begin{enumerate}
        \setcounter{enumi}{1}
        \item Any equilibrium strategy is {monotone.}
    \end{enumerate} 

    \noindent
    Any equilibrium strategy $\strat^*$ must be optimal against the interim belief $\interim^*$ consistent with it. Whenever $\prior \in (0,1)$, $\interim^* = \interimfcn \left( \strat^*; \experiment \right) \in (0,1)$, and so 
    $\Prob_{\interim^*} \left( \quality = H \mid s' \right) > \Prob_{\interim^*} \left( \quality = H \mid S = s \right)$ for $s', s \in \signalset$ such that $s' > s$. 

    \begin{enumerate}
        \setcounter{enumi}{2}
        \item {All equilibria exhibit adverse selection.}
    \end{enumerate}

    \noindent
    \textit{A fortiori}, $\Psi (\strat; \experiment) \leq \prior$ for any monotone strategy $\strat$. To see this, note that $p_H(.)$ first order stochastically dominates $p_L(.)$ since it likelihood ratio dominates it\footnote{Theorem 1.C.1 in \textcite{shaked_shantikumar_2007}.}.
    Therefore, $\nu_L (\strat; \experiment) \geq \nu_H (\strat; \experiment)$.
    The result then follows since $\frac{
        \interimfcn (\strat; \experiment)
    }{
        1 - \interimfcn (\strat; \experiment)
    } = \frac{\prior}{1 - \prior} \times \frac{\nu_H (\strat; \experiment)}{\nu_L (\strat; \experiment)}$.



    \begin{enumerate}
        \item The set of equilibrium strategies is non-empty and compact.
    \end{enumerate}

    \begin{enumerate}[label=\roman*]
        \item The set of equilibrium strategies is non-empty.
    \end{enumerate}

    \noindent 
    Define $\Phi(.): [0,1]^m \to 2^{[0,1]^m}$ to be the buyers' \textit{best response correspondence}. $\Phi(.)$ maps any strategy $\strat$ to the set of strategies that are optimal against the interim belief $\Psi(\strat; \experiment)$ it induces:
    %
    \begin{equation*}
        \Phi(\strat) = \left\{ \strat' \in [0,1]^m: \strat' \textrm{ is optimal against } \Psi(\strat; \experiment) \right\}
    \end{equation*}
    %
    A strategy $\strat^*$ is an equilibrium strategy if and only if it is a fixed point of buyers' best response correspondence; $ \strat^* \in \Phi(\strat^*)$. I establish that the correspondence $\Phi$ has at least such fixed point through Kakutani's Fixed Point Theorem. 


    $\Phi$ is trivially non-empty; every interim belief has some strategy optimal against it. It is also convex valued; if two distinct approval probabilities are optimal after some outcome $s \in \signalset$, \textit{any} approval probability is optimal upon that outcome. 


    The only task that remains is to prove that $\Phi$ is upper-semi continuous. 
    For this, take an arbitrary sequence of strategies $\{ \strat_n \}$ such that $\strat_n \to \strat_{\infty}$. Denote the interim beliefs consistent with these strategies as $\interim_n := \Psi (\strat_n; \experiment)$. Since $\Psi(.;\experiment)$ is continuous in buyers' strategies, we also have $\interim_n \to \interim_{\infty}$ where $\interim_{\infty} = \Psi \left( \strat_{\infty}; \experiment \right)$. Now, take a sequence of strategies $\left\{\strat_n^* \right\}$ where $\strat_n^* \in \Phi (\strat_n)$. 
    Note that every $\strat_n^*$ is monotone since optimality against any interim belief $\interim \in (0,1)$ requires monotonicity. 
    We want to show that $\Phi$ is upper semicontinuous; i.e.:
    %
    \begin{equation*}
        \strat_n^* \to \strat_{\infty}^* \implies \strat_{\infty}^* \in \Phi (\strat_{\infty})
    \end{equation*}
    %

    By the Monotone Subsequence Theorem, the sequence $\left\{\strat_n^* \right\}$ has a subsequence $\strat_{n_k}^* \to \strat_{\infty}^*$ of strategies whose norms $\lvert \lvert \strat_{n_k}^* \rvert \rvert$ are monotone in their indices $n_k$. Here, I take the case where these norms are increasing, the proof is analogous for the opposite case. Since $\strat^*_{\infty}$ is the limit of a subsequence of monotone strategies, it must be a monotone strategy too. Assuming otherwise leads to a contradiction; for any $s, s' \in \signalset$ such that $s' > s$:
    %
    \begin{equation*}
        \strat^*_{\infty}(s) > 0 \textrm{ \& } \strat^*_{\infty} (s') < 1 
        \hspace{0.2cm}
        \implies 
        \hspace{0.2cm}
        \exists N \in \mathbb{N} \textrm{ s.t. } \forall \textrm{ } n_k \geq N 
        \hspace{0.3cm}
        \strat_{n_k}^* (s) > 0 \textrm{ \& } \strat_{n_k}^* (s') < 1
    \end{equation*}
    %

    Now let $\Bar{s}$ be the highest outcome for which $\strat_{\infty}^* (\Bar{s}) > 0$. I show that:
    %
    \begin{itemize}
        \item If $\strat_{\infty}^* (\Bar{s}) \in (0,1)$, then:
        %
        \begin{equation*}
            \frac{
                \interim_{\infty}
            }{
                1 - \interim_{\infty}
            }
            \times
            \frac{\Bar{s}}{1-\Bar{s}} = \frac{c}{1-c}
        \end{equation*}
        \item If $\strat_{\infty}^* (\Bar{s}) = 1$, then:
        %
        \begin{equation*}
            \frac{
                \interim_{\infty}
            }{
                1 - \interim_{\infty}
            }
            \times
            \frac{s}{1-s}
            \hspace{0.2cm}
            \begin{cases}
                \leq \frac{c}{1-c} & s < \Bar{s} \\
                \geq \frac{c}{1-c} & s \geq \Bar{s}
            \end{cases}
        \end{equation*}
    \end{itemize}

    The first case easily follows by noting that:
    %
    \begin{equation*}
        \strat_{\infty}^* (\Bar{s}) \in (0,1)
        \hspace{0.1cm}
        \implies
        \hspace{0.1cm}
        \strat_{n_k}^* (\Bar{s}) \in (0,1)
        \hspace{0.1cm}
        \implies
        \hspace{0.1cm}
        \frac{
                \interim_{n_k}
            }{
                1 - \interim_{n_k}
            }
            \times
            \frac{\Bar{s}}{1-\Bar{s}} = \frac{c}{1-c}
            \hspace{0.1cm}
        \implies
        \hspace{0.1cm}
        \frac{
                \interim_{\infty}
            }{
                1 - \interim_{\infty}
            }
            \times
            \frac{\Bar{s}}{1-\Bar{s}} = \frac{c}{1-c}
    \end{equation*}
    %
    for all $n_k \geq N' \in \mathbb{N}$.
    %
    The second case follows similarly, by noting that $\strat_{\infty}^* (\Bar{s}) = 1$ and $\strat_{\infty}^* (s') = 0$ for all $s' < \Bar{s}$ implies $\strat_{n_k}^* (\Bar{s}) > 0$ and $\strat_{n_k}^* (s') = 0$ for all $n_k \geq N'' \in \mathbb{N}$.

    \begin{enumerate}[label=\roman*]
        \setcounter{enumi}{1}
        \item The set of equilibrium strategies is compact. 
    \end{enumerate}

    $\Sigma$ is a subset of $[0,1]^m$ and therefore bounded, hence it suffices to show that is closed. Let $\left\{ \strat_n^{**} \right\}$ be a sequence of equilibrium strategies. Note that this means $\strat_n^{**} \in \Phi (\strat_n^{**})$. Since $\Phi(.)$ is upper semicontinuous, $\strat_n^{**} \to \strat_{\infty}$ implies $\strat_{\infty} \in \Phi (\strat_{\infty})$, and therefore $\strat_{\infty}$ is an equilibrium strategy itself. 

\end{proof}

\propselectivebetter*

\begin{proof}
    This is an immediate corollary to Lemmas \ref{lem:selectivebetter} and \ref{lem:overapprove} below; both of independent interest. 
\end{proof}

\begin{restatable}{lem}{lemoverapprove}
    \label{lem:overapprove}
    Take three monotone strategies $\strat'', \strat'$ and, $\strat$, ordered from the least selective to the most. If $\sumpayoff ( \strat'; \experiment ) \leq \sumpayoff ( \strat; \experiment )$, then $\sumpayoff ( \strat''; \experiment ) \leq \sumpayoff ( \strat'; \experiment )$.
\end{restatable}

\begin{proof}
    For the three strategies $\strat'', \strat'$, and $\strat$, consider three sets $Z, Z', Z'' \subset \left( S \times [0,1] \right)^n$ where the seller's score profile $\mathbf{z}$ might lie:
    %
    \begin{equation*}
        \mathbf{z} \in
        %
        \begin{cases}
            Z & \textrm{if } \mathbf{z} \textrm{ trades with some buyer under } \strat'' \textrm{ but not } \strat \\
            Z' & \textrm{if } \mathbf{z} \textrm{ trades with some buyer under } \strat' \textrm{ but not } \strat \\
            Z'' & \textrm{if } \mathbf{z} \textrm{ trades with some buyer under } \strat'' \textrm{ but not } \strat' 
        \end{cases}
    \end{equation*}
    %
    Notice that $Z' \cap Z'' = \emptyset$ and $Z' \cup Z'' = Z$.
    %
    We can write the difference between total surplus under different strategies as:
        %
        \begin{equation*}
            \sumpayoff ( \strat'; \signalstr ) - \sumpayoff ( \strat; \signalstr )
            =
            \Prob \left( 
                \mathbf{z} \in Z'
            \right)
            \times
            \left[ 
                \Prob \left( 
                    \quality = H \mid
                    \mathbf{z} \in Z'
                \right)
                - c
            \right]
        \end{equation*}
        %
        and:
        %
        \begin{equation*}
            \sumpayoff ( \strat''; \signalstr ) - \sumpayoff ( \strat'; \signalstr )
            =
            \Prob \left( 
                \mathbf{z} \in Z''
            \right)
            \times
            \left[ 
                \Prob \left( 
                    \quality = H \mid
                    \mathbf{z} \in Z''
                \right)
                - c
            \right]
        \end{equation*}
        %
        Therefore we want to prove that:
        %
        \begin{equation*}
            \Prob \left( \quality = H \mid \mathbf{z} \in Z' \right) \leq c
            \hspace{0.1cm}
            \implies
            \hspace{0.1cm}
            \Prob \left( \quality = H \mid \mathbf{z} \in Z'' \right) \leq c
        \end{equation*}

        Now, note that $\Prob \left( \quality = H \mid \mathbf{z} \in Z \right)$ is a convex combination of $\Prob \left( \quality = H \mid \mathbf{z} \in Z' \right)$ and $\Prob \left( \quality = H \mid \mathbf{z} \in Z'' \right)$. Furthermore:
        %
        \begin{equation*}
            \Prob \left( \quality = H \mid \mathbf{z} \in Z \right) \geq \Prob \left( \quality = H \mid \mathbf{z} \in Z \cap Z'' \right) = \Prob \left( \quality = H \mid \mathbf{z} \in Z'' \right)
        \end{equation*}
        %
        which then implies:
        %
        \begin{equation*}
            \Prob \left( \quality = H \mid \mathbf{z} \in Z'' \right) \leq \Prob \left( \quality = H \mid \mathbf{z} \in Z \right) \leq \Prob \left( \quality = H \mid \mathbf{z} \in Z' \right) \leq c
        \end{equation*}

\end{proof}


\thmextensive*

\begin{proof}
    For each $j \in \left\{ 1,2,...,m \right\}$, define $\strat_j$ to be the strategy:
    %
    \begin{equation*}
        \strat_j (s) := 
        \begin{cases}
            0 & \typesig < \typesig_j \\
            1 & \typesig \geq \typesig_j
        \end{cases}
    \end{equation*}
    %
    Moreover, let $F_{\quality} (x) = \sum\limits_{\typesig \in \signalset: \typesig \leq x } p_{\quality} (x) $. In a market with $n$ buyers, the interim belief $\interim_{j:n}$ consistent with buyers using the strategies $\strat_j$ is then implicitly given by:
    %
    \begin{equation*}
        \frac{\interim_{ j:n }}{1 - \interim_{ j:n }} = \frac{ \sum_{k=0}^{n-1} F_H(s_{j-1})^k }{ \sum_{k=0}^{n-1} F_L(s_{j-1})^k }
    \end{equation*}
    %
    Note that for all $j > 1$, the RHS is bounded and strictly decreasing in $n$, so the sequence 
    $\left\{ \interim_{ j:n } \right\}$ is convergent. 

    \noindent \textbf{Case 1:} $s_m = 1$.

    To prove the Theorem's statement for this case, I first show that $\interim_{m:n} \overset{n}{\to} 0$. 
    %
    Let $X_n$ be the random variable that is uniformly distributed over the set $\left\{ F_H(s_{m-1})^k \right\}_{k=0}^{n-1}$. Then, note that:
    %
    \begin{equation*}
        \frac{\interim_{ m:n }}{1 - \interim_{ m:n }} = \frac{ \sum_{k=0}^{n-1} F_H(s_{m-1})^k }{ \sum_{k=0}^{n-1} F_L(s_{m-1})^k } = \Exp \left[ X_n \right]
    \end{equation*}
    %
    Now, fix any $x > 0$. Since $F_H(s_{m-1})^k$ is strictly decreasing in $k$, for any $\delta < 1$ of our choice, we can find some $N_{x;\delta} \in \mathbb{N}$ such that for all $n \geq N_{x;\delta}$ implies $\Prob \left( X_n \leq x \right) \geq \delta$ and $\Exp \left[ X_n \right] \leq \delta x + (1 - \delta)$. 
    Fixing $x = \frac{\varepsilon}{2 \delta}$ for some $\varepsilon > 0$ small, we have $\Exp \left[ X_n \right] \leq \frac{\varepsilon}{2} + 1 - \delta$. Since we can take $\delta$ arbitrarily close to 1, this shows that $\Exp \left[ X_n \right] \to 0$, proving this first claim. 

    Since buyers must always accept to trade upon observing $s_m = 1$ in equilibrium, this implies that there is some $N \in \mathbb{N}$ for which $\strat_m$ is the most selective equilibrium strategy for all $n \geq N$. So, for $n \geq N$,  a seller with a Low quality asset never trades. Moreover, every additional buyer increases the probability that a seller with a High quality asset trades. As $n \to \infty$, such a seller trades almost surely. We thus prove that $\sumpayoff^n \left( \hat{\strat}; \experiment \right) \to \sumpayoff^f$.

    \noindent \textbf{Case 2:} $s_m < 1$

    The case where buyers' experiment $\experiment$ is uninformative is trivial; it always yields the no-information benchmark. So, I assume that $s_m \neq s_1$. 

For any $j \in \left\{1,2,...,m\right\}$, the sequence $\left\{ \frac{ \interim_{j;n} }{ 1 - \interim_{j;n} } \times \frac{s_j}{1 - s_j} \right\}_{n=1}^{\infty}$ is bounded and monotone decreasing, thus convergent. Let $\mathcal{L}_j$ be the limit of this sequence. If $\mathcal{L}_m < \frac{c}{1-c}$, by Lemma \ref{lem:eqm_algorithm}, there is some $N' \in \mathbb{N}$ such that for all $n \geq N'$, the most selective equilibrium is more selective than $\strat_m$. So, buyers must be indifferent when they trade---expected trade surplus must be 0. Since total surplus is bounded below by $\sumpayoff^{\emptyset}$, we conclude that $\sumpayoff^n \left( \hat{\strat}; \experiment \right) = \sumpayoff^{\emptyset} = 0$ for all $n \geq N'$. 

    Now consider the case $\mathcal{L}_m \geq \frac{c}{1-c}$. Since $\interim_{j:n}$ is decreasing in $n$, the most selective equilibrium with $n$ buyers, $\hat{\strat}_n$, must get weakly more selective with $n$. So, the sequence $\left\{ r_{\quality} (\hat{\strat}_n; \experiment) \right\}_{n=1}^{\infty}$ is weakly increasing in $n$, convergent, and Cauchy. If for any $N \in \mathbb{N}$, $\hat{\strat}_N$ is more selective than $\strat_m$, we are done by the argument in the preceding paragraph. Otherwise, the sequence $\left\{ r_{\quality} (\hat{\strat}_n; \experiment) \right\}_{n=1}^{\infty}$ converges to a number below $1$.
    %
    If are both constant at 0, we are done---total surplus is equal to that under the no-information benchmark along the sequence. Otherwise, $r_{L} (\hat{\strat}_n; \experiment) > r_{H} (\hat{\strat}_n; \experiment)$ along the sequence. Since both sequences are Cauchy, there exists some $N \in \mathbb{N}$ and $M \geq N$ such that for all $m \geq M$, we have:
    %
    \begin{align*}
        &\prior \times (1 - c) \times \left[ 1 -  r_H (\hat{\strat}_m; \experiment) \right]^{m}  - ( 1 - \prior ) \times c \times \left[ 1 - r_L (\hat{\strat}_m; \experiment)^{m} \right] 
        \\
        \approx
        &\prior \times (1 - c) \times \left[ 1 -  r_H (\hat{\strat}_N; \experiment) \right]^{m}  - ( 1 - \prior ) \times c \times \left[ 1 - r_L (\hat{\strat}_N; \experiment)^{m} \right]
        \\
        >
        &\prior \times (1 - c) \times \left[ 1 -  r_H (\hat{\strat}_N; \experiment) \right]^{m+1}  - ( 1 - \prior ) \times c \times \left[ 1 - r_L (\hat{\strat}_N; \experiment)^{m+1} \right]
        \\
        \approx
        &\prior \times (1 - c) \times \left[ 1 -  r_H (\hat{\strat}_{m+1}; \experiment) \right]^{m+1}  - ( 1 - \prior ) \times c \times \left[ 1 - r_L (\hat{\strat}_{m+1}; \experiment)^{m+1} \right]
    \end{align*}
    %
    This proves that total surplus is eventually decreasing. 

    Furthermore, since there is at least one outcome of the experiment $\experiment$ where a buyer surely trades with the seller, as $n \to \infty$, the seller trades almost surely regardless of quality. Hence, total surplus converges to $\prior - c$. Since total surplus can never be negative, it must be that $\sumpayoff^{\emptyset} = \prior - c$ in this case. 

\end{proof}

\thmintensivebinary*

I will use 
Lemmas \ref{lem:poolbelief_approval}, \ref{lem:binary_nolowmixing}, and \ref{lem:binary_eqmregions} below, of independent interest, to prove Theorem \ref{thm:intensive_binary}. Throughout, I denote the most and least selective equilibrium strategies under the experiment $\signalstr$ as $\hat{\strat_{\experiment}^*}$ and $\check{\strat_{\experiment}^*}$, respectively. I drop the subscript whenever the experiment in question is obvious. 

\begin{lem}
    \label{lem:poolbelief_approval}
    Let $\signalstr$ be a binary experiment, with outcomes in $\signalset = \{s_L, s_H\}$; $s_L \leq s_H$. 
    $\interimfcn(\strat; \signalstr)$ is:
    %
    \begin{enumerate}[label=\roman*]
        \item strictly increasing in $\strat(s_L)$, whenever $\strat(s_H) = 1$,
		%
        \item strictly decreasing in $\strat(s_H)$ whenever $\strat(s_L) = 0$.
    \end{enumerate}
\end{lem}

\begin{proof}
    \textit{Part i:}

    \noindent
    Let $\strat (s_L) \in (0,1)$ and $\strat (s_H) = 1$. 
    The interim belief $\interimfcn (\strat; \experiment)$ is then given by:
    %
    \begin{align*}
        \interimfcn ( \strat; \signalstr ) &= 
        \Prob \left( \quality = H \mid
        \textrm{visit received} \right)
        \\
        &= \sum\limits_{i=0}^{n-1} \Prob ( \textrm{visited after i\textsuperscript{th} rejection} \mid \textrm{visit received} ) \times \Exp \left[ \quality = H \mid \textrm{i } s_L \textrm{ signals} \right]
        \\
        &= \sum\limits_{i=0}^{n-1} 
        \frac{
            \Prob ( \textrm{visited after i\textsuperscript{th} rejection})
        }{
            \Prob ( \textrm{visit received} )
        }
        \times \Exp \left[ \quality = H \mid \textrm{i } s_L \textrm{ signals}
        \right]
    \end{align*}

    \noindent
    Note that $\Exp \left[ \quality = H \mid \textrm{i } s_L \textrm{ signals} \right] < \Exp \left[ \quality = H \mid \textrm{i+1 } s_L \textrm{ signals} \right]$; since every $s_L$ signal is further evidence for $\quality = L$. We have:
    %
    \begin{align*}
        \Prob ( \textrm{ visited after i\textsuperscript{th} rejection} ) = 
        &\Prob \left( 
            \textrm{buyer was (i+1)\textsuperscript{st} in order } \mid \textrm{seller got i rejections}
        \right)
        \\
        &\times
        \Prob \left( \textrm{seller got i rejections} \right)
        \\
        = &\frac{1}{n} \times \Prob ( \textrm{i } s_L \textrm{ signals} ) \times \left[ 1 - \strat(s_L) \right]^{i}
    \end{align*}
    %
    The proof is completed by noting that:
    %
    \begin{equation*}
        \frac{
            \Prob ( \textrm{ visited after (i+1)\textsuperscript{st} rejection} ) 
        }{
            \Prob ( \textrm{ visited after i\textsuperscript{th} rejection} ) 
        } =
        \frac{
            \Prob ( \textrm{i+1 } s_L \textrm{ signals} )
        }{
            \Prob ( \textrm{i } s_L \textrm{ signals} ) 
        }
        \times [1 - \strat(s_L) ]
    \end{equation*}
    %
    decreases, and thus $\interimfcn(\strat; \experiment)$ increases, in $\strat (s_L)$.
    %

    \noindent
    \textit{Part ii:}

    \noindent
    Now take $\strat(s_L) = 0$. We then have:
    %
    \begin{align*}
        r_H (\strat; \signalstr) &= 1 - p_H(s_H) \strat(s_H)
        &
        r_L (\strat; \signalstr) &= 1 - p_L(s_H) \strat(s_H)
    \end{align*}
    %
    and:
    %
    \begin{align*}
        \interimfcn(\strat; \signalstr) &\propto \frac{1 + r_H + ... + r_H^{n-1}}{1 + r_L + ... + r_L^{n-1}}
        \\
        &=
        \frac{
            1 - r_H^{n}
        }{
            1 - r_L^{n}
        }
        \times
        \frac{
            1 - r_L
        }{
            1 - r_H
        } = 
        \frac{
            1 - r_H^{n}
        }{
            1 - r_L^{n}
        }
        \times
        \frac{
            p_L(s_H)
        }{
            p_H(s_H)
        }
        \\
        &\propto \frac{
            1 - r_H^{n}
        }{
            1 - r_L^{n}
        } = 
        \frac{
            1 - \left( 1 - p_H(s_H) \strat(s_H) \right)^n
        }{
            1 - \left( 1 - p_L(s_H) \strat(s_H) \right)^n
        }
    \end{align*}
    %
    Differentiating the last expression with respect to $\strat(s_H)$ and rearranging its terms reveals that this derivative is proportional to:
    %
    \begin{equation*}
        \frac{s_H}{1-s_H}
        \times
        \left( 
            \frac{
                 r_H 
            }{
                 r_L 
            }
        \right)^{n-1}
        -
        \frac{
            1 - \left( r_H \right)^n
        }{
            1 - \left( r_L \right)^n
        }
    \end{equation*}
    %
    The positive term is
    the likelihood ratio of one $s_H$ signal and $n-1$ rejections, and the negative term is the likelihood ratio from \textit{at most} $n-1$ rejections. Since acceptances only happen with $s_H$ signals, the negative term strictly exceeds the positive term. This can be verified directly, too:
    %
    \begin{align*}
        \frac{
            1 - (r_H)^n
        }{
            1 - (r_L)^n
        }
        >
        \frac{s_H}{1-s_H}
        \times
        \left(
            \frac{r_H}{r_L}
        \right)^{n-1}
        &\iff
        %\\
        \frac{
            1 - (r_H)^n
        }{
            1 - (r_L)^n
        }
        \times
        \frac{1 - r_L}{1 - r_H}
        >
        \left( \frac{r_H}{r_L} \right)^{n-1}
        \\
        &\iff
        \frac{
            1 + ... + (r_H)^{n-1}
        }{
            1 + ... + (r_L)^{n-1}
        }
        >
        \left( \frac{r_H}{r_L} \right)^{n-1}
    \end{align*}
    %
    The last inequality can be verified easily. Thus, $\interimfcn(\strat; \signalstr)$ decreases in $\strat(s_H)$. 

\end{proof}

The Corollary below follows from Lemma \ref{lem:poolbelief_approval}. Let both $\experiment'$ and $\experiment$ are binary experiments, where the former is Blackwell more informative than the latter. If, under both experiments, every buyer accepts upon ``good news'' and rejects upon ``bad news'', the interim belief under $\experiment'$ is lower. 

\begin{cor}
    \label{cor:poolbelief_information}
    Let $\experiment'$ and $\experiment$ be two binary experiments, where the former is Blackwell more informative than the latter. Let the strategies $\strat'$ and $\strat$ for these respective experiments be defined as:
    %
    \begin{align*}
        \strat' (s') &:= 
        \begin{cases}
            0 & s' = s_L' \\
            1 & s' = s_H'
        \end{cases}
        &
        \strat (s) &:= 
        \begin{cases}
            0 & s = s_L \\
            1 & s = s_H
        \end{cases}
    \end{align*}
    %
    Then, $\interimfcn \left( \strat'; \signalstr' \right) \leq \interimfcn \left( \strat; \signalstr \right)$.

\end{cor}

\begin{proof}
    Establishing that this holds for a pair $(\experiment', \experiment)$ for which either (i) $s_H' > s_H$ and $s_L = s_L'$, or (ii) $s_H' = s_H$ and $s_L > s_L'$ suffices. I will only prove the first case, the second is analogous. 
    %
    Below I show that the outcome induced by $\strat$ under experiment $\signalstr$ can be replicated by some strategy $\Tilde{\strat}$ under experiment $\signalstr'$, where $\Tilde{\strat} (s_L) > 0$ and $\Tilde{\strat}(s_H) = 1$. Then, the desired conclusion follows from Lemma \ref{lem:poolbelief_approval}. 

    Take the pair $(\strat, \signalstr)$. The probabilities that a buyer accepts or rejects trade, conditional on $\quality$, is given by:
    %
    \begin{align*}
        \frac{
            \Prob_{\strat} \left( \textrm{rejected}  \mid \quality = H \right)
        }{
            \Prob_{\strat} \left( \textrm{rejected}  \mid \quality = L \right)
        } &= \frac{s_L}{1-s_L}
        &
        \frac{
            \Prob_{\strat} \left( \textrm{accepted}  \mid \quality = H \right)
        }{
            \Prob_{\strat} \left( \textrm{accepted}  \mid \quality = L \right)
        }
        &=
        \frac{s_H}{1-s_H}
    \end{align*}
    %
    For the pair $( \Tilde{\strat}, \signalstr' )$ where $\Tilde{\strat}(s_H') = 1$, we have:
    %
    \begin{align*}
        \frac{
            \Prob_{\Tilde{\strat}} \left( \textrm{rejected}  \mid \quality = H \right)
        }{
            \Prob_{\Tilde{\strat}} \left( \textrm{accepted} \mid \quality = L \right)
        } &= \frac{s_L}{1-s_L}
        &
        \frac{
            \Prob_{\Tilde{\strat}} \left( \textrm{accepted} \mid \quality = H \right)
        }{
            \Prob_{\Tilde{\strat}} \left( \textrm{accepted}  \mid \quality = L \right)
        }
        &=
        \frac{p_H'(s_H) + \Tilde{\strat} (s_L) p_H'(s_L)
        }{p_L'(s_H) + \Tilde{\strat} (s_L) p_L'(s_L)}
    \end{align*}
    %
    where $\{ p_L', p_H' \}$ are the distributions for the experiment $\signalstr'$. It is easy to verify that the expression on the right falls from $\frac{s_H'}{1-s_H'}$ to 1 monotonically and continuously as $\Tilde{\strat} (s_L)$ rises from 0 to 1. Thus, there is a unique interior value of $\Tilde{\strat} (s_L)$ that replicates the outcome of $(\strat; \signalstr)$. 

\end{proof}

\begin{lem}
    \label{lem:binary_nolowmixing}
    Let $\signalstr$ be a binary experiment, with outcomes in $\signalset = \{s_L, s_H\}$; $s_L \leq s_H$. Let $\strat^{\star}$ be buyers' equilibrium strategy, either in the most or least selective equilibrium. Then, $\strat^{\star} (s_L) \in \{0,1\}$.
%
\end{lem}

\begin{proof}

    I start by proving this for the least selective equilibrium; i.e. $\check{\strat^*}(s_L) \in \{ 0,1 \}$.  For $s_L^{\textrm{mute}}$ defined in Definition \ref{defn:mute}, observe that when $s_L \geq s_L^{\textrm{mute}}$, $\strat(s_L) = \strat(s_H) = 1$ is an equilibrium; so we must have $\check{\strat^*}(s_L) = 1$. The strategy $\strat$ defined by $\strat(s_H) = \strat(s_L) = 1$ gives rise to the interim belief $\interimfcn (\strat; \experiment) = \prior$, which in turn renders approving upon the outcome $s_L$ optimal. In turn, if $s_L < s_L^{\textrm{mute}}$, we must have $\strat^* (s_L) = 1$ for any equilibrium strategy; since the equilibrium interim belief always lies below the prior belief (Proposition \ref{prop:eqmexist}).

    Now consider the most selective equilibrium strategy; $\hat{\strat^*}$.
    For contradiction, let $1 > \hat{\strat^*}(s_L) > 0$ and $\hat{\strat^*}(s_H) = 1$. Lemma \ref{lem:poolbelief_approval} establishes that the interim belief falls as $\strat(s_L)$ falls; which implies there must be another, more selective equilibrium strategy $\strat^*$ such that $\strat^* (s_L) = 0$ and $\strat^* (s_H) = 1$.

\end{proof}

\noindent
Lemma \ref{lem:binary_nolowmixing} establishes that
when their experiment $\experiment$ is binary,
buyers \textit{never} mix upon seeing ``bad news'', $s = s_L$, neither in the most nor the least selective equilibrium. Following up, Lemma \ref{lem:binary_eqmregions} establishes that a more informative binary experiment pushes buyers to reject upon bad news in both equilibria. 

\begin{lem}
    \label{lem:binary_eqmregions}
    Let $\signalstr$ be a binary experiment, with outcomes in $\signalset = \{ s_L, s_H \}$; $s_L \leq s_H$. Buyers' acceptance probabilities upon ``bad news'', $s = s_L$, in the least and most selective equilibrium strategies are given by:
    %
    \begin{align*}
        \check{\strat^*}(s_L) &=
            \begin{cases}
                1 & s_L \geq s_L^{\textrm{mute}} \\
                0 & s_L < s_L^{\textrm{mute}}
            \end{cases}
        &
        \hat{\strat^{*}} (s_L) &=
            \begin{cases}
                1 & s_L < s_L^{\dag} (s_H) \\
                0 & s_L \geq s_L^{\dag} (s_H)
            \end{cases}
    \end{align*}
    %
    where $s_L^{\dag} (.)$ is an increasing function of $s_H$, and $s_L^{\dag} (s_H) \geq s_L^{\textrm{safe}}$.
\end{lem}

\begin{proof}
    Note that there exists an equilibrium where $\strat(s_L) = 1$ if and only if:
    %
    \begin{equation*}
        \frac{\prior}{1-\prior} \times \frac{s_L}{1-s_L} \geq \frac{c}{1-c}
    \end{equation*}
    %
    which, combined with Lemma \ref{lem:binary_nolowmixing}, proves the part of the Lemma for the selective equilibrium. 

    Now, define the strategies $\strat_0$ as $\strat_1$ as:
    %
    \begin{align*}
        \strat_0(s)
        &=
        \begin{cases}
            0 & s = s_L \\
            0 & s = s_H
        \end{cases}
        &
        \strat_1(s)
        &=
        \begin{cases}
            0 & s = s_L \\
            1 & s = s_H
        \end{cases}
    \end{align*}
    %
    A necessary and sufficient condition for an equilibrium $\strat^*$ where $\strat^*(s_L) = 0$ to exist is:
    %
    \begin{equation*}
        \frac{
            \interimfcn (\strat_{1} ; \signalstr)
        }{
            1 - \interimfcn (\strat_{1} ; \signalstr)
        } \times
        \frac{s_L}{1 - s_L} \leq \frac{c}{1-c}
    \end{equation*}
    %
    Sufficiency follows since either:
    %
    \begin{equation*}
        \frac{
            \interimfcn (\strat_{0} ; \signalstr)
        }{
            1 - \interimfcn (\strat_{0} ; \signalstr)
        } \times
        \frac{s_H}{1 - s_H} \leq \frac{c}{1-c}
    \end{equation*}
    %
    which implies $\strat_0$ is an equilibrium, or there is an equilibrium strategy $\strat^*$ such that $\strat^* (s_L) = 0$ and $\strat^* (s_H) > 0$ by Lemma \ref{lem:poolbelief_approval}. The condition is necessary, since any strategy that is less selective than $\strat_1$ induces a higher interim belief, by Lemma \ref{lem:poolbelief_approval}. 

    By Corollary \ref{cor:poolbelief_information}, whenever this necessary and sufficient condition holds for an experiment $\experiment$, it also holds for a (Blackwell) more informative experiment $\experiment'$. Moreover, whenever the low signals are rejected in the least selective equilibrium, they must be in the most selective equilibrium.
    This concludes the proof. 

\end{proof}

\begin{proof}[Proof, Theorem \ref{thm:intensive_binary}:]
    By Lemma \ref{lem:binary_eqmregions}, Blackwell improving buyers' experiment shifts
    both their least selective and most selective equilibrium strategies once from \textit{always} accepting trade to rejecting upon the low signal. By Lemma \ref{lem:overapprove}, this shift in buyers' strategy increases efficiency---and therefore each buyer's expected surplus. 

    Let $\left\{ \strat_{\alpha} \right\}_{\alpha \in [0,1]}$ be the family of strategies where buyers reject upon the low signal:
    %
    \begin{equation*}
        \strat_{\alpha} (s) = 
        \begin{cases}
            0 & s = s_L \\
            1 & s = s_H
        \end{cases}
    \end{equation*}
    %

    By Lemma \ref{lem:poolbelief_approval}, the interim belief $\interim_{\alpha}$ that the strategy $\strat_{\alpha}$ induces is strictly decreasing in $\alpha$. Thus, at most one of these can be an equilibrium strategy for a given experiment. Furthermore, whenever buyers' expected surplus  from $\strat_1$ is weakly positive, this must be the equilibrium strategy; decreasing $\alpha$ can only make approving upon the high signal \textit{more} profitable. Hence, whenever buyers reject upon the low signal in equilibrium, efficiency is given by: $\sumpayoff ( \strat^*; \experiment ) = \max \left\{ 0 , \sumpayoff (\strat_1; \experiment ) \right\}$. 
    %
    The Theorem then follows from the Claim below:

    \begin{claim*}
        $\max \left\{ 0, \sumpayoff ( \strat_{1}; \signalstr ) \right\}$ is:
        %
        \begin{enumerate}[label=\roman*]
            \item weakly increasing in $s_H$ whenever there is some equilibrium strategy $\strat^*$ s.t. $\strat^* (s_L) = 0$.
            \item hump-shaped in $s_L$. As $s_L$ falls, it: 
                \begin{itemize}
                    \item weakly increases when $s_L \geq s_L^{as}$,
                    \item weakly decreases when $s_L \leq s_L^{as}$
                \end{itemize}
        \end{enumerate}
        %
        where $s_L^{as}$ is defined implicitly as:
        %
        \begin{equation*}
        \frac{
            \prior
        }{
            1 - \prior
        }
        \times
        \left( 
            \frac{
                s_L^{\textrm{as}}
            }{
                1 - s_L^{\textrm{as}}
            }
        \right)^{n-1}
        \times
        \frac{s_H}{1 - s_H} = \frac{c}{1-c}
    \end{equation*}
    %
    \end{claim*}



    \begin{proof}[Proof of the Claim.]\leavevmode\\

    \vspace{-20pt}

    \begin{enumerate}[label = \textbf{Part \roman*.}]
        \setcounter{enumi}{0}
        \item Increasing the strength of good news; i.e. $s_H$.
    \end{enumerate}

    \noindent
    Let $\signalstr$ and $\signalstr'$ be two binary experiments with outcome sets $\signalset = \{ s_L, s_H \}$ and $\signalset' = \{ s_L', s_H' \}$.
    %
    The experiment $\experiment'$ carries \textit{marginally stronger good news} than experiment $\experiment$:
    %
    \begin{align*}
        s_L' &= s_L & s_H' &= s_H + \delta
    \end{align*}
    %
    for some small $\delta$ such that $1 - s_H \geq \delta > 0$. I show that $\sumpayoff ( \strat_{1}' ; \experiment') > \sumpayoff ( \strat_{1}; \experiment )$; where $\strat_1'$ is defined analogously to $\strat_1$ for experiment $\experiment'$.

    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \setcounter{enumi}{0}
        \item Replicating $\signalstr'$ with a signal pair $(\typesig, \hat{\typesig})$.
    \end{enumerate}
    %

    Rather than observing the outcome of experiment $\signalstr'$,
    %
    say a buyer initially observes her original signal $\typesig$, and then potentially an additional auxilliary signal $\hat{\typesig}$. The first signal she receives, $s$, records the outcome of $\experiment$. If the low outcome $s_L$ materialises, the buyer observes no more information. 
    If, however, the high outcome $s_H$ materialises, she then observes the additional auxiliary signal $\hat{s}$. This auxiliary signal records the outcome of \textit{another} binary experiment, $\hat{\experiment}$. The outcome of $\hat{\experiment}$ is independent both from $\typesig$ and anything else any other buyer observes. Conditional on the asset's quality $\quality$, the distribution over its outcomes is given by the pmf $p_{\quality}(.)$:
    %
    \begin{align*}
        %
        \hat{p}_{H} (\hat{s_H})
        &= 1 - \varepsilon \times
        \frac{s_L}{1-s_L}
        &
        %
        \hat{p}_{L} (\hat{s_H})
        &= 1 - \varepsilon \times \frac{s_H}{1-s_H}
    \end{align*}
    %
    The evolution of the buyer's beliefs when she observes this signal pair is determined by the two likelihood ratios:
    %
    \begin{align}
        \dfrac{
            \Prob ( 
            (\typesig, \hat{\typesig}) = (s_H, \hat{s_H})
            %\typesig = s_H, \hat{\typesig} = \hat{s_H} 
            \mid \quality = H )
        }{
            \Prob ( 
            (\typesig, \hat{\typesig}) = (s_H, \hat{s_H})
            %\typesig = S, \hat{\typesig} = \hat{s_H} 
            \mid \quality = L )
        }
        &=
        \dfrac{s_H}{1-s_H} \times 
        \dfrac{
            1 - \varepsilon \times \dfrac{s_L}{1-s_L}
        }{
            1 - \varepsilon \times \dfrac{s_H}{1-s_H}
        }
        \label{eqn:likelihood_high}
        \\
         \dfrac{
            \Prob ( (\typesig, \hat{\typesig}) = (s_H, \hat{s_L})
            %
            \mid \quality = H )
        }{
            \Prob ( 
            (\typesig, \hat{\typesig}) = (s_H, \hat{s_L})
            %
            \mid \quality = L )
        }
        &=
        \dfrac{s_L}{1-s_L}
        \label{eqn:likelihood_2_high}
    \end{align}
    %
    Note that the likelihood ratio \ref{eqn:likelihood_high} increases continuously with $\varepsilon$. 

    The information from observing the pair $(s, \hat{s})$ as such is equivalent to observing the outcome of experiment $\experiment'$, when:
    %
    \begin{equation}
    \label{eqn:epsiloneqvhigh}
        %
        \dfrac{s_H}{1-s_H} \times 
        \dfrac{
            1 - \varepsilon \times \dfrac{s_L}{1-s_L}
        }{
            1 - \varepsilon \times \dfrac{s_H}{1-s_H}
        }
        =
        \frac{s_H + \delta}{1 - (s_H + \delta)}
        %
    \end{equation}
    %
    for our chosen $(\delta, \varepsilon)$. I choose $\varepsilon$ to satisfy this equality for our $\delta$. As such, $\varepsilon$ becomes a continuously increasing function of $\delta$.
    %
    Furthermore, note that by varying $\varepsilon$ between 0 and $\frac{1 - s_H}{s_H}$, we can replicate \textit{any} experiment $\signalstr'$ with $s_L' = s_L$ and $1 \geq s_H' \geq s_H$. 

    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \setcounter{enumi}{1}
        \item $\payoff (\strat_{1}'; \signalstr' ) \geq \payoff (\strat_{1}; \signalstr ) $.
    \end{enumerate}


    The buyer who observes the signal pair $(s, \hat{s})$ obtains equivalent information to that from $\experiment'$. We now must identify the strategy $\Tilde{\strat}: \{ s_L, (s_H, \hat{s_H}), (s_H, \hat{s_L}) \} \to [0,1]$ for this signal pair that replicates the outcome of the strategy $\strat_1'$ for experiment $\experiment'$. This strategy is defined as:
    %
    \begin{align*}
        \Tilde{\strat} ( s_H, \hat{s_H} ) &= 1
        &
        \Tilde{\strat} (s_L) = \Tilde{\strat} ( s_H, \hat{s_L} ) &= 0
    \end{align*}
    %
    and replicates the likelihood ratios of an acceptance and rejection signal under $\experiment'$.

    Now, fix the seller's \textit{signal profile} $\mathbf{s} = \{ (\typesig^i, \hat{\typesig}^i) \}_{i=1}^{n}$ (defined in Section \ref{section:useful_definitions}). I call a seller a \textit{marginal admit} if his score profile is such that:
    %
    \begin{enumerate}[label=\roman*]
        \item for at least one $i \in \{ 1,2,...,n \}$, $\typesig^i = \typesig_H$, and
        \item for \textit{every} $i \in \{ 1,2,...,n \}$, either $\typesig^i = \typesig_L$, or $\hat{\typesig}^i = \hat{\typesig}_L$.
    \end{enumerate}
    %
    These marginal admits drive the wedge between efficiency under $\experiment'$ and $\signalstr$: while some buyer trades under $\experiment$, they \textit{all} reject him under $\hat{\experiment}$. So:
    %
    \begin{equation*}
        \sumpayoff (\strat_{1}'; \signalstr') - \sumpayoff (\strat_{1}; \signalstr)
        =
        \Prob \left( \textrm{marginal admit} \right)
        \times
        \underbrace{
            \left[ 
                c -
            \Prob \left( \quality = H \mid \textrm{marginal admit} \right)
        \right]
        }_{(1)}
    \end{equation*}
    %
    A marginal admit only has signal realisations $(\typesig, \hat{\typesig}) = (s_H, \hat{s_L})$ or $\typesig = s_L$. These carry equivalent information about $\quality$. Thus, the expression (1) above equals:
    %
    \begin{equation*}
        c - \Prob \left[ \quality = H \mid \typesig^1 = ... = \typesig^n = s_L \right]
    \end{equation*}
    %
    In the relevant region where there is an equilibrium strategy that leads to rejections after the low outcome $s_L$, the expression above must be weakly positive:
    %
    \begin{align*}
        c - \Prob \left[ \quality = H \mid \typesig^1 = ... = \typesig^n = s_L \right]
        &\propto
        \frac{c}{1-c} \times \frac{\prior}{1 - \prior} \times \left( 
            \frac{s_L}{1 - s_L}
        \right)^n
        \\
        &\leq 
        \frac{c}{1-c} - \frac{\prior}{1 - \prior} \times 
        \frac{\sum\limits_{k=0}^{n-1} p_H(s_L)^k}{\sum\limits_{k=0}^{n-1} p_L(s_L)^k} \times \frac{s_L}{1 - s_L}
        \\
        &= \frac{c}{1-c} - \frac{\interimfcn (\strat_1; \experiment)}{1 - \interimfcn (\strat_1; \experiment)} \times \frac{s_L}{1 - s_L} \leq 0
    \end{align*}
    %
    where the last inequality follows from the necessary and sufficient condition the proof of Lemma \ref{lem:binary_eqmregions} introduced for such an equilibrium to exist. 

    \begin{enumerate}[label = \textbf{Part \roman*.}]
        \setcounter{enumi}{1}
        \item Increasing the strength of bad news; i.e. decreasing $s_L$.
    \end{enumerate}


    Now, let the experiment $\experiment'$ carry \textit{marginally stronger bad news} than experiment $\experiment$ instead; for some arbitrarily small $\delta \in [0, s_L]$:
    %
    \begin{align*}
        s_L' &= s_L - \delta & s_H' &= s_H
    \end{align*}
    %
    Where $\strat_1'$ and $\strat_1$ are defined as before, I show that:
    %
    \begin{enumerate}[label=\roman*]
        \item $\sumpayoff ( \strat'_{1}; \experiment) - \sumpayoff (\strat_1; \experiment) \geq 0$ when $s_L \geq s_L^{as}$, and
        \item $\sumpayoff ( \strat'_{1}; \experiment) - \sumpayoff (\strat_1; \experiment) \leq 0$ when $s_L \leq s_L^{as}$
    \end{enumerate}


    \noindent

    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \setcounter{enumi}{0}
        \item Replicating $\experiment'$ with a signal pair $(s, \hat{s})$.
    \end{enumerate}


    As before, let each buyer observe \textit{two} signals, potentially: $\typesig$ and $\hat{\typesig}$. She first observes $\typesig$, which records the outcome of $\experiment$. If the high outcome $\typesig_H$ materialises, she receives no further information. If, however, the low outcome $\typesig_L$ materialises, she then observes the additional auxiliary signal $\hat{\typesig}$, which records the outcome of \textit{another} binary experiment, $\hat{\experiment}$. As before, the outcome of this experiment is independent both from $\typesig$ and anything observed by any other buyer. Its distribution conditional on the asset's quality $\quality$ is given by the pmf $p_{\quality} (.)$:
    %
    \begin{align*}
        \hat{p}_H \left( \hat{\typesig}_H \right)
        &=
        \varepsilon \times \frac{s_H}{1 - s_H}
        &
        \hat{p}_L \left( \hat{\typesig}_H \right) &= \varepsilon \times \frac{s_L}{1 - s_L}
    \end{align*}
    %
    The evolution of the buyer's beliefs upon seeing the signal pair $(\typesig, \hat{\typesig})$ is then determined by the two likelihood ratios:
    %
    \begin{align}
        \dfrac{
            \Prob \left( (\typesig, \hat{\typesig}) = ( s_L, \hat{s_H}) \mid \quality = H \right)
        }{
            \Prob \left( (\typesig, \hat{\typesig}) = ( s_L, \hat{s_H}) \mid \quality = H \right)
        }
        &=
        \dfrac{s_H}{1 - s_H}
        \\
        \dfrac{
            \Prob \left( (\typesig, \hat{\typesig}) = ( s_L, \hat{s_L}) \mid \quality = H \right)
        }{
            \Prob \left( (\typesig, \hat{\typesig}) = ( s_L, \hat{s_L}) \mid \quality = H \right)
        }
        &=
        \dfrac{
            s_L
        }{
            1 - s_L
        }
        \times
        \dfrac{
            1 - \varepsilon \times \dfrac{s_H}{1 - s_H}
        }{
            1 - \varepsilon \times \dfrac{s_L}{1 - s_L}
        }
        \label{eqn:likelihoodlow}
    \end{align}
    %
    Note that \ref{eqn:likelihoodlow} is continuously and strictly decreasing with $\varepsilon$, taking values between $\frac{s_L}{1 - s_L}$ and 0 as $\varepsilon$ varies between 0 and $\frac{s_H}{1 - s_H}$. The signal pair $(\typesig, \hat{\typesig})$ is informationally equivalent to $\signalstr'$ when:
    %
    \begin{equation*}
        \dfrac{
            s_L
        }{
            1 - s_L
        }
        \times
        \dfrac{
            1 - \varepsilon \times \dfrac{s_H}{1 - s_H}
        }{
            1 - \varepsilon \times \dfrac{s_L}{1 - s_L}
        }
        =
        \frac{s_L - \delta}{1 - \left( s_L - \delta \right)}
    \end{equation*}
    %
    I choose $\varepsilon$ to satisfy this equality. As before, $\varepsilon$ then becomes a continuously increasing function of $\delta$. 

    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \setcounter{enumi}{1}
        \item $\sumpayoff ( \strat_{1}'; \experiment' ) - \sumpayoff ( \strat_{1}; \experiment )
    \hspace{0.2cm}
    \begin{cases}
        \geq 0 & s_L \geq s_L^{\textrm{as}} \\
        \leq 0 & s_L \leq s_L^{\textrm{as}}
    \end{cases}
    $
    \end{enumerate}


    The buyer who observes the signal pair $(s, \hat{s})$ obtains equivalent information to that from $\experiment'$. We now must identify the strategy $\Tilde{\strat}: \{ (s_L, \hat{s_H}), (s_L, \hat{s_L}) , s_H \} \to [0,1]$ for this signal pair that replicates the outcome of the strategy $\strat_1'$ for experiment $\experiment'$. This strategy is defined as:
    %
    \begin{align*}
        \Tilde{\strat} ( s_L, \hat{s_H} ) = \Tilde{\strat} ( s_H ) &= 1
        &
        \Tilde{\strat} (s_L, \hat{s_L}) &= 0
    \end{align*}
    %
    and replicates the likelihood ratios of an approval and rejection signal under $\experiment'$.

    Now, fix the seller's \textit{score profile}: $\mathbf{s} = \{ (\typesig^i, \hat{\typesig}^i) \}_{i=1}^{n}$. I call a seller a \textit{marginal reject} if:
    %
    \begin{enumerate}[label=\roman*]
        \item for every $i \in \{ 1,2,...,n \}$, $\typesig^i = \typesig_L$, and
        \item for at least one $i \in \{ 1,2,...,n \}$, $\hat{\typesig}^i = \hat{\typesig}_H$.
    \end{enumerate}
    %
    Marginal rejects drive the wedge between efficiency under $\experiment'$ and $\experiment$: while \textit{no} buyer trades under $\experiment$, \textit{at least one} buyer does under $\experiment'$. So:
    %
    \begin{equation*}
        \sumpayoff (\strat_{1}'; \signalstr') - \sumpayoff (\strat_{1}; \signalstr)
        =
        \Prob \left( \textrm{marginal reject} \right)
        \times
        \underbrace{
            \left[ 
            \Prob \left( \quality = H \mid \textrm{marginal reject} 
            \right)
            -
            c
        \right]
        }_{(2)}
    \end{equation*}
    %
    For a marginal reject, buyers observe either $(\typesig^i, \hat{\typesig}^i) = (\typesig_L, \hat{\typesig}_L)$, or $(\typesig^i, \hat{\typesig}^i) = (\typesig_L, \hat{\typesig}_H)$. Denote the number of buyers who observed the latter as $\#$. Since the seller is a marginal reject, $\# \geq 1$. Then, (2) equals:
    %
    \begin{equation*}
        \sum\limits_{i=1}^{n}
        \underbrace{
            \frac{
                \Prob \left( i \textrm{ } \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)  
            }{
                \sum\limits_{j=1}^{n} 
                \Prob \left( j \textrm{ } \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)
            }
        }_{(3)}
        \times 
        \Prob \left( \quality = H \mid \# = i \right) - c
    \end{equation*}
    %
    where:
    %
    \begin{align*}
        \Prob \left( i \textrm{ } \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)
        =
        k \times &\binom{n}{i} \times
        \left( \frac{s_H}{1 - s_H} \times \varepsilon \right)^i \times 
        \left(
            1 - \frac{s_H}{1 - s_H} \times \varepsilon
        \right)^{n-i}
        \\
        +
        (1 - k) \times &\binom{n}{i} \times
        \left( \frac{s_L}{1 - s_L} \times \varepsilon \right)^i \times 
        \left(
            1 - \frac{s_L}{1 - s_L} \times \varepsilon
        \right)^{n-i}
    \end{align*}
    %
    %
    and $k = \Prob \left( \quality = H \mid \typesig^1 = ... = \typesig^n = s_L \right)$. Thus, the limit of expression (3) as $\varepsilon \to 0$ (and therefore, $\delta \to 0$) for any $i > 1$ is:
    %
    \begin{equation}
        \label{eqn:thmbinary_limit}
        \lim\limits_{\varepsilon \to 0}
            \frac{
                \frac{1}{\varepsilon} \times
                \Prob \left( i \textrm{ } \hat{\typesig} = \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)  
            }{
                \frac{1}{\varepsilon} \times
                \sum\limits_{j=1}^{n} 
                \Prob \left( j \textrm{ } \hat{\typesig} = \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)
            }
            = 0
    \end{equation}
    %
    Therefore, we get:
    %
    \begin{align*}
        &\lim\limits_{\varepsilon \to 0}
        \sum\limits_{i=1}^{n}
            \frac{
                \Prob \left( i \textrm{ } \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)  
            }{
                \sum\limits_{j=1}^{n} 
                \Prob \left( j \textrm{ } \hat{s_H} \textrm{ signals } \mid \typesig^1 = ... = \typesig^n = s_L \right)
            }
        \times 
        \Prob \left( \quality = H \mid \# = i \right) - c
        \\
        &= 
        %
        \Prob \left( \quality = H \mid \# = 1 \right)
        - c
        \\
        &\propto
        \frac{\prior}{1 - \prior}
        \times 
        \left( 
            \frac{
                s_L
            }{
                1 - s_L
            }
        \right)^{n-1}
        \times
        \frac{s_H}{1 - s_H} - \frac{c}{1-c}
    \end{align*}
    %
    proving the claim.
    \end{proof}

\end{proof}

\propthresholdbinary*

\begin{proof}\leavevmode\\

    \vspace{-25pt}

    \begin{enumerate}[label=\roman*]
        \item The least selective equilibrium:
    \end{enumerate}

    By Lemma \ref{lem:binary_nolowmixing}, the probability that the seller trades upon the low outcome in
    the least selective equilibrium is:
    %
    \begin{equation*}
        \check{\strat}^* (s_L)
        =
        \begin{cases}
            1 & s_L \geq s_L^{\textrm{mute}} \\
            0 & s_L < s_L^{\textrm{mute}}
        \end{cases}
    \end{equation*}
    %
    Thus, efficiency equals (i) the expected surplus from always approving the applicant when $s_L \geq s_L^{\textrm{mute}}$, and (ii) $\max \left\{ 0, \sumpayoff \left( \strat_1; \experiment \right) \right\}$ when $s_L < s_L^{\textrm{mute}}$ (established in the proof of Theorem \ref{thm:intensive_binary}):
    %
    \begin{equation*}
        \sumpayoff (\check{\strat}^*; \experiment) = 
        %
        \begin{cases}
            \prior - c & s_L \geq s_L^{\textrm{mute}} \\ 
            \max \left\{ 0, \sumpayoff \left( \strat_1; \experiment \right) \right\}
            & s_L < s_L^{\textrm{mute}}
        \end{cases}
        %
    \end{equation*}
    %

    Since always trading is always feasible, we have $\max \left\{ 0, \sumpayoff \left( \strat_1; \experiment \right) \right\} \geq \prior - c$ when $s_L < s_L^{\textrm{mute}}$ by Lemma \ref{lem:overapprove}. Furthermore, the final Claim in Theorem \ref{thm:intensive_binary}'s proof establishes that as $s_L$ falls, the expression $\max \left\{ 0, \sumpayoff \left( \strat_1; \experiment \right) \right\}$ weakly increases (decreases) when $s_L \geq s_L^{\textrm{as}}$ ($s_L \leq s_L^{\textrm{as}}$).
    %
    Thus the desired conclusion is established. 

    \begin{enumerate}[label=\roman*]
        \setcounter{enumi}{1}
        \item The most selective equilibrium:
    \end{enumerate}

    \noindent
    By Lemma \ref{lem:binary_eqmregions}, the most selective equilibrium shifts from one where a buyer always trades to one where she rejects upon the low signal when $s_H \geq s_H^{\dag} (s_L)$, where $s_H^{\dag} (.)$ is an increasing function of $s_L$. Following the arguments made for the least selective equilibrium then, efficiency:
    %
    \begin{itemize}
        \item weakly increases as $s_L$ decreases, when $s_L \geq \min \left\{ s_L^{\textrm{as}}, s_L^{\dag} (s_H) \right\}$
        \item weakly decreases as $s_L$ decreases, when $s_L \leq \min \left\{ s_L^{\textrm{as}}, s_L^{\dag} (s_H) \right\}$.
    \end{itemize}
    %
    The desired result follows by noting that $s_L^{\dag}(s_H) \geq s_L^{\textrm{safe}}$, and therefore 
    $\min \left\{ s_L^{\dag}, s_L^{\textrm{as}} (s_H) \right\}
    \geq
    \min \left\{ s_L^{\textrm{safe}}, s_L^{\textrm{as}} (s_H) \right\}$.

\end{proof}

\thmintensive*

\begin{proof}
    %
    The Theorem focuses either on the least, or the most selective equilibrium strategies under both experiments. In the discussion below, I let $\strat^*$ and $\strat^{*'}$ denote whichever equilibria we are focusing on under the respective experiments $\experiment$ and $\experiment'$. When I need to distinguish between the least and most selective equilibria, I denote them as $ (\check{\strat}, \check{\strat}')$ and $ (\hat{\strat}, \hat{\strat}')$, respectively.
    %
    Following the notation introduced in Definition \ref{defn:local_mps}, let $\signalset \cup \signalset' = \left\{ s_1, s_2, ..., s_M \right\}$ be the joint support of the experiments $\signalstr$ and $\signalstr'$, with elements increasing in their indices as usual. 
    %
    Since $\experiment'$ is obtained by a \textit{local} mean preserving spread of $\experiment$, there is a monotone strategy $\strat': \signalset' \to [0,1]$ whose outcome under $\experiment'$ replicates the outcome of $\strat^*$ under $\experiment$:
    %
    \begin{equation*}
        {\strat}'(s) = 
            \begin{cases}
                \strat^*(s_j) & s \in \{ s_{j-1}, s_{j+1} \} \\
                \strat^*(s) & s \notin \{ s_{j-1}, s_{j+1} \}
            \end{cases}
    \end{equation*}

    \noindent
    \textbf{Claim 1.} Efficiency under the most (least) selective equilibrium of $\experiment'$ weakly exceeds that under $\experiment$ when $\hat{\strat} (s_j) = 1$ ($\check{\strat} (s_j) = 1$).

    Now suppose $s_j$ leads to trade under $\strat^*$; $\strat^*(s_j) = 1$. Therefore, $\strat'(s_{j-1}) = {\strat}' (s_{j+1}) = 1$. Below, I show that $\strat^{*'}$ is \textit{more selective than} $\strat'$. By Lemma \ref{lem:selectivebetter}, it follows that $\sumpayoff \left( \strat^{*'}; \experiment' \right) \geq \sumpayoff \left( \strat'; \experiment' \right) = \sumpayoff \left( \strat; \experiment \right)$. 

    If $s_{j-1} = \min \signalset \cup \signalset'$ or $\strat^{*'} (s_{j-2}) = 0$, $\strat^{*'}$ must necessarily be more selective than $\strat'$; and we are done. So, for contradiction, I assume the following:
    %
    \begin{itemize}
        \item $s_{j-1} > \min \signalset \cup \signalset'$
        \item $\strat^{*'} (s_{j-2}) > 0$
        \item $\strat^{*'}$ is \textit{less} selective than $\strat'$, where the two strategies differ.
    \end{itemize}


    \begin{enumerate}[label=Case \roman*.]
        \item $\strat^*$ and $\strat^{*'}$ are the least selective equilibrium strategies; i.e. $\strat^* = \check{\strat}$ and $\strat^{*'} = \check{\strat}'$.
    \end{enumerate}

    I will prove the contradiction by constructing a strategy $\Tilde{\strat}: \signalset \to [0,1]$ for experiment $\experiment$, such that:
    %
    \begin{enumerate}[label=\roman*]
        \item $\Tilde{\strat}$ replicates the outcome $\check{\strat}'$ induces in $\experiment'$,
        \item That $\check{\strat}'$ is an eqm. strategy under $\experiment'$ implies that $\Tilde{\strat}$ is an eqm. strategy under $\experiment$,
        \item But $\Tilde{\strat}$ is less selective than $\check{\strat}$, contradicting that $\check{\strat}$ is the least selective equilibrium strategy under $\experiment$.
    \end{enumerate}


    I define the strategy $\Tilde{\strat}: \signalset \to [0,1]$ for $\signalstr$ as:
    %
    \begin{equation*}
        { \Tilde{ \strat } } ( s ) := 
            \begin{cases}
                1 & s = s_i \\
                \strat' (s) & s \neq s_i
            \end{cases}
    \end{equation*}
    %
    it is seen easily that $\Tilde{\strat}$ replicates the outcome of $\check{\strat}'$. Furthermore, $\check{\strat}'$ is an equilibrium under $\experiment'$ if and only if $\Tilde{\strat}$ is an equilibrium under $\experiment$: they induce the same interim belief $\interim$, and share the following necessary and sufficient condition for optimality:
    %
    \begin{equation*}
        \Prob_{\interim} \left( 
            \quality = H \mid s_{j-2}
        \right)
        %
        \begin{cases}
             = c & \strat'(s_{j-2}) < 1
             \\
             \geq c & \strat'(s_{j-2}) = 1
        \end{cases}
    \end{equation*}
    %
    The strategy
    $\Tilde{\strat}$ under experiment $\experiment$ replicates the outcome of $\check{\strat}'$ under experiment $\experiment'$, and $\strat'$ under $\experiment'$ replicates the outcome of 
    $\check{\strat}$ under experiment $\experiment$. Since we assumed that $\check{\strat}'$ is less selective than $\strat'$, it must be that $\Tilde{\strat}$ is less selective than $\check{\strat}$.
    %

    \begin{enumerate}[label=Case \roman*.]
        \setcounter{enumi}{1}
        \item $\strat^*$ and $\strat^{*'}$ are the most selective equilibrium strategies; i.e. $\strat^* = \hat{\strat}$ and $\strat^{*'} = \hat{\strat}'$.
    \end{enumerate}


    Since strategy $\strat'$ for experiment $\experiment'$ replicates the outcome of $\hat{\strat}$ for experiment $\experiment$, the two strategies induce the same interim belief $\interim$. Therefore, if $\Prob_{\interim} \left( \quality = H \mid s_{j-1} \right) \geq c$, $\strat'$ is an equilibrium under $\experiment'$; meaning $\hat{\strat}'$ must be more selective than $\strat'$. 

    Otherwise, say $\Prob_{\interim} \left( \quality = H \mid s_{j-1} \right) < c$. Then, by Lemma \ref{lem:eqm_algorithm}, there must be an equilibrium strategy that is more selective than $\strat'$ under $\experiment'$.



    \noindent
    \textbf{Claim 2.} Efficiency under the most (least) selective equilibrium of $\experiment'$ falls weakly below that under $\experiment$ if:
    %
    \begin{enumerate}[label= \roman*.]
        \item $s_j$ leads to rejections under $\experiment$; i.e. $\hat{\strat} (s_j) = 0$ ($\check{\strat} (s_j) = 0$), and
        \item the following condition holds:
        %
        \begin{equation*}
            \frac{\prior}{1 - \prior} \times \left( \frac{ r_H ( \strat; \experiment ) }{  r_L ( \strat; \experiment )  } \right)^{n-1} \times \frac{s_{j+1}}{1 - s_{j+1}} \leq \frac{c}{1-c}
        \end{equation*}
    \end{enumerate}

    Now, suppose $s_j$ leads to rejections under $\strat^*$; $\strat^* (s_j) = 0$. Consequently, 
    we have $\strat' ( s_{j-1} ) = \strat' ( s_{j+1} ) = 0$. 
    I establish Claim 2 in two steps:
    %
    \begin{enumerate}[label = Step \arabic*.]
        \item $\strat^{*'}$ is less selective than $\strat'$; trade is likelier when when $s_j$ is locally spread.
        \item This efficiency when the condition in Claim 2 is met; $ \sumpayoff ( \strat^{*'}; \experiment' ) \leq \sumpayoff ( \strat' ; \experiment' ) = \sumpayoff (\strat^*; \experiment)$.
    \end{enumerate}


    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \item 
    \end{enumerate}

    \noindent
    If $s_{j+1} = \max \signalset \cup \signalset'$ or $\strat^{*'}(s_{j+1}) > 0$, it must be the case that $\strat^{*'}$ is less selective than $\strat'$, and we are done. So instead, I assume that $s_{j+1} < \max \signalset \cup \signalset'$ and $\strat^{*'}(s_{j+1}) = 0$.

    \begin{enumerate}[label = Case \roman*.]
        \item $\strat^*$ and $\strat^{*'}$ are the least selective equilibrium strategies; i.e. $\strat^* = \check{\strat}$ and $\strat^{*'} = \check{\strat}'$
    \end{enumerate}

    Since $\strat'$ replicates the outcome of $\check{\strat}$, we have $\interimfcn ( \check{\strat}; \experiment ) = \interimfcn ( \strat'; \experiment' ) = \interim$. Thus, $\strat'$ must be an equilibrium strategy under $\experiment'$ if $\Prob_{\interim} \left( \quality = H \mid s_{j+1} \right) \leq c$: the optimality conditions for all signals below $s_{j+1}$ are satisfied \textit{a fortiori}, and those for the signals above $s_{j+1}$ are satisfied 
    since $\check{\strat}$ has the same optimality conditions under $\experiment$. So, $\check{\strat}'$ must be less selective than $\strat'$, since the former is the least selective equilibrium.
    %
    If on the other hand, $\Prob_{\interim} \left( \quality = H \mid 
    s_{j+1} \right) > c$, there must be an equilibrium strategy under experiment $\experiment'$ that is \textit{less} selective than  $\strat'$, by Lemma \ref{lem:eqm_algorithm}.


    \begin{enumerate}[label=Case \roman*.]
        \setcounter{enumi}{1}
        \item $\strat^*$ and $\strat^{*'}$ are the most selective equilibrium strategies; i.e. $\strat^* = \hat{\strat}$ and $\strat^{*'} = \hat{\strat}'$.
    \end{enumerate}

    $\hat{\strat}'$ is the most selective equilibrium strategy under experiment $\experiment'$, and we assumed that $\hat{\strat}' (s_{j+1}) = 0$. The strategy $\Tilde{\strat}$ defined below for experiment $\experiment$ replicates the outcome $\hat{\strat}'$ generates under experiment $\experiment'$:
    %
    \begin{equation*}
        \Tilde{\strat} (s) =
        \begin{cases}
            0 & s \leq s_j \\
            \hat{\strat}' (s) & s > s_j
        \end{cases}
    \end{equation*}
    %
    Note that $\Tilde{\strat}$ must be an equilibrium under experiment $\experiment$, since the interim belief it induces is the same as the one $\hat{\strat}'$ does, and its optimality constraints are a subset of the latter's. But since $\hat{\strat}$ is the \textit{most} selective equilibrium strategy under $\experiment$, $\Tilde{\strat}$ must be less selective than it. 

    \begin{enumerate}[label = \textbf{Step \arabic*.}]
        \setcounter{enumi}{1}
        \item 
    \end{enumerate}

    The statement is trivially true when $\strat' = \strat^{*'}$, so I focus on the case where these two strategies differ. As Step 1 established, $\strat^{*'}$ must be less selective than $\strat'$. This implies that $\strat^{*'} ( s_{j+1} ) > 0$. To see why, say we had $\strat^{*'} (s_{j+1}) = 0$ instead. We can then construct a strategy $\Tilde{\strat}$ for experiment $\experiment$, which replicates the outcome $\strat^{*'}$ generates under experiment $\experiment'$:
    %
    \begin{equation*}
        \Tilde{\strat} (s) =
        \begin{cases}
            0 & s \leq s_j \\
            \strat^{*'} (s) & s > s_j
        \end{cases}
    \end{equation*}
    %
    As they induce the same interim belief and the optimality constraints of the latter are a subset of the former's, $\Tilde{\strat}$ must be an equilibrium under $\experiment$. This contradicts with $\strat^{*}$ and $\strat^{*'}$ being the least selective strategies; since $\strat^{*'}$ being less selective than $\strat'$ implies that $\Tilde{\strat}$ must be less selective than $\strat^*$. It also contradicts with $\strat^*$ and $\strat^{*'}$ being the most selective strategies; since it would imply that $\strat'$, more selective than $\strat^{*'}$, should be an equilibrium under $\experiment'$.

    Given that $\strat^{*'} (s_{j+1}) > 0$, I now take another strategy $\strat^{\delta}_{\experiment'}: \signalset' \to [0,1]$ for experiment $\experiment'$: 
    %
    \begin{align*}
        \strat^{\delta}_{\experiment'} (s) =
        \begin{cases}
            1 & s > s_{j+1} \\
            \delta & s = s_{j+1} \\
            0 & s < s_{j+1}
        \end{cases}
    \end{align*}
    %
    where $\delta > 0$ is small enough so that $\strat^{\delta}_{\experiment'}$ is more selective than $\strat^{*'}$, but less selective than $\strat'$. I will show that, when the condition stated in Claim 2 holds, we have $\sumpayoff \left( \strat^{\delta}_{\experiment'}; \experiment' \right) \leq 
    \sumpayoff \left( \strat'; \experiment' \right)
    $ for $\delta \to 0$. Lemma \ref{lem:overapprove} then implies that $ \sumpayoff \left( \strat^{*'}; \experiment' \right) \leq \sumpayoff \left( \strat^{\delta}_{\experiment'}; \experiment' \right)$, which coins the result. 

    To show this, I construct another experiment $\experiment^{\textrm{re}}$ under which I will use compare two strategies, $\strat_{\textrm{re}}$ and $\strat_{\textrm{re}}^{\delta}$, that replicate the outcomes of the strategies $\strat'$ and $\strat^{\delta}_{\experiment'}$, respectively. The experiment $\experiment^{\textrm{re}}$ has three possible outcomes, $\left\{ s_L^{\textrm{re}}, s_{\delta}^{\textrm{re}}, s_H^{\textrm{re}} \right\}$. Conditional on the applicant's quality $\quality$, its outcome distribution is independent from any other information any evaluator sees, and is given by the following pmf $p_{\quality}^{\textrm{re}}$:
    %
    \begin{align*}
        p_{\quality} (s^{\textrm{re}}) = 
        \begin{cases}
            1 - r_{\quality} ( \strat^*; \experiment ) & s = s^{\textrm{re}}_H \\
            \delta \times p_{\quality}' ( s_{j+1} ) & s = s^{\textrm{re}}_{\delta} \\
            r_{\quality} \left( \strat^*; \experiment \right) - \delta \times p_{\quality}' ( s_{j+1} )
            & s = s^{\textrm{re}}_L
        \end{cases}
    \end{align*}
    %
    Define the strategies $\strat_{\textrm{re}}$ and $\strat_{\textrm{re}}^{\delta}$ for this experiment as follows:
    %
    \begin{align*}
        \strat_{\textrm{re}}(s) &= 
        \begin{cases}
            1 & s = s^{\textrm{re}}_H \\
            0 & s = s^{\textrm{re}}_{\delta} \\
            0 & s = s^{\textrm{re}}_L
        \end{cases}
        &
        \strat_{\textrm{re}}^{\delta} &= 
        \begin{cases}
            1 & s = s^{\textrm{re}}_H \\
            1 & s = s^{\textrm{re}}_{\delta} \\
            0 & s = s^{\textrm{re}}_L
        \end{cases}
    \end{align*}

    Now note that these two strategies replicate the outcomes of the strategies $\strat'$ and $\strat^{\delta}_{\experiment'}$, respectively. Under $\strat_{\textrm{re}}(s)$, the probability that a buyer trades, conditional on the seller's quality, is the same as it is under strategy $\strat'$ (or $\strat^{*}$, which it replicates), and under $\strat_{\textrm{re}}^{\delta}$, it is the same as it is under $\strat^{\delta}_{\experiment'}$. 

    So, the difference between efficiency under these two strategies is determined by the \textit{marginal reject} who:
    %
    \begin{itemize}
        \item is rejected by \textit{every} buyer under the strategy $\strat_{\textrm{re}}$.
        \item is accepted by \textit{at least one} buyer under the strategy $\strat_{\textrm{re}}^{\delta}$.
    \end{itemize}
    %
    Where $\mathbf{s^{\textrm{\textbf{re}}}} = \left\{ s^1, ..., s^n \right\}$ is the seller's signal profile under the experiment $\experiment^{\textrm{re}}$, he has:
    %
    \begin{itemize}
        \item \textit{no} $s_H^{\textrm{re}}$ signals; $s^i \neq s_H^{\textrm{re}}$ for all $i \in \{1,2,...,n\}$ and
        \item \textit{at least one} $s_{\delta}^{\textrm{re}}$ signal; there exists some $i \in \{1,2,...,n\}$ such that $s^i = s_H^{\textrm{re}}$.
    \end{itemize}
    %
    Thus we have:
    %
    \begin{align*}
        \sumpayoff ( \strat^{\delta}_{\experiment'} ; \experiment') - 
        \sumpayoff ( \strat'; \experiment' )
        &=
        \sumpayoff ( \strat^{\delta}_{\textrm{re}} ; \experiment^{\textrm{re}}) - 
        \sumpayoff ( \strat_{\textrm{re}}; \experiment^{\textrm{re}} ) 
        \\
        &=
        \Prob \left( \textrm{marginal reject} \right) \times
        \underbrace{
            \left[ 
            \Prob \left( \quality = H \mid \textrm{marginal reject} 
            \right)
            -
            c
        \right]
        }_{(2)}
    \end{align*}

    The expression labelled (2) above equals:
    %
    \begin{align*}
        \sum\limits_{i=1}^{n}
        \frac{
            \Prob \left( i \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - i \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }{
            \sum\limits_{k = 1}^{n} \Prob \left( k \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - k \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }   
        \times
        %\\
        \Prob \left( \quality = H \mid i \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n-i \textrm{ }s_{L}^{\textrm{re}} \textrm{ signals} \right) - c
    \end{align*}

    Since the probability that a buyer observes the $s_{\delta}^{\textrm{re}}$ signal is proportional to $\delta$, we have\footnote{See expression \ref{eqn:thmbinary_limit} and the surrounding discussion in the proof of Theorem \ref{thm:intensive_binary} for a more detailed explanation of this.}:
    %
    \begin{equation*}
        \lim\limits_{\delta \to 0}
        \frac{
            \Prob \left( i \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - i \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }{
            \sum\limits_{k = 1}^{n} \Prob \left( k \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - k \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }
        = 0 
    \end{equation*}
    %
    Therefore, we get:
    %
    \begin{align*}
        &\lim\limits_{\delta \to 0}
        \sum\limits_{i=1}^{n}
        \frac{
            \Prob \left( i \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - i \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }{
            \sum\limits_{k = 1}^{n} \Prob \left( k \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n - k \textrm{ } s_{L}^{\textrm{re}} \textrm{ signals} \right)
        }   
        \times
        %\\
        \Prob \left( \quality = H \mid i \textrm{ } s_{\delta}^{\textrm{re}} \textrm{ and } n-i \textrm{ }s_{L}^{\textrm{re}} \textrm{ signals} \right) - c
        \\[0.2cm]
        &\lim\limits_{\delta \to 0} \Prob \left( \quality = H \mid \textrm{one } s_{\delta}^{\textrm{re}} \textrm{ signal and } n - 1 \textrm{  } s_L^{\textrm{re}} \textrm{ signals} \right) - c
        \\[0.2cm]
        \propto 
        &\lim\limits_{\delta \to 0} 
        \frac{\prior}{1 - \prior} \times 
        \frac{ p_H' (s_{j+1}) }{ p_L' (s_{j+1}) } \times 
        \left( 
            \frac{
                r_H (\strat^*; \experiment) - \delta \times p_H' (s_{j+1})
            }{
                r_L (\strat^*; \experiment) - \delta \times p_L' (s_{j+1})
            }
        \right)^{n-1} - \frac{c}{1-c}
        \\[0.2cm]
        =
        &\frac{\prior}{1 - \prior} \times \frac{s_{j+1}}{1 - s_{j+1}} \left( \frac{r_H (\strat^*; \experiment)}{r_L (\strat^*; \experiment)} \right)^{n-1} - \frac{c}{1-c}
    \end{align*}

\end{proof}

