\section{Problem types}

Here we give further details of the adjoint approach used for each solver type.

\subsection{Eigenvalue problems}
\texttt{Dedalus} eigenvalue problems take the generalized form
%
\begin{equation}
\left(\lambda \vec{M}(\vec{p}) + \vec{L}(\vec{p})\right)\vec{X} = 0,
\end{equation}
%
meaning the adjoint eigenvalue problem is simply
%
\begin{equation}
\left(\bar{\lambda}\vec{M}^\dagger(\vec{p}) + \vec{L}^\dagger(\vec{p})\right)\vec{Y} = 0.
\end{equation}
%
For dense solves, the left eigenvectors and eigenvalues can be returned by the eigenvalue library routines wrapped in \texttt{scipy.linalg}.
For sparse solves which find a small number of eigenmodes near a target eigenvalue, a shift-invert method is used, requiring an LU decomposition of a matrix pencil of $\vec{M}$ and $\vec{L}$.
For solving the adjoint eigenvalue problem, this LU decomposition can be reused, leading to significant computational savings for the adjoint solve.

Once the adjoint eigenvalue problem is solved, the sensitivity of the eigenvalue $\lambda$ with respect to parameters is obtained with the equation (see \cite{Luchini_2014}, for example)
%
\begin{equation}
\pderiv{\lambda}{\vec{p}} = -\frac{\langle \vec{Y},\left(\lambda\pderiv{ \vec{M}}{\vec{p}}+\pderiv{\vec{L}}{\vec{p}}\right)\vec{X}\rangle}{\langle \vec{Y}, \vec{M}\vec{X}\rangle}.
\label{equ:eigenvalue_sens}
\end{equation}
%
The sensitivity of the eigenvector with respect to parameters is then
%
\begin{equation}
(\lambda \vec{M}(\vec{p})+\vec{L}(\vec{p}))\pderiv{\vec{X}}{\vec{p}}=-\left( \vec{M}\pderiv{\lambda}{\vec{p}}+\lambda \pderiv{\vec{M}}{\vec{p}} + \pderiv{\vec{L}}{\vec{p}}\right)\vec{X}.
\label{equ:eigenvector_sens}
\end{equation}
%
This is a singular equation when $\lambda$ is a generalized eigenvalue, but from the Fredholm alternative theorem, it is solvable when the right hand side is orthogonal to the adjoint eigenvector $\vec{Y}$.
This directly gives the eigenvalue sensitivity equation (\ref{equ:eigenvalue_sens}), and therefore there exists a unique solution for the eigenvector sensitivity that is orthogonal to $\vec{X}$.
This sensitivity analysis naturally carries forward to higher order derivatives, as outlined by \cite{Mensah_2020}.

\subsection{Linear boundary value problems}
\texttt{Dedalus} LBVPs take the form
%
\begin{equation}
\vec{L}\vec{X}=\vec{F}(\vec{p}),
\end{equation}
%
so the adjoint state equation is simply
%
\begin{equation}
\vec{L}^\dagger\vec{Y}=\vec{G},
\end{equation}
%
for a right-hand-side $\vec{G}$ (that depends on the cost functional or upstream solves).
The LU decomposition used for the forward solve can be reused for the adjoint solve. 
A VJP of $\vec{F}$ with cotangents $\vec{Y}$ then propagates sensitivities to the parameters $\vec{p}$ on which $\vec{F}$ depends.

\subsection{Nonlinear boundary value problems}
\texttt{Dedalus} nonlinear boundary value problems can be written as
%
\begin{equation}
\vec{L}\vec{X}=\vec{F}(\vec{X}, \vec{p}),
\end{equation}
%
and is solved via Newton-Kantorovich iterations.
The adjoint of this solve is obtained via the linearization of the final solution stage, solving
%
\begin{equation}
\underbrace{\left(\vec{L}-\pderiv{\vec{F}}{ \vec{X}}\right)^\dagger}_{\vec{H}}\vec{Y} = \vec{G},
\end{equation}
%
for a right-hand-side $\vec{G}$ (that depends on the cost functional or upstream solves). 
The factorization of $\vec{H}$ from the final Newton iteration is reused for the adjoint state equation.
A VJP of $\vec{F}$ with cotangents $\vec{Y}$ then propagates sensitivities to the parameters $\vec{p}$ and state $\vec{X}$.

\subsection{Initial value problems}

\texttt{Dedalus} IVPs take the form
%
\begin{equation}
\vec{M}\partial_t\vec{X} + \vec{L}\vec{X} = \vec{F}(\vec{X}, \vec{p}, t),
\end{equation}
%
which are either solved via a multistep IMEX scheme \cite{Wang_2008} or a Runge-Kutta IMEX scheme \cite{Ascher_1997}.
For both of these timestepping schemes, each step requires computing the explicit terms $\vec{F}$, solving linear systems, and updating the state $\vec{X}$.
To provide the adjoint of this sequence, we have manually implemented the adjoint of the timestepping base classes (for an example of how to derive the adjoint timestepping schemes, see \cite{Mannix_2024}).
An $s$-step multistep IMEX scheme takes the form
%
\begin{equation}
(a^n_{0}\vec{M}+b^n_{0}\vec{L})\vec{X}_{n}=\sum_{i=1}^{s}\left[c^n_i\vec{F}(\vec{X}_{n-i})-(a^n_i\vec{M}+b^n_i\vec{L})\vec{X}_{n-i}\right],
    \label{equ:imex}
\end{equation}
%
where the coefficients $(a^n_i, b^n_i, c^n_i)$ depend on the timestep at step $n$, and revert to lower order multistep IMEX schemes for early iterations where not enough steps are computed for higher order schemes. 
The adjoint of this scheme is
%
\begin{equation}
(a_{0}^n\vec{M}+b_{0}^n\vec{L})^\dagger\vec{Y}_{n}=\sum_{i=1}^s\left(c^{n+i}_i\pderiv{\vec{F}(\vec{X}_{n})}{\vec{X}_{n}}-(a^{n+i}_i\vec{M}+b^{n+i}_i\vec{L})\right)^\dagger\vec{Y}_{n+i}.
 \label{equ:IMEX_adjoint}
\end{equation}
%
Similarly, a Runge-Kutta IMEX scheme with $s$ stages is
%
\begin{equation}
(\vec{M}+\textrm{d}t^nH_{i,i}\vec{L})\vec{X}_{n,i}=\vec{M}\vec{X}_{n,0}+\textrm{d}t^n\sum_{j=0}^{i-1}[A_{i,j}\vec{F}_{n,j}-H_{i,j}\vec{L}\vec{X}_{n,j}],
\end{equation}
%
with $\vec{X}_n=\vec{X}_{n,0}=\vec{X}_{n-1,s}$ and where $\textrm{d}t^n$ is the timestep at iteration $n$. 
This has the adjoint
\begin{equation}
    (\vec{M}+\textrm{d}t^nH_{i,i}\vec{L})^\dagger \vec{Y}_{n,i} =
    \begin{cases}
    \vec{Y}_{n+1,0}, & \textrm{if } i=s,\\
    \sum_{j=i+1}^{s} \textrm{d}t^n\left(A_{j,i}\pderiv{\vec{F}_{n,i}}{\vec{X}_{n,i}}-H_{j,i}\vec{L}\right)^\dagger\vec{Y}_{n,j}, & \textrm{if } 0<i<s,
    \end{cases}
\end{equation}
%
with
%
\begin{equation}
    \vec{Y}_{n,0}=\sum_{j=1}^{s} \left(\vec{M}^\dagger+\textrm{d}t^n\left[A_{j,0}\pderiv{ \vec{F}_{n,0}}{x_{n,0}} -H_{j,0}\vec{L}\right]^\dagger\right)\vec{Y}_{n,j},
\end{equation}
%
and where $\vec{Y}_n=\vec{Y}_{n,0}=\vec{Y}_{n-1,s}$.

In both cases we see that an adjoint step requires VJPs of $\vec{F}$ with cotangents, solving linear systems given via transposes of the forward problem matrices, and updating the cotangents.
The LU decompositions in the direct solve loop are reused where possible, i.e.\ unless they must be rebuilt due to a change in the timestep. 
The VJPs of $\vec{F}$ are performed using the automatic differentiation technique discussed in the manuscript.
As the state at each iteration of the forward solve is required to compute VJPs in the adjoint solve, checkpointing is used using the {checkpoint\_schedules} library \cite{Dolci2024}, which includes many state-of-the-art checkpointing schemes \cite{Stumm_2009, Aupy_2016, Aupy_2017, Pringle_2016, Herrmann_2020, Maddison_2024}.
This allows the user to easily choose between memory and disk based checkpointing.

The adjoint timestepping schemes propagate sensitivities backwards in time from the cotangents defined at the final-time. 
These final-time-condition cotangents stem from VJPs with upstream calculations which can be the cost functional, or other solvers such as LBVPs, NLVPs or other IVPs.
Although it seems that this formulation only provides the sensitivities with respect to each direct state $\vec{X}_n$, we can obtain the sensitivity with respect to constant parameters $\vec{p}$ by adding them to the state $\vec{X}$. 
Similarly, if the cost functional depends on a quantity $\mathcal{J}_I$ integrated over $t$, we can include this in the equation set by including the ODE $\partial_t \mathcal{I} = \mathcal{J}_I$.
This means that the integrated quantity at the final iteration $\mathcal{I}_n$ is obtained with the same accuracy as the forward integration, and its influence on the cotangent calculation is now naturally included through the adjoint timestepping routine.

\section{Example implementation details}
Here we give further details of the implementations for each example.

\subsection{Parametric sensitivity and numerical continuation}
The problem is discretized in the wall-normal direction with Chebyshev polynomials with $256$ modes. 
The streamwise and spanwise directions are parameterized by wavenumbers $\alpha$ and $\beta$. 
A sparse eigenvalue solve is performed with the \texttt{scipy.sparse.eigs} routine which wraps \texttt{ARPACK}.

\subsection{Nonlinear optimization}
The ball is discretized with spin-weighted spherical harmonics in the longitudinal and latitudinal dimensions and one-sided Jacobi polynomials in the radial direction \cite{Vasil_2019}. 
We use spherical harmonics up to degree $\ell=15$, and a radial resolution up to polynomials of maximum degree $31$.
Nonlinear terms are dealiased using a $3/2$-dealiasing rule. A second order semi-implicit multistep BDF scheme is used with fixed timestep $\Delta t=5\times10^{-4}$.
We have checked that increasing the resolution and decreasing the timestep does not significantly affect the results.
The direct solution is provided by solving an LBVP to obtain $\vec{u}$ from $\boldsymbol{\omega}$, followed by an IVP to evolve either $\vec{A}$ or $\vec{B}$.
The adjoint solve requires propagating cotangents back from the cost functional through the IVP and then through the LBVP.

\subsection{Resolvent analysis}
The radial direction in the disk is discretized with Zernike polynomials \cite{Vasil_2016} up to a maximum degree of 127, with the annular and spanwise directions parameterized by wavenumbers $m$ and $k$.
A spectrally accurate weight matrix $\vec{W}$ that discretizes the $L^2$-norm is generated with Zernike quadrature. 
The action of the resolvent matrix $\boldsymbol{\mathcal{H}}$ on a forcing vector $\hat{\vec{f}}$ is obtained via an LBVP.
The optimal basis that maximizes the Rayleigh quotient
%
\begin{equation}
\sigma=\frac{\|\boldsymbol{\mathcal{H}}\hat{\vec{f}}\|_\vec{W}}{\|\hat{\vec{f}}\|_\vec{W}},
\end{equation}
%
is found by computing the singular value decomposition (SVD) of $\vec{R}_\vec{M}=\vec{M}^{-1}\boldsymbol{\mathcal{H}}\vec{M}$, where $\vec{M}$ is the Cholesky decomposition of the weight matrix, $\vec{W}=\vec{M}^\dagger\vec{M}$ (trivial here since $\vec{W}$ is diagonal).
Finding the SVD requires matrix-free application routines for both $\boldsymbol{\mathcal{H}}_\vec{M}$ and $\boldsymbol{\mathcal{H}}_\vec{M}^\dagger$, the latter of which requires the adjoint of the LBVP.

\subsection{Phase reduction analysis}
Time is discretized with a complex-Fourier basis with $512$ modes. Dealiasing is performed on a grid twice the size to properly account for cubic nonlinearities.

\section{Verification}
In this section we perform verification tests to ensure that our computed gradients are consistent with the direct problem. 
For the plane-Poiseuille and optimal dynamo examples, we use the Taylor-remainder test (see \cite{Farrell2013}, for example).
This test checks that
%
\begin{equation}
    \mathcal{J}(\vec{p}+\epsilon \vec{p}')=\mathcal{J}(\vec{p}) + \epsilon \langle \vec{Y}, \vec{p}'\rangle + \mathcal{O}(\epsilon^2),
\end{equation}
%
where $\vec{p}'$ is a perturbation, and $\vec{Y}$ is the computed cotangent. 
This test confirms the correctness of $\vec{Y}$ by showing that
%
\begin{equation}
|\mathcal{J}(\vec{p}+\epsilon \vec{p}')-\mathcal{J}(\vec{p})-\epsilon \langle \vec{Y}, \vec{p}'\rangle| \approx 0,
\end{equation}
%
and decays at a second order in $\epsilon$.
This provides a simple and effective test for verifying cotangents and can be applied for linear and nonlinear problems. 
The results of these Taylor-remainder tests are shown in table \ref{tab:verification}, showing excellent accuracy of the computed gradients. 
We also plot the remainders for a range of values of $\epsilon$ in Fig.\ \ref{fig:verification}, showing that the remainders decay at second order over a range of perturbation sizes.

For the linear tests, direct error metrics are shown in Table \ref{tab:verification_linear}, and again indicate that the discrete adjoint is computed correctly.
For the pipe-flow example, we use the fact that $\boldsymbol{\mathcal{H}}_\vec{M}$, is a linear operator to directly verify the adjoint relation
%
\begin{equation}
\langle \vec{Y}, \boldsymbol{\mathcal{H}}_\vec{M}\vec{X}\rangle =\langle \boldsymbol{\mathcal{H}}_\vec{M}^\dagger\vec{Y}, \vec{X}\rangle.
\end{equation}
%
For the FitzHugh-Nagumo equation, we check the tangential phase tendency
%
\begin{equation}
Z_u\deriv{u_0}{t} + Z_v\deriv{v_0}{t} = 1,
\label{eqn:fitzhugh_error}
\end{equation}
%
for all times. 
This test requires that the phase sensitivity function is the gradient of the phase function $\Phi((u,v)^T)$ evaluated on the limit cycle \cite{Ermentrout2010}. 

