\begin{prop}\label{prop:threedim}
    Let $X$ be a normal variety with rational singularities with $d\coloneqq \dim X$, and let $\pi\colon Y\to X$ be a log resolution with reduced exceptional divisor $E$.
    Suppose that $X$ is quasi-$F$-injective.
    Then 
    \[
    C^{-1}_{n}\colon R^{2}\pi_{*}\Omega^{d-1}_Y(\log E)(-E)\to R^{2}\pi_{*}G_n\Omega^{d-1}_Y(\log E)(-E)
    \]
    is injective for all $n\geq 0$.
\end{prop}
\begin{proof}
    Since the assertion is local on $X$, we may assume that $X=\Spec R$ is affine.
    If $d\leq 2$, then the assertion is obvious since $R^{2}\pi_{*}\Omega^{d-1}_Y(\log E)(-E)=0$.
    Thus, we may assume that $d\geq 3$.
    Let $x\in X$ be a closed point, and let $\m\subset R$ be the maximum ideal corresponds to $x\in X$.

    Since $X$ is quasi-$F$-injective, we can take $l\geq1$ such that $H^{d}_{\m}(\sO_X)\to H^{d}_{\m}(Q_{X,l})$ is injective.
By \eqref{diagram:Q Vs O}, we have the following commutative diagram
\[
\begin{tikzcd}
H^{d-1}_{\m}(Q_{X,l})\arrow[r, twoheadrightarrow]\arrow[d] & H^{d-1}_{\m}(\mathcal{B}_{l,X})\arrow[d,"R_{l-1}"]\\
  \mathllap{0\,=\,\, } H^{d-1}_{\m}(F_{*}\sO_X)\arrow[r]& H^{d-1}_{\m}(\mathcal{B}_{X}),
\end{tikzcd}
\]
where the top horizontal arrow is surjective $H^{d}_{\m}(\sO_X)\to H^{d}_{\m}(Q_{X,l})$ is injective, and $H^{d-1}_{\m}(F_{*}\sO_X)=0$ since $X$ is Cohen--Macaulay.
Thus, the restriction 
\[
H^{d-1}_{\m}(\mathcal{B}_{l,X})\xrightarrow{R_{l-1}} H^{d-1}_{\m}(\mathcal{B}_X)
\] is a zero map.
By Lemma \ref{lem:vanishing of higher B} and Remark \ref{rem:B and BOmega}, the above map coincides with a map
\[
H^{d-1}_{\m}(R\pi_{*}B_l\Omega^1_Y)\xrightarrow{C_{l-1}} H^{d-1}_{\m}(R\pi_{*}B\Omega^1_Y),
\]
and thus this is also a zero map.
Recall that $B_n\Omega^1_Y=B_n\Omega^1_Y(\log E)$ for all $n\geq 0$ by Lemma \ref{lem:FOmega^{d-1}/ZOmega} (1).
Thus, local duality \cite[\href{https://stacks.math.columbia.edu/tag/0AAK}{Tag 0AAK}]{stacks-project} yields that
\[
\mathcal{H}^{-d+1}R\sHom_{\sO_X}(R\pi_{*}B\Omega^1_Y(\log E),\omega^{\bullet}_X)\to \mathcal{H}^{-d+1}R\sHom_{\sO_X}(R\pi_{*}B_l\Omega^1_Y(\log E),\omega^{\bullet}_X)
\]
is a zero map.
By Grothendieck duality, 
\[
R^1\pi_{*}\sHom_{\sO_Y}(B\Omega^1_Y(\log E),\omega_Y)\to R^1\pi_{*}\sHom_{\sO_Y}(B_l\Omega^1_Y(\log E),\omega_Y)
\]
is a zero map.
Since we have
\[
\sHom_{\sO_Y}(B_n\Omega^1_Y(\log E),\omega_Y)\cong \frac{F^n_{*}\Omega^{d-1}_Y(\log E)(-E)}{Z_n\Omega^{d-1}_Y(\log E)(-E)}
\]
for all $n\geq 0$ by Lemma \ref{lem:preliminaries-duality} (3),
\[
R^{1}\pi_{*}\left(\frac{F_{*}\Omega^{d-1}_Y(\log E)(-E)}{Z\Omega^{d-1}_Y(\log E)(-E)}\right)\to R^{1}\pi_{*}\left(\frac{F^l_{*}\Omega^{d-1}_Y(\log E)(-E)}{Z_l\Omega^{d-1}_Y(\log E)(-E)}\right)
\]
is a zero map.
By \eqref{GGOmega/Z,iterated,specail}, we have the following commutative diagram:
\begin{tiny}
\[
\begin{tikzcd}
F^n_{*}R^{1}\pi_{*}\left(\frac{F_{*}\Omega^{d-1}_Y(\log E)(-E)}{Z\Omega^{d-1}_Y(\log E)(-E)}\right)\arrow[r]\arrow[d,"0"] & R^{2}\pi_{*}G_n\Omega^{d-1}_Y(\log E)(-E) \arrow[r,"C_{n+1,n}^{-1}"]\arrow[d,equal] & R^{2}\pi_{*}G_{n+1}\Omega^{d-1}_Y(\log E)(-E) \arrow[d,"C^{-1}_{n+l,n+1}"] \\
F^n_{*}R^{1}\pi_{*}\left(\frac{F^l_{*}\Omega^{d-1}_Y(\log E)(-E)}{Z_l\Omega^{d-1}_Y(\log E)(-E)}\right)\arrow[r] &R^{2}\pi_{*}G_n\Omega^{d-1}_Y(\log E)(-E)\arrow[r,"C^{-1}_{n+l,n}"]& R^{2}\pi_{*}G_{n+l}\Omega^{d-1}_Y(\log E)(-E)
\end{tikzcd}
\]
\end{tiny}
for all $n\geq 0$.
By diagram chasing, 
\[
C^{-1}_{n+1,n}\colon R^{2}\pi_{*}G_n\Omega^{d-1}_Y(\log E)(-E)\to R^{2}\pi_{*}G_{n+1}\Omega^{d-1}_Y(\log E)(-E)
\]
is injective for all $n\geq 0$.
Since we have a decomposition \eqref{eq:decomposition,specail}, 
    \[
    C_n^{-1}=C_{n,n-1}^{-1} \circ\cdots \circ C_{1,0}^{-1}, 
    \]
    the map
\[
    C_{n}^{-1}\colon R^{2}\pi_{*}\Omega^{d-1}_Y(\log E)(-E)\to R^{2}\pi_{*}G_n\Omega^{d-1}_Y(\log E)(-E)
    \]
    is injective for all $n\geq 0$, as desired.
\end{proof}

\begin{proof}[Proof of Theorem \ref{introthm:injective action}]
    The assertion follows from Propositions \ref{prop:higherdim} and \ref{prop:threedim}.
\end{proof}


\begin{proof}[Proof of Theorem \ref{Introthm:F-inj}]
    The assertion follows from Theorems \ref{Intromain:up to C} and \ref{introthm:injective action}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{Introthm:SFR}]
    Since $X$ is strongly $F$-regular, it is $F$-injective.
    By \cite[Theorem 3.5]{Baudin-Kawakami-Rysler}, $X$ has rational singularities.
    Therefore, the assertion follows from Theorem \ref{Introthm:F-inj}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{Introthm:klt}]
    By \cite[Corollary 1.3]{ABL}, $X$ has rational singularities.
    By \cite[Theorem A]{KTTWYY2}, $X$ is quasi-$F$-pure, and in particular, quasi-$F$-injective (Remark \ref{rem:quasi-F-inj}).
    Then the assertion follows from Theorems \ref{Intromain:up to C} and \ref{introthm:injective action}.
\end{proof}

\begin{eg}\label{eg:counterex}
   Fix a positive integer $d\geq 3$ and a prime number $p$.
   By \cite[Theorem 2 and Corollary on p.~519]{Mukai}, there exists a smooth projective variety $Z$ of $\dim Z=d-1$ and an ample Cartier divisor $A$ on $Z$ such that $H^0(Z,\Omega^1_Z(-A))\neq 0$.
   Let $X$ be the affine cone $\Spec \bigoplus_{m\geq 0} H^0(Z,\sO_Z(mA))$, and let $\pi\colon Y\to X$ be the blow-up at the vertex of the affine cone.
   Then $\pi\colon Y\to X$ is a log resolution, and 
   \[
   R^{d-1}\pi_{*}\Omega^{d-1}_Y(\log E)(-E)\neq 0 .
   \]
   In fact, by the reside exact sequence, we have a short exact sequence
   \[
   0\to \Omega^{d-1}_Y(-E) \to  \Omega^{d-1}_Y(\log E)(-E) \to \Omega^{d-2}_E(-E) \to 0.
   \]
   Then we have an exact sequence
   \[
   R^{d-1}\pi_{*}\Omega^{d-1}_Y(\log E)(-E) \to R^{d-1}\pi_{*}\Omega^{d-2}_E(-E) \to R^d\pi_{*}\Omega^{d-1}_Y(-E)=0.
   \]
   Since we have
   \[
   R^{d-1}\pi_{*}\Omega^{d-1}_E(-E)=H^{d-1}(Z, \Omega^{d-1}_Z(A))\cong H^0(Z,\Omega^1_Z(-A))\neq 0,
   \]
   we conclude.
\end{eg}




\begin{rem}
    It is known that Steenbrink vanishing is related to extension theorems for differential forms (see \cite{GKK}).  
Let $X$ be a normal variety, and let $\pi\colon Y \to X$ be a log resolution with reduced exceptional divisor $E$.  
We consider the \emph{logarithmic extension property} for differential forms on $X$, namely, the surjectivity of the natural restriction map:
\[
\pi_{*}\Omega^i_Y(\log E) \hookrightarrow \Omega^{[i]}_X,
\]
where $\Omega^{[i]}_X$ denotes the sheaf of reflexive differential $i$-forms on $X$.  
Since the property is local on $X$, we may assume $X$ is affine.  
In this setting, we have the exact sequence:
\[
0\to \pi_{*}\Omega^i_Y(\log E) \to \Omega^{[i]}_X \to H^{1}_E(Y,\Omega^i_Y(\log E)),
\]
so that the logarithmic extension property reduces to the vanishing:
\[
H^{1}_E(Y,\Omega^i_Y(\log E)) = 0.
\]
Assume further that $X$ has only isolated singularities.  
Then, by formal duality, we obtain:
\[
H^{1}_E(Y,\Omega^i_Y(\log E)) \cong R^{d-1}\pi_{*}\Omega^{d-i}_Y(\log E)(-E),
\]
which shows that the extension property follows from Steenbrink-type vanishing.  
In particular, Theorems \ref{Introthm:F-inj}, \ref{Introthm:SFR} and \ref{Introthm:klt} yield the logarithmic extension property for one-forms on isolated
rational singularities that has dimension $\geq 4$ or dimension $\geq 3$ and $F$-injective, 
on isolated 3-dimensional strongly $F$-regular singularities, and on isolated 3-dimensional klt threefolds in $p>41$, when $E$ supports a $\pi$-ample divisor.
However, stronger results have already been established in \cite[Theorem D]{Kaw4}, \cite[Theorem A]{Kawakami-Sato}, and \cite[Theorem B]{Kawakami-Sato} respectively.  
For example, it is shown in \cite[Theorem A]{Kawakami-Sato} that the logarithmic extension property holds in all dimensions for strongly $F$-regular varieties and all proper birational morphisms $f\colon Z\to X$, without any assumption on the codimension of the singular locus.
\end{rem}







