\begin{document}
	\title{Brunn-Minkowski and Reverse Isoperimetric Inequalities for Dual Quermassintegrals}
	\author{Shay Sadovsky}
	\address{Courant Institute of Mathematical Sciences, New York University, NY}
	\email{ss20011@nyu.edu}

	\author{Gaoyong Zhang}
	\address{Courant Institute of Mathematical Sciences, New York University, NY}
	\email{gaoyong.zhang@nyu.edu}





\subjclass{52A40}

\keywords{Convex body, cube, dual Brunn-Minkowski theory, dual quermassintegrals, 
Brunn-Minkowski inequality, John's position, reverse isoperimetric inequality.}

\thanks{Research of Zhang supported, in part, by NSF Grant  DMS--2005875.}

	\maketitle


\begin{abstract}
	This paper establishes two new geometric inequalities in the dual Brunn-Minkowski theory. The first, originally conjectured by Lutwak, is the Brunn-Minkowski inequality for dual quermassintegrals of
origin-symmetric convex bodies. The second, generalizing Ball's volume ratio inequality, is a reverse isoperimetric inequality: among all origin-symmetric convex bodies in John's position, the cube maximizes the dual quermassintegrals.
\end{abstract}



\section{Introduction}
In his seminal paper \cite{lutwak1975}, Erwin Lutwak introduced the dual mixed volumes as a natural dual notion to that of the classical mixed volume (due to Minkowski, for more see \cite{Schneider-book-NEW}). These dual mixed volumes are defined there as follows: Given $K_1,\dots K_n \subseteq \RR^n$ compact convex sets with non-empty interiors that contain the origin, henceforth referred to as convex bodies, their dual mixed volume is given by
\begin{equation}
	\wt{V} (K_1,\dots, K_n)=\frac{1}{n} \int_{\Sph^{n-1}} \rho_{K_1}(u) \dots \rho_{K_n}(u)\, du
\end{equation}
where $\Sph^{n-1}$ is the usual $n-1$ dimensional unit sphere, and $\rho_K(x) = \sup\{\lambda \ge 0: \lambda x \in K\}$ is the radial function of the convex body $K$.

In the case where $K_1,\dots, K_j = K$ are equal, and $K_{j+1},\dots,K_n = B_2^n$ are equal to the unit ball, we denote
\begin{equation}\label{eq:def-radial}
	\wt{V}_{j}(K) = \wt{V} (K_1,\dots, K_n) = \frac{1}{n} \int_{\Sph^{n-1}}  \rho_{K}^j(u)\, du,
\end{equation}
and call this quantity the $j$-th dual quermassintegral or $j$-th dual volume of $K$. Indeed, this name is fitting, as the dual quermassintegrals have a geometric formulation as integrals over volumes of lower dimensional sections,
$$\wt{V_j}(K)=\frac{\omega_n}{\omega_j}\int_{G_{n,j}} \Vol_j(K\cap \xi)d\xi$$
in analogy to the definition of the usual quermassintegrals as integrals over volume of lower dimensional projections, where $\omega_j$ denotes the volume of the $j$-dimensional unit ball
and $G_{n,j}$ is the Grassmann manifold of $j$-dimensional subspaces.

For any $q\in \R$, the $q$-th dual quermassintegral of the convex body $K$ is defined by
\begin{equation}\label{d-v}
\wt V_q(K) = \frac1n \int_{\sn} \rho_K^q (u)\, du.
\end{equation}


We state the following well known alternative definition of the dual quermassintegral (as can be seen e.g. in \cite{gardner2007dual}). For $K\subseteq \RR^n$
\begin{equation}\label{eq:def-norm}
	\wt{V}_{q}(K) = \frac qn \int_K |x|^{q-n} \, dx, \ \ \ q>0.
\end{equation}
One may check that \eqref{eq:def-radial} and \eqref{eq:def-norm} are equivalent by switching to polar coordinates.

The normalized $q$-th dual quermassintegral of $K$ is
\begin{equation}\label{ndv}
\barV_q(K) = \Big(\frac1{n\omega_n} \int_{\sn} \rho_K^q (u)\, du\Big)^\frac1q = \Big(\frac{\wt V_q(K)}{\omega_n}\Big)^\frac1q.
\end{equation}
Then
\[
\barV_0(K) = e^{\frac1{n\omega_n}E(K)}, \ \ \ E(K)=\int_{\sn} \log \rho_K(u)\, du,
\]
where $E(K)$ is called the dual entropy of $K$.

In \cite{lutwak1975}, Lutwak proved the elementary properties of the dual mixed volumes, as well as several inequalities analogous to fundamental inequalities in convex geometry, such as a dual Alexandrov-Fenchel inequality and a dual isoperimetric inequality. These examples are only a fraction of the many dual problems and properties which can be found in what is today called the ``dual Brunn-Minkowski theory". In particular there exists a radial sum analogous to  the Minkowski sum, a dual Alexandrov-Fenchel inequality, a dual isoperimetric inequality, and a dual Minkowski problem, introduced in \cite{HLYZ-2018} analogously to the usual Minkowski problem of geometric measures. We refer the reader to the extensive work of Huang, Lutwak, Yang and Zhang on the dual Brunn-Minkowski theory in \cite{HLYZ-2016geometric} and the recent survey \cite{HYZ-2025-survey}.

In this work, we extend the dual theory to two new inequalities. The first of these inequalities is the Brunn-Minkowski inequality  of dual quermassintegrals which has been conjectured by Lutwak and presented in various talks and seminars by the group Lutwak-Yang-Zhang and their collaborators (as stated, e.g. in \cite{HYZ-2025-survey}).

\begin{conj}[Lutwak]
	If $K$ and $L$ are origin-symmetric convex bodies, then
	\[
	\wt V_j (K+L)^\frac1j \ge \wt V_j (K)^\frac1j + \wt V_j (L)^\frac1j, \ \ \ j=2, \ldots, n-1,
	\]
	with equality if and only if $K$ and $L$ are dilates of each other.
\end{conj}


We begin with showing that the conjectured Brunn-Minkowski inequality for $\wt{V}_j$ is true.
Recently, an amazing breakthrough in proving general Brunn-Minkowski inequalities by
using analytic tools has been achieved by
 Kolesnikov-Milman \cite{KM-ajm2018, KM-jfa2017} and
  Kolesnikov-Livshyts \cite{kolesnikov-livshyts}, which allowed Cordero-Erausquin and Rotem in \cite{cordero-rotem} to prove  Brunn-Minkowski inequalities for a large class of measures in $\rn$.
  As a corollary of these recent works, we present a solution to the conjecture, extended to all $q> 0$.

\begin{thm}\label{thm:BM}
	Let $K,L$ be origin-symmetric convex bodies in $\RR^n$. Then, for $0< q \le n$,
	\begin{equation}\label{eq:BM-Wj}
		 \wt{V}_{q}(K+ L)^{\frac{1}{q}} \ge \wt{V}_{q}(K)^{\frac{1}{q}}
 + \wt{V}_{q}(L)^{\frac{1}{q}},
	\end{equation}
\end{thm}
with equality if $K$ and $L$ are dilates of each other.

The equality cases of Lutwak's conjecture have yet to be resolved, and in fact are only known for the case of $q\le 1$, for which the inequality together with its equality condition were shown by Xi-Zhang in \cite{xi-zhang}. Note that the case of $q=n$ of \eqref{eq:BM-Wj}
is the classical Brunn-Minkowski inequality of origin-symmetric convex bodies.

We present the results of \cite{kolesnikov-livshyts} and \cite{cordero-rotem} and the resulting proof of the theorem in Section \ref{sec:dual-BM}.

Our second theorem follows the path of the reverse isoperimetric inequalities, firstly due to Ball \cite{Ball-lnm1988, ball1991volume} and later to Barthe \cite{barthe1998extremal}, Schechtman-Schmuckenschl\"ager \cite{schechtman1995concentration}, Schmuckenschl\"ager \cite{schmuckenschlager1999extremal},
Lutwak-Yang-Zhang \cite{LYZ-JDG2004, LYZ-AJM2007, LYZ-JDG2010}, Li-Leng \cite{LL-MZ2012},
Schuster-Weberndorfer \cite{SW-jdg2012}, Li-Huang-Xi \cite{LHX-aam2017}, and others.
They showed that several quantities of convex bodies are extremized by cubes, cross-polytopes,
 or simplices when the bodies are restricted to either John or Lowner position. We present
 such a reverse isoperimetric inequality for dual
quermassintegrals.

Denote by $B_p^n = \{x\in \RR^n:\|x\|_p\le 1\}$, $1\le p\le \infty$.

\begin{thm}\label{thm:reverse-isop}
	Let $K\subseteq \RR^n$ be an origin-symmetric convex body.
	If $K$ is in John's position, i.e. if $B_2^n$ is the ellipsoid of largest volume  contained in $K$, then
	\begin{equation}\label{eq:thm-reverse-isop}
		\barV_q(K) \le \barV_q(B_\infty^n), \ \  q\in (-\infty, n],    %\label{r-iso}
      \end{equation}
      with equality in each of the inequalities if and only if $K$ is a rotation of $B_\infty^n$.
\end{thm}

The case of $q=n$ of \eqref{eq:thm-reverse-isop} is Ball's volume ratio inequality of origin-symmetric
convex bodies \cite{Ball-lnm1988}.  For an arbitrary convex body $K$ that is in John's position,
Ball's volume ratio inequality says that the volume of $K$ is less than the volume of a regular simplex,
see \cite{ball1991volume}.

