        \cdot \alpha r_k \widetilde{\dhat}(k) \\
        &\leq (1 + (2220n+5080)\beta\eps +28\eps\log\left( \dhat^{-1}(u)\right) + 30\zeta \\
        &\hspace{13em} + (6np+2)\epsh +\sOh(\eps)) \cdot \frac{\bin(k)\widetilde{\dhat}(k)}{\dhat(k)}  
    \end{align*}
    The last inequality follows from assuming $(1110n+2540)\beta\eps +(3np+1)\epsh +14\eps\log\left( \dhat^{-1}(u)\right) + 15\zeta +\sOh(\eps) \leq \frac{1}{2}$.
    Next we bound the ratio $\frac{\widetilde{\dhat}(k)}{\dhat(k)}$ using \Cref{lem:dhatdist},
    \begin{align*}
        \sampdist(k) &\leq \Bigl(1+ (2220n+5080)\beta\eps +28\eps\log\left( \dhat^{-1}(u)\right)+ 30\zeta \\
        &\hspace{6em}+ (6np+2)\epsh +\sOh(\eps)\Bigr) \cdot (1 + w_k\eps_\dchat (k+2)) \cdot \bin(k)\\
        &\leq \Bigl(1+ (2220n+5080)\beta\eps +28\eps\log\left( \dhat^{-1}(u)\right)+ 30\zeta + (6np+2)\epsh +  \\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad w_k\eps_\dchat (k+2) + \sOh(\eps)\Bigr) \cdot \bin(k)
    \end{align*}
    Where $w_k = \max\left(\frac{\dhat(k-1)}{\dhat(k)}, \frac{\dhat(k+1)}{\dhat(k)}\right)$.
    Since $r_k \leq 1$, it follows that $\dhat(k) \geq \frac{\bin(k)}{\alpha}$ and $\dhat(k+1) = \frac{\bin(k+1)}{\alpha r_{k+1}}$. This implies $\frac{\dhat(k+1)}{\dhat(k)} \leq \frac{\bin(k+1)}{\bin(k) r_{k+1}}$. Similarly, we have $\frac{\dhat(k-1)}{\dhat(k)} \leq \frac{\bin(k-1)}{\bin(k) r_{k-1}}$. Combining these, $w_k$ can be upper bounded as follows, 
    \begin{align*}
        w_k &= \max\left(\frac{\dhat(k-1)}{\dhat(k)}, \frac{\dhat(k+1)}{\dhat(k)}\right) \leq \max\left(\frac{\bin(k-1)}{\bin(k)r_{k-1}}, \frac{\bin(k+1)}{\bin(k)r_{k+1}}\right)    
    \end{align*}
    This yields the following bound: $w_k \bin(k) \leq \max\left(\frac{\bin(k-1)}{r_{k-1}}, \frac{\bin(k+1)}{r_{k+1}}\right)$.
    Thus, $w_k \bin(k) \leq \max\left(\dhat(k-1), \dhat(k+1)\right) \leq \dhat(k-1)+ \dhat(k+1)$.
    Using this bound, we can upper bound the sum $\sum_{k=0}^{n} w_k\eps_\dchat (k+2) \bin(k)$ as follows, 
    \begin{align*}
        \sum_{k=0}^{n} w_k\eps_\dchat (k+2) \bin(k) &\leq \alpha\epsh \sum_{k=0}^{n} (k+2) \left(\dhat(k-1)+ \dhat(k+1)\right)\\
        &\leq 2\alpha\epsh(n+2)
    \end{align*}
    The last inequality follows from the fact that $k \leq n$, $\sum_{i=0}^{n-1} \dhat(i) \leq 1$ and $\sum_{i=1}^{n} \dhat(i) \leq 1$.  
    Therefore, the statistical distance between the sampler's distribution and the Binomial distribution is given by,
    \begin{align*}
        &\dtv(\sampdist, \bin) = \frac{1}{2} \sum_{k=0}^{n} \left|\sampdist(k) - \bin(k)\right|\\
        \leq& \frac{1}{2} \sum_{k=0}^{n} \left|(2220n+5080)\beta\eps +28\eps\log\left( \dhat^{-1}(u)\right) + 30\zeta + (6np+2)\epsh \right.\\
        &\hspace{15em} \left. + 2\alpha\epsh(n+2) + \sOh(\eps) \right| \cdot \bin(k) \\
        \leq& (1110n+2554)\beta\eps + 14\alpha\eps + 15\zeta + (3np + 1)\epsh + \alpha\epsh(n+2) + \sOh(\eps)\\
        =& (1110 \beta + 3cp + c + \alpha c) n\eps + 15\zeta + \sOh(\eps)
    \end{align*} 
    This completes the proof. \qed
\end{proof}
