\subsection*{Proof of \Cref{lem:dhatdist}}
{\dhatdistlem*}

\begin{proof}
Without loss of generality, let us assume that $\dhat(-1) = \dhat(n+1) = 0$. 
Let us also assume that the ideal output of $\lfloor\dinvhat(u)\rfloor$ is $k$, and let $k'$ be the value of $\lfloor{\dinvhat}(u)\rfloor$ as computed in \Cref{alg:btrapprox}. Note that $k' \in (1\pm \epsh) \dinvhat(u)$. Now, because, $\beta \geq 2 \lceil\log_2 n\rceil$, we have $\epsh\dinvhat(u) \leq c\eps n \leq 1$, and hence, $k' \in \{k-1, k, k+1\}$. Since for all $t \in [n]$,  $\Pr\limits_{u}\left(\lfloor\dinvhat(u)\rfloor = t\right) = \dhat(t)$, 
\begin{align*}
    \widetilde{\dhat}(k) &= \sum_{t \in \{k-1, k, k+1\}}\Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = t\right) \cdot \Pr_u\left(\lfloor\dinvhat(u)\rfloor = t\right)\\
    &= \sum_{t \in \{k-1, k, k+1\}}\Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = t\right) \cdot \dhat(t)
\end{align*}
Observe that, given $\lfloor\dinvhat(u)\rfloor = \crdy{t}$, $k' = \crdy{t}+1$ is possible only when $(1+\epsh)\dinvhat(u) \geq \crdy{t}+1$, that is, $\dinvhat(u) \geq \frac{\crdy{t}+1}{(1+\epsh)}$.
Therefore, given $\lfloor\dinvhat(u)\rfloor = \crdy{t}$, and assuming $\dinvhat(u)$ is uniformly distributed over the range $[\crdy{t}, \crdy{t}+1)$,
we have, 
\begin{align*}
    &\Pr_{\eps,u}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t}\right) \\
    =& \int_{v=\crdy{t}}^{v=\crdy{t}+1}\Pr_{\eps}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t} , \dinvhat(u) = v\right) \cdot \\
    &\qquad\qquad\qquad\qquad\qquad f\left(\dinvhat(u) =v \mid \lfloor\dinvhat(u)\rfloor = \crdy{t}\right) \,dv\\
    =&  \int_{v=\frac{\crdy{t}+1}{1+\epsh}}^{v=\crdy{t}+1}\Pr_{\eps}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t} , \dinvhat(u) = v\right) \,dv
\end{align*}
where $f$ is the uniform probability density function.
The last equality follows from the fact that, we have $\Pr_{\eps}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = t , \dinvhat(u) = v\right) = 0$ for $v \in \left[\frac{\crdy{t}}{1-\epsh}, \frac{\crdy{t}+1}{1+\epsh}\right]$. 

Since the error in the computation of $\dinvhat(u)$ is uniformly distributed over the range $[-\epsh, \epsh]$, therefore, 
$\Pr_{\eps}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t} , \dinvhat(u) = v\right) \leq 1/2$ for all $v \in \left[\frac{\crdy{t}+1}{1+\epsh}, \crdy{t}+1\right]$. 
Thus, we have 
$\Pr\limits_{\eps,u}\left(k' = \crdy{t}+1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t}\right) \leq \int_{v=\frac{\crdy{t}+1}{1+\epsh}}^{v=\crdy{t}+1} \frac{1}{2} \, dv = \frac{\epsh(\crdy{t}+1)}{2(1+\epsh)} \leq \frac{\epsh(\crdy{t}+1)}{3}$.
Similarly, we can upper bound the probability of $k'$ being $\crdy{t}-1$ given $\lfloor\dinvhat(u)\rfloor = \crdy{t}$, by $\Pr\limits_{\eps,u}\left(k' = \crdy{t}-1 \mid \lfloor\dinvhat(u)\rfloor = \crdy{t}\right) \leq \frac{\epsh (\crdy{t}+1)}{3}$.
Therefore, combining, we can upper bound the probability mass:
\begin{align*}
    \label{eq:hub}
    \widetilde{\dhat}(k) &\leq \frac{\epsh k}{3}  \dhat(k-1) + \dhat(k) + \frac{\epsh (k+2)}{3}  \dhat(k+1) \notag \leq \left(1+w_k\epsh (k+2)\right) \dhat(k)
\end{align*}
Next, observing that $\dinvhat(u) \in \left[\frac{k}{1-\epsh}, \frac{k+1}{1+\epsh}\right]$ ensures no possibility of error, we derive a lower bound for the probability of $k'=k$ given $\lfloor\dinvhat(u)\rfloor = k$ as 
\begin{align*}
    \Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = k\right) 
    &= \int_{v=k}^{v=k+1}\Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = k , \dinvhat(u) = v\right) \cdot\\
    &\qquad\qquad\qquad\quad f\left(\dinvhat(u) =v \mid \lfloor\dinvhat(u)\rfloor = k\right) \, dv\\
    \geq  \int_{v=\frac{k}{1-\epsh}}^{v=\frac{k+1}{1+\epsh}}&\Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = k , \dinvhat(u) = v\right) \, dv
\end{align*}
Since for all $v \in \left[\frac{k}{1-\epsh}, \frac{k+1}{1+\epsh}\right]$, $\Pr_{\eps,u}\left[k' = k \mid \lfloor\dinvhat(u)\rfloor = k , \dinvhat(u) = v\right] = 1$,
\begin{align*}
    \Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = k\right) \geq \frac{k+1}{(1+\epsh)} - \frac{k}{(1-\epsh)} \geq (1-\epsh(3k+1))
\end{align*}
Where the last inequality follows from the fact that $\frac{1}{1+\epsh} \geq 1 - \epsh$ and $\frac{1}{1-\epsh} \leq 1 + 2\epsh$ for $\epsh \leq \frac{1}{2}$. Consequently, $ \widetilde{\dhat}(k)$
%
 is at least 
 $\Pr_{\eps,u}\left(k' = k \mid \lfloor\dinvhat(u)\rfloor = k\right) \cdot \dhat(k) \notag = (1-\epsh(3k+1)) \dhat(k) $.
%
 %
  %
%
This completes the proof. \qed
\end{proof}

