\section{Background notions}\label{sec:background}
	Throughout this section let $X$ be a compact, connected, $\CAT$ $4$-manifold, potentially with non-empty boundary $\partial X$. 

	\begin{definition}\label{definition:pseudo_isotopy}
		Let $f,g\colon X\to X$ be a pair of $\CAT$-isomorphisms.  We say that $f$ is \emph{pseudo-isotopic} to $g$ if there exists a $\CAT$-isomorphism, called a \emph{pseudo-isotopy} \[
		F\colon X\times I\to X\times I
		\] such that 
    \begin{itemize}
        \item $F\vert_{X\times \{0\}}=f\times\Id\colon X\times\{0\}\to X\times\{0\}$
        \item $F\vert_{X\times\{1\}}=g\times\Id\colon X\times\{1\}\to X\times\{1\}$
        \item $F\vert_{\partial X\times I}=f\vert_{\partial X}\times \Id$.
    \end{itemize}  We say that $f$ and $g$ are \emph{isotopic} if they are pseudo-isotopic via a level-preserving pseudo-isotopy.
	\end{definition}

