\section{Dipole Polarizability}


A competing phenomenon in the determination of $Q_{_S}(2_{_1}^+)$ values in light nuclei is the $E1$-polarizability, which must be corrected for in Coulomb-excitation codes~\cite{czosnyka1983d}. The {\sc E1} polarization correction arises from virtual excitations of giant dipole resonance ({\sc GDR}) states,
which polarize the final excited level via the two-step process:  $\rvert i\rangle \rightarrow \rvert n\rangle \rightarrow \rvert f\rangle $ or $0_{_1}^+ \rightarrow 1_{_{GDR}}^-\rightarrow 2_{_1}^+$, for the general case of an even-even nucleus. Previous studies show that $E1$-polarizability corrections are necessary in order to reproduce the excitation probabilities measured for the $J = 1/2$ first excited levels in $^{7}$Li and $^{17}  $O~\cite{hausser1973e1,hausser1972nuclear,kuehner1982measurement}, where $Q_{_S}(J=1/2)=0$ and the $E1$ polarizability is the only second-order effect. This is included in the effective quadrupole interaction by the dimensionless polarizability parameter $\kappa$, which measures deviations between the
actual effects from the {\sc GDR} and the hydrodynamic model~\cite{orce2015new}. The value of $\kappa(0^+_{_1})$ can be determined from the $(-2)$ moment of the total photo-absorption cross section, $\sigma_{_{-2}}$~\cite{orce2015new,levinger1957migdal},
\begin{equation}
 \sigma_{_{-2}} = \int_{0}^{E_{\gamma}} \frac{\sigma_{_{total}}(E_{_{\gamma}})}{E_{_{\gamma}}^{^2}}~dE_{_{\gamma}} = 2.38 \kappa ~ A^{5/3} ~\mbox{$\upmu$b/MeV}.
\label{eq:238}
\end{equation}

% using the empirical $\sigma_{_{-2}}$ value~\cite{levinger1957migdal}, 
% \begin{equation}
% 	\sigma_{_{-2}}=\int_{0}^{E_{\gamma}} \frac{\sigma_{_{total}}(E_{_{\gamma}})}{E_{_{\gamma}}^{^2}}~dE_{_{\gamma}}. 
% 	\label{eq:sigma-2int2}
% \end{equation}




As mentioned before, the interference term $P_{_{02}}^{(1,2)}$ entails an $E1$ component. Similar to Eq.~\ref{eq:re}, the GDR effect can be approximated by~\cite{deBoer1968} 
\begin{equation}
 d_p(\xi,\vartheta) = \frac{P_{_{02}}^{(1,2)}(E1)}{P_{_{02}}^{(1)}} \approx -7.37\frac{ T_{lab} \sigma_{_{-2}}  }{(1+A_p/A_t)Z_tZ_tR^2} \phi(\xi,\vartheta),
\end{equation}
where $\phi(\xi,\vartheta)$ also contains kinematical information and varies between approximately 0.03 and 0.1~\cite{deBoer1968} and $R=1.25~A^{1/3}$ fm is the spherical nuclear radius. Ultimately, we can approximate the second-order excitation probability by the sum, $P_{_{02}}^{(2)} =  P_{_{02}}^{(1)}[1+r_{p}(\xi,\vartheta) + d_p(\xi,\vartheta) ]$.
% \begin{equation}
%  P_{_{02}}^{(2)} =  P_{_{02}}^{(1)}(1+r_{p}(\xi,\vartheta) + d_p(\xi,\vartheta) ).
% \end{equation}
However, there is currently no experimental data of $\sigma_{_{-2}}$ or $\kappa$ values for excited states in even-even nuclei.
Recent developments using the formalism of H\"ausser and collaborators~\cite{hausser1973e1} based on $E1$ and $E2$ matrix elements,
second-order perturbation theory and the hydrodynamic model,
show that $\sigma_{_{-2}}(2^+_{_1})$ and $\kappa(2^+_{_1})$ can be calculated as~\cite{Orce2024}
\begin{eqnarray}
\sigma_{-2}(2^+_{_1}) &=& 0.6\frac{Z A^{2/3} S(E1)}{\langle 0^+_{_1}\mid\mid \hat{E2} \mid\mid 2^+_{_1}\rangle} ~~\mbox{fm$^2/$MeV}, \label{eq:extd_kappa} \\
% {\langle i||\hat{M}(E2)||f\rangle} ~~\mbox{fm$^2/$MeV}, \\
\kappa(2^+_{_1}) &=& \frac{1}{0.00039\frac{A}{Z}}\frac{S(E1)}{\langle 0^+_{_1}\mid\mid \hat{E2} \mid\mid 2^+_{_1}\rangle}, \label{eq:extd_kappa2}
\end{eqnarray}
for the two-step process, $0_{_1}^+ \rightarrow 1_{_{GDR}}^-\rightarrow 2_{_1}^+$,
where Eqs.~\ref{eq:extd_kappa} and \ref{eq:extd_kappa2} satisfy Eq.~\ref{eq:238} and $S(E1)$ is defined as
\begin{equation}
 S(E1):= \frac{1}{2J_i+1}
 \sum_{J_n,\Delta T} W_{inf} \frac{\langle i\parallel\hat{E1}\parallel n\rangle \langle n\parallel\hat{E1}\parallel f\rangle}{E_{_{\gamma}}},
 \label{eq:SE1}
\end{equation}
in units of e$^2$fm$^2/$MeV,  where the sum considers all intermediate states $\rvert n\rangle = \rvert 1^-_{_{GDR}}\rangle$ connecting both the initial
$\rvert i \rangle = \rvert 0^+_{_1}\rangle$ and final $\rvert f \rangle =\rvert 2^+_{_1}\rangle$ states via isovector $E1$ transitions --- following the isospin selection rule $\Delta T = 1$ for $N=Z$ self-conjugate nuclei~\cite{isospinselection} ---
and $W_{inf}=W(1102,21)$ is the corresponding Racah W-coefficient~\cite{racah1942theory}.
Consequently, $\sigma_{_{-2}}(2^+_{_1})$ and $\kappa(2^+_{_1})$ values can be determined from theoretical models by computing $E1$ and $E2$ matrix elements.
The calculated $\kappa(2^+_{_1})$ value is then input in {\sc GOSIA}~\cite{czosnyka1983d} for further analysis.

