\section{{Exponentially fading memory signature and its first properties}}\label{sect:definition}
{\paragraph{Notations.} Throughout }this paper, $(\Omega, \F, (\F_t)_{t \in \R}, \P)$ will denote a filtered probability space. We will use the notion of increment semimartingales, i.e., processes $X$ such that, for all $s \in \R$, the process $(X_{s + t} - X_s)_{t \geq 0}$ is a semimartingale in the usual sense with respect to $(\F_{s+t})_{t \geq 0}$. In this case, the notion of stochastic integral can be generalized, and integration over the whole real line becomes possible. For details, we refer to the works of \citet*{basseoconnor2010martingaletypeprocessesindexedreal,OConnor2014}. This theory allows us to manipulate stochastic integrals on the real line in exactly the same way as standard stochastic integrals on $\R_+$. With a slight abuse of terminology, we will henceforth use the terms semimartingales and increment semimartingales interchangeably.

An important example of an increment semimartingale we will often use is a two-sided Brownian motion: a centered Gaussian process $W = (W_t)_{t \in \R}$ such that $W_0 = 0$, and for any $s \in \R$ and $t > 0$, the increment $W_{s + t} - W_s$ is distributed as $\mathcal{N}(0, t)$ and is independent of $\F_s$.

For $t_0 \in \R \cup \{-\infty\}$, we will denote the Itô integral by $\int_{t_0}^\cdot Y_t dX_t$ and the Stratonovich integral by $\int_{t_0}^\cdot Y_t \circ dX_t$. If both $X$ and $Y$ are continuous semimartingales, then we have the relation 
$$
\int_{t_0}^\cdot Y_t \circ dX_t = \int_{t_0}^\cdot Y_t dX_t  + \frac{1}{2} \int_{t_0}^\cdot d\langle X,Y\rangle_t.
$$
We denote by $\odot$ the Hadamard product: for two vectors $\bm{x} = (x^1, \ldots, x^d) \in \R^d$ and $\bm{y} = (y^1, \ldots, y^d) \in \R^d$, we define 
$$
\bm{x} \odot \bm{y} := (x^i y^i)_{i = 1, \ldots, d} \in\R^d.
$$
{We write $\bm x \prec \bm y$ if $x^i < y^i$ for $i = 1, \ldots, d$. We use $\lesssim$ to denote an inequality up to a positive constant, and $\lesssim_a$ to denote an inequality up to a positive constant depending on $a$.}

\subsection{Preliminaries on signatures}\label{subsection:prelimeray}
In this subsection, we recall the necessary notations related to the signatures. For a more detailed introduction of signatures and its properties, we refer to the work of \citet{Chevyrev2016}.

\paragraph{Definition of signature.}
Consider an $\R^d$-valued continuous semimartingale $X = (X_t)_{t \in [0, T]}$ defined on a finite interval $[0, T]$. Its signature over $[s, t] \subset [0, T]$ is nothing else but a collection of \textit{properly ordered} iterated Stratonovich integrals of different orders $n \in \N_0$,
\begin{equation}\label{eq:signature_word}
    \sigX[s, t]^\word{i_1 \cdots i_n} := \int_{s < u_1 < \cdots < u_n < t} \circ d X_{u_1}^{i_1} \cdots \circ d X_{u_n}^{i_n} = \int_s^t \sigX[u_n]^\word{i_1 \cdots i_{n-1}} \circ d X_{u_n}^{\word{i_n}},
\end{equation}
where $i_1, \ldots, i_n \in \{1, \ldots, d\}$. The iterated integrals of order $n \in \N_0$ are then the elements of $(\R^d)^{\otimes n}$. Let $\{e_1, \ldots, e_d\}$ denote the canonical basis of $\R^d$. Then, the basis of $(\R^d)^{\otimes n}$ is given by the vectors  
$$
e_{i_1} \otimes \ldots \otimes e_{i_n},\quad i_1, \ldots, i_n \in \{1, \ldots, d\},
$$ 
identified with words $\word{v} = \word{i_1 \ldots i_n}$ of length $|\word{v}| = n$ over the alphabet $\alphabet = \{\word{1}, \ldots, \word{d}\}$. This explains the indexation in \eqref{eq:signature_word}. For the particular case $n = 0$, we set $(\R^d)^{\otimes 0} \cong \R$, and denote the empty word corresponding to its basis vector by $\emptyword$. By convention, we set $ \sigX^\word{\emptyword} \equiv 1$.

This allows us to write the \textit{$n$-th level of signature} $\sigX[s, t]^n = (\sigX[s, t]^{\word{v}})_{|\word{v}| = n} \in (\R^d)^{\otimes n}$ shortly as 
\begin{equation}\label{eq:sig_definition}
    \sigX[s, t]^n := \int_{s < u_1 < \cdots < u_n < t} \circ d X_{u_1} \otimes \cdots \otimes \circ d X_{u_n}.
\end{equation}

The \textit{path signature} of $X$ is then given by a sequence of all signature levels, also called a {tensor sequence}:
\begin{equation}
    \sigX[s, t] := (1, \sigX[s, t]^1, \dots, \sigX[s, t]^n, \dots),
\end{equation}
which is an element of the \textit{extended tensor algebra}:
\begin{equation}
    \eTA := \left\{\bell = (\bell^n)_{n \geq 0} \colon \ \bell^n \in (\R^d)^{\otimes n} \right\}.
\end{equation}
We will also denote $\sigX := \sigX[0, t]$.

The signature plays a similar role to polynomials on path-space. Indeed, in dimension $d=1$, the signature $\sigX[s, t]$ of $X$ is the sequence of monomials $\left( \frac{1}{n!} (X_t - X_s)^n \right)_{n \in \N}$.

\begin{sqexample}
    In the case $d=2$ and $X_t = \widehat{W}_t := (t, W_t)$ where $W$ is a 1-dimensional Brownian motion, the first orders of signature are given by
\begin{equation}\label{eq:sig_example_bm}
    \sig^0 = 1,
    \quad
    \sig^1 =
    \begin{pmatrix}
        t \\
         W_t
    \end{pmatrix},
    \quad
    \sig^2 =
    \begin{pmatrix}
        \frac{t^2}{2!} & \int_0^t s d W_s \\
        \int_0^t W_s ds & \frac{W_t^2}{2!}
    \end{pmatrix}
\end{equation}
\end{sqexample}
\paragraph{Tensor algebra.}
The basis of $\eTA$ is given by all the words $\word{v}$ over the alphabet $\alphabet$, so that each element $\bell \in \eTA$ can be represented as 
\begin{equation}
    \bell = \sum_{n \geq 0} \sum_{|\word{v}| = n} \ell^{\word{v}} \word{v}.
\end{equation}

We also define the \textit{truncated tensor algebra} of order $N \in \N$ by
\begin{equation}
    \tTA{N} := \left\{ \bell \in \eTA \colon \ \bell^n = 0, \ n > N \right\},
\end{equation}
and the \textit{tensor algebra} $\TA := \bigcup_{N \geq 0} \tTA{N}$ as the algebra containing only finite tensor sequences. Similarly, the \textit{truncated signature} of order $N \in \N$ is defined by
\begin{align} \label{def:sig-trunc}
    \sigX[s, t]^{\leq N} := \left( 1, \sigX[s, t]^1, \dots, \sigX[s, t]^N, 0, \dots, 0, \dots \right).
\end{align}

Along with the natural sum and multiplication by constants for the elements of $\eTA$, we define the tensor product of $\bp, \bq \in \eTA$ as
\begin{equation}
    \bp \otimes \bq = \left( \sum_{k = 0}^n \bp^k \otimes\bq^{n - k} \right)_{n \geq 0},
\end{equation}
or, in coordinate form,
\begin{equation}
    (\bp \otimes \bq)^{\word{v}} = \sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} p^{\word{u}} q^{\word{w}},
\end{equation}
where $\word{uw}$ is the concatenation of the words $\word{u}$ and $\word{w}$, identified with the tensor product of vectors corresponding to $\word{u}$ and $\word{w}$.

We define the bracket $\langle \cdot, \cdot \rangle: \TA \times \eTA \to \R$ by
\begin{equation}
    \langle \bp, \bq \rangle = \sum_{n \geq 0} \sum_{|\word{v}| = n} \bp^{\word{v}} \bq^{\word{v}}.
\end{equation}

\subsection{Exponentially fading memory signature}

We now consider an $\R^d$-valued increment semimartingale $X = (X_t)_{t \in \R}$ and a vector $\blambda = (\lambda^{1}, \ldots, \lambda^{d}) \in \R^d$ with positive entries, i.e., $\blambda \succ 0$. 
We will denote $\Delta := \{(s, t) \in \R^2 \colon\ s \leq t\}$.

To define the EFM-signature over the infinite time interval, we introduce exponential damping of the integrators $\circ dX_u^i$ by weights $e^{-\lambda^i(t - u)}$, for some positive constants $\lambda^i > 0$.
\begin{definition} \label{def:sig}
    The {$\blambda$-exponential fading memory} signature of $X$ is defined by  
    \begin{align*}
        \ssigX[s, t]\colon \Omega \times \Delta &\to \eTA \\
        (\omega, s, t) &\mapsto \ssigX[s, t](\omega) := (1, \ssigX[s, t][X][\blambda, 1](\omega), \ldots, \ssigX[s, t][X][\blambda, n](\omega), \ldots),
    \end{align*}
    where
    \begin{equation}\label{eq:fm_sig_def}
        \ssigX[s, t][X][\blambda, n] := \int_{s < u_1 < \cdots < u_n < t} e^{-\blambda(t - u_1)} \odot dX_{u_1} \circ \otimes \cdots \circ \otimes e^{-\blambda(t - u_n)} \odot dX_{u_n}
    \end{equation}
    takes values in $(\R^d)^{\otimes n}$, for $n \geq 0$. We also denote $\ssigX := \ssigX[-\infty, t]$.
\end{definition}

{We postpone the question of the well-definedness of the iterated integrals in \eqref{eq:fm_sig_def} as well as the fading memory property to Section~\ref{sect:well_posed}.
}

\begin{sqremark} \label{rmk:sig_iteration_def}
    Explicitly, the components of $\X_t^{\blambda, n}$ are given by
    \begin{equation}
        \ssigX[s, t][X][\blambda, \word{i_1 \cdots i_n}] := \int_{s < u_1 < \cdots < u_n < t} e^{-\lambda^{i_1}(t - u_1)} dX_{u_1}^{i_1} \circ \cdots \circ  e^{-\lambda^{i_n}(t - u_n)} dX_{u_n}^{i_n}.
    \end{equation}
    They can also be expressed in an iterated form:
    \begin{align} \label{eq:def_stat_sig_coef}
        \sigX[s, t]^{\blambda, \word{i_1 \cdots i_n}} = \int_{s}^t e^{-\lambda^{\word{i_1 \cdots i_n}} (t - u_n)} \sigX[u_n]^{\blambda, \word{i_1 \cdots i_{n-1}}} \circ dX_{u_n}^{i_n},
    \end{align}
    where we set
    \begin{equation} \label{eq:lam_v}
        \lambda^{\word{i_1 \cdots i_n}} := \sum_{k=1}^n \lambda^{i_k}.
    \end{equation}
    In particular, we set $\lambda^{\emptyword} = 0$. It is clear that $\lambda^{\word{uv}} = \lambda^{\word{u}} + \lambda^{\word{v}}$ for all words $\word{u}, \word{v}$.
\end{sqremark}

\begin{sqexample}
    For a one-dimensional process $X_t$ with $d = 1$, its EFM-signature is given by
    \begin{equation}
        \ssigX[s, t][X][\blambda] = \left(1,\, (U_t - U_s),\, \frac{(U_t - U_s)^2}{2!},\, \ldots,\, \frac{(U_t - U_s)^n}{n!},\, \ldots\right),
    \end{equation}
    where 
    \begin{equation}\label{eq:OU_def}
        U_t := \int_{-\infty}^t e^{-\lambda^1(t - s)}\, dX_s.
    \end{equation}
    In particular, if $X = W$ is a Brownian motion, its EFM-signature is nothing other than the powers of the increments of the corresponding stationary Ornstein--Uhlenbeck process with mean-reversion coefficient $\lambda^1$. In the general case, the process $U$ can be interpreted as a continuous-time version of the exponential moving average of the past increments of $X$.
\end{sqexample}

\begin{sqexample}
    In the case $d = 2$ and $X_t = \widehat{W}_t := (t, W_t)$, the first levels of the signature are given by
    \begin{equation}\label{eq:fm_sig_examle}
        \sig^{\blambda, 0} = 1,
        \quad
        \sig^{\blambda, 1} =
        \begin{pmatrix}
            (\lambda^1)^{-1} \\
            U_t
        \end{pmatrix},
        \quad
        \sig^{\blambda, 2} =
        \begin{pmatrix}
            \frac{(\lambda^1)^{-2}}{2!} & (\lambda^1)^{-1} \int_{-\infty}^t e^{-(\lambda^1 + \lambda^2)(t-s)}\, dW_s \\
            \int_{-\infty}^t e^{-(\lambda^1 + \lambda^2)(t-s)} U_s\, ds & \frac{U_t^2}{2!}
        \end{pmatrix},
    \end{equation}
    where $U = (U_t)_{t \in \R}$ is a stationary Ornstein–Uhlenbeck process defined by
    \begin{equation}
        U_t = \int_{-\infty}^t e^{-\lambda^2(t-s)}\, dW_s.
    \end{equation}
    This is to be compared with the (standard) signature of $\widehat{W}$ given in \eqref{eq:sig_example_bm}.
\end{sqexample}

\begin{sqexample}
The entries $\lambda^i$ of the vector $\blambda$ are hyperparameters that control how quickly the influence of the past of the $i$-th signal component $X^i$ fades, or equivalently, how rapidly the signature elements involving the integrators $dX^i$ revert to their mean. More precisely, the mean-reversion rate of $\sigX^{\blambda, \word{v}}$ is given by $\lambda^{\word{v}}$. Multiple time scales can be explored either by computing higher-order terms of the EFM-signature, as shown in the previous example, or by extending the path dimension {duplicating path components and} assigning them different values of $\lambda^i$. For instance, taking the path $\bar X_t = (X_t, X_t)$ and $\blambda = (\lambda^1, \lambda^2)$, we obtain
\begin{equation}\label{eq:fm_sig_examle}
    \sigX^{\blambda, 0} = 1,
    \quad
    \sigX^{\blambda, 1} =
    \begin{pmatrix}
        U_t^{\lambda^1}\\
        U_t^{\lambda^2}
    \end{pmatrix},
    \quad
    \sigX^{\blambda, 2} =
    \begin{pmatrix}
        \frac{(U_t^{\lambda^1})^2}{2!} & \int_{-\infty}^t e^{-(\lambda^1 + \lambda^2)(t-s)}U_s^{\lambda^1}\circ dX_s \\
        \int_{-\infty}^t e^{-(\lambda^1 + \lambda^2)(t-s)} U_s^{\lambda^2}\circ dX_s & \frac{(U_t^{\lambda^2})^2}{2!}
    \end{pmatrix},
\end{equation}
where $U = (U_t^{\lambda^i})_{t \in \R}$ is given by
\begin{equation}
    U_t^{\lambda^i} = \int_{-\infty}^t e^{-\lambda^i(t-s)}\, dX_s.
\end{equation}
This construction allows for explicit representation of Volterra processes $\int_{-\infty}^t K(t-s)\,dX_s$ with 
\begin{equation}\label{eq:sum_exp}
    K(t) = \sum_{k=1}^n c_k e^{\lambda^k t}, \quad t \geq 0
\end{equation}
and the polynomials of these processes. Due to the remarkable approximation power of kernels of the form \eqref{eq:sum_exp}, this also opens the door to a tractable approximation of nonlinear functionals of Volterra processes with more general kernels, see, e.g., \citet{CarmonaCoutin} and \citet{abi2019multifactor}.
\end{sqexample}

By definition, the EFM-signature is time-invariant in the sense of \eqref{eq:time_invariance}. This result is formalized in the following proposition.

\begin{proposition}
    If $X = (X_t)_{t \in \R}$ is a continuous semimartingale and $Y_\cdot = X_{\cdot + h}$ for some $h \in \R$, then
    \begin{equation}\label{eq:fm_sig_TI}
        \ssigX[t][Y] = \ssigX[t + h][X].
    \end{equation}
\end{proposition}

\begin{proof}
    \eqref{eq:fm_sig_TI} follows immediately from the change of variables $v_i = u_i + h$ for $i = 1, \ldots, n$ in \eqref{eq:fm_sig_def}.
\end{proof}


\subsection{EFM-signature dynamics}

We start by introducing two operators that are important for understanding the properties of the EFM-signature and for the analysis of its dynamics.

\begin{definition}\label{def:G_oper}
    The operator $\G\colon \eTA \to \eTA$ is defined by
    $$
    \G\colon \bell = \sum_{n \geq 0}\sum_{|\word{v}| = n} \ell^{\word{v}} \mapsto \G\bell = \sum_{n \geq 0}\sum_{|\word{v}| = n} \lambda^{\word{v}}\ell^{\word{v}},
    $$
    where $\lambda^{\word{v}}$ is given by \eqref{eq:lam_v}.
\end{definition}
In other words, $\G$ is a diagonal operator multiplying each entry of the tensor algebra element by the corresponding mean-reversion coefficient. We note that this operator is not continuous with respect to any norm on $\eTA$.

\begin{definition}\label{def:D_operator}
    For $\blambda \in\R^d$ and $h \in\R$, we define the operator $\D\colon \eTA \to \eTA$ by
    \begin{align}\label{eq:D_def}
        \D\colon
        \bell = \sum_{n \geq 0}\sum_{|\word{v}| = n} \ell^{\word{v}} \mapsto \D \bell =  \sum_{n \geq 0}\sum_{|\word{v}| = n} e^{-\lambda^{\word{v}} h}  \ell^{\word{v}}.
    \end{align}
\end{definition}
\begin{proposition}\label{prop_D_ppties}
    The following properties hold
    \begin{enumerate}
        \item[(i)] $\D$ is a dilation operator multiplying the $i$-th basis vector by $e^{-\lambda^ih}$.
        \item[(ii)] For all $h_1, h_2 \in \R$, $\D[h_1]\D[h_2] = \D[h_1 + h_2]$, so that $(\D[h])_{h \geq 0}$ form a semigroup.
        \item[(iii)] For all $\blambda_1, \blambda_2 \in \R^d$, $\D[h][\blambda_1]\D[h][\blambda_2] = \D[h][\blambda_1 + \blambda_2]$.
        \item[(iv)] For all $c \in \R$, $\D[ch] = \D[h][c\blambda]$.
        \item[(v)] $\D$ is an operator exponential of $-h\G$, i.e.,
        $\D = e^{-h\G} = \sum_{n\geq0}\dfrac{(-h\G)^n}{n!}$.
        \item[(vi)] For $h \in\R$, $\, \dfrac{d}{dh}\D = -\Lambda \D = -\D \Lambda$. 
        \item[(vii)] For $\bp, \bq \in \eTA$, we have $\D(\bp\otimes\bq) = (\D\bp)\otimes(\D\bq)$.
        \item[(viii)] For $\bp, \bq \in \eTA$, we have $\G(\bp\otimes\bq) = (\G\bp)\otimes\bq + \bp\otimes(\G\bq)$. 
    \end{enumerate}
\end{proposition}
\begin{proof}
    The properties {(i)}--{(vi)} follow immediately from the definition. For the last two properties, recall that
    $$
    (\bp \otimes \bq)^{\word{v}} = \sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} p^{\word{u}} q^{\word{w}},
    $$
    so that 
    $$
    (\D(\bp \otimes \bq))^{\word{v}} = e^{-\lambda^{\word{v}}h}\sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} p^{\word{u}} q^{\word{w}} = \sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} (e^{-\lambda^{\word{u}}h}p^{\word{u}})(e^{-\lambda^{\word{w}}h}q^{\word{w}}) = ((\D\bp) \otimes (\D\bq))^{\word{v}},
    $$
    since $\lambda^{\word{v}} = \lambda^{\word{u}} + \lambda^{\word{w}}$ for all $\word{u}, \word{w}$ such that $\word{uw} = \word{v}$. Similarly,
    $$
    (\G(\bp \otimes \bq))^{\word{v}} = \lambda^{\word{v}}\sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} p^{\word{u}} q^{\word{w}} = \sum_{\substack{\word{u}, \word{w} \\ \word{uw} = \word{v}}} (\lambda^{\word{u}} p^{\word{u}}q^{\word{w}} +  \lambda^{\word{w}}p^{\word{u}}q^{\word{w}}) = ((\G\bp) \otimes \bq)^{\word{v}} + (\bp \otimes (\G\bq))^{\word{v}}.
    $$
\end{proof}

Proposition~\ref{prop_D_ppties} allows us to rewrite the iterated integrals in the EFM-signature more concisely. Indeed, it follows from \eqref{eq:def_stat_sig_coef} that $\ssigX[]$ can be written as 
\begin{equation}\label{eq:sig_as_D}
    \ssigX[s, t] = \int_{s}^t \D[t - u](\ssigX[u]\otimes\circ dX_u), \quad -\infty \leq s \leq t.
\end{equation}

The following proposition is a compact formulation of the variation of constants formula written in terms of the operators $\G$ and $\D$.
{
\begin{proposition}\label{prop:variation_of_c}
    {Fix $s \in \R\cup\{-\infty\}$.} Suppose that $\bsigma = (\bsigma_t)_{t \geq s}$ is a continuous $\eTA$-valued semimartingale such that
    $$
    \int_{s}^t e^{-2\lambda^{\word{v}}(t - u)} d\langle \bsigma^{\word{v}} \rangle_u < \infty.
    $$
    for all words $\word{v}$ and $t\geq s$.
    Then, for all $\bell_s \in\eTA$, the process
    \begin{equation}
        \bell_t = \D[t - s]  \bell_{s} + \int_{s}^t \D[t - u] d\bsigma_u.     
    \end{equation}
    solves the equation
    \begin{equation}
        d\bell_t = -\G \bell_t dt + d\bsigma_t, \quad t \geq s.
    \end{equation}
\end{proposition}
\begin{proof}
    The proof follows immediatetly from Proposition~\ref{prop_D_ppties}\,{(vi)}.
\end{proof}
}
Proposition~\ref{prop:variation_of_c} combined with \eqref{eq:sig_as_D} yield that the dynamics of the EFM-signature is given by
\begin{equation}\label{eq:sig_sde}
    d\ssigX[s, t] = -\G \ssigX[s, t]\,dt + \ssigX[s, t]\otimes\circ dX_t, \quad t \geq s.
\end{equation}
The second term in \eqref{eq:sig_sde} corresponds to the standard signature dynamics equation, while the first one is the mean-reversion term appearing due to the exponential weights in \eqref{eq:fm_sig_def}.
\begin{sqremark}
    This and all the following $\eTA$-valued equations are understood element-wise. This means that for any truncation order $N$, the truncated equation reduces to a linear multidimensional Stratonovich SDE with coefficients depending only on the elements of $\ssigX[s, t]$ up to level $N$. {Hence, the SDE} admits a unique strong solution.
\end{sqremark}
The EFM-signature allows us to construct a fundamental solution of \eqref{eq:sig_sde}.

\begin{proposition}\label{prop:fundamental_sol}
    Fix $\mathbbm{x}\in \eTA$. The solution to the equation 
    \begin{equation}\label{eq:sig_sde_fund}
    \begin{aligned}
        d\mathbf{\Phi}^{s, \mathbbm{x}}_t &= -\G \mathbf{\Phi}^{s, \mathbbm{x}}_tdt + \mathbf{\Phi}^{s, \mathbbm{x}}_t\otimes\circ dX_t,\quad t \geq s, \\
        \mathbf{\Phi}^{s, \mathbbm{x}}_s &= \mathbbm{x}.
    \end{aligned}
    \end{equation}
    is given by $\mathbf{\Phi}^{s, \mathbbm{x}}_t = (\D[t - s]\mathbbm{x})\otimes\ssigX[s, t]$.
\end{proposition}
\begin{proof}
    Using Proposition~\ref{prop_D_ppties}\,{(vi)} and \eqref{eq:sig_sde}, we obtain
    \begin{align}
        d((\D[t - s]\mathbbm{x})\otimes\ssigX[s, t]) &= d(\D[t - s]\mathbbm{x})\otimes\ssigX[s, t] + (\D[t - s]\mathbbm{x})\otimes d\ssigX[s, t] \\
        &= -(\G\D[t - s]\mathbbm{x})\otimes\ssigX[s, t]\,dt - (\D[t - s]\mathbbm{x})\otimes \G\ssigX[s, t]\,dt + (\D[t - s]\mathbbm{x})\otimes\ssigX[s, t]\otimes\circ dX_t \\
        &= -\G((\D[t - s]\mathbbm{x})\otimes\ssigX[s, t])dt + ((\D[t - s]\mathbbm{x})\otimes\ssigX[s, t])\otimes\circ dX_t,
    \end{align}
    where we used Proposition~\ref{prop_D_ppties}\,{(viii)} for the last equality. This shows that $(\D[t - s]\mathbbm{x})\otimes\ssigX[s, t]$ satisfies \eqref{eq:sig_sde_fund}. Observing that the system \eqref{eq:sig_sde_fund}, truncated at any order $N \in \mathbb{N}$, admits a unique strong solution as a linear SDE concludes the proof.
\end{proof}



\subsection{Well-definedness of the EFM-signature and fading-memory property}\label{sect:well_posed}
The goal of this subsection is to address two following questions. The first one is the conditions under which the EFM-signature \eqref{eq:fm_sig_def} of a continuous semimartingale is well-defined. The second one is the notion of fading memory, in the spirit of \cite*{Boyd1985FadingMA}. We introduce all the definitions and notations from rough path theory necessary to state the main results. Their proofs will rely on the improper rough convolution, which will be introduced later in Section~\ref{sect:rough_paths}.

\begin{definition}
    Following \citet{Boyd1985FadingMA}, we say that the EFM-signature has the fading memory property with respect to a weighted metric~$\varrho$ on the path space $(\mathcal{X}, \varrho)$ if, for all $s \le t$ and $n \in \mathbb{N}_0$, the mapping
    $$
    X \in \mathcal{X} \mapsto \sigX[s, t]^{\lambda, n},
    $$
    is continuous with respect to~$\varrho$.
\end{definition}

In words, this means that if two paths $X, Y \in \mathcal{X}$ are close in the recent past {(proximity in the \textit{weighted} metric $\brho$)}, then the EFM-signatures $\sigX[s, t]^{\lambda, n}$ and $\sigX[s, t][Y]^{\lambda, n}$ will also be close. Of course, to make this definition precise, one must explicitly specify the path space~$\mathcal{X}$ and the distance~$\varrho$.

We first consider absolutely continuous paths $X = (X_t)_{t \leq T}$ and define its weighted variation norm by
\begin{equation}\label{eq:noem_BV_lambda}
    \|X\|_{\mathrm{BV},\blambda; [s, t]} := \int_{s}^t|\D[t-u] \dot X_u|\,du, \quad { \|X\|_{\mathrm{BV},\blambda} := \|X\|_{\mathrm{BV},\blambda; (-\infty, T]}}.
\end{equation}

The proposition below establishes the fading memory property of the EFM-signature. {Note that
for continuously differentiable $X$, the fading memory property implies that} each level of the EFM-signature is a fading memory operator for the signal $u_t = \dot X_t$ in the sense of \citet{Boyd1985FadingMA}. Of course, the signature approach admits much rougher input signals, since we pass from $u$ to its integral $X$. This means that $u = \dot X$ may be not defined in terms of \cite{Boyd1985FadingMA}. One can think about a Brownian motion $X = W$, which is almost surely nowhere differentiable; in this case, $u$ corresponds to the white noise, which is, of course, not a continuous process.

\begin{proposition}\label{prop:fm_bv_case}
    For the absolutely continuous path $X = (X_t)_{t\leq T}$ such that $\|X\|_{\mathrm{BV},\blambda} < \infty$, the EFM-signature is well-defined, and for all $s \leq t \leq T$, the following bound holds:
    \begin{equation}\label{eq:BV_bound}
        \left|\sigX[s, t]^{\lambda, n}\right| \leq \dfrac{\|X\|_{\mathrm{BV},\blambda; [s, t]}^n}{n!}.
    \end{equation}
    Moreover, the EFM-signature has the fading memory property with respect to the weighted variation distance induced by $\|\cdot\|_{\mathrm{BV},\blambda}$.
\end{proposition}
\begin{proof}
    Repeating the proof of \cite[Lemma 5.1]{Lyons2014RoughPS}, for $n \geq 1$, we obtain 
    \begin{align}
        \left|\sigX[s, t]^{\lambda, n}\right| &= \left|\int_{s < u_1 < \cdots < u_n < t} \D[t-u_1] \dot X_{u_1} \otimes \ldots \otimes \D[t-u_n]\dot X_{u_n}\, du_1 \ldots d{u_n}\right| \\
        &\leq \int_{s < u_1 < \cdots < u_n < t}  \left|\D[t-u_1] \dot X_{u_1}\otimes \ldots \otimes \D[t-u_n] \dot X_{u_n}\right|\, du_1 \ldots d{u_n} \\
        &= \int_{s < u_1 < \cdots < u_n < t}  \prod_{k=1}^n \left|\D[t-u_k] \dot X_{u_k}\right|\, du_1 \ldots d{u_n} \\
        &= \dfrac{1}{n!}\left(\int_{s}^{t} \left|\D[t-u]  \dot X_{u}\right|\, du\right)^n = \dfrac{\|X\|_{\mathrm{BV},\blambda; [s, t]}^n}{n!}.
    \end{align}
    To prove the continuity, we proceed by induction in $n$ and we claim that the continuity is uniform in $s, t$ once the absolutely continuous paths $X, Y$ satisfy
    \begin{equation}\label{eq:BV_M_assumption}
        \|X\|_{\mathrm{BV}, \blambda} < M, \quad \|Y\|_{\mathrm{BV}, \blambda} < M.
    \end{equation}
    For $n = 0$, $\sigX[s, t]^{\blambda, n} \equiv 1$, and the continuity follows trivially. Suppose that we proved the uniform continuity for all $\sigX[s, t]^{\blambda, k} \equiv 1, \ k \leq n$, and recall that
    $$
    \sigX[s, t]^{\blambda, n+1} = \int_s^t \D[t - u](\sigX[s, u]^{\blambda, n}\otimes dX_u).
    $$
    for some constant $M > 0$. Then, the difference between two signatures reads 
    \begin{align}
        \sigX[s, t][X]^{\blambda, n+1} - \sigX[s, t][Y]^{\blambda, n+1} = \int_s^t \D[t - u]((\sigX[s, u][X]^{\blambda, n} - \sigX[s, u][Y]^{\blambda, n})\otimes dX_u) + \int_s^t \D[t - u](\sigX[s, u][Y]^{\blambda, n}\otimes d(X_u - Y_u)).
    \end{align}
    {Since $\|\D[T-t]X\|_{\mathrm{BV},\blambda; [s, t]} \leq \|X\|_{\mathrm{BV},\blambda}$, we have $\|X\|_{\mathrm{BV},\blambda; [s, t]} \lesssim_{\blambda, t, T} \|X\|_{\mathrm{BV},\blambda}$ and}
    \begin{align}
        |\sigX[s, t][X]^{\blambda, n+1} - \sigX[s, t][Y]^{\blambda, n+1}| \lesssim_{\blambda, t, T}  \|X\|_{\mathrm{BV}, \blambda} \sup_{s \leq u \leq T}|\sigX[s, u][X]^{\blambda, n} - \sigX[s, u][Y]^{\blambda, n}| + \|X - Y\|_{\mathrm{BV}, \blambda}\sup_{s \leq u \leq T}|\sigX[s, u][Y]^{\blambda, n}|.
    \end{align}
    We note that $\|X\|_{\mathrm{BV}, \blambda}$ and $\sup\limits_{s \leq u \leq T}|\sigX[s, u][Y]^{\blambda, n}|$ are bounded thanks to \eqref{eq:BV_M_assumption} and \eqref{eq:BV_bound}, so that $|\sigX[s, t][X]^{\blambda, n+1} - \sigX[s, t][Y]^{\blambda, n+1}| \to 
    0$ uniformly in $s, t$ as $\|X - Y\|_{\mathrm{BV}, \blambda} \to 0$ by the induction hypothesis. This finishes the proof.
\end{proof}

We will show that the idea of fading memory can be generalized to encompass irregular drivers $X$ thanks to rough path theory, namely, through the notion of the {exponentially weighted rough path} that we introduce below. To proceed, we need to introduce some notations related to Hölder spaces and rough path spaces.

\paragraph{Hölder spaces.} In this subsection, as well as in Section~\ref{sect:rough_paths}, all Hölder functions $f$ take values in $(\R^d)^{\otimes n}$ for some $n \in \N_0$, where $d$ denotes the dimension of the driving path. This guarantees that $\D[]f$ is well-defined as a restriction of the operator $\D[]$ in Definition~\ref{def:D_operator}.  
For continuous functions $A = (A_{u, v})_{s \leq u \leq v \leq t}$, we define the Hölder norm
\begin{equation}\label{eq:holder_seminorm_def}
    \|A\|_{\alpha; [s, t]} := \sup_{\substack{u, v \in [s, t] \\ 0 < |u - v| < 1}} \dfrac{|A_{u, v}|}{|u - v|^{\alpha}}.
\end{equation}
We adopt the standard notations
\begin{equation}
    \delta f_{s,t} := f_t - f_s, \quad \hat\delta f_{s,t} := f_t - \D[t-s]f_s, \quad s \leq t,
\end{equation}
where the operator $\D[t-s]$ is defined by \eqref{eq:D_def}. 

The constraint $0 < |u - v| < 1$ in \eqref{eq:holder_seminorm_def} is added to simplify the further analysis of Hölder functions on infinite time intervals. Notice that this additional constraint does not affect any rough path result since Hölder regularity is always considered as a local property.

Let $\mathcal{C}^\alpha([s, t])$ denote the space of $\alpha$-Hölder paths on $[s, t]$ with finite seminorm
\[
    \|f\|_{\alpha; [s, t]} := \|\delta f\|_{\alpha; [s, t]}.
\]
Similarly, $\hat{\mathcal{C}}^\alpha([s, t])$ denotes the space of paths on $[s, t]$ with finite seminorm
\[
     \|f\|_{\alpha; [s, t]}^\wedge := \|\hat\delta f\|_{\alpha; [s, t]}.
\]

For functions $A= (A_{u, v})_{u \leq v \leq T}$ defined on infinite time horizons $(-\infty, T]$, we propose to use the exponentially weighted Hölder seminorms with coefficients $\brho \in \R^d$, $\brho \succ 0$:
\begin{equation}
     \|A\|_{\alpha, \brho} := \sup_{\substack{u, v \in (-\infty, T] \\ 0 < |u - v| < 1}} \dfrac{|\D[T-u][\brho]A_{u, v}|}{|u - v|^{\alpha}},
\end{equation}
and we denote by ${\mathcal{C}}^{\alpha, \brho}((-\infty, T])$ the space of functions $f$ such that $\|f\|_{\alpha, \brho} := \|\delta f\|_{\alpha, \brho} < \infty$. Similarly, we define $\|f\|_{\alpha, \brho}^\wedge := \|\hat\delta f\|_{\alpha, \brho}$ and denote the corresponding Hölder space by $\hat{\mathcal{C}}^{\alpha, \brho}((-\infty, T])$.

\begin{sqremark}\label{rmk:holder_spaces}
    It is straightforward that the finiteness of $\|f\|_{\alpha, \brho}$ (respectively $\|f\|_{\alpha, \brho}^\wedge$) implies the finiteness of $\|f\|_{\alpha; [s, t]}$ (resp. $\|f\|_{\alpha; [s, t]}^\wedge$) for all $s < t \leq T$. Moreover, if $0 \prec \brho \prec \brho'$, then $\|f\|_{\alpha, \brho'} \leq \|f\|_{\alpha, \brho}$ (resp. $\|f\|_{\alpha, \brho'}^\wedge \leq \|f\|_{\alpha, \brho}^\wedge$) and {${\mathcal{C}}^{\alpha, \brho}((-\infty, T]) \subset {\mathcal{C}}^{\alpha, \brho'}((-\infty, T])$ (resp. $\hat{\mathcal{C}}^{\alpha, \brho}((-\infty, T]) \subset \hat{\mathcal{C}}^{\alpha, \brho'}((-\infty, T])$).}
\end{sqremark}

The following lemma clarifies the relationship between the weighted and unweighted norms.

\begin{lemma}\label{lem:holder_weighted}
    For $f \in {\mathcal{C}}^{\alpha, \brho}((-\infty, T])$, 
    \begin{equation}
        \|f\|_{\alpha, \brho} = \sup_{R \leq T}\left(\|\D[T-R][\brho]f\|_{\alpha; [R, T]}\right).
    \end{equation}
\end{lemma}
\begin{proof}
    Denote $C := \sup\limits_{R \leq T}\left(\|\D[T-R][\brho](\delta f)\|_{\alpha; [R, T]}\right)$. For all $s, t \in [R, T]$ such that $0 < |t - s| < 1$, we have
    $$
    |\D[T-R][\brho](\delta f_{s, t})| \leq |\D[T-s][\brho](\delta f_{s, t})| \leq \|f\|_{\alpha, \brho}|t-s|^{\alpha},
    $$
    so that
    $
    \|\D[T-R][\brho] f\|_{\alpha; [R, T]} \leq \|f\|_{\alpha, \brho},
    $
    and hence $C \leq \|f\|_{\alpha, \brho}$.

    Conversely, for all $R \leq T$ and $t \in [R, T]$ such that $0 < |t - R| < 1$,
    $$
    |\D[T-R][\brho](\hat\delta f_{R, t})| \leq \|\D[T-R][\brho] f\|_{\alpha; [R, T]}|t - R|^\alpha \leq C|t - R|^\alpha
    $$
    Dividing by $|t - R|^\alpha$ and taking the supremum over $R$ and $t$ yields $\|f\|_{\alpha, \brho} \leq C$.
\end{proof}
It is clear that the same result holds for the ``hatted'' norms $\|\cdot\|_{\alpha, \brho}^\wedge$.

However, the finiteness of $\|f\|_{\alpha, \brho}^\wedge$ appears to be insufficient to properly define the EFM-signature. One should also require boundedness with exponential weight, i.e., the finiteness of the norm
\begin{equation}
    \|f\|_{\infty, \brho} := \sup_{t \in (-\infty, T]} \left|\D[T - t][\brho] f_t\right|.
\end{equation}
We denote the space of weighted bounded Hölder functions by
\begin{equation}\label{eq:hat_C_b_alpha_rho}
    \hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T]) := \left\{ f \in \hat{\mathcal{C}}^{\alpha, \brho}((-\infty, T]) \colon\ \|f\|_{\alpha, \brho}^\wedge + \|f\|_{\infty, \brho} < \infty \right\}.
\end{equation}

\paragraph{Rough path spaces.}  
We recall the definition of the standard $\alpha$-Hölder rough path for $\alpha \in \left(\frac{1}{3}, \frac{1}{2}\right]$ over a finite interval. A more comprehensive introduction to rough path theory can be found in \citet{friz2020course}.

\begin{definition}
    For a finite time interval $[R, T]$ and $\alpha \in \left(\frac{1}{3}, \frac{1}{2}\right]$, the space $\mathscr{C}^\alpha([R, T], \R^d)$ of $\alpha$-Hölder rough paths over $\R^d$ consists of pairs $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)$ satisfying 
    \begin{equation}
        \|\mathbb{X}^1\|_{\alpha; [R, T]} < \infty, \quad
        \|\mathbb{X}^2\|_{2\alpha; [R, T]} < \infty,
    \end{equation}
    as well as the Chen's identity
    \begin{equation}\label{eq:chen_standard}
        \mathbb{X}^2_{s, t} = \mathbb{X}^2_{s, u} + \mathbb{X}^2_{u, t} + \mathbb{X}^1_{s, u} \otimes \mathbb{X}^1_{u, t}, \quad R \leq s \leq u \leq t \leq T
    \end{equation}
    We denote
    \begin{equation}
         \|\mathbf{X}\|_{\alpha; [R, T]} := \|\mathbb{X}^1\|_{\alpha; [R, T]} + \|\mathbb{X}^2\|_{2\alpha; [R, T]}.
    \end{equation}
\end{definition}

The natural extension of this definition to paths defined on infinite time intervals $(-\infty, T]$ consists in replacing the Hölder space and norm conditions by their weighted counterparts.

\begin{definition}[Exponentially weighted rough path]
    For $\alpha \in \left(\frac{1}{3}, \frac{1}{2}\right]$ and $\brho \in \R^d$ with $\brho \succ 0$, the space $\mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$ of $(\alpha, \brho)$-Hölder rough paths over $\R^d$ consists of pairs $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)$ satisfying
    \begin{equation}
        \|\mathbb{X}^1\|_{\alpha, \brho} < \infty, \quad
        \|\mathbb{X}^2\|_{2\alpha, \brho} < \infty,
    \end{equation}
    and Chen's identity \eqref{eq:chen_standard} for all $s \leq u \leq t \leq T$. We also define the norm
    \begin{equation}
         \|\mathbf{X}\|_{\alpha, \brho} := \|\mathbb{X}^1\|_{\alpha, \brho} + \|\mathbb{X}^2\|_{2\alpha, \brho}.
    \end{equation}
\end{definition}

It follows from Remark~\ref{rmk:holder_spaces} that the restriction of a rough path $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$ to $[R, T]$ lies in $\mathscr{C}^\alpha([R, T], \R^d)$ for all $R < T$. Moreover, for all $\brho'$ such that $0 \prec \brho \prec \brho'$, we have the inclusion
\[
    \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d) \subset \mathscr{C}^{\alpha, \brho'}((-\infty, T], \R^d).
\]

For $\mathbf{X}, \mathbf{Y} \in \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$, we define the exponentially weighted rough path distance by
\begin{equation}\label{eq:fm_rp_distance}
    \varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) := \|\mathbb{X}^1 - \mathbb{Y}^1\|_{\alpha, \brho} + \|\mathbb{X}^2 - \mathbb{Y}^2\|_{2\alpha, \brho},
\end{equation}
which induces the exponentially weighted rough path topology on $\mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$.

Our main result concerning the existence of the EFM-signature states that the only condition for the EFM-signature with parameters $\blambda$ to be well-defined as an element of $\hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$ is that the rough path lift $\mathbf{X}$ belongs to $\mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$ for some $\brho$ such that $0 \prec \brho \prec \blambda$.

\begin{theorem}\label{thm:fm_sig_existence}
    Fix $T \in \R$. If $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ for some $\alpha \in \left(\frac{1}{3}, \frac{1}{2}\right]$ and $0 \prec \brho \prec \blambda$, then the EFM-signature $\ssigX[]$ given by \eqref{eq:fm_sig_def} is well-defined. Moreover, for all $s \in [-\infty, T]$ and all $n \geq 0$, we have 
    \[
        \mathbb{X}^{\blambda, n}_{s, \cdot} \in \hat{\mathcal{C}}^{\alpha, \brho}_b((s, T]).
    \]
\end{theorem}
\begin{proof}
    For the proof, we refer to Section~\ref{sect:rough_paths}. The statement follows from Corollary~\ref{corollary:fm_sig_s_fin} for finite $s$ and from Corollary~\ref{corollary:fm_sig_s_inf} for $s = -\infty$.
\end{proof}

\begin{sqremark}
    For standard rough path theory on finite intervals, the rough integral of a semimartingale $X$ coincides with either Itô integration or Stratonovich integration, depending on the choice of the lift:
\[
\begin{aligned}
\mathbb{X}^{2, \mathrm{It\hat{o}}}_{s,t} = \int_s^t X_u \otimes dX_u,\quad 
\mathbb{X}^{2, \mathrm{Strato}}_{s,t} = \int_s^t X_u \otimes \circ dX_u.
\end{aligned}
\]
This result can be readily extended to our setting on infinite intervals by taking the limit as in \eqref{eq:improper_conv}. In particular, we can define the EFM-signature of a semimartingale in terms of either the Itô or Stratonovich integral. Throughout this paper, we will adopt the Stratonovich lift for continuous semimartingales.
\end{sqremark}

The fading memory property can now be understood as the continuity of the signature map with respect to the exponentially weighted rough path distance \eqref{eq:fm_rp_distance}, providing a rough path generalization of the results of \citet{Boyd1985FadingMA} and Proposition~\ref{prop:fm_bv_case}.

\begin{theorem}[Fading memory property]\label{thm:rough_fm}
    Let $\mathbf{X}, \mathbf{Y} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ for  some $\alpha \in \left(\frac{1}{3}, \frac{1}{2}\right]$ and $0 \prec \brho \prec \blambda$. 
    Then, the EFM-signature $\ssigX[]$ has the fading memory propery w.r.t. the exponentially weighted rough path distance $\varrho_{\alpha, \brho}$ given by \eqref{eq:fm_rp_distance}, that is, for all $-\infty \leq s \leq t \leq T$ and $n \geq 0$,
    \[
        |\mathbb{X}_{s, t}^{\blambda, n} - \mathbb{Y}_{s, t}^{\blambda, n}| \to 0 \quad \text{as} \quad \varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) \to 0.
    \]
\end{theorem}
\begin{proof}
    The proof is given in Subsection~\ref{sect:rough_fm_proof}.
\end{proof}

\subsection{EFM-signature as a stationary process}
As a time-invariant transformation, EFM-signature is expected to produce a stationary output in response to the stationary input.
Indeed, the EFM-signature $\ssigX[] = (\ssigX[t])_{t\in\R}$ can be seen as a $\eTA$-valued stochastic process, which exists by Kolmogorov's extension theorem. In this subsection, we will show that if $X$ is a process with stationary increments, then its EFM-signature is a stationary process, i.e., for all $t_1 < \ldots < t_n$ and for all $h \in \R$, we have
\begin{equation}
    \mathcal{L}(\ssigX[t_1], \ldots, \ssigX[t_n]) = \mathcal{L}(\ssigX[t_1 + h], \ldots, \ssigX[t_n + h]).
\end{equation}
The proof relies on the following technical lemma.

\begin{lemma}\label{lem:stationarity}
    Let $\eta_t$ and $\sigma_t$ be stationary càdlàg adapted processes (possibly multivariate), such that, for all $h \in\R$,
    \begin{equation}
        \mathcal{L}((\eta_{t}, \sigma_{t}, X_t)_{t\in\R}) = \mathcal{L}((\eta_{t+h}, \sigma_{t+h}, X^h_t)_{t\in\R}),
    \end{equation}
    where $X_t^h := X_{t + h} - X_h$.
    Then, for all $\mu > 0$ and $i \in \{1, \ldots, d\}$, $Y_t = \int_{-\infty}^t e^{-\mu(t-s)}\sigma_s \circ dX_s^i$ is stationary and
    \begin{equation}\label{eq:int_law_eq}
        \mathcal{L}((\eta_{t}, Y_{t}, X_t)_{t\in\R}) = \mathcal{L}((\eta_{t+h}, Y_{t+h}, X^h_t)_{t\in\R}).
    \end{equation}
\end{lemma}
\begin{proof}
    The proof of this statement follows the lines of the proof of \cite[Proposition~1]{sauri2017brownian}, with the following straightforward modifications: considering a semimartingale with stationary increments instead of Brownian motion, using Stratonovich integration instead of Itô integration, and adding the equality \eqref{eq:int_law_eq}, which also follows immediately from the referenced proof.
\end{proof}

\begin{theorem}\label{thm:stationarity}
    Suppose that $X = (X_t)$ is an $\R^d$-valued continuous semimartingale with stationary increments. Then, $\ssigX[] = (\ssigX[t])_{t \in \R}$ is a stationary $\eTA[d]$-valued process. In particular, for all $t \in \R$,
    \begin{equation}
        \mathcal{L}(\ssigX[t]) = \mathcal{L}(\ssigX[0]).
    \end{equation}
\end{theorem}

\begin{proof}
We show the stationarity of the truncated EFM-signature $\sigX[]^{\blambda, \leq N}$ for all $N$ by induction on words $\word{v}$, ordered first by length and then lexicographically (this order is denoted by $\prec$). For $\word{v} = \emptyword$, the EFM-signature is a constant process equal to $1$. 

For the induction step, consider a word $\word{v} = \word{v'i}$ and suppose that the process $(\sigX[]^{\blambda, \word{w}})_{\word{w} \prec \word{v}}$ is stationary, and that
\begin{equation}
    \mathcal{L}(((\sigX[t]^{\blambda, \word{w}})_{\word{w} \prec \word{v}}, X_t)_{t \in \R}) = \mathcal{L}(((\sigX[t+h]^{\blambda, \word{w}})_{\word{w} \prec \word{v}}, X_t^h)_{t \in \R}).
\end{equation}
Recall that $\sigX[]^{\blambda, \word{v}}$ is given by \eqref{eq:def_stat_sig_coef}. It follows from Lemma~\ref{lem:stationarity}, with $\eta_t = (\sigX^{\blambda, \word{w}})_{\word{w} \prec \word{v}}$, $\sigma_t = \sigX[t]^{\blambda, \word{v'}}$, and $\mu = \lambda^{\word{v}}$, that $\sigX[t]^{\blambda, \word{v}}$ is stationary, and for all $h \in \R$, we have
\begin{equation}
    \mathcal{L}(((\sigX[t]^{\blambda, \word{w}})_{\word{w} \preceq \word{v}}, X_t)_{t \in \R}) = \mathcal{L}(((\sigX[t+h]^{\blambda, \word{w}})_{\word{w} \preceq \word{v}}, X_t^h)_{t \in \R}).
\end{equation}

This proves the stationarity of the finite-dimensional processes $\sigX[]^{\blambda, \leq N}$ for all $N \in \N$, and hence implies the stationarity of $\ssigX[]$.
\end{proof}

Another advantage of increments stationarity is that it allows one to verify the conditions of Theorem~\ref{thm:fm_sig_existence}, showing that $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$.

\begin{proposition}\label{prop:stat_holder_const}
    Let $X = (X_t)_{t \leq T}$ be a continuous $\R^d$-valued semimartingale with stationary increments, and suppose that for some interval $[t_0, t_0 + h]$, the Hölder constants satisfy
    \begin{equation}\label{eq:Holder_const}
         \E\left[\|\mathbb{X}^{1}\|_{\alpha; [t_0, t_0 + h]}\right]  + \E\left[\|\mathbb{X}^{2}\|_{2\alpha; [t_0, t_0 + h]}\right] < \infty.
    \end{equation}
    Then, $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ almost surely.
\end{proposition}

\begin{proof}
    First, by the stationarity of increments, the law of $\|\mathbb{X}^{1}\|_{\alpha; [t_0, t_0 + h]}$ and $\|\mathbb{X}^{2}\|_{2\alpha; [t_0, t_0 + h]}$ does not depend on $t_0$.
    For $R = T - nh$, $n \in \mathbb{N}$, using the subadditivity of the Hölder seminorms, we have
    \begin{align}
        \|\D[T-R][\brho]\mathbf{X}\|_{\alpha; [R, T]} 
        &\leq \sum_{k=1}^{n} \|\D[T-R][\brho]\mathbf{X}\|_{\alpha; [T - kh, T - (k - 1)h]} \\
        &\leq \sum_{k=1}^{+\infty} \|\D[kh][\brho]\mathbf{X}\|_{\alpha; [T - kh, T - (k - 1)h]}.
    \end{align}
    The case of arbitrary $R < T$ follows similarly. Taking the supremum over $R$ and applying Lemma~\ref{lem:holder_weighted} yields
    \begin{equation}
        \|\mathbf{X}\|_{\alpha, \brho} \leq \sum_{k=1}^{+\infty} \|\D[kh][\brho]\mathbf{X}\|_{\alpha; [T - kh, T - (k - 1)h]}.
    \end{equation}
    Taking expectations and using the stationarity to observe that $\mathbb{E}[\|\mathbf{X}\|_{\alpha; [T - kh, T - (k - 1)h]}]$ is finite and independent of $k$, we conclude that
    \[
        \mathbb{E}[\|\mathbf{X}\|_{\alpha, \brho}] < \infty,
    \]
    hence $\|\mathbf{X}\|_{\alpha, \brho}$ is almost surely finite.
\end{proof}
\begin{sqremark}\label{rem:BM_EFM_sig_well_def}
        The condition \eqref{eq:Holder_const} can be verified using the Kolmogorov continuity theorem for rough paths (see, e.g., \cite[Theorem 3.1]{friz2020course}). Proposition~\ref{prop:stat_holder_const}, in particular, establishes the well-definedness of the EFM-signature of $d$-dimensional (possibly time-augmented) Brownian motion $\ssigX[][W]$ ($\ssigX[][\widehat W]$ respectively).
\end{sqremark}

\section{Properties of the EFM-signature}\label{sect:algebraic_prop}

In this section, we establish results on the algebraic and analytic properties of EFM-signatures, which closely resemble those of standard signatures. 

\subsection{Chen's identity}
Chen's identity for signatures (see \cite{chen1958integration}) states that for any $0 \leq s \leq u \leq t \leq T$,
\begin{equation}
    \sigX[s, t] = \sigX[s, u] \otimes \sigX[u, t].
\end{equation}
In other words, to compute the signature of a concatenated path $X * Y$, one can compute independently the signatures of $X$ and $Y$, and then take their tensor product.

When dealing with EFM-signatures, the algebraic structure of iterated integrals remains unchanged, except that each component $\sigX[s, u]^{\blambda, \word{v}}$ of the EFM-signature over $[s, u]$ must be multiplied by $e^{-\lambda^{\word{v}}(t - u)}$ to compensate for the difference in exponential weights in \eqref{eq:fm_sig_def}. This means that the EFM-signature $\ssigX[s, u]$ must be appropriately \emph{discounted} using the operator $\D[t - u]$ before applying the tensor product. In other words, the contribution of past segments to the EFM-signature decays exponentially at rate $\lambda^i$ for the $i$-th component of the path. More precisely, the following result holds.

\begin{proposition}\label{prop:Chen_FM}
    {Fix $\blambda\in\R^d, \blambda\succ 0$ and let $X = (X_t)_{t\in\R}$ be continuous $\R^d$-valued semimartingale such that $\ssigX[]$ is well-defined. } Then,
    \begin{equation}\label{eq:stat_chen}
        \ssigX[s, t] = (\D[t - u]\ssigX[s, u]) \otimes \ssigX[u, t]
    \end{equation}
    for all $s \leq u \leq t$.
\end{proposition}
{\begin{proof}
    The proof follows from Proposition~\ref{prop:fundamental_sol} together with the EFM-signature dynamics \eqref{eq:sig_sde}.
\end{proof}
}

\subsection{EFM-signature of linear path}\label{sect:linear_path}
Chen's identity is a crucial property for the computation of signatures. Indeed, a standard approach to computing the signature of a discrete path is to approximate it by a piecewise linear path, compute the signature of each linear segment—which is known explicitly—and then recover the signature of the entire path by performing the tensor multiplication of the segment signatures.

We begin by noticing that when {all the components of $\blambda$ are equal}, the EFM-signature of a linear path can be computed in closed form as an exponential, similarly to the standard signature. For 
$\bell\in\eTA$, we define the tensor product exponential as the series
$$
e\conpow{\bell} := \sum_{k \geq 0}\dfrac{\bell\conpow{k}}{k!}.
$$
\begin{lemma}
    Suppose that $\blambda = (\lambda, \ldots, \lambda)$ for some $\lambda > 0$. For a linear path $X_t = t \bm{x}$ with $\bm{x} \in \R^d$, its EFM-signature $\mathbb{X}^{\blambda}_{s, t} = (\mathbb{X}^{\blambda, n}_{s, t})_{n \geq 0}$ is given explicitly by
    \begin{equation}\label{eq:linear_path_stat_sig}
        \ssigX[s, t] = e^{\otimes\left(\frac{1 - e^{-\lambda(t - s)}}{\lambda(t-s)}  (X_{t} - X_s)\right)}.
    \end{equation}

In particular, the EFM-signature of a linear path over $(-\infty, t]$ is constant and equals
\begin{equation}\label{eq:linear_path_stat_sig_inf}
    \mathbb{X}^{\blambda}_{t} = \exp\left({\otimes\frac{\bm{x}}{\lambda}}\right).
\end{equation}
Moreover, the EFM-signature of a piecewise-linear path with breakpoints $t_0 < t_1 < \ldots < t_n$ is given recursively by
\begin{equation}\label{eq:piecewise_linear_path_stat_sig_inf}
   \ssigX[t_0, t_n] = (\D[t_n - t_{n-1}]\ssigX[t_0, t_{n-1}]) \otimes e^{\otimes\left(\frac{1 - e^{-\lambda(t_{n} - t_{n-1})}}{\lambda(t_{n}-t_{n-1})} (X_{t_{n}} - X_{t_{n-1}})\right)}. 
\end{equation}
\end{lemma}
\begin{proof}
A straightforward computation shows that
\begin{equation}
    \mathbb{X}^{\blambda, n}_{s, t} = \dfrac{1}{n!}\left(\dfrac{1 - e^{-\lambda(t - s)}}{\lambda(t-s)} (X_{t} - X_s)\right)^{\otimes n}, \quad n \geq 0,
\end{equation}
so that \eqref{eq:linear_path_stat_sig} holds. \eqref{eq:linear_path_stat_sig_inf} follows as a limit as $s \to -\infty$.
The formula \eqref{eq:piecewise_linear_path_stat_sig_inf} follows from Chen's identity \eqref{eq:stat_chen}.
\end{proof}

The case where $\blambda$ has different components is more delicate, as the computation involves integrals of the form
\begin{equation}\label{eq:interated_exp_int}
    \int_{s < u_1 < \cdots < u_n < t} e^{-\lambda^{i_1}(t - u_1)} \cdots e^{-\lambda^{i_n}(t - u_n)} \, d u_1 \ldots d u_n,
\end{equation}
which are no longer symmetric, making it impossible to use formulas like \eqref{eq:linear_path_stat_sig}. Fortunately, these integrals can still be computed explicitly via the following lemma.
\begin{lemma}\label{lem:linear_path}
    Fix $\blambda = (\lambda^1, \ldots, \lambda^d)\in\R^d, \, \blambda\succ 0$.
    For each word $\word{v} = \word{i_1\ldots i_n}$, the components of the EFM-signature $\ssigX[]$ of the linear path $X_t = tx$ are given by
    \begin{equation}\label{eq:linear_path_coefs_explicit}
        \mathbb{X}^{\blambda, \word{v}}_{s, t} = (x^{i_1}\cdot\ldots\cdot x^{i_n})\sum_{k=0}^{n} c_k e^{-\mu_k (t - s)}, \qquad \mathbb{X}^{\blambda, \word{v}}_{t} = (x^{i_1}\cdot\ldots\cdot x^{i_n})\prod\limits_{k=1}^n\dfrac{1}{\mu_k}
    \end{equation}
    where $c_k = \prod\limits_{l \neq k}\dfrac{1}{\mu_l - \mu_k}$ and $\mu_k = \sum\limits_{j = 1}^k\lambda^{i_j}, \ k = 0, \ldots, n,$ with $\mu_{0} = 0$.
\end{lemma}
\begin{proof}
    The proof is given in Appendix~\ref{sect:linear_path_proof}.
\end{proof}

We can now state the result for general $\blambda$. The EFM-signature of a linear path can be also written in exponential form, as in \eqref{eq:linear_path_stat_sig}, using the notion of Magnus exponential. 

We rely on the classical result due to \citet{magnus}, adapted to the right multiplication case. It states that the solution to the linear system on $\tTA{N}$
\begin{align}
    \dot{\mathbbm{x}}_t^N &= \mathbbm{x}_t^N\otimes \bm A(t), \quad t \geq s,\\
    \mathbbm{x}_s^N &= \emptyword,
\end{align}
is given by
\begin{equation}\label{eq:magnus_exp}
    \mathbbm{x}_t^N = \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k(s, t)\right),
\end{equation}
where 
\begin{equation}\label{eq:magnus_omega}
\begin{aligned}
    \bm{\Omega}_1(s, t) &= \int_{s}^t \bm A(u_1)du_1, \\
    \bm{\Omega}_2(s, t) &= \dfrac{1}{2}\int_s^tdu_1\int_s^{u_1}du_2 [\bm A(u_1), \bm A(u_2)], \\
    \bm{\Omega}_3(s, t) &= \dfrac{1}{6}\int_s^tdu_1\int_s^{u_1}du_2\int_s^{u_2}du_3 \left([\bm A(u_1), [\bm A(u_2), \bm A(u_3)]] + [[\bm A(u_1), \bm A(u_2)], \bm A(u_3)]\right), \\
    \ldots \\
    \bm{\Omega}_n(s, t) &= \sum_{j=1}^{n-1}\dfrac{B_j}{j!}\sum_{\substack{k_1 + \ldots + k_j = n-1 \\ k_1 \geq 1, \ldots, k_j \geq 1}}\int_s^t\mathrm{ad}_{\bm{\Omega}_{k_1}(s, u)}\ldots\mathrm{ad}_{\bm{\Omega}_{k_j}(s, u)}\bm{A}(u)\,du,
\end{aligned}
\end{equation}
{the bracket $[\cdot, \cdot]$ is the inverse commutator $[\bp, \bq] := \bq \otimes\bp - \bp\otimes\bq$, $\mathrm{ad}_{\bm{B}}\bm{A} := [\bm B, \bm A]$, and $B_j$ stands for the Bernoulli numbers defined through the generating function
$$
\dfrac{x}{e^x-1} = \sum_{n \geq 0}\dfrac{B_n}{n!}x^n.
$$}
The following result requires the inversion of the operator $\G$ introduced in Definition~\ref{def:G_oper}. Although $\G$ is diagonal, it is not injective, since $\G\emptyword = 0$. For this reason, we will use its generalized inverse $\G^\dag$, defined by
\begin{align}\label{eq:G_inv}
    \G^\dag \colon \bell = \sum_{n \geq 0} \sum_{|\word{v}| = n} \ell^{\word{v}} &\mapsto \G^\dag \bell = \sum_{n \geq 1} \sum_{|\word{v}| = n} \frac{1}{\lambda^{\word{v}}} \ell^{\word{v}}.
\end{align}

\begin{theorem}\label{thm:linear_path_magnus}
    Fix $\blambda = (\lambda^1, \ldots, \lambda^d)\in\R^d, \, \blambda\succ 0$. For a linear path $X_t = t \bm{x}$ with $\bm{x} \in \R^d$, its EFM-signature $\mathbb{X}^{\blambda}_{s, t}$ is given by
    \begin{equation}\label{eq:linear_path_stat_sig_magnus}
        \ssigX[s, t] = \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k^{\blambda, {\bm x}}(s, t)\right), \quad
        \ssigX[t] = \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k^{\blambda, {\bm x}}(-\infty, t)\right) = \sum_{k \geq 0}{\bf H}_{\bm x}^k\emptyword,
    \end{equation}
    where ${\bm{\Omega}}_k^{\blambda, {\bm x}}(s, t)$ is given by \eqref{eq:magnus_omega} with $\bm A(u) = \D[t - u]{\bm x}$ and ${\bf H}_{\bm x}\colon \bell \mapsto \G^\dag(\bell\otimes {\bm x})$. The coefficients of the EFM-signature are given explicitly by \eqref{eq:linear_path_coefs_explicit}.
    Moreover, if $\lambda^1 = \ldots = \lambda^d =: \lambda$, then 
    \begin{equation}\label{eq:linear_path_stat_sig_magnus_equal}
        \ssigX[s, t] = e^{\otimes\left(\frac{1 - e^{-\lambda(t - s)}}{\lambda} {\bm x}\right)}, \quad \mathbb{X}^{\blambda}_{t} = \exp\left({\otimes\frac{\bm{x}}{\lambda}}\right).
    \end{equation}
\end{theorem}
\begin{proof}
    In the case of the linear path, the EFM-signature equation \eqref{eq:sig_as_D} reads
    \begin{equation}\label{eq:linear_path_D_sig}
        \ssigX[s, t] = \int_{s}^t \D[t - u](\ssigX[s, u]\otimes x) du, \quad t \geq s.
    \end{equation}
    This implies that $\mathbbm{y}_t := \D[s - t]\ssigX[s, t]$ satisfies the linear equation 
    \begin{align}
        d{\mathbbm{y}}_t &= \mathbbm{y}_t\otimes (\D[s - t]\bm x)\, dt, \quad  t \geq s,\\
        \mathbbm{y}_0 &= \emptyword,
    \end{align}
    so that 
    $$
    \ssigX[s, t] = \D[t - s]{\mathbbm{y}}_t = \D[t - s]\exp\left(\otimes \sum_{k \geq 1}\tilde{\bm{\Omega}}_k^{\blambda, \bm x}(s, t)\right),
    $$
    where $\tilde{\bm{\Omega}}_k^{\blambda, \bm x}(s, t)$ are given by \eqref{eq:magnus_omega} with $\bm A(u) = \D[s - u]\bm x$. Thanks to Proposition~\ref{prop_D_ppties}\,{(vii)}, one has 
    $$
    \D e^{\otimes\bell} = e^{\otimes \D\bell}, \quad h \in \R,\quad \bell \in\eTA.
    $$
    Applying again Proposition~\ref{prop_D_ppties}\,{(vii)}, we obtain that
    $$
    \D[t-s]\tilde{\bm{\Omega}}_k^{\blambda, \bm x}(s, t) = {\bm{\Omega}}_k^{\blambda, \bm x}(s, t), \quad k \geq 1,
    $$
    so that the exponential representation in \eqref{eq:linear_path_stat_sig_magnus} holds. 

    The second part of \eqref{eq:linear_path_stat_sig_magnus} follows from the application of the Picard iterations to \eqref{eq:linear_path_D_sig} and noticing that for all $\bell$ such that $\bell^{\emptyword} = 0$, we have
    \begin{equation}\label{eq:D_int}
        \int_{s}^t \D[t-u]\bell\, du = \G^\dag(\mathrm{Id} - \D[t-s])\bell, \quad\int_{-\infty}^t \D[t-u]\bell\, du = \G^\dag\bell.
    \end{equation}

    In the case $\lambda^1 = \ldots = \lambda^d = \lambda$, the generator $\bm A(u)$ becomes commutative, so that $[\bm A(u_1), \bm A(u_2)] \equiv 0$ and $\bm \Omega_k^{\blambda, \bm x}(s, t) \equiv 0$ for $k \geq 2$. The formula \eqref{eq:linear_path_stat_sig_magnus_equal} follows immediately from \eqref{eq:D_int} with $\bell = \bm x$.
\end{proof}
\begin{corollary}
    The EFM-signature of a piecewise-linear path with breakpoints $t_0 < t_1 < \ldots < t_n$ is given recursively by
\begin{equation}\label{eq:piecewise_linear_path_stat_sig_piece_magnus}
       \ssigX[t_0, t_n] = (\D[t_n - t_{n-1}]\ssigX[t_0, t_{n-1}]) \otimes \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k^{\blambda, \frac{X_{t_n} - X_{t_{n-1}}}{t_n - t_{n-1}}}(t_{n-1}, t_n)\right). 
    \end{equation}
\end{corollary}
\begin{corollary}
    The EFM-signature $\sigX[s, t]^{\blambda, \leq N}$, truncated at order $N$, belongs to the standard Lie group $G^N$ corresponding to the Lie algebra $\mathfrak{g}^N$ generated by $\word{1}, \ldots, \word{d}$. 
\end{corollary}
\begin{proof}
    Since $\bm A(u) = \D[t - u]\bm x = \sum_{i=1}^d e^{-\lambda^i(t-u)}x^i\word{i} \in \mathfrak{g}^N$, the formula \eqref{eq:linear_path_stat_sig_magnus} implies that $\sigX[s, t]^{\blambda, \leq N} \in G^N$. It remains to notice that $\D[h]$ preserves the group as a dilation operator multiplying the $i$-th component of the path by $e^{-\lambda^i h}$, so that the EFM-signature of piecewise linear paths also belongs to $G^N$ thanks to \eqref{eq:piecewise_linear_path_stat_sig_piece_magnus}. Finally, an arbitrary path can be approximated by a piecewise linear one and the statement follows from the closedness of $G^N$.
\end{proof}

Thus, the EFM-signature process $\sigX[t]^{\blambda, \leq N}$, being a Lie group-valued process, can be seen as a mean-reverting analogue of the signature. Moreover, since the signature of $d$-dimensional Brownian motion $\sigX[][W]$ is the Brownian motion on $G^N$ in the sense of \cite[Definition 1.2]{Baudoin}, the EFM-signature $\ssigX[][W]$ plays the role of the Ornstein--Uhlenbeck process on $G^N$.

\subsection{Time reparametrization}
It is well-known that the signature of path is invariant under time reparametrizations. Namely, for any smooth reparametrization $\psi\colon\ [0, T] \to [0, T]$, denote $\tilde X_t := X_{\psi_t}$. It follows that
$$
\int_{0 < u_1 < \cdots < u_n < T} \circ d X_{u_1} \otimes \cdots \otimes \circ d X_{u_n}  = \int_{0 < u_1 < \cdots < u_n < T} \circ d\tilde X_{u_1} \otimes \cdots \otimes \circ d\tilde X_{u_n}.
$$
Similarly, for the EFM-signatures,
\begin{align*}
    &\int_{s < u_1 < \cdots < u_n < t}  e^{-\blambda(t - u_1)}\odot d X_{u_1} \otimes\circ  \cdots  \otimes \circ e^{-\blambda(t - u_n)} \odot d X_{u_n} \\ = &\int_{s < u_1 < \cdots < u_n < t}  e^{-\blambda(\psi_t - \psi_{u_1})}\odot d\tilde X_{u_1} \otimes\circ \cdots \otimes \circ e^{-\blambda(\psi_t - \psi_{u_n})}\odot d\tilde X_{u_n}.
\end{align*}
At first glance, it may seem that the EFM-signature is not invariant under time reparametrization. However, the notion of time-invariance does not exist without a time structure. Therefore, any path $(X_t)_{t \in \R}$ parametrized by $t \in \R$ should be interpreted as a time-evolving process, equipped with a corresponding time process $(\tau_t)_{t \in \R}$. In this setting, it is natural to define the EFM-signature as $\ssigX[s, t][X][\blambda] = (\ssigX[s, t][X][\blambda, n])_{n \geq 0}$, where
\begin{equation}
    \ssigX[s, t][X][\blambda, n] := \int_{s < u_1 < \cdots < u_n < t}  e^{-\blambda(\tau_t - \tau_{u_1})} \odot d X_{u_1} \circ \otimes \cdots \otimes \circ e^{-\blambda(\tau_t - \tau_{u_n})} \odot  d X_{u_n},
\end{equation}
which is indeed invariant under the simultaneous reparametrization of both the path $\tilde X_t = X_{\psi_t}$ and the time process $\tilde \tau_t = \tau_{\psi_t}$, for any smooth reparametrization $\psi\colon \R \to \R$. To simplify notation, we will always assume that the parametrization of the path is chosen so that $\tau_t = t$ for all $t \in \R$.

\subsection{Uniqueness of the EFM-signature}

The uniqueness of the signature means that the signature determines the path up to tree-like equivalence, as shown by \cite{hambly2010uniqueness}. In particular, the signature of the time-augmented path $\widehat{X}_t = (t, X_t),\ t \in [0, T]$ determines the path uniquely; see, for instance, \cite[Lemma 2.6]{cuchiero2022theocalib} for a simple proof in the case of continuous semimartingales. However, this proof is not applicable in the EFM-signature framework, since polynomials of the form $(X_t^i)^n$ cannot be represented as elements of the EFM-signature. Nevertheless, the uniqueness result remains true.

For notational simplicity, when working with time-augmented paths $\widehat{X} = (t, X_t)$, we denote the time component by the letter $\word{0}$, and the spatial components of $X$ by the letters $\word{1}, \ldots, \word{d}$.

\begin{theorem}\label{thm:uniqueness}
    Let $X = (X_t)_{-\infty < t \leq T}$ and $Y = (Y_t)_{-\infty < t \leq T}$ be two continuous $\R^d$-valued semimartingales. Consider the time-augmented paths $\widehat{X}_t := (t, X_t)$ and $\widehat{Y}_t := (t, Y_t)$ with EFM-signatures $\ssig[t][X]$ and $\ssig[t][Y]$. Then $\ssigX[T][\widehat X] = \ssig[T][Y]$ if and only if
    $
    X_t = Y_t + c
    $
    for all $t \in (-\infty, T]$ and some real constant $c \in \R$.
\end{theorem}

\begin{proof}
    {It is clear that $X_t = Y_t + c$ for $t \leq T$ implies equality of the EFM-signatures. We will prove the converse in two steps.}

    \textbf{Step 1}. We will show that $\ssig[T][X] = \ssig[T][Y]$ implies 
    \begin{equation}\label{eq:unique_laplace}
        \int_{-\infty}^T e^{-\mu(T - t)}\bracketssig[t][X]{\word{i}}dt =
        \int_{-\infty}^T e^{-\mu(T - t)}\bracketssig[t][Y]{\word{i}}dt, \quad \mu > \lambda^0 + \lambda^i, \quad i \in \{1, \ldots, d\}.
    \end{equation}
    First, it follows from Lemma \ref{lemma:exp_representations} that for $k \geq 1$,
    $$
    \int_{-\infty}^T e^{-(k\lambda^0 + \lambda^i)(T - t)}\bracketssig[t][X]{\word{i}}dt = \int_{-\infty}^T e^{-(k\lambda^0 + \lambda^i)(T - t)}\bracketssig[t][Y]{\word{i}}dt, \quad i \in \{1, \ldots, d\}.
    $$
    Denoting $Z_t^i := \bracketssig[t][X]{\word{i}} - \bracketssig[t][Y]{\word{i}}$, this can be written as
    \begin{equation}
        J_k^i := \int_{-\infty}^T e^{-k\lambda^0 (T - t)} \bigl(Z_t^i e^{-(\lambda^0 + \lambda^i)(T - t)}\bigr) dt = 0, \quad k \geq 0,
    \end{equation}
    and we want to show that
    \begin{equation}
        J_{\mu}^i := \int_{-\infty}^T e^{-(\mu - \lambda^0 - \lambda^i)(T - t)} \bigl(Z_t^i e^{-(\lambda^0 + \lambda^i)(T - t)}\bigr) dt = 0, \quad \mu > \lambda^0 + \lambda^i.
    \end{equation}
    By Theorem~\ref{thm:fm_sig_existence}, the EFM-signature elements belong to $\hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$, so that $(Z_t^i e^{-\lambda^i (T - t)})$ is almost surely bounded and the integral
    \[
        \int_{-\infty}^T |Z_t^i| e^{-(\lambda^0 + \lambda^i)(T - t)} dt
    \]
    is almost surely finite.

    Note that $e^{-(\mu - \lambda^0 - \lambda^i)(T - t)}$ can be approximated arbitrarily well by
    \begin{equation}\label{eq:series_repr}
        e^{-(\mu - \lambda^0 - \lambda^i)(T - t)} \approx \sum_{k=0}^N c_k e^{-k \lambda^0 (T - t)}, \quad t \geq 0,
    \end{equation}
    uniformly on $\R^+$.  
    Indeed, taking $x = e^{-\lambda^0 (T - t)} \in (0,1]$ makes this approximation equivalent to the uniform approximation by a polynomial
    \[
        x^\beta \approx \sum_{k=0}^N c_k x^k, \quad x \in (0,1],
    \]
    with $\beta = \frac{\mu - \lambda^0 - \lambda^i}{\lambda^0} > 0$,  
    which holds since the function $x \mapsto x^\beta$ is continuous on $[0,1]$. This means that for any $\epsilon > 0$, there exist $N$ and coefficients $c_0, c_1, \ldots, c_N$ such that
    \[
        |J_\mu^i| = \left|J_\mu^i - \sum_{k=0}^N c_k J_k^i \right| \leq \epsilon,
    \]
    so that $J_\mu^i = 0$.

    \textbf{Step 2}. Differentiating \eqref{eq:unique_laplace} with respect to $\mu$, we obtain
    \begin{equation}
    (-1)^n \int_{-\infty}^T e^{-\mu(T - t)} (T - t)^n Z_t^i \, dt = 0,
    \end{equation}
    for all $n \in \N$ and $\mu > \lambda^0 + \lambda^i$.
    Since the Laguerre polynomials form a basis of $L^2(\R^+, e^{-\mu x}dx)$, we conclude that $Z_t^i \equiv 0$ for $i = 1, \ldots, d$, by continuity.
     As $\bracketssig[t][X]{\word{i}}$ and $\bracketssig[t][Y]{\word{i}}$  satisfy the equations
    \begin{align}
        d \bracketssig[t][X]{\word{i}} = -\lambda^i \bracketssig[t][X]{\word{i}}dt + dX_t^{i}, \\
        d \bracketssig[t][Y]{\word{i}} = -\lambda^i \bracketssig[t][Y]{\word{i}}dt + dY_t^{i}, 
    \end{align}
    it follows that $d(X_t^{i} - Y_t^{i}) \equiv 0$ for $i = 1, \ldots, d$, which implies the statement of the theorem.
\end{proof}

The uniqueness result allows us to conclude that any functional of the path $X$ can be expressed as a function of the EFM-signature of this path:
$$
F\big((X_s)_{s \leq t}\big) = \tilde{F}\big(\ssigX[t][\widehat{X}]\big),
$$
for some function $\tilde{F}$, provided that the EFM-signature $\ssigX[t][\widehat{X}]$ captures all the information contained in the path $(X_s)_{s \leq t}$.

\subsection{Linearization property}

Another important operation on $\eTA$ is the shuffle product, which allows for the linearization of products of two linear functionals of the signature; see \cite*[Theorem 2.15]{lyons2007differential}. For basis vectors $\word{v}, \word{w} \in \eTA$ and letters $\word{i}, \word{j}$, the shuffle product is defined recursively by
\begin{align*}
    (\word{v} \word{i}) \shuprod (\word{w} \word{j}) &
    = (\word{v} \shuprod (\word{w} \word{j})) \word{i} + ((\word{v} \word{i}) \shuprod \word{w}) \word{j}, \\
    \word{w} \shuprod \emptyword &= \emptyword \shuprod \word{w} = \word{w},
\end{align*}
and extended to $\eTA$ by linearity. The following proposition establishes the shuffle property for EFM-signatures.

\begin{proposition}\label{prop:shuffle}
    If $\bell_1, \bell_2 \in \TA$, then $\bell_1 \shuprod\bell_2 \in \TA$ and
    \begin{equation}
        \bracketssigX{\bell_1}\bracketssigX{\bell_2} = \bracketssigX{\bell_1\shuprod\bell_2}.
    \end{equation}
\end{proposition}
\begin{proof}
    By linearity, it is enough to prove the proposition for $\bell_1 = \word{u}$ and $\bell_2 = \word{v}$ with $\word{u}, \word{v} \in V$. We proceed by induction on $|\word{u}| + |\word{v}|$. If $\word{u} = \emptyword$ or $\word{v} = \emptyword$, the equality is trivial.

    Therefore, we consider $\word{u} = \word{\tilde u i}$ and $\word{v} = \word{\tilde v j}$ for some $i, j \in \alphabet$.
    Since
    \begin{align}
        d\bracketssigX{\word{u}} &= -\lambda^{\word{u}}\bracketssigX{\word{u}}\,dt + \bracketssigX{\word{\tilde u}}\circ dX_t^i,\\
        d\bracketssigX{\word{v}} &= -\lambda^{\word{v}}\bracketssigX{\word{v}}\,dt + \bracketssigX{\word{\tilde v}}\circ dX_t^j,
    \end{align}
    we have
    \begin{align}
        &d\left(\bracketssigX{\word{u}}\bracketssigX{\word{v}}\right) = 
        d\bracketssigX{\word{u}}\bracketssigX{\word{v}} + \bracketssigX{\word{u}}d\bracketssigX{\word{v}}
        \\ &= -(\lambda^{\word{u}} + \lambda^{\word{v}})\bracketssigX{\word{u}}\bracketssigX{\word{v}}\,dt + \bracketssigX{\word{v}}\bracketssigX{\word{\tilde u}}\circ dX_t^i + \bracketssigX{\word{u}}\bracketssigX{\word{\tilde v}}\circ dX_t^j,
    \end{align}
    so that 
    \begin{align}
        \bracketssigX{\word{u}}\bracketssigX{\word{v}} &= \int_{-\infty}^te^{-(\lambda^{\word{u}} + \lambda^{\word{v}})(t-s)}\left[\bracketssigX[s]{\word{v}}\bracketssigX[s]{\word{\tilde u}}\circ dX_s^i + \bracketssigX[s]{\word{u}}\bracketssigX[s]{\word{\tilde v}}\circ dX_s^j\right] \\
        &= \int_{-\infty}^te^{-(\lambda^{\word{u}} + \lambda^{\word{v}})(t-s)}\left[\bracketssigX[s]{\word{v}\shuprod\word{\tilde u}}\circ dX_s^i + \bracketssigX[s]{\word{u} \shuprod\word{\tilde v}}\circ dX_s^j\right] \\ 
        &= \bracketssigX[s]{(\word{v}\shuprod\word{\tilde u})\word{i} + (\word{u} \shuprod\word{\tilde v})\word{j}},
    \end{align}
    where we have used the induction hypothesis and \eqref{eq:def_stat_sig_coef}.
\end{proof}

\begin{sqremark}
    An alternative proof of the shuffle property consists in noticing that the EFM-signature $\sigX[T]$ can be seen as the standard signature of the weighted process $X^T = (X^T_t)_{t \leq T}$ defined by
    $$
        dX^T_t = \D[T - t](dX_t), \quad t \leq T.
    $$
    We denote this signature by $\sigX[t]^T$ and observe that the shuffle property holds for it. Finally, since
    $$
        \ssigX[T] = \sigX[T]^T,
    $$
    the shuffle property holds for the EFM-signature as well.
    This perspective also provides an alternative proof of Chen's identity \eqref{eq:stat_chen}, which follows from the classical Chen's identity for $\sigX[t]^T$ combined with the multiplicative property of $\D$ given by Proposition~\ref{prop_D_ppties}\,(ii).
\end{sqremark}

\subsection{Universal approximation theorem} 
The goal of this section is to show that a sufficiently large class of functions of path $F((X_t)_{t \leq T})$ can be approximated by a linear functional of the EFM-signature $\bracketssigX[T][\widehat X]{\bell}$ of the time-augmented path $\widehat X_t = (t, X_t)$. In particular, if the approximation holds for $F$, the time-invariant output signal \eqref{eq:time_invariance} is approximated uniformly in $t\in\R$, i.e.,
\begin{equation}
    Y_t = F((X_s)_{s\leq t}) \approx \bracketssigX[t][\widehat X]{\bell}, \quad t \in\R.
\end{equation}

As for signatures, this result is based on the Stone--Weierstrass approximation theorem \cite[Theorem 7.32]{rudin1976principles}.

\begin{theorem}[Stone--Weierstrass]
    Let $K \subset \mathcal{X}$ be a compact set and let $\mathcal{A}$ denote the class of functions $f\colon\ \mathcal{X} \to \R$ satisfying:
    \begin{enumerate}
        \item Every $f \in \mathcal{A}$ is continuous;
        \item the constant function $1 \in \mathcal{A}$;
        \item if $f, g \in \mathcal{A}$, then $fg \in \mathcal{A}$;
        \item for $x, y \in \mathcal{X}$, such that $x \not= y$, there exists $f \in \mathcal{A}$, such that $f(x) \not= f(y)$.
    \end{enumerate}
    Then, for any continuous function $F\colon\ \mathcal{X} \to \R$ and for any $\epsilon > 0$, there exists $f \in \mathcal{A}$, such that $|F(x) - f(x)| < \epsilon$ for all $x \in K$.
\end{theorem}

Since for standard signatures on a finite interval $[0, T]$, the natural path space is the space of rough paths $\mathscr{C}^{\alpha}([0, T], \R^d)$, see, for example, \cite{cuchiero2022theocalib}, we will use $\mathcal{X} = \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$ with $0 \prec \brho \prec \blambda,$ and consider functionals
\begin{equation}\label{eq:sig_as_rp_functional}
    F\colon\ \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d) \to \R, \quad \mathbf{X} \mapsto F(\mathbf{X}),
\end{equation}
continuous in the exponentially weighted rough path topology. Since $\mathbf{X}$ contains all the increments of $X$, the set of functionals of the form \eqref{eq:sig_as_rp_functional} contains all dependencies of the form $Y_t = F((X_t - X_s)_{s \leq t})$.

\begin{theorem}\label{thm:UAT} 
    Consider a compact set $K \subset \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$ and a continuous function $F \colon\ \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d) \to \R$. Then, for any $\epsilon > 0$, there exists $\bell \in \TA$ such that, for all $\mathbf{X} \in K$,
    \[
        \left| F(\mathbf{X}) - \bracketssigX[T][\widehat X]{\bell} \right| < \epsilon.
    \]
\end{theorem}
\begin{proof}
    The proof consists in the application of the Stone--Weierstrass theorem.
    As the class $\mathcal{A}$, we choose the class of finite linear functionals of the EFM-signature:
\begin{equation}
    \mathcal{A}:=\left\{\mathbf{X} \mapsto \bracketssigX[T][\widehat X]{\bell}\colon\ \bell\in\TA \right\}.
\end{equation}

Each functional in this class is continuous by Theorem~\ref{thm:rough_fm}.
The second condition of the Stone--Weierstrass theorem is trivially satisfied since $\bracketssigX[t][\hat X]{\emptyword} \equiv 1$. The third condition holds due to the shuffle property given by Proposition~\ref{prop:shuffle}. The point-separation condition 4 follows from the uniqueness result, Theorem~\ref{thm:uniqueness}.
\end{proof}

This result can be seen as a combination of the classical universal approximation theorem for signatures and Theorem~1 in the paper by \cite{Boyd1985FadingMA} considering the approximation of operators with fading memory, which is essentially the continuity in the weighted distance.

\begin{sqremark}
    One can establish a similar result for regular processes by choosing the space of absolutely continuous paths with finite norm $\|X\|_{\mathrm{BV}, \blambda} < \infty$. The continuity of the signature map in this case follows from Proposition~\ref{prop:fm_bv_case}.
\end{sqremark}

\subsection{Moment problem}
The universal approximation theorem allows us to establish that a measure defined on a compact set of paths is determined by the expected EFM-signature. Namely, the following proposition holds.
\begin{proposition}\label{prop:momentss}
    Let $\P$ and $\Q$ be probability measures on a compact set $K \subset \mathscr{C}^{\alpha, \brho}((-\infty, T], \R^d)$. If their expected (time-augmented) EFM-signatures are equal, i.e.
    \begin{equation}\label{eq:moments_equality}
        \E^\P[\ssigX[T][\widehat X]] = \E^\Q[\ssigX[T][\widehat X]],
    \end{equation}
    then $\P = \Q$.
\end{proposition}
\begin{proof}
It is sufficient to prove that for any continuous function $F\colon K \to \R$,
\begin{equation}\label{eq:func_eq_moment_pb}
    \E^\P\left[F(\mathbf{X})\right] = \E^\Q\left[F(\mathbf{X})\right].
\end{equation}
By Theorem \ref{thm:UAT}, for any $\epsilon > 0$, there exists $\bell \in \TA$ such that 
$$
\left|F((X_s)_{s \leq T}) - \bracketssigX[T][\widehat X]{\bell}\right| < \epsilon.
$$
Since 
$
\E^\P\left[\bracketssigX[T][\widehat X]{\bell}\right] = \E^\Q\left[\bracketssigX[T][\widehat X]{\bell}\right],
$
it follows that
$$
\left|\E^\P[F(\mathbf{X})] - \E^\Q[F(\mathbf{X})]\right| < 2\epsilon.
$$
As $\epsilon > 0$ can be chosen arbitrarily small, the equality \eqref{eq:func_eq_moment_pb} holds, which completes the proof.
\end{proof}
\begin{sqremark}
    The compactness assumption above can be weakened in the context of the signature moments problem, as shown by \citet{Chevyrev2022}. We believe that the same ideas and techniques can be extended to the setting of EFM-signatures to obtain stronger results. For instance, we conjecture that the notions of tensor normalization and robust signature moments, in the spirit of \cite{Chevyrev2022}, can be suitably defined for the EFM-signature as well.
\end{sqremark}

\section{EFM-signature of the time-augmented Brownian motion}\label{sect:SSig_BM}

In this section, we focus on a particularly interesting case where the path is the time-augmented standard Brownian motion $\widehat{W}_t = (t, W_t^1, \ldots, W_t^d)$. {Recall that the EFM-signature of $\widehat{W}$ is well-defined, see Remark~\ref{rem:BM_EFM_sig_well_def}.} While its standard signature $\sig[]$ inherits several key properties of Brownian motion---namely, $\sig[0] = \emptyword$, and $\sig[t, t+h]$ is independent of $\F_t$ with a law depending only on $h$---the EFM-signature $\ssig[]$ can be viewed as an Ornstein--Uhlenbeck process on the Lie group. Indeed, beyond the mean-reverting dynamics 
\begin{equation}\label{eq:fm_sig_bm_sde}
    d\ssig[t] = -\G \ssig[t]\,dt + \ssig[t]\otimes\circ d\widehat{W}_t, \quad t\in\R,
\end{equation}
and the stationarity established in Theorem~\ref{thm:stationarity}, we will show that it is an ergodic Markov process. Moreover, we prove that the non-stationary version $\ssig[0, t]$ converges exponentially fast to the stationary distribution in the Wasserstein distance. Finally, we compute the expected EFM-signature in both the stationary and non-stationary settings, in analogy with the celebrated result of \citet{fawcett}.

\subsection{Markov property for $\ssig[]$}

The EFM-signature $\ssig[]$ can be considered as an adapted $\eTA[d+1]$-valued stochastic process. We equip the state space $\eTA[d+1]$ with the norm  
$$
\|\bell\|_2 := \sqrt{\sum_{n \geq 0} \sum_{|\word{v}| = n} |\bell^\word{v}|^2},
$$
and denote 
$$
{L}^2\eTA[d+1] = \left\{ \bell\in\eTA[d+1] \colon\ \|\bell\|_2 < +\infty\right\}.
$$

When equipped with a scalar product
$$
\langle\bell, \bsigma\rangle_{2} := \sum_{n \geq 0} \sum_{|\word{v}| = n} \bell^\word{v}\bsigma^\word{v},
$$
it becomes a separable Hilbert space isomorphic to the standard $\ell^2$ space.
We denote by $\mathcal{B}({L}^2\eTA[d+1])$ the Borel sigma-algebra generated by the open sets of ${L}^2\eTA[d+1]$.

The following lemma ensures that $\ssig$ and $\ssig[0, t]$ are indeed elements of ${L}^2\eTA[d+1]$ for any $t \in \R$.

\begin{lemma}\label{lemma:L1_bound}
    There exists a constant $M_{\blambda} > 0$, such that 
    $$
    \E[\|\ssig[t]\|_2^2] \leq M_{\blambda}, \quad t \in\R \quad \text{ and } \quad \sup_{t\geq 0}\E[\|\ssig[0, t]\|_2^2] \leq M_{\blambda}.
    $$
\end{lemma}
\begin{proof}
    The proof is given in Appendix~\ref{app:lemma_l1_proof}
\end{proof}

Lemma~\ref{lemma:L1_bound} states that $\ssig[] = (\ssig)_{t \in \R}$ can be considered as a general Markov process with state space $({L}^2\eTA[d+1],\, \mathcal{B}({L}^2\eTA[d+1]))$, as shown in the following proposition.

\begin{theorem}\label{thm:Markov}
    The process $\ssig[] = (\ssig)_{t \in\R}$ is a Markov process in the sense that for any measurable bounded function $f: L^2\eTA[d+1] \to \R$, the Markov property is verified:
    \begin{equation}
        \E\left[f(\ssig) \, \Big| \, \F_s\right] = \E\left[f(\ssig) \, \Big| \, \ssig[s]\right], \quad t \geq s.
    \end{equation}
\end{theorem}
\begin{proof}
    For a measurable bounded $f$ and $t \geq 0$, we have
    \begin{equation}
        \E\left[f(\ssig) \, \Big| \, \F_s\right] = \E\left[f(\D[t - s]\ssig[s]\otimes\ssig[s, t]) \, \Big| \, \F_s\right] = \E\left[f(\D[t - s]\bell\otimes\ssig[s, t]) \, \Big| \, \F_s\right] \bigg|_{\bell = \ssig[s]} = \E\left[f(\D[t - s]\bell\otimes\ssig[s, t])\right] \bigg|_{\bell = \ssig[s]}.
    \end{equation}
    Here we have used the Chen's identity, the measurability of $\ssig[s]$ with respect to $\F_s$ and finally, independence of $\ssig[s, t]$ and $\F_s$.
\end{proof}

\subsection{Ergodicity of $\ssig[]$}

As we have already shown in Theorem~\ref{thm:stationarity} and Theorem~\ref{thm:Markov}, $\ssig$ is a stationary Markov process. The process $(\ssig[0, t])_{t \geq 0}$ corresponds to its nonstationary version, starting from $\ssig[0, 0] = \emptyword$ (i.e., we assume that the underlying path is constant on the negative half-line: $\widehat{W}_t \equiv 0$ for $t < 0$). As a one-dimensional analogy, one can think of the stationary Ornstein--Uhlenbeck process $\int_{-\infty}^t e^{-\lambda(t-s)}\,dW_s$ and its nonstationary {counterpart} $\int_{0}^t e^{-\lambda(t-s)}\,dW_s$.

A natural question arises: How quickly does the law of $\ssig[0, t]$ converge to the stationary distribution $\mathcal{L}(\ssig)$?

In this section, we will show that, exactly as in the Ornstein--Uhlenbeck case, this convergence is geometric in the Wasserstein distance 
\begin{equation}\label{eq:Wasser_def}
    \mathcal{W}_2(\mu, \nu) = \sqrt{\inf_{\pi\in \Pi(\mu, \nu)}\int\|\mathbbm{x} - \mathbbm{y}\|^2_2\,\pi(d\mathbbm{x}, d\mathbbm{y})}, \quad \mu, \nu \in \mathcal{P}(L^2\eTA),
\end{equation}
where $\Pi(\mu, \nu)$ stands for a set of all coupling of $\mu$ and $\nu$.


More precisely, we will prove that the dependence on the initial condition decays exponentially with rate $\min_{i}\lambda^i$. In particular, this will imply the uniqueness of the invariant distribution and the ergodicity of the EFM-signature process.

\begin{theorem}\label{thm:ergodicity}
Let $W = (W_t)_{t \in \R}$ denote a Brownian motion and let $x = (x_t)_{t \leq 0}$ be a continuous semimartingale. Consider the path obtained by concatenation of $(x_t)_{t \leq 0}$ with $(W_t)_{t \geq 0}$ at $t = 0$:
$$
X_t = \begin{cases}
    x_t, \ &t \leq 0, \\
    x_0 + W_t, \ &t > 0,
\end{cases} \qquad
$$ Assume {that $x$ and $(W_t - W_0)_{t \geq 0}$ are independent} and that the EFM-signature $\widehat{\mathbbm{x}}^{\blambda}_t$ of the time-augmented path $\widehat{x}_t = (t, x_t)$ is well-defined as a process in ${L}^2\eTA[d+1]$ for $t \leq 0$ with $\E[\|\widehat{\mathbbm{x}}^{\blambda}_0\|_2^2] < \infty$. Let $\ssigX[t][\widehat{X}]$ denote the EFM-signature of $\widehat{X}_t = (t, X_t), \, t\in\R$ and set  $\mu_t = \mathcal{L}(\ssigX[t][\widehat{X}]),\, t \geq 0$. Then,
there exists a unique ergodic measure $\mu_* = \mathcal{L}(\ssig[t])$ and a constant $M_{\blambda} > 0$ such that
\begin{equation}\label{eq:wasserstein_bound}
    \mathcal{W}_2^2(\mu_t, \mu_*) \leq 2M_{\blambda}\left(\E\left[\left\|\widehat{\mathbbm{x}}^{\blambda}_0\right\|_2^2\right] + M_{\blambda}\right)e^{-2\lambda^{\mathrm{min}} t},
\end{equation}
where $\lambda^{\mathrm{min}} = \min\limits_i \lambda^i$. In particular, taking $x \equiv 0$, one obtains
\begin{equation}\label{eq:wasserstein_bound}
    \mathcal{W}_2^2(\mathcal{L}(\ssig[0, t]), \mathcal{L}(\ssig[t])) \leq 2M_{\blambda}^2 e^{-2\lambda^{\min} t},
\end{equation}
\end{theorem}
\begin{proof}
    First, note that $\ssigX[t][\widehat{X}] = \widehat{\mathbbm{x}}^{\blambda}_t$ for $t \leq 0$.
    By Chen's identity \eqref{eq:stat_chen}, we have, for $t \geq 0$,
\begin{equation}
    \ssigX[t][\widehat{X}] = \D[t]\ssigX[0][\widehat{X}]\otimes\ssig[0, t], \quad \ssig[t] = \D[t]\ssig[0]\otimes\ssig[0, t],
\end{equation}
and 
\begin{equation}
    \ssigX[t][\widehat{X}] -  \ssig[t] = \D[t]\left(\ssigX[0][\widehat{X}] - \ssig[0]\right)\otimes\ssig[0, t].
\end{equation}
We note that the norm $\|\cdot\|_2$ is compatible with the tensor product, i.e., for any $\bell, \bp \in \eTA[d+1]$ such that $\|\bell\|_2 < +\infty$ and $\|\bp\|_2 < +\infty$, we have
$$
\|\bell\otimes\bp\|_2 = \|\bell\|_2 \|\bp\|_2 < +\infty.
$$
Then, 
\begin{equation}\label{eq:exp_conv_wasser}
    \left\|\ssigX[t][\widehat{X}] -  \ssig[t]\right\|_2^2 = \left\|\D[t]\left(\ssigX[0][\widehat{X}] - \ssig[0]\right)\right\|_2^2 \|\ssig[0, t]\|_2^2.
\end{equation}
Conditioning with respect to $x$ and then taking the expectation, we obtain
\begin{equation}\label{eq:ergodicity_ineq}
\begin{aligned}
    \E\left[\left\|\ssigX[t][\widehat{X}] -  \ssig[t]\right\|_2^2\right] &= \E\left[\left\|\D[t]\left(\ssigX[0][\widehat{X}] - \ssig[0]\right)\right\|_2^2\right]\E[\|\ssig[0, t]\|_2^2] \\
    &\leq e^{-2\lambda^{\mathrm{min}} t}\E\left[\left\|\ssigX[0][\widehat{X}] - \ssig[0]\right\|_2^2 \right]\E[\|\ssig[0, t]\|_2^2] \\
    &\leq 2M_{\blambda}\left(\E\left[\left\|\ssigX[0][\widehat{X}]\right\|_2^2\right] + M_{\blambda}\right)e^{-2\lambda^{\mathrm{min}} t},
\end{aligned}
\end{equation}
where we applied Lemma~\ref{lemma:L1_bound} and the trivial observation that $\|\D\bell\|_2 \leq e^{-\lambda^{\mathrm{min}} h}\|\bell\|_2$ for all $\bell \in \eTA[d+1]$ such that $\bell^{\emptyword} = 0$.

By definition \eqref{eq:Wasser_def}, the same bound holds for $\mathcal{W}_2^2(\mu_t, \mu_*)$. In particular, \eqref{eq:ergodicity_ineq} implies the uniqueness of the invariant measure $\mu_*$. Hence, this invariant measure is ergodic \cite[Corollary 5.12]{hairer2006ergodic}. 
\end{proof}

\begin{corollary}
    The continuous-time version of the Birkhoff--Khinchin ergodic theorem \cite[Corollary 10.9]{kallenberg1997foundations} then implies that, for any measurable integrable function $f: \eTA[d+1] \to \R$,
\begin{equation}\label{eq:time-average}
    \lim_{T \to \infty} \frac{1}{T} \int_0^T f(\ssig)\,dt = \E\left[f(\ssig[0])\right].
\end{equation}

The convergence in \eqref{eq:time-average} is important for applications, as it allows for the estimation of relevant statistics (e.g., signature moments) and enables learning the law of the stationary process from a single trajectory observed over a sufficiently long time horizon.
\end{corollary}

\subsection{Expected EFM-signature of the Brownian motion.}
The expected signature of Brownian motion is given by Fawcett's formula (see \cite{fawcett}). 

In this section, we aim to compute the expected EFM-signatures:
\begin{enumerate}
    \item $\Essig[] := \ssigE[t]$, corresponding to the stationary distribution;
    \item $\Essig[t - s] := \ssigE[s, t]$, the expected EFM-signature on $[s, t]$.
\end{enumerate}
Since $\mathcal{L}(\ssig[s, t])$ converges weakly to the stationary law $\mathcal{L}(\ssig[t])$ as $s \to -\infty$, and since $\sup\limits_{t \geq s} \E[\|\ssig[s, t]\|_2^2] \leq M_{\blambda}$ by Lemma~\ref{lemma:L1_bound}, the expected EFM-signatures converge as well:
\begin{equation}
    \Essig[h] \underset{h \to \infty}{\longrightarrow} \Essig[].
\end{equation}


The importance of the Magnus expansion for the computation of expected signatures in a general semimartingale context was highlighted by \citet*{friz2022unified, friz2024expected}. We will show that for the time-augmented Brownian motion path, the expected EFM-signature computation problem reduces to the computation of an EFM-signature of a linear path, a problem we have already treated in Subsection~\ref{sect:linear_path} using the Magnus exponential. Indeed, let us denote $\word{\tilde 0} := \word{0}$ and $\word{\tilde i} := \word{ii}$ for $\word{i} \in \{\word{1}, \ldots, \word{d}\}$ and the alphabet $\tilde A_{d + 1} = \{\word{\tilde 0}, \word{\tilde 1}, \ldots, \word{\tilde{d}}\}$. Note that the words formed by the letters of $\tilde A_{d + 1}$ form a subset of words in the initial alphabet $ A_{d + 1} = \{\word{ 0}, \word{ 1}, \ldots, \word{{d}}\}$ that correspond to the non-zero elements of the expected EFM-signature. 

Let $\mathbb{T}^{\tilde\blambda}$ denote the EFM-signature of the linear path $T_t = t\cdot (1, \frac{1}{2}, \ldots, \frac{1}{2})$ corresponding to the new alphabet $\tilde A_{d + 1}$ and $\tilde\blambda = (\lambda^{\word{\tilde{0}}}, \lambda^{\word{\tilde{1}}}, \ldots, \lambda^{\word{\widetilde{d}}})$. We recall that this signature is given in closed form by Theorem~\ref{thm:linear_path_magnus}.

\begin{theorem}\label{thm:expected_sig}
    Let $\Essig[]$ and $\Essig[t-s]$ be defined as above. Then,
    \begin{equation}\label{eq:expected_fm_sig}
    \begin{aligned}
        \Essig[t-s] = \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k^{\Essig[]}(s, t)\right),\quad
        \Essig[] = \exp\left(\otimes \sum_{k \geq 1}\bm{\Omega}_k^{\Essig[]}(-\infty, t)\right) = \sum_{k=0}^\infty {\bf H}_{\left(\word{1} +  \frac12\sum\limits_{i=1}^{d}\word{ii}\right)}^k\emptyword,
    \end{aligned}
    \end{equation}   
    where ${\bm{\Omega}}_k^{\Essig[]}(s, t)$ is given by \eqref{eq:magnus_omega} with $\bm A(u) = \D[t - u]\left(\word{1} +  \dfrac12\sum\limits_{i=1}^{d}\word{ii}\right)$, and the operator ${\bf H}$ is defined in Theorem~\ref{thm:linear_path_magnus}. The non-zero coefficients are given explicitly by
    \begin{equation}
        (\Essig[t-s])^{\word{\tilde{i}_1 \ldots \tilde{i}_n}} = \mathbb{T}_{0, t-s}^{\tilde\blambda, \word{\tilde{i}_1 \ldots \tilde{i}_n}}, \quad (\Essig[])^{\word{\tilde{i}_1 \ldots \tilde{i}_n}} = \mathbb{T}_{0}^{\tilde\blambda, \word{\tilde{i}_1 \ldots \tilde{i}_n}}.
    \end{equation}
    Moreover, if $\lambda^0 = 2\lambda^1 = \ldots = 2\lambda^d =: \lambda$, then 
    \begin{equation}
        \Essig[t-s] = \exp\left(\otimes\left(\frac{1 - e^{-\lambda(t - s)}}{\lambda}\right)  \left(\word{1} +  \frac12\sum\limits_{i=1}^{d}\word{ii}\right)\right), \quad \Essig[] = \exp\left({\otimes\frac{1}{\lambda}\left(\word{1} +  \frac12\sum\limits_{i=1}^{d}\word{ii}\right)}\right).
    \end{equation}
\end{theorem}
\begin{proof}
    Recall that the signature dynamics reads:
    \begin{equation}
        d\ssig[s, t] = -\G\ssig[s, t] dt + \ssig[s, t]\otimes\word{1}dt + \sum_{i=1}^{d}\ssig[s, t]\otimes\word{i}\circ dW_t^{i}, \quad t \geq s.
    \end{equation}
    Converting the Stratonovich integrals to Itô integrals, we deduce
    \begin{equation}
        d\ssig[s, t] = -\G\ssig[s, t] dt + \ssig[s, t]\otimes\left(\word{1} +  \dfrac12\sum_{i=1}^{d}\word{ii}\right)dt + \sum_{i=1}^{d}\ssig[s, t]\otimes\word{i}\, dW_t^{i}, \quad t \geq s.
    \end{equation}
    Using the variation of constant and taking the expectation, one obtains
    \begin{equation}\label{eq:expected_sig_equation}
        \ssigE[s, t] = \int_s^{t}\D[t-u]\left(\ssigE[s, u]\otimes\left(\word{1} +  \dfrac12\sum_{i=1}^{d}\word{ii}\right)\right)du, \quad t \geq s.
    \end{equation}
    Since $\left(\word{1} +  \dfrac12\sum\limits_{i=1}^{d}\word{ii}\right) = \left(\word{\tilde{1}} +  \dfrac12\sum\limits_{i=1}^{d}\word{\tilde{i}}\right)$, the solution of \eqref{eq:expected_sig_equation} corresponds exactly to the stationary signature of a linear path $T_t = (t, \frac{t}{2}, \ldots, \frac{t}{2})$ with $\tilde\blambda = (\lambda^{\word{\tilde{0}}}, \lambda^{\word{\tilde{1}}}, \ldots, \lambda^{\word{\tilde{d}}})$ indexed by the words in the alphabet $\{\word{\tilde{1}}, \ldots, \word{\tilde{d}}\}$.
    We conclude by applying Theorem~\ref{thm:linear_path_magnus}.
\end{proof}

\begin{sqremark}
    One can equivalently use the recursive formulas
obtained by a straightforward computation: for all words $\word{v}$ and $\word{i}, \word{j} \in \{ \word{1}, \ldots, \word{d}\}$ such that $\word{i} \neq \word{j}$, we have 
    \begin{align}
        \Essig[][\lambda, \word{v0}] = \dfrac{1}{\lambda^{\word{v0}}}\Essig[][\lambda, \word{v}], \quad \Essig[][\lambda, \word{vii}] = \dfrac{1}{2}\dfrac{1}{\lambda^{\word{vii}}}\Essig[][\lambda, \word{v}], \quad \Essig[][\lambda, \word{v0i}] = 0,  \quad \Essig[][\lambda, \word{vij}] = 0,
    \end{align}
    and
    \begin{align}
        \Essig[t][\lambda, \word{v0}] = \int_0^te^{-\lambda^{\word{v0}}(t-s)}\Essig[s][\lambda, \word{v}]\,ds, \quad \Essig[t][\lambda, \word{vii}] = \frac12\int_0^te^{-\lambda^{\word{vii}}(t-s)}\Essig[s][\lambda, \word{v}]\,ds, \quad \Essig[t][\lambda, \word{v0i}] = 0, \quad \Essig[t][\lambda, \word{vij}] = 0.
    \end{align}
     The coefficients of the expected EFM-signature are no longer symmetric in the sense that
    \[
    \Essig[][\lambda, \word{ii0}] = \dfrac{1}{\lambda^{\word{ii0}}\lambda^{\word{ii}}} \not= \dfrac{1}{\lambda^{\word{0ii}}\lambda^{\word{0}}} = \Essig[][\lambda, \word{0ii}], \quad \word{i} \in \{1, \ldots, d\},
    \]
    as they are in Fawcett's formula until one has $\lambda^0 = 2\lambda^1 = \ldots = 2\lambda^d$. The choice $\lambda^0 = 2\lambda^i$ comes naturally from the fact that the quadratic variation of the Ornstein--Uhlenbeck processes
    $$
    \widehat{\mathbb{W}}_t^{\blambda, \word{i}} = \int_{-\infty}^t e^{-\lambda(t-u)}dW_u^i, \quad i = 1, \ldots, d,
    $$
    appearing at the first level of the EFM-signature, equals in this case
    $$
    \widehat{\mathbb{W}}_t^{\blambda, \word{0}} = \int_{-\infty}^t e^{-2\lambda(t-u)}du.
    $$
    % which is a natural time-extension of the Brownian motion trajectory.
\end{sqremark}

\begin{sqexample}   
As an illustration of the expected EFM-signature, we consider a prediction problem. Suppose that the output signal $Y = (Y_t)_{t \in \R}$ is given as a linear combination of EFM-signature elements:
\begin{equation}
    Y_t = \bracketssig{\bell}, \quad t \in\R.
\end{equation}

As follows immediately from Chen's identity \eqref{eq:stat_chen}, the conditional expectation and variance are given by
\begin{equation}\label{eq:prediction}
    \E[Y_{t+h} \mid \F_t] = \left\langle \bell, \D\ssig \otimes \Essig[h] \right\rangle, \quad 
    \mathbb{V}\mathrm{ar}[Y_{t+h} \mid \F_t] = \left\langle \bell\shupow{2}, \D\ssig \otimes \Essig[h] \right\rangle - \left\langle \bell, \D\ssig \otimes \Essig[h] \right\rangle^2.
\end{equation}
Figure~\ref{fig:prediction} illustrates the use of this prediction model for a stationary signal
$$
Y_t = \dfrac{1}{1.01 + \sin(U_t)}, \quad dU_t = -\kappa U_t\,dt + \nu\,dW_t,
$$
with $\kappa = 15$ and $\nu = 1.5$. First, we learn the coefficients $\bell$ via standard linear regression against the EFM-signature $\ssig$, truncated at order $5$, over the interval $[0, 1]$. The signature parameters are chosen as $\blambda = (10, 10)$. We then apply the prediction formula~\eqref{eq:prediction} to estimate the conditional expectation of the signal given $\mathcal{F}_1$. The shaded region represents one standard deviation.

