\end{sqexample}

\section{Linear functionals of EFM-signatures}\label{sect:linear_forms}

As we saw in previous sections, the linear functional of the EFM-signature $\bracketssig[t]{\bell}$ of the time-augmented Brownian motion, with $\bell \in \TA$, is a natural candidate for time-invariant path-dependent modeling, since: 
\begin{itemize}
    \item $\ssig[t]$ is a stationary Markov process by Theorem~\ref{thm:Markov};
    \item $\ssig[t]$ uniquely determines the path $\widehat{W}$ up to time $t$ by Theorem~\ref{thm:uniqueness};
    \item functionals of the form $\bracketssig[t]{\bell}$ are universal approximators of path functionals by Theorem~\ref{thm:UAT};
    \item the expected EFM-signature $\E[\ssig[t]]$ can be computed explicitly by Proposition~\ref{thm:expected_sig}.
\end{itemize}

This section is dedicated to studying the properties of linear functionals of the EFM-signature $\bracketssig{\bell}$. For simplicity and clarity of the proposed proofs, we establish Itô's decomposition only in the case where the coefficient $\bell \in \TA$ is finite. Analogous results for possibly infinite linear functionals of the signature of extended Brownian motion can be found in the works by \citet{abijaber2024signature} and \citet*{jaber2024pathdependentprocessessignatures}. We expect that the approach proposed in these works can be extended to the case of EFM-signatures.

\subsection{Itô's decomposition}
We start this subsection by considering a general continuous semimartingale path $X$ in $\R^d$. The following definition is useful for obtaining the semimartingale decomposition of linear functionals of the signature.

\begin{definition}
    For a tensor sequence $\bell \in \eTA$ and a word $\word{u}$, the \emph{projection} $\bell\proj{\word{u}}$ is defined as
    \begin{equation}
        \bell\proj{\word{u}} = \sum_{n \geq 0}\sum_{\word{v} \in V_n} \bell^{\word{v}\word{u}}\, \word{v}.
    \end{equation}
\end{definition}
In other words, the projection retains only the coefficients of $\bell$ corresponding to words that end with $\word{u}$, and replaces each such word $\word{v}\word{u}$ by its prefix $\word{v}$. The connection between this projection and differentiation becomes evident in the following decomposition:
\begin{equation}
    \bracketsigX{\bell} = \bracketsigX[0]{\bell} + \sum_{i=1}^d \int_0^t \bracketsigX[s]{\bell\proj{\word{i}}} \circ dX_s^i,
\end{equation}
or, expressed in terms of tensor sequences,
\begin{equation}
    \bell = \bell^\emptyword + \sum_{i=1}^d \bell\proj{\word{i}} \, \word{i}.
\end{equation}
This decomposition leads to the Itô formula for (possibly infinite) linear functionals of the signature of semimartingales, as shown by \cite*[Theorem 3.3]{jaber2024pathdependentprocessessignatures}. In the case of EFM-signatures, a similar result holds, with the only difference being the presence of exponential kernels in their definition, which introduces an additional mean-reverting term.

\begin{proposition}\label{prop:ito_general}
    Let $\bell_t \in \TA$ be continuously differentiable (element-wise). Then the linear functional $\bracketssigX{\bell_t}$ satisfies the stochastic differential equation:
    \begin{equation}
        d\bracketssigX{\bell_t} = \bracketssigX{\dot\bell_t - \G\bell_t}\,dt + \sum_{i=1}^d \bracketssigX{\bell_t\proj{\word{i}}} \circ dX_t^i.
    \end{equation}
\end{proposition}

\begin{proof}
    Recall that by \eqref{eq:sig_sde}, for any non-empty word $\word{v} = \word{i_1 \ldots i_n}$, the corresponding EFM-signature component satisfies
    \begin{equation}
        d\sigX^{\lambda, \word{v}} = -\lambda^{\word{v}} \sigX^{\lambda, \word{v}}\,dt + \sigX^{\lambda, \word{v'}} \circ dX_t^{i_n},
    \end{equation}
    where $\word{v'} := \word{i_1 \ldots i_{n-1}}$. 
    The result follows by plugging this expression into the definition
    \[
        \bracketssigX{\bell_t} = \sum_{n \geq 0} \sum_{\word{v} \in V_n} \bell_t^{\word{v}}\, \sigX^{\lambda, \word{v}},
    \]
    and applying the product rule:
    \begin{align}
        d\bracketssigX{\bell_t} &= \sum_{n \geq 0}\sum_{\word{v} \in V_n}\dot\bell_t^{\word{v}}\sigX^{\lambda, \word{v}}dt +
        \sum_{n \geq 0}\sum_{\word{v} \in V_n}\bell_t^{\word{v}}d\sigX^{\lambda, \word{v}} \\
        &= \sum_{n \geq 0}\sum_{\word{v} \in V_n}\left(\dot\bell_t^{\word{v}}\sigX^{\lambda, \word{v}} - \lambda ^{\word{v}} \bell_t^{\word{v}}  \sigX^{\lambda, \word{v}} \right)dt +
        \sum_{n \geq 0}\sum_{\word{v} \in V_n}\bell_t^{\word{v}}\sigX[t]^{\lambda, \word{v'}}\circ dX_t^{i_n} \\
        &= \bracketssigX{\dot\bell_t - \G \bell_t}dt + \sum_{i=1}^d \bracketssigX{\bell_t\proj{\word{i}}}\circ dX_t^i.
    \end{align}
\end{proof}
This proposition allows us to derive the Itô formula for the EFM-signature $\ssig$ of the extended standard Brownian motion $\widehat{W}_t = (t, W_t^1, \ldots, W_t^d)$.

\begin{proposition}\label{prop:Ito_BM}
    Let $\bell_t \in \TA[d+1]$ be continuously differentiable (element-wise). Then the process $\bracketssig{\bell_t}$ satisfies:
    \begin{equation}\label{eq:ito_decomposition}
        d\bracketssig{\bell_t} = \bracketssig{\dot\bell_t - \G\bell_t + \bell_t\proj{0} + \dfrac{1}{2}\sum_{i = 1}^{d}\bell_t\proj{ii}}\,dt + \sum_{i=1}^{d}\bracketssig{\bell_t\proj{i}}\,dW_t^{i}.
    \end{equation}
\end{proposition}

\begin{proof}
    Applying Proposition~\ref{prop:ito_general} to the EFM-signature $\ssig$ yields:
    \begin{equation}\label{eq:Strato_decomp}
        d\bracketssig{\bell_t} = \bracketssig{\dot\bell_t - \G\bell_t + \bell_t\proj{0}}\,dt + \sum_{i=1}^{d}\bracketssig{\bell_t\proj{i}} \circ dW_t^{i}.
    \end{equation}
    To convert the Stratonovich integral to an Itô integral, we compute the quadratic covariation between $W^{i-1}$ and $\bracketssig{\bell_t\proj{i}}$. Applying again Proposition~\ref{prop:ito_general} to $\bracketssig{\bell_t\proj{i}}$, we find:
    \[
        d\left\langle W^{i}, \bracketssig[\cdot]{\bell_\cdot\proj{i}} \right\rangle_t = \bracketssig{\bell_t\proj{ii}}\,dt.
    \]
    Therefore, rewriting \eqref{eq:Strato_decomp} in Itô form yields the desired result \eqref{eq:ito_decomposition}.
\end{proof}

\begin{sqexample}[OU representation revisited]\label{ex:OU_repr_revisited}
     The Itô decomposition can be used to find an approximation of an Ornstein--Uhlenbeck process $Y_t = \int_{-\infty}^t e^{-\mu(t-s)}\,dW_s$ satisfying
    $$
    dY_t = -\mu Y_t\, dt + dW_t,
    $$
    in the form $\bracketssig{\bell^\mu}$ for fixed $\blambda$ and for arbitrary $\mu > 0$. Indeed, applying Itô's formula and equating the drift and the volatility of $Y_t$ and $\bracketssig{\bell^\mu}$, we obtain
\begin{equation}
\begin{cases}
     -\G \bell^\mu + \bell^\mu \proj{0} = -\mu \bell^\mu , \\
    \bell^\mu \proj{1} = \emptyword.
\end{cases}
\end{equation}
It is clear that $\bell^\mu$ satisfies this condition if it is a solution to the algebraic equation
\begin{equation}\label{eq:OU_algebraic}
    \bell^\mu = (\G(\bell^\mu) - \mu \bell^\mu)\word{0} + \word{1} = \mathcal{B}\bell^\mu + \word{1},
\end{equation}
where the operator $\mathcal{B} : \eTA \to \eTA$ is defined by 
$
\mathcal{B}\colon \bell \mapsto (\G(\bell) - \mu \bell)\word{0}.
$
This is a linear equation which can be solved with the resolvent:
\begin{equation}
    \bell^\mu = \sum_{k \geq 0} \mathcal{B}^k \word{1},
\end{equation}
which corresponds to the Picard iterations for the equation \eqref{eq:OU_algebraic}. Note that this can be rewritten explicitly as
\begin{equation}\label{eq:ou_representation}
    \bell^\mu = \sum_{k \geq 0} c_k \word{1} \word{0} \conpow{k},
\end{equation}
with
\begin{equation}
    \begin{cases}
        c_0 = 1, \\
        c_{k + 1} = (k\lambda^0 + \lambda^1 - \mu) c_k, \quad k \geq 0.
    \end{cases}
\end{equation}
This is the formula we used in the introductory Subsection~\ref{ex:OU_repr}. If we denote
\begin{equation}\label{eq:OU_approx}
    \bell^{\mu, N} = \sum_{k = 0}^N c_k \word{1} \word{0} \conpow{k}, \quad Y_t^N = \bracketssig{\bell^{\mu, N}},
\end{equation}
one can verify that 
$$
d(Y_t - Y_t^N) = -\mu (Y_t - Y_t^N) dt + \bracketssig{c_{N + 1} \word{10}^{\otimes N}},
$$
so that 
$$
\E[(Y_t - Y_t^N)^2] = \E\left[\left(\int_{-\infty}^t e^{-\mu(t-s)} \bracketssig[s]{c_{N + 1} \word{10}^{\otimes N}} ds\right)^2\right] \leq \dfrac{c_{N + 1}^2}{2\mu} \left\langle (\word{10}^{\otimes N}) \shupow{2}, \Essig[] \right\rangle.
$$
A cumbersome but straightforward computation shows that the right-hand side expression converges to $0$ as $N \to +\infty$, so that $Y_t^N \to Y_t$ in $L^2$. 
\end{sqexample}

\subsection{A remark on the characteristic function of linear functional of $\ssig$}

In this section, we show how the approach introduced in \cite{abijaber2024signature} can be adapted to compute the characteristic functions of the EFM-signature:
\begin{equation}
    \phi(\bell) := \E\left[e^{i\bracketssig{\bell}}\right] = \E\left[e^{i\bracketssig[0]{\bell}}\right], \quad t \in \R,
\end{equation}
and
\begin{equation}
    \phi_T(\bell) := \E\left[e^{i\bracketssig[0, T]{\bell}}\right], \quad T > 0,
\end{equation}
for a given $\bell \in \TA[d+1]$.

The following theorem provides a representation of these characteristic functions in terms of the solution to an infinite-dimensional system of mean-reverting Riccati equations. In this characterization, we allow for infinite linear combinations of EFM-signature elements. To that end, and only in this subsection, we assume the necessary convergence of the infinite series involved.

\begin{theorem}\label{thm:char}
    Let $T > 0$. Suppose that $\bpsi_t \in \eTA[d+1],\, t \geq 0$, is a smooth solution to the mean-reverting Riccati equation
    \begin{equation}\label{eq:riccati_cf}
    \begin{cases}
        \dot\bpsi_t = -\G\bpsi_t + F(\bpsi_t), \quad t \geq 0,\\
        \bpsi_0 = i\bell,
    \end{cases}
    \end{equation}
    with $F(\bpsi) = \bpsi\proj{0} + \frac12 \sum\limits_{i = 1}^{d}\bpsi\proj{ii} + \frac{1}{2}\sum\limits_{i = 1}^{d}\left(\bpsi\proj{i}\right)\shupow{2}$, such that the processes $M = (M_t)_{t\leq 0}$ and $N^T = (N_t^T)_{t\in[0, T]},$ given by 
    \begin{equation}
        M_t := e^{\bracketssig{\bpsi_{-t}}}, \quad N_t^T = e^{\bracketssig[0, t]{\bpsi_{T-t}}}.
    \end{equation}
    are well-defined and the Itô's formula can be applied.
    Then $M$ and $N^T$ are local martingales. If, in addition, they are true martingales, then the following expression for the characteristic functions holds:
    \begin{align}\label{eq:cf_repr}
        M_t &=  \E\left[e^{i\bracketssig[0]{\bell}} \big| \F_t\right], \quad t \leq 0, \\
        N_t^T &= \E\left[e^{i\bracketssig[0, T]{\bell}} \big| \F_t\right], \quad t \in [0, T].
    \end{align}
    In particular, the characteristic functions are given by
    $$
    \phi(\bell) = M_{-\infty} = \lim_{T\to\infty}e^{\bpsi_{T}^\emptyword} \quad \text{and} \quad \phi_T(\bell) = N_0^T = e^{\bpsi_{T}^\emptyword}.
    $$
\end{theorem}

\begin{proof}
    Applying the Itô's formula to $\bracketssig{\bpsi_{-t}}$, we obtain
    \begin{equation}
        d\bracketssig{\bpsi_{-t}} = \bracketssig{-\dot\bpsi_{-t} - \G\bpsi_{-t} + \bpsi_{-t}\proj{0} + \sum_{i=1}^{d}\bpsi_{-t}\proj{ii}}dt + \sum_{i=1}^{d}\bracketssig{\bpsi_{-t}\proj{i}}dW_t^{i}.
    \end{equation}
    The application of Itô's formula to $M$ for $t \leq 0$ yields 
    \begin{align}
        dM_t &= M_t d\bracketssig{\bpsi_{-t}} + \dfrac{1}{2}M_t\sum_{i=1}^{d}\bracketssig{\bpsi_{-t}\proj{i}}^2dt \\
        &= M_t \bracketssig{-\dot\bpsi_{-t} - \G\bpsi_{-t} + \bpsi_{-t}\proj{0} + \sum_{i=1}^{d}\bpsi_{-t}\proj{ii} + \sum_{i=1}^{d}\left(\bpsi_{-t}\proj{i}\right)\shupow{2}}dt + M_t \sum_{i=1}^{d}\bracketssig{\bpsi_{-t}\proj{i}}dW_t^{i}.
    \end{align}
    Since $\bpsi_t$ satisfies \eqref{eq:riccati_cf}, the $dt$-term vanishes, so that $M$ is a local martingale. The same argument shows that $N^T$ is a local martingale as well.

    Now, note that $M_0 = e^{\bracketssig[0]{\bpsi_{0}}} = e^{i\bracketssig[0, T]{\bell}}$ and $N_T^T = e^{\bracketssig[0, T]{\bpsi_{0}}} = e^{i\bracketssig[0, T]{\bell}}$, so that \eqref{eq:cf_repr} holds for $t = 0$ and $t = T$, respectively. If $M$ and $N^T$ are true martingales, the equality \eqref{eq:cf_repr} will hold for all $t \leq 0$ and $t \in [0, T]$, correspondingly.

    By \eqref{eq:cf_repr}, $M$ is uniformly integrable, so that it is closable and we set $M_{-\infty} = \lim\limits_{t \to -\infty} M_t$. We note that
    \[
    \phi(\bell) = M_{-\infty}, \quad \phi_T(\bell) = N_0^T = e^{\bracketssig[0, 0]{\bpsi_{T}}} = e^{\bpsi_T^\emptyword}.
    \]
    Since the law of $\ssig[0, T]$ converges weakly to the law of $\ssig[0]$ as $T \to \infty$, so does the characteristic function:
    \begin{equation}
        e^{\bpsi_T^\emptyword} = \E\left[e^{i\bracketssig[0, T]{\bell}}\right] \underset{T \to\infty}{\longrightarrow} \E\left[e^{i\bracketssig[0]{\bell}}\right]. %= e^{\bpsi_\infty^\emptyword}.
    \end{equation}
    This finishes the proof. %proves that $\lim\limits_{t \to -\infty}\bracketssig{\bpsi_{-t}} = \bpsi_\infty^\emptyword$ and finishes the proof.
\end{proof}

We note that the existence of the solution $\bpsi$ satisfying Itô's decomposition \eqref{eq:ito_decomposition} and the true martingality of $M$ and $N^T$ are the assumptions that are difficult to verify even in the one-dimensional case $d = 1$. Some partial results concerning $\eTA$-valued Riccati ODEs were obtained by \cite*{cuchiero2025signaturesdesaffinepolynomial} and \cite*{jaber2024fourierlaplace}.

{\begin{sqexample}
    The equation \eqref{eq:riccati_cf} can be solved numerically using Euler's scheme or the predictor-corrector semi-integrated scheme described in Section~\ref{sect:numerical_ode}. Note that the only difference from the Riccati equation corresponding to the standard signature is the linear term $-\G\bpsi_t$. Appearing thanks to the mean reversion of the EFM-signature, it stabilizes the equation and forces all the coefficients except for $\psi_t^{\emptyword}$ to vanish as $t \to \infty$. A numerical illustration in Figure~\ref{fig:cf_plot} shows that the characteristic function $\phi_T(\bell)$, obtained by numerically solving the mean-reverting Riccati equation using the predictor--corrector scheme, converges to the stationary value $\phi(\bell)$ computed by the Monte Carlo method.
\begin{figure}[H]
    \begin{center}
    \includegraphics[width=1\linewidth]{images/CF_plots.pdf}
    \caption{Real (on the left) and imaginary (on the right) parts of $\phi_T(\bell) = e^{\bpsi_T^\emptyword}$ for $\bell = \word{1}\conpow{4}$ and $\blambda = (1, 1)$ for different truncation orders $N$. The horizontal black line corresponds to the stationary value $\phi(\bell)$ estimated by the Monte Carlo method.}
    \label{fig:cf_plot}
    \end{center}
\end{figure}
\end{sqexample}
