\section{Rough path view on the EFM-signature}\label{sect:rough_paths}

This section is devoted to the construction of the EFM-signature with rough path techniques. Namely, our goal is to make sense of the improper rough convolution on $(-\infty, T]$. Indeed, we would like to define the $(n+1)$-th level of the EFM-signature recursively as
\begin{equation}\label{eq:recursive_fm_sig_rough}
    \mathbb{X}^{\blambda, n + 1}_{s, t} = \int_s^t \D[t - u](\mathbb{X}^{\blambda, n}_{s, u} d\mathbf{X}_u^{}).
\end{equation}
The case of finite $s > -\infty$ is completely covered by the rough convolution relying on the mild sewing lemma as presented by \citet{Gerasimovis2018HrmandersTF} and \citet{gubinelli2010rough}. However, this framework does not cover the case of an infinite integration domain $s = -\infty$. For this reason, we extend the rough convolution result of \cite{Gerasimovis2018HrmandersTF} by exploiting the ideas of improper integration used by \citet*{Bellingeri02112022}.

Notice that the operator $\D[]$ satisfies the condition
$$
\|\D[t]u - u\| \lesssim \|u\|,
$$
needed for the applicability of the rough convolution results of \cite{Gerasimovis2018HrmandersTF},
since $\|\D\| \leq 1$ for all $h \geq 0$. As in the standard rough integration case, the rough convolution relies on the notion of controlled paths.

\begin{definition}
Let $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)\in \mathscr{C}^{\alpha}([s, t])$ for some $\alpha \in (\frac13, \frac12]$. We say that $(Y, Y') \in \mathcal{C}^{\alpha}([s, t])\times\mathcal{C}^{\alpha}([s, t])$ is controlled by $\mathbf{X}$ according to the semigroup $\D[]$, if the remainder term $R^Y$ defined by
$$
R^Y_{u, v} = \hat\delta Y_{u, v} - \D[v-u](Y'_uX_{u, v}),
$$
belongs to $\mathcal{C}^{2\alpha}([s, t])$. We write $(Y, Y')\in\mathscr{D}_{\D[], X}^{2\alpha}([s, t])$ and define the seminorm on $\mathscr{D}_{\D[], X}^{2\alpha}([s, t])$ by
$$
\|Y, Y'\|_{X, 2\alpha} = \|Y'\|_\alpha^\wedge + \|R^Y\|_{2\alpha}. 
$$
\end{definition}

The convolution integral is then defined by
\begin{equation}\label{eq:rough_conv_def}
    Z_t = \int_s^t \D[t - u](Y_u d\mathbf{X}_u)= \lim_{|\mathcal{P}|\to 0}\sum_{[u, v]\in \mathcal{P}}\D[t - u](Y_uX_{u, v} + Y'_u\mathbb{X}^{2}_{u, v}),
\end{equation}
where the limit is taken over all partitions $\mathcal{P}$ of the interval $[s, t]$.
We cite the result on the rough convolution \cite[Theorem 3.5]{Gerasimovis2018HrmandersTF}, slightly simplified for our purposes. 
\begin{theorem}
Fix $s \leq t$ and $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)\in \mathscr{C}^{\alpha}([s, t])$ for some $\alpha \in (\frac13, \frac12]$. Let $(Y, Y') \in \mathscr{D}^{2\alpha}_{\D[], X}([s, t])$. Then the integral $Z$ given by \eqref{eq:rough_conv_def} exists as an element of $\mathcal{C}^{\alpha}([s, t])$. Moreover, $(Z, Y) \in \mathscr{D}^{2\alpha}_{\D[], X}([s, t])$, and one has the bounds
    \begin{equation}\label{eq:conv_int_control}
        \left|\int_u^v \D[v - r](Y_r d\mathbf{X}_r) - \D[v - u](Y_uX_{u, v} + Y'_u\mathbb{X}^{2}_{u, v}) \right| \leq (\|R^Y\|_{2\alpha}\|\mathbb{X}^{1}\|_{\alpha} + \|Y'\|_{\alpha}^\wedge\|\mathbb{X}^2\|_{2\alpha})|v - u|^{3\alpha},
    \end{equation}
    \begin{equation}
        \|Z, Y\|_{X, 2\alpha} \lesssim \|Y\|_\alpha^\wedge + \|\mathbf{X}\|_\alpha(\|Y_0'\| + \|Y, Y'\|_{X, 2\alpha}).
    \end{equation}
\end{theorem}

This result allows us to define recursively the EFM-signature over finite intervals.
\begin{corollary}\label{corollary:fm_sig_s_fin}
Fix $s \leq t$ and let $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)\in \mathscr{C}^{\alpha}([s, t])$ for some $\alpha \in (\frac13, \frac12]$. Then the EFM-signature
\begin{equation}
    \mathbb{X}^{\blambda, n + 1}_{s, t} = \int_s^t \D[t - u](\mathbb{X}^{\blambda, n}_{s, u} d\mathbf{X}_u^{}),
\end{equation}
is well-defined 
as a rough convolution of $(\mathbb{X}^{\blambda, n}_{s, \cdot}, \mathbb{X}^{\blambda, n - 1}_{s, \cdot}) \in \mathscr{D}_{\D[], X}^{2\alpha}([s, t])$ with respect to $\mathbf{X}$.
\end{corollary}

\subsection{Improper rough convolution}
The goal of this subsection is to define the rough convolution over $(-\infty, T]$ as an improper integral
$$
Z_t = \int_{-\infty}^t\D[t - u](Y_ud\mathbf{X}_u) := \lim_{R \to -\infty}\int_R^t \D[t - u](\mathbb{X}^{\blambda, n}_{u} d\mathbf{X}_u^{}).
$$
The space $\hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$ defined in \eqref{eq:hat_C_b_alpha_rho} appears to fit well with our purposes, so that we will consider $Y \in \hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$.
This naturally leads to the following definition of the corresponding controlled path space and allows us to formulate the integration result.

\begin{definition}
Let $\mathbf{X} = (\mathbb{X}^1, \mathbb{X}^2)\in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ for some $\alpha \in (\frac13, \frac12]$ and $\brho \succ 0$. We say that $(Y, Y') \in \mathcal{C}^{\alpha, \brho}_b((-\infty, T])\times\mathcal{C}^{\alpha, \brho}_b((-\infty, T])$ is controlled by $\mathbf{X}$ according to the semigroup $\D[]$, if the remainder term $R^Y$ defined by
$$
R^Y_{s, t} = \hat\delta Y_{s, t} - \D[t-s](Y'_sX_{s, t}),
$$
belongs to $\mathcal{C}^{2\alpha, \brho}((-\infty, T])$. We write $(Y, Y')\in\mathscr{D}_{\D[], X}^{2\alpha, \brho}((-\infty, T])$ and define the seminorm on $\mathscr{D}_{\D[], X}^{2\alpha, \brho}((-\infty, T])$ by
$$
\|Y, Y'\|_{2\alpha, \brho}^\wedge = \|Y'\|_{\alpha, \brho}^\wedge + \|R^Y\|_{2\alpha, \brho}. 
$$
\end{definition}

\begin{theorem}[Improper rough convolution]\label{thm:improper_rough}
    Let $Y \in \mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$ and $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ for some $\alpha \in (\frac13, \frac12]$ and $0 \prec \brho \prec \blambda$. Then, for $t \leq T$, the improper rough convolution 
    \begin{equation}\label{eq:improper_conv}
        Z_t = \lim_{R\to -\infty}\int_R^t\D[t - u](Y_ud\mathbf{X}_u),
    \end{equation}
    is well-defined as an element of $\hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$ and
    \begin{align}\label{eq:improper_convergence_control}
        \left|Z_t - \int_R^t\D[t - u](Y_ud\mathbf{X}_u)\right| \lesssim \|\D[T-R][\blambda - \brho]\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge).
    \end{align}
    Moreover, the couple $(Z, Y)$ belongs to $\mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$ and the following bounds hold
    \begin{equation}\label{eq:improper_bound_1}
        \|Z\|_{\alpha, \brho}^\wedge + \|Z\|_{\infty, \brho} \lesssim \|\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge),
    \end{equation}
    \begin{equation}\label{eq:improper_bound_2}
        \|Z, Y\|_{2\alpha, \brho}^\wedge \lesssim \|\mathbf{X}\|_{\alpha, \brho}(\|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge) + \|Y, Y'\|_{2\alpha, \brho}^\wedge.
    \end{equation}
\end{theorem}
\begin{proof} The proof consists of three steps.
    \paragraph{Step 1. Existence of the limit \eqref{eq:improper_conv}.} 
    Without loss of generality suppose that $t = T$. Let us denote
    $$
    Z^R = \int_{R}^T\D[T-u](Y_ud\mathbf{X}_u), \quad R \leq T.
    $$
    Take $S < R \leq T$ such that $|R - S| \leq 1$. We have
    $$
    Z^R - Z^{S} = \int_{S}^{R}\D[T-u](Y_ud\mathbf{X}_u) = \int_{S}^{R}\D[R-u]\D[T-R](Y_ud\mathbf{X}_u) = \int_{S}^{R}\D[R-u](\D[T-R] Y_u) d(\D[T-R]\mathbf{X}_u),
    $$
    where we used Proposition~\ref{prop_D_ppties}\,(vii) for the last equality. 
    By \eqref{eq:conv_int_control}, we have
\begin{align}\label{eq:cauchy_diff}
        |Z^R - Z^{S}| &\leq |\D[T-S](Y_{S}X_{S, R} + Y_{S}'\mathbb{X}^{2}_{S, R})| \\
        &+ (\|\D[T - R] R^Y\|_{2\alpha; [S, R]}\|\D[T-R] X\|_{\alpha; [S, R]} + \|\D[T-R]Y'\|_{\alpha; [S, R]}^\wedge\|\D[T-R]\mathbb{X}^2\|_{2\alpha; [S, R]})
    \end{align}
    Since for all $f$, by Lemma~\ref{lem:holder_weighted},
    $$
    \|\D[T-R]f\|_{\alpha; [S, R]} = \|\D[T-S][\brho]\D[T-R][\blambda - \brho]\D[R-S][-\brho]f\|_{\alpha; [S, R]} \leq \||\D[T-R][\blambda - \brho]\D[R-S][-\brho]f\|_{\alpha, \brho} \lesssim_{\brho} \||\D[T-R][\blambda - \brho]f\|_{\alpha, \brho},
    $$ the second and third terms of  the right-hand side of \eqref{eq:cauchy_diff} are bounded by
\begin{align}\label{eq:norms_control}
        \|\D[T-R][\blambda - \brho] R^Y\|_{2\alpha, \brho}\|\D[T-R][\blambda - \brho] X\|_{\alpha, \brho} + \|\D[T-R][\blambda - \brho]Y'\|_{\alpha, \brho}^\wedge\|\D[T-R][\blambda - \brho]\mathbb{X}^2\|_{2\alpha, \brho}.
    \end{align}
    The first term  of \eqref{eq:cauchy_diff}  reads
\begin{align}\label{eq:first_part_improper_bound}
        |\D[T-S](Y_{S}X_{S, T} + Y_{S}'\mathbb{X}^{2}_{S, T})| &= |\D[T-S][\blambda - \brho](\D[T-S][\brho]Y_{S}\D[T-S][\brho]X_{S, R} + \D[T-S][\brho]Y_{S}'\D[T-S][\brho]\mathbb{X}^{2}_{S, R})|\\
        &\leq \|Y\|_{\infty, \brho}\|\D[T-S][\blambda - \brho]X\|_{\alpha, \brho} + \|Y'\|_{\infty, \brho}\|\D[T-S][\blambda - \brho]\mathbb{X}^{2}\|_{2\alpha, \brho}.
    \end{align}
    Combining \eqref{eq:norms_control} and \eqref{eq:first_part_improper_bound}, we obtain
    \begin{equation}
        |Z^R - Z^{S}| \lesssim \|\D[T-R][\blambda - \brho]\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge), \quad 0 \leq R - S \leq 1.
    \end{equation}
    For the general $S < R \leq T$, there exist $\Delta \in (0, 1]$ and $n \in \N$ such that $R - S = n\Delta$. Hence, we can bound
    \begin{align}
        |Z^R - Z^S| \leq \sum_{k = 0}^{n - 1}|Z^{R - k\Delta} - Z^{R - (k + 1)\Delta}| &\lesssim \sum_{k = 0}^{\infty}\|\D[T-R + k\Delta][\blambda - \brho]\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge) \\
         &\lesssim_{\blambda, \brho} \|\D[T-R][\blambda - \brho]\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge).
    \end{align}
    This implies the Cauchy criterion for $(Z^R)_{R \leq T}$ and the existence of the limit $Z = \lim\limits_{R\to-\infty}Z^R$ satisfying \eqref{eq:improper_convergence_control}.

    \paragraph{Step 2. Showing that $Z \in \hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$.}

    For all $s, t \in (-\infty, T]$ such that $|t-s| \leq 1$, we apply \eqref{eq:conv_int_control}:
    \begin{align}
        |\D[T-s][\brho]\hat\delta Z_{s, t}| &= \left|\int_s^t\D[t-u]\D[T-s][\brho](Y_ud\mathbf{X}_u)\right| \\
        &\leq |\D[t-s]\D[T-s][\brho](Y_sX_{s,t})| + |\D[t-s]\D[T-s][\brho](Y'_s\mathbb{X}^{2}_{s, t})| + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho})|t - s|^{3\alpha} \\
        &\leq \|Y\|_{\infty, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho}|t-s|^\alpha + \|Y'\|_{\infty, \brho}\|\mathbb{X}^{2}\|_{2\alpha, \brho}|t-s|^{2\alpha} + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho})|t - s|^{3\alpha},
    \end{align}
    so that
    \begin{align}
        \|Z\|_{\alpha,\brho}^\wedge &\leq  \|Y\|_{\infty, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\infty, \brho}\|\mathbb{X}^{2}\|_{2\alpha, \brho} + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho}) \\
        &\leq \|\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge).
    \end{align}
    To bound $\|Z\|_{\infty, \brho}$, we take $s \leq T$ and write
    \begin{align}
        |\D[T-s][\brho]Z_s| = \left|\D[T-s][\brho]\int_{-\infty}^s\D[s-u](Y_ud\mathbf{X}_u)\right| &\leq \sum_{k \geq 0} \left|\D[T-s][\brho]\D[k]\int_{s-k-1}^{s-k}\D[(s - k)-u](Y_ud\mathbf{X}_u)\right| \\
        &= \sum_{k \geq 0} \left|\D[k][\blambda - \brho]\int_{s-k-1}^{s-k}\D[(s - k)-u]\D[T-(s-k)][\brho](Y_ud\mathbf{X}_u)\right|.
    \end{align}
    Applying the bound \eqref{eq:conv_int_control} to each integral and proceeding as in Step 1 of the proof, we can show that 
    \begin{align}
        |\D[T-s][\brho]Z_s| &\lesssim_{\blambda, \brho} \sum_{k \geq 0} \|\D[k][\blambda - \brho]\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge) \\
        &\lesssim_{\blambda, \brho}  \|\mathbf{X}\|_{\alpha, \brho}(\|Y\|_{\infty, \brho} + \|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge).
    \end{align}
    Taking the supremum in $s$ finishes the proof of \eqref{eq:improper_bound_1}.

    \paragraph{Step 3. Showing that $(Z, Y) \in \mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$.}
    For all $s < t \leq T$ such that $|t - s| \leq 1$, we have
    \begin{align}
        |\D[T-s][\brho](\hat\delta Y_{s,t})| &\leq |\D[t-s](\D[T-s][\brho]Y'_s\D[T-s][\brho]X_{s, t})| + |\D[T-s][\brho]R^Y_{s, t}| \\
        &\leq \|Y'\|_{\infty, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho}|t-s|^{\alpha} + \|R^Y\|_{2\alpha, \brho}|t-s|^{2\alpha},
    \end{align}
    so that
    \begin{equation}
        \|Y\|_{\alpha, \brho} \leq \|Y'\|_{\infty, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|R^Y\|_{2\alpha, \brho} \leq \|\mathbf{X}\|_{\alpha, \brho}(\|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge) + \|Y, Y'\|_{2\alpha, \brho}^\wedge.
    \end{equation}
    To bound $\|R^Z\|_{2\alpha, \brho}$, we again use \eqref{eq:conv_int_control} and proceed as in Step 2:
    \begin{align}
        |\D[T-s][\brho]R^Z_{s, t}| &= |\D[T-s][\brho]\hat\delta Z_{s, t} - \D[T-s][\brho]\D[t-s](Y_sX_{s,t})| = \left|\int_s^t\D[t-u]\D[T-s][\brho](Y_ud\mathbf{X}_u) - \D[t-s]\D[T-s][\brho](Y_sX_{s,t})\right| \\
        &\leq |\D[t-s]\D[T-s][\brho](Y'_s\mathbb{X}^{2}_{s, t})| + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho})|t - s|^{3\alpha} \\
        &\leq \|Y'\|_{\infty, \brho}\|\mathbb{X}^{2}\|_{2\alpha, \brho}|t-s|^{2\alpha} + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho})|t - s|^{3\alpha},
    \end{align}
    and we obtain
    \begin{align}
        \|R^Z\|_{2\alpha, \brho} &\leq\|Y'\|_{\infty, \brho}\|\mathbb{X}^{2}\|_{2\alpha, \brho} + (\|R^Y\|_{2\alpha, \brho}\|\mathbb{X}^{1}\|_{\alpha, \brho} + \|Y'\|_{\alpha, \brho}^\wedge\|\mathbb{X}^2\|_{2\alpha, \brho}) \\
        &\leq \|\mathbf{X}\|_{\alpha, \brho}(\|Y'\|_{\infty, \brho} + \|Y, Y'\|_{2\alpha, \brho}^\wedge).
    \end{align}
    This finishes the proof.
\end{proof}
\begin{corollary}\label{corollary:fm_sig_s_inf}
    If $\mathbf{X} \in \mathscr{C}^{\alpha, \brho}((-\infty, T])$ for some $\alpha\in (\frac13, \frac12]$ and $0 \prec \brho \prec \blambda$, then the EFM-signature $\ssigX[]$ is well-defined. More precisely, for all $n \geq 0$, we have $\mathbb{X}^{\blambda, n}_{\cdot} \in \hat{\mathcal{C}}^{\alpha, \brho}_b((-\infty, T])$ and $(\mathbb{X}^{\blambda, n}_{\cdot}, \mathbb{X}^{\blambda, n - 1}_{\cdot}) \in  \mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$, and the following bounds hold (with $\mathbb{X}^{\blambda, k}_{\cdot} \equiv 0$ for $k < 0$):
    \begin{equation}\label{eq:fm_sig_bnd_1}
        \|\mathbb{X}^{\blambda, n}_{\cdot}\|_{\alpha, \brho}^\wedge + \|\mathbb{X}^{\blambda, n}_{\cdot}\|_{\infty, \brho} \lesssim \|\mathbf{X}\|_{\alpha, \brho}(\|\mathbb{X}^{\blambda, n - 1}_{\cdot}\|_{\infty, \brho} + \|\mathbb{X}^{\blambda, n-2}_{\cdot}\|_{\infty, \brho} + \|\mathbb{X}^{\blambda, n-1}_{\cdot}, \mathbb{X}^{\blambda, n-2}_{\cdot}\|_{2\alpha, \brho}^\wedge),
    \end{equation}
    \begin{equation}\label{eq:fm_sig_bnd_2}
        \|\mathbb{X}^{\blambda, n}_{\cdot}, \mathbb{X}^{\blambda, n-1}_{\cdot}\|_{2\alpha, \brho}^\wedge \lesssim \|\mathbf{X}\|_{\alpha, \brho}(\|\mathbb{X}^{\blambda, n-2}_{\cdot}\|_{\infty, \brho} + \|\mathbb{X}^{\blambda, n-1}_{\cdot}, \mathbb{X}^{\blambda, n-2}_{\cdot}\|_{2\alpha, \brho}^\wedge) + \|\mathbb{X}^{\blambda, n-1}_{\cdot}, \mathbb{X}^{\blambda, n-2}_{\cdot}\|_{2\alpha, \brho}^\wedge.
    \end{equation}
\end{corollary}
\begin{proof}
    We have $\mathbb{X}^{\blambda, 0}_{t} \equiv 1$ and we define 
    $$
    \mathbb{X}^{\blambda, 1}_{t} = \int_{-\infty}^t\D[t-u](\mathbb{X}^{\blambda, 0}_{u}d\mathbf{X}_u)
    $$
    as an improper convolution of $(\mathbb{X}^{\blambda, 0}_{\cdot}, 0)$ using Theorem~\ref{thm:improper_rough}. Indeed, $(\mathbb{X}^{\blambda, 0}_{\cdot}, 0) \in \mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$, since
    $$
    R^{\mathbb{X}^{\blambda, 0}_{\cdot}}_{s,t} = \mathbb{X}^{\blambda, 0}_{t} - \D[t-s]\mathbb{X}^{\blambda, 0}_{s} \equiv 0.
    $$
    Theorem~\ref{thm:improper_rough} implies that $\mathbb{X}^{\blambda, 1}_{\cdot} \in \mathcal{C}^{\alpha, \brho}_b((-\infty, T])$ and $(\mathbb{X}^{\blambda, 1}_{\cdot}, \mathbb{X}^{\blambda, 0}_{\cdot}) \in  \mathscr{D}^{2\alpha, \brho}_{\D[], X}((-\infty, T])$.

    For $n \geq 2$, we proceed by induction, defining $\mathbb{X}^{\blambda, n}_{t}$ as an improper convolution with $Y_t = \mathbb{X}^{\blambda, n-1}_{t}$ and $Y_t' = \mathbb{X}^{\blambda, n-2}_{t}$ and applying the theorem. 
\end{proof}

\subsection{Fading memory property: proof of Theorem~\ref{thm:rough_fm}}\label{sect:rough_fm_proof}
    To prove the continuity at a fixed $\mathbf{X}$, we can suppose that there exists a constant $M$ such that
    \begin{equation}\label{eq:norm_ball}
        \|\mathbf{X}\|_{\alpha, \brho} \leq M,\quad \|\mathbf{Y}\|_{\alpha, \brho} \leq M,
    \end{equation}
    since $\|\mathbf{X}\|_{\alpha, \brho} = \varrho_{\alpha, \brho}(\mathbf{0}, \mathbf{X})$. 

    Note that for $s > -\infty$, the result follows from the stability result for rough convolutions by \cite[Lemma 3.13]{Gerasimovis2018HrmandersTF}. Thus, it is sufficient to consider only the case $s = -\infty$.

    We proceed by induction in $n$. For $n = 0$, $\mathbb{X}_{t}^{\blambda, n} \equiv \mathbb{Y}_{t}^{\blambda, n} \equiv 1$, and the statement holds trivially. Suppose that $\mathbf{X} \mapsto \mathbb{X}_{t}^{\blambda, k}$ is continuous for all $k \leq n$ and $t \leq T$. 

    Fix $t \leq T$ and $\varepsilon > 0$. We will show that one can choose $r > 0$ such that $|\mathbb{X}_{t}^{\blambda, n+1} - \mathbb{Y}_{t}^{\blambda, n+1}| < \varepsilon$ for all $\mathbf{X}, \mathbf{Y}$ satisfying $\varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) < r$.
    Recall that
    \begin{equation}\label{eq:recursive_int_fm_sig}
        \mathbb{X}_{t}^{\blambda, n+1} = \int_{-\infty}^t\D[t-u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u) = \lim_{R \to -\infty} \int_{R}^t\D[t-u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u).
    \end{equation}
    The bound \eqref{eq:improper_convergence_control} yields
    \begin{equation}
        \left|\mathbb{X}_{t}^{\blambda, n+1} - \int_R^t\D[t - u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u)\right| 
        \lesssim \|\D[t-{R}][\blambda-\brho]\mathbf{X}\|_{\alpha, \brho}(\|\mathbb{X}_{\cdot}^{\blambda, n}\|_{\infty, \brho} + \|\mathbb{X}_{\cdot}^{\blambda, n - 1}\|_{\infty, \brho} + \|\mathbb{X}_{\cdot}^{\blambda, n}, \mathbb{X}_{\cdot}^{\blambda, n-1}\|_{2\alpha, \brho}).
    \end{equation}
    Applying recursively \eqref{eq:fm_sig_bnd_1}, \eqref{eq:fm_sig_bnd_2}, and using \eqref{eq:norm_ball}, we can show that
    \begin{equation}
        \left|\mathbb{X}_{t}^{\blambda, n+1} - \int_R^t\D[t - u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u)\right| \lesssim_M \|\D[T-{ R}][\blambda-\brho]\mathbf{X}\|_{\alpha, \brho} \lesssim_M e^{-\mu(T-{ R})},
    \end{equation}
    where $\mu = \min_{i}(\lambda^i - \rho^i)$. This shows that the convergence \eqref{eq:recursive_int_fm_sig} is uniform in $\mathbf{X}$ satisfying \eqref{eq:norm_ball}, so that we can choose $R < T$ such that 
    \begin{equation}
        \left|\mathbb{X}_{t}^{\blambda, n+1} - \int_R^t\D[t - u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u)\right| \leq \frac{\varepsilon}{4},
    \end{equation}
    for all $\mathbf{X}$ satisfying \eqref{eq:norm_ball}. It remains to control the difference 
    \begin{equation}\label{eq:diff_to_control}
        \left|\int_R^t\D[t - u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u) - \int_R^t\D[t - u](\mathbb{Y}_{u}^{\blambda, n}d\mathbf{Y}_u)\right|.
    \end{equation}
    We note that $\mathbb{X}_{u}^{\blambda, n}$ satisfies the Chen's identity
    \begin{equation}
        \mathbb{X}_{u}^{\blambda, n} = \sum_{k=0}^n(\D[u - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \mathbb{X}_{R, u}^{\blambda, n - k},
    \end{equation}
    so that 
    \begin{align}
        \int_R^t\D[t - u](\mathbb{X}_{u}^{\blambda, n}d\mathbf{X}_u) &= \sum_{k=0}^n \int_R^t(\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \D[t - u](\mathbb{X}_{R, u}^{\blambda, n - k}d\mathbf{X}_u) \\
        &= \sum_{k=0}^n (\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \int_R^t\D[t - u](\mathbb{X}_{R, u}^{\blambda, n - k}d\mathbf{X}_u) \\
        &= \sum_{k=0}^n (\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \mathbb{X}_{R, t}^{\blambda, n - k + 1}.
    \end{align}
    Hence, it is sufficient to control
    \begin{align}\label{eq:fm_sig_diff}
        &(\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \mathbb{X}_{R, t}^{\blambda, n - k + 1} - (\D[t - R]\mathbb{Y}_{R}^{\blambda, k}) \otimes \mathbb{Y}_{R, t}^{\blambda, n - k + 1} \\
         &=(\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes (\mathbb{X}_{R, t}^{\blambda, n - k + 1} - \mathbb{Y}_{R, t}^{\blambda, n - k + 1}) + (\D[t - R]\mathbb{X}_{R}^{\blambda, k} - \D[t - R]\mathbb{Y}_{R}^{\blambda, k}) \otimes \mathbb{Y}_{R, t}^{\blambda, n - k + 1},
    \end{align}
    for all $k = 0, \ldots, n$.
    In the first term, we have
    \begin{align}
        |\D[t - R]\mathbb{X}_{R}^{\blambda, k}| = |\D[t - R][\blambda - \brho]\D[t - R][\brho]\mathbb{X}_{R}^{\blambda, k}| \lesssim_{R, t, T, \brho} \|\mathbb{X}_{\cdot}^{\blambda, k}\|_{\infty, \brho} \lesssim_M 1. 
    \end{align} 
     where we recursively applied \eqref{eq:fm_sig_bnd_1} and \eqref{eq:fm_sig_bnd_2}. The second part of the first term
    \begin{equation}
        |\mathbb{X}_{R, t}^{\blambda, n - k + 1} - \mathbb{Y}_{R, t}^{\blambda, n - k + 1}| \lesssim_{R, t} \|\mathbb{X}_{R, \cdot}^{\blambda, n - k + 1} - \mathbb{Y}_{R, \cdot}^{\blambda, n - k + 1}\|_{\alpha; [R, T]}.
    \end{equation}
    By the stability result for rough convolutions \cite[Lemma 3.13]{Gerasimovis2018HrmandersTF}, this norm tends to $0$ as $\varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) \to 0$.

    In the second term, the second multiplier is bounded by the standard scaling argument
    \begin{equation}
        |\mathbb{Y}_{R, t}^{\blambda, n - k + 1}|\lesssim_{R, t}  \left(\|Y\|_{\alpha; [R, t]} + \sqrt{\|\mathbb{Y}^{2}\|_{2\alpha; [R, t]}}\right)^{n - k + 1} \lesssim_{R,T, \brho, M} 1,
    \end{equation}
    while the first one
    $$
    |\D[t - R](\mathbb{X}_{R}^{\blambda, k} - \mathbb{Y}_{R}^{\blambda, k})| \to 0,
    $$
    as $\varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) \to 0$ by the induction hypothesis. Thus, one can choose $r > 0$ such that 
    \begin{equation}
        \left|(\D[t - R]\mathbb{X}_{R}^{\blambda, k}) \otimes \mathbb{X}_{R, t}^{\blambda, n - k + 1} - (\D[t - R]\mathbb{Y}_{R}^{\blambda, k}) \otimes \mathbb{Y}_{R, t}^{\blambda, n - k + 1}\right| \leq \dfrac{\varepsilon}{2(n + 1)},
    \end{equation}
    for $\mathbf{X}, \mathbf{Y}$ such that $\varrho_{\alpha, \brho}(\mathbf{X}, \mathbf{Y}) < r$. This implies that \eqref{eq:diff_to_control} is less than $\dfrac{\varepsilon}{2}$ and concludes the proof.

