\section{Proof of Lemma~\ref{lem:linear_path}}\label{sect:linear_path_proof}
The computation reduces to evaluating the iterated integral \eqref{eq:interated_exp_int}. After a change of variables 
$$u_j = t - \sum\limits_{k = 1}^{n - j - 1}\tau_k,\quad j = 1, \ldots, n,$$ 
this integral becomes
    \begin{equation}
        \int_{\tau_j \geq 0,\ \sum\limits_{j=1}^n \tau_j \leq t - s} e^{-\sum\limits_{j=1}^n\lambda^{i_j}\sum\limits_{k = 1}^{n - j - 1}\tau_k}\,d\tau_1\ldots d\tau_n = \int_{\tau_j \geq 0,\ \sum\limits_{j=1}^n \tau_j \leq t - s} e^{-\sum\limits_{k=1}^n\left(\sum\limits_{j = 1}^{n - k - 1}\lambda^{i_j}\right)\tau_k}\,d\tau_1\ldots d\tau_n.
    \end{equation}
    Setting $\mu_k = \sum\limits_{j = 1}^{n - k - 1}\lambda^{i_j}$ for $k = 1, \ldots, n$ and introducing $\mu_{n + 1} = 0$, as well as $\tau_{n + 1} = (t - s) - \sum\limits_{k=1}^n \tau_k$, the integral becomes one over the simplex $C := \left\{\tau = (\tau_1, \ldots, \tau_{n+1}) \in \R^{n+1}\colon\ \sum\limits_{k=1}^{n+1}\tau_k = t - s\right\}$:
    \begin{equation}
        \int_{C} e^{-\sum\limits_{k=1}^{n+1}\mu_k\tau_k}\,d\tau.
    \end{equation}
    By induction, this integral can be written as the convolution of exponential functions $f_k(t) = e^{-\mu_k t}$:
    \begin{equation}
        \int_{C} e^{-\sum\limits_{k=1}^{n+1}\mu_k\tau_k}\,d\tau = (f_1 \star \ldots \star f_{n+1})(t - s).
    \end{equation}
    The Laplace transform of each $f_k$ is $L[f_k](w) = \dfrac{1}{w + \mu_k}$, so
    \begin{equation}
        L\left[\int_{C} e^{-\sum\limits_{k=1}^{n+1}\mu_k\tau_k}\,d\tau\right](w) = \prod\limits_{k=1}^{n+1}\dfrac{1}{w + \mu_k} = \sum\limits_{k = 1}^{n+1}\dfrac{c_k}{w + \mu_k},
    \end{equation}
    where the coefficients $c_k = \prod\limits_{l \neq k}\dfrac{1}{\mu_l - \mu_k}$ come from the partial fraction decomposition, valid when all $\mu_k$ are distinct. Applying the inverse Laplace transform yields
    \begin{equation}
         \int_{C} e^{-\sum\limits_{k=1}^{n+1}\mu_k\tau_k}\,d\tau = \sum_{k=1}^{n+1}c_ke^{-\mu_k (t-s)}.
    \end{equation}
    A straightforward reindexing $k \mapsto n + 1 - k$ concludes the proof of the first formula. The second one is obtained by taking the limit $(t - s)\to +\infty$.
\section{Proof of Lemma~\ref{lemma:L1_bound}}\label{app:lemma_l1_proof}
\begin{proof}
    {We prove the lemma only in the case of one-dimensional Brownian motion $d = 1$. The multidimensional generalization is straightforward.}
    To prove the convergence of the series
    \begin{equation}\label{eq:l2_norm_series}
        \E[\|\ssig[0, t]\|_2^2] = \sum_{n \geq 0} \sum_{|\word{v}| = n} \E[|\sig[0, t]^{\blambda, \word{v}}|^2],
    \end{equation}  
    we will recursively bound $\E[|\sig[0, t]^{\blambda, \word{v}}|^2]$ for each $\word{v}$.
    For a word $\word{v}$ such that $|\word{v}| = n > 0$, we consider three cases. In the first case, where $\word{v} = \word{v'0}$, apply Hölder's inequality:
    \begin{equation}
        \E\left[\left(\int_{0}^t e^{-\lambda^{\word{v}}(t-s)} \sig[0, s]^{\blambda, \word{v'}}\,ds\right)^2\right]
        \leq \int_{0}^t e^{-\lambda^{\word{v}}(t-s)} \E\left[|\sig[0, s]^{\blambda, \word{v'}}|^2\right]\,ds
        \int_{0}^t e^{-\lambda^{\word{v}}(t-s)}\,ds
        \leq \dfrac{1}{(\lambda^{\word{v}})^2} \sup_{s \geq 0} \E\left[|\sig[0, s]^{\blambda, \word{v'}}|^2\right].
    \end{equation}

    For $\word{v} = \word{v'1}$, with $\word{v'}$ not ending in $\word{1}$, the Stratonovich integral coincides with the Itô integral, and we have
    \begin{equation}
    \E\left[\left(\int_{0}^te^{-\lambda^{\word{v}}(t-s)}\sig[0, s]^{\blambda, \word{v'}}\circ dW_s\right)^2\right] = \int_{0}^te^{-2\lambda^{\word{v}}(t-s)}\E\left[|\sig[0, s]^{\blambda, \word{v'}}|^2\right]\,ds \leq \dfrac{1}{2\lambda^{\word{v}}} \sup_{s \geq 0} \E\left[|\sig[0, s]^{\blambda, \word{v'}}|^2\right]. 
    \end{equation}
    Finally, if $\word{v} = \word{v''11}$, then
    \begin{align}
    \E\left[\left(\int_{0}^te^{-\lambda^{\word{v}}(t-s)}\sig[0, s]^{\blambda, \word{v'}}\circ dW_s\right)^2\right] &\leq \E\left[\left(\int_{0}^te^{-\lambda^{\word{v}}(t-s)}\sig[0, s]^{\blambda, \word{v'}} dW_s\right)^2\right] + \E\left[\left(\dfrac{1}{2}\int_{0}^te^{-\lambda^{\word{v}}(t-s)}\sig[0, s]^{\blambda, \word{v''}} ds\right)^2\right] \\ 
    &\leq \dfrac{1}{2\lambda^{\word{v}}} \sup_{s \geq 0} \E\left[|\sig[0, s]^{\blambda, \word{v'}}|^2\right] + \dfrac{1}{(2\lambda^{\word{v}})^2} \sup_{s \geq 0} \E\left[|\sig[0, s]^{\blambda, \word{v''}}|^2\right], 
    \end{align}
    where the integrals are bounded as in the first two cases.

    Combining these three bounds and noting that the bound does not depend on $t$, we obtain
    \begin{align}\label{eq:recursive_bound}
        \sup_{t \geq 0} \E\left[|\sig[0, t]^{\blambda, \word{v}}|^2\right]
        &\leq \left(\dfrac{1}{(\lambda^{\word{v}})^2} \lor \dfrac{1}{2\lambda^{\word{v}}} \right) \sup_{t \geq 0} \E\left[|\sig[0, t]^{\blambda, \word{v'}}|^2\right] + \dfrac{1}{(2\lambda^{\word{v}})^2} \sup_{s \geq 0} \E\left[|\sig[0, s]^{\blambda, \word{v''}}|^2\right]
        \\
        &\leq \dfrac{C_{\blambda}}{n} \sup_{t \geq 0} \E\left[|\sig[0, t]^{\blambda, \word{v'}}|^2\right] + \dfrac{C_{\blambda}}{n^2} \sup_{t \geq 0} \E\left[|\sig[0, t]^{\blambda, \word{v''}}|^2\right],
    \end{align}
    since $\lambda^{\word{v}} \geq n \min\limits_{i \in \{0, 1\}} \lambda^i$, with a constant $C_{\blambda} \geq 1$ depending only on $\blambda$.

Applying \eqref{eq:recursive_bound} recursively, we obtain
\begin{equation}
    \sup_{t \geq 0} \E\left[|\sig[0, t]^{\blambda, \word{v}}|^2\right] \leq \dfrac{(2C_{\blambda})^n}{n!}.
\end{equation}

Finally, noting that there are $2^n$ terms in \eqref{eq:l2_norm_series} corresponding to words of length $n$, and taking the supremum in $t$, we obtain
\begin{equation}
    \sup_{t \geq 0} \E[\|\ssig[0, t]\|_2^2] \leq \sum_{n \geq 0} 2^n {\dfrac{(2C_{\blambda})^n}{n!}} < +\infty,
\end{equation}
which completes the proof of the second bound. The first one can be shown analogously.
\end{proof}

\section{Useful lemma}
\begin{lemma}\label{lemma:exp_representations}
    The following relationship holds:
    \begin{equation}\label{eq:exp_i_repr}
        \int_{-\infty}^T e^{-(k\lambda^0 + \lambda^i)(T - t)}\bracketssig[t][X]{\word{i}}dt = \sum\limits_{m=1}^{k} b_{k,m}\bracketssig[T][X]{\word{i0}\conpow{m}}, \quad k \geq 1,
    \end{equation}
    with $b_{k, m} = (-\lambda^0)^{m-1}\dfrac{(k - 1)!}{(k - m )!},\ m = 1, \ldots, k$.
\end{lemma}
\begin{proof}
    Applying Itô's decomposition to the both parts of \eqref{eq:exp_i_repr}, and equating the $dt$-terms, we obtain
    \begin{equation}
        -(k\lambda^0 + \lambda^i) \int_{-\infty}^T e^{-(k\lambda^0 + \lambda^i)(T - t)}\bracketssig[t][X]{\word{i}}dt + \bracketssig[T][X]{\word{i}} = -(m\lambda^0 + \lambda^i)\sum\limits_{m=1}^{k}b_{k,m}\bracketssig[T][X]{\word{i0}\conpow{m}} + \sum\limits_{m=1}^{k} b_{k,m}\bracketssig[T][X]{\word{i0}\conpow{(m-1)}},
    \end{equation}
    or, equivalently,
    \begin{equation}
        -(k\lambda^0 + \lambda^i)\sum\limits_{m=1}^{k} b_{k,m}\bracketssig[T][X]{\word{i0}\conpow{m}} + \bracketssig[T][X]{\word{i}} =
        \sum\limits_{m=1}^{k}\left(-(m\lambda^0 + \lambda^i) b_{k,m} + b_{k,m+1}\right)\bracketssig[T][X]{\word{i0}\conpow{(m-1)}} + b_{k, 1}\bracketssig[T][X]{\word{i}}.
    \end{equation}
    with $b_{k, k + 1} := 0$.
    This leads to
    \begin{equation}
        b_{k, 1} = 1, \quad b_{k, m + 1} = \lambda^0(m - k)b_{k, m} = (\lambda^0)^{m - 1}(m - k)(m - 1 - k)\ldots (1 - k) = (-\lambda^0)^{m}\dfrac{(k - 1)!}{(k - m - 1)!},
    \end{equation}
    and completes the proof.
\end{proof}


\section{Numerical scheme for infinite-dimensional ODEs}\label{sect:numerical_ode}
In this section, we tackle the problem of numerical solution of an infinite-dimensional ODE on $\bpsi_t \in \eTA$:
\begin{equation}\label{eq:inf_dim_ode}
\begin{cases}
    \dot\bpsi_t = -\G\bpsi_t + F(\bpsi_t), \quad t \geq 0,\\
    \bpsi_0 = \bell,
\end{cases}
\end{equation}

By Proposition \ref{prop:variation_of_c}, the equation \eqref{eq:inf_dim_ode} can be rewritten in the integral form
\begin{equation}
    \bpsi_t = \D[{t}](\bell) + \int_0^t\D[{t - s}]F(\bpsi_s)\,ds.
\end{equation}
We denote by $\hat\bpsi$ an approximated solution truncated at order $N$ and corresponding to the discretization step $h$. We also denote by $\hat F(\psi)$ the value of $F(\psi)$ truncated at the same order $N$.
This allows us to construct a semi-integrated scheme for numerical resolution of \eqref{eq:inf_dim_ode}:
\begin{align}
    \bpsi_{t + h} = \D[{h}](\bpsi_t) + \int_t^{t + h}\D[{t + h - s}]F(\bpsi_s)\,ds \approx  \D[{h}](\bpsi_t) + \int_t^{t+h}\D[{t + h - s}]\,ds F(\bpsi_t),
\end{align}
so that
\begin{equation}
    \hat\bpsi_{t + h} = \D\hat\bpsi_t + \mathcal{C}_h^\lambda \hat F(\hat\bpsi_t),
\end{equation}
where the operator $\mathcal{C}_h\colon \eTA \to\eTA$ is defined by
\begin{equation}
    \mathcal{C}_h\colon \bell = \sum_{n\geq 0}\sum_{|\word{v
    }| = n}\bell^{\word{v}} \mapsto \mathcal{C}_h\bell = \sum_{n\geq 0}\sum_{|\word{v
    }| = n}\left(\frac{1 - e^{-\lambda^{\word{v}} h}}{\lambda^{\word{v}}}\right)\bell^{\word{v}}
\end{equation}
with convention $\left(\frac{1 - e^{-\lambda^{\word{v}} h}}{\lambda^{\word{v}}}\right)\bigg|_{\lambda^{\word{v}} = 0} = h$.

To improve the numerical stability, we use the predictor-corrector scheme:
\begin{align}
    \hat\bpsi_{t + h}^P &= \D\hat\bpsi_t + \mathcal{C}_h^\lambda F(\hat\bpsi_t), \\
    \hat\bpsi_{t + h} &= \D\hat\bpsi_t + \mathcal{C}_h^\lambda \left(\frac{F(\hat\bpsi_t) + F(\hat\bpsi_{t + h}^P)}{2}\right). \\
\end{align}

