\begin{definition}
A strictly upper triangular matrix $M$ is said to have an {\it $RC(k,l;m)$-formation} (or simply an {\it $RC$-formation}) for $k<m<l$ if $M$ satisfies 
\begin{align*}
\left\{
\begin{array}{ll}
M(k, m+1)=M(k,l)=M(m,l)=M(m,m+1)=2 \\
M(k,j)=2 \text{ when } j \leq m-1. \\
M(i,l)=2 \text{ when } i \geq m+2. \\
M(k,m)=0 \text{ or } 2. \
M(m+1,l)=0 \text{ or } 2. \\
M(m-1, m+1)=0 \text{ or } 2. \
M(m, m+2)=0 \text{ or } 2. \\
M(i,j)=0 \text{ otherwise}. 
\end{array}
\right.
\end{align*}
\end{definition}

\noindent The following proposition would be useful for matrices of a large size. 


\begin{proposition}
Any strictly upper triangular matrix of an $RC$-formation is a CN-realizable matrix. 
\end{proposition}

\begin{proof}
Let $M$ be an $n \times n$ matrix of an $RC(k,l;m)$-formation. 
Take a B-ladder diagram $D$ of $M$ as 
$$B^k_l \ B^k_{k+1}B^k_{k+2} \dots B^k_{m-1} (B^k_{m}) B^k_{m+1}\ (B^{m-1}_{m+1}) B^m_{m+1} (B^m_{m+2}) \ B^{m}_l (B^{m+1}_l) B^{m+2}_l \dots B^{l-2}_l B^{l-1}_l.$$
Since $M$ has the $rc(l,m+1)$-$rc(m,l)$-formation if the $(k,l)$ entry is replaced with 0, keeping $B^k_l$ at the top, $D$ is transformed into 
\begin{align*}
& B^k_k \ W^k_{k+1} \dots (W^{m-1}_m W^{m-1}_m) W^{m}_{m+1} W^{m-1}_{m} W^{m-1}_{m} \dots W^{k}_{k+1} (W^{m-1}_m W^{m-1}_m )\\
& (W^{m+1}_{m+2} W^{m+1}_{m+2}) W^{l-1}_{l} \dots W^{m+1}_{m+2} W^{m+1}_{m+2} W^{m}_{m+1} (W^{m+1}_{m+2} W^{m+1}_{m+2}) \dots W^{l-1}_{l}
\end{align*}
by the ladder moves of the proof of Proposition \ref{prop-alpha}. 
Apply the ladder moves L6, (L7 if $M(k,m)=2$) and L5 for the black edge $B^k_l$ with the white edges $W^k_{k+1} \dots (W^{m-1}_{m} W^{m-1}_{m} ) W^{m}_{m+1} W^{m-1}_{m}$. 
Then $B^k_l$ is shortened to $B^m_l$. 
After some L3 (and L5 if $M(m,m+2)=2)$, apply L8 for $B^m_l$ with the white edges $W^{l-1}_{l} \dots W^{m+1}_{m+2}$ to obtain $B^m_{m+1}$. 
By L1, we obtain a W-ladder diagram. 
(See Figure \ref{fig-rc-ex}.)
\end{proof}

