\subsection{OU matrix}
\label{sub-sec-OU}

In this subsection, we give a positive answer to Conjecture \ref{conj-OU} when $n \leq 6$. 
The following proposition was shown in \cite{AY-5} for $N=5$. 

\begin{proposition}
If Conjecture \ref{conj-CN} is true for $n \leq N$, then Conjecture \ref{conj-OU} is true for $n \leq N$, too. 
\label{prop-3to2}
\end{proposition}

\begin{proof}
Let $M$ be an $n\times n$ non-negative matrix. 
Suppose that $M$ is the OU matrix of a pure $n$-braid diagram $b$. 
By the definitions of CN matrix and OU matrix, $M+M^T$ is the CN matrix of the projection of $b$. 
By Proposition \ref{prop-T0}, $M+M^T$ is an even T0 matrix. 
Conversely, suppose that $M+M^T$ is an even T0 matrix. 
By the assumption that Conjecture \ref{conj-CN} is true for $n\leq N$, $M+M^T$ is the CN matrix of some pure $n$-braid projection $B$ for $n\leq N$. 
By Corollary 1 in \cite{AY-5}, $M$ is the OU matrix of some pure $n$-braid diagram whose projection is $B$ for $n\leq N$. 
This completes the proof of Proposition \ref{prop-3to2}.
\end{proof}


\noindent From Propositions \ref{prop-CN6} and \ref{prop-3to2}, we have the following corollary, which is an answer to Conjecture \ref{conj-OU} for $n \leq 6$. 

\begin{corollary}
A $6 \times 6$ non-negative integer matrix $M$ is the OU matrix of some pure $6$-braid diagram if and only if $M+M^T$ is an even T0 matrix. 
\label{cor-OU6}
\end{corollary}



\subsection{Crossing matrix}
\label{sub-sec-CM}

In this subsection, we give a positive answer to Conjecture \ref{conj-C} when $n \leq 6$ and prove Theorem \ref{thm-true6}. 
The following proposition was shown in \cite{AY-5} for $N=5$. 

\begin{proposition}
If Conjecture \ref{conj-CN} is true for $n \leq N$, then Conjecture \ref{conj-C} is true for $n \leq N$, too. 
\label{prop-3to1}
\end{proposition}

\begin{proof}
Let $M=(M(i,j))$ be an $n\times n$ matrix. 
Assume that Conjecture \ref{conj-CN} is true for $n\leq N$. 
Suppose that $M$ is the crossing matrix of a positive pure $n$-braid diagram $b$. 
Since $b$ is positive, $M$ coincides with the OU matrix of $b$ by Proposition \ref{prop-C-OU}, and $M$ is non-negative integer matrix. 
Since $b$ is pure, $M$ is symmetric by Proposition \ref{prop-T0-set}. 
By Proposition \ref{prop-3to2}, $M+M^T=2M$ is an even T0 matrix for $n\leq N$, and hence $M$ is a T0 symmetric matrix for $n\leq N$. 
Conversely, suppose that $M$ is a non-negative T0 symmetric matrix. 
Then, $M+M^T=2M$ is a non-negative even T0 (symmetric) matrix. 
By the assumption that Conjecture 3 is true for $n\leq N$, $2M$ is the CN matrix of some pure $n$-braid projection $B$ for $n\leq N$. 
The number of intersections with the strands $s_i$ and $s_j$ of $B$ is $2M(i,j)$. 
Let $B(i,j)$ be the number of intersections between the strands $s_i$ and $s_j$ of $B$ where $s_i$ crosses $s_j$ from left to right. 
(We remark that $B(i,j)+B(j,i)=2M(i,j)$.) 
Since $B$ is pure, $B(i,j)=B(j,i)=M(i,j)$. 
Let $b$ be a positive pure $n$-braid diagram whose projection is $B$. 
Then, for each crossing $c$ between the strands $s_i$ and $s_j$ of $b$, $s_i$ crosses $s_j$ from left to right at $c$ if and only if $s_i$ crosses under $s_j$ at $c$. 
Hence, the number of crossings between $s_i$ and $s_j$ of $b$ where $s_i$ crosses over $s_j$ coincides with the number of crossings between $s_i$ and $s_j$ of $b$ where $s_i$ crosses under $s_j$. 
Then, the $(i,j)$ entry of the OU matrix of $b$ is $B(i,j) \ (=M(i,j))$, i.e. the OU matrix of $b$ is $M$. Since $b$ is positive, the crossing matrix of $b$ is aslo $M$ by Proposition \ref{prop-C-OU}. 
This completes the proof of Proposition \ref{prop-3to1}.
\end{proof}


\noindent From Propositions \ref{prop-CN6} and \ref{prop-3to1}, we have the following corollary, which is an answer to Conjecture \ref{conj-C} for $n \leq 6$. 

\begin{corollary}
A $6 \times 6$ integer matrix $M$ is the crossing matrix of some positive pure $6$-braid if and only if $M$ is a non-negative integer T0 symmetric matrix. 
\label{cor-CM6}
\end{corollary}

\medskip
\noindent We prove Theorem \ref{thm-true6}. \\

\noindent {\it Proof of Theorem \ref{thm-true6}.} \ It follows from Proposition \ref{prop-CN6}, Corollaries \ref{cor-OU6} and \ref{cor-CM6}. \qed 


