\subsection{Sign coordinate}
\label{sub:Sign coorinate}

\begin{dfn}\label{dfn:even sign coordinates}
Let $k$ be a non-negative integer. Let $X$ be a $2k$-dimensional compact, oriented, differentiable manifold, and let $\hat{A} \colon X \to \mathcal{F}(\mathcal{\hat{H}})$ be a continuous map. We fix $\mu > 0$ and an open set $U \subset X$, as described in Proposition \ref{prop:mu exist}, such that $U$ contains $F$ and the space $(\mathcal{\hat{H}}, \hat{A}_x)_{<\mu}$ is defined for all $x \in U$. We assume that $\dim(\mathcal{\hat{H}}, \hat{A}_x)_{<\mu} = 2^k$ for all $x \in F$. We also fix an action of $Cl_{2k}$ on $(\mathcal{\hat{H}}, \hat{A}_x)_{<\mu}$ such that it becomes a $\mathbb{Z}_2$-graded irreducible representation.
\begin{enumerate}
\item We say that a coordinate $(V;a_1,...,a_{2k})$ $(x\in V \subset U)$ of $X$ is an (even) sign coordinate of $x$ when $\hat{A}_{<\mu}|_V \simeq \sum_{n=1}^{2k}a_{i}\hat{\gamma_i}:(\mathcal{\hat{H}}, \hat{A})_{<\mu}|_V\to (\mathcal{\hat{H}}, \hat{A})_{<\mu}|_V.$\\
Here, $\simeq$ means fiber homotopy equivalence.
\item When a sign coordinate $(V;a_{1},...,a_{2k})$ $(V\subset U)$ can be taken in $x \in F$, define the following sign.
\begin{align*}
\operatorname{sign}(x)=\frac{\frac{\partial(a_{1},...,a_{2k+1})}{\partial (x_{1},...,x_{2k})}}{\lvert \frac{\partial(a_{1},...,a_{2k})}{\partial (x_{1},...,x_{2k})}\rvert}\in \{-1,1\}.
\end{align*}
Here $(V;x_{1},...,x_{2k})$ is an oriented coordinate of $X$, and $\frac{\partial(a_{1},...,a_{2k})}{\partial (x_{1},...,x_{2k})}$ is the Jacobian.
\end{enumerate}
\end{dfn}


\begin{dfn}\label{dfn:odd sign coordinates}
Let $k$ be a non-negative integer. Let $X$ be a ($2k+1$)-dimensional compact, oriented, differentiable manifold, and let $A\colon X\to Fred_{sa}(\mathcal{H})$ be a continuous map. We fix $\mu > 0$ and an open set $U \subset X$, as described in Proposition \ref{prop:mu exist}, such that $U$ contains $F$ and the space $(\mathcal{H}, A_x)_{<\mu}$ is defined for all $x \in U$. We assume that $\dim(\mathcal{H}, A_x)_{<\mu} = 2^k$ for all $x \in F$. We also fix an action of $Cl_{2k}$ on $(\mathcal{H}, A_x)_{<\mu}$ such that it becomes an irreducible representation.
\begin{enumerate}
\item We say that a coordinate $(V;a_1,...,a_{2k+1})$ $(x\in V \subset U)$ of $X$ is an (odd) sign coordinate of $x$ when $A_{<\mu}|_V \simeq \sum_{n=1}^{2k+1}a_{i}\gamma_i:(\mathcal{H},A)_{<\mu}|_V\to (\mathcal{H},A)_{<\mu}|_V.$\\
Here, $\simeq$ means fiber homotopy equivalence.
\item When a sign coordinate $(V;a_{1},...,a_{2k+1})$ $(V\subset U)$ can be taken in $x \in F$, define the following sign.
\begin{align*}
\operatorname{sign}(x)=\frac{\frac{\partial(a_{1},...,a_{2k+1})}{\partial (x_{1},...,x_{2k+1})}}{\lvert \frac{\partial(a_{1},...,a_{2k+1})}{\partial (x_{1},...,x_{2k+1})}\rvert}\in \{-1,1\}.
\end{align*}
Here $(V;x_{1},...,x_{2k+1})$ is an oriented coordinate of $X$, and $\frac{\partial(a_{1},...,a_{2k+1})}{\partial (x_{1},...,x_{2k+1})}$ is the Jacobian.
\end{enumerate}
\end{dfn}

\begin{dfn}
An element $x \in F$ of the Fermi set is called a Fermi point if a sign coordinate can be defined for it.
\end{dfn}

Let $U_1$ and $U_2$ be open neighborhoods of the origin in $\mathbb{R}^n$. Consider a diffeomorphism $f\colon U_1 \to U_2$ satisfying $f(0)=0$ and $\det{T}>0$, where $T=Jf(0)$ is the Jacobian matrix of $f$ at the origin. The image of $T$, denoted $Im(T)$, is the image of the linear map $T$. We define $f_1\colon Im(T) \to U_2$ by $f_1=f \circ T^{-1}$, so that $f=f_1 \circ T$. Here, $Jf$ and $Jf_1$ denotes the Jacobian matrix of $f$ and $f_1$, respectively.
\begin{lem}\label{Decomposition of f}
$Jf_1(0)=E_n$, where $E_n$ is the $n\times n$ identity matrix.
\end{lem}

\begin{proof}
This is clear from the definition of $f_1$ and the differentiation of composite and inverse functions.
\end{proof}

\begin{lem}\label{lem:4.9}
\begin{enumerate}
\item Let $U_1,U_2\subset \mathbb{R}^n$ be open neighborhoods of 0, $f:U_1 \to U_2$ a smooth map such that $f(0)=0$ and $Jf(0)=E_n$.
Then $f|_{D(r)}:D(r)\to D(r^{\prime})$ is a diffeomorphism and there exists a positive real numbers $r, r^{\prime}>0\,(r^{\prime}\ge r>0) $ such that $f|_{D(r)}\simeq i$.
Here, $D(r)$ is an open ball of radius $r$ centered at the origin, and $i:D(r)\to D(r^{\prime})$
is the inclusion map.
\item Let \( T \in SL(n;\mathbb{R}) \) be a linear transformation. 
Then for any \( r > 0 \), there exists \(0< r'' < r \) such that 
\[
\operatorname{Im}(T|_{D(r'')}) \subset D(r),
\]
and the map \( T \colon D(r'') \to D(r) \) is homotopic to the inclusion \( i \colon D(r'') \hookrightarrow D(r) \); that is, \( T \simeq i \).
\end{enumerate}
\end{lem}

\begin{proof}
\begin{enumerate}
\item
For any real number $t \in \mathbb{R}$, we define a homotopy $f_{t}\colon U_1 \to \mathbb{R}^n$
by the formula
\begin{align*}
f_t(x)=tx+(1-t)f(x).
\end{align*} 
This definition ensures that $f_t(0)=0$ and $f_t(1)=1$.  

Next, we define a map $F\colon U_1\times [0,1] \to \mathbb{R}^n \times [0,1]$ by $F(x,t)=(f_t(x),t)$.
By definition, the image of the point $(0,t)$ under the map $F$ is $F(0,t)=(0,t)$.
Furthermore, the Jacobian matrix of $F$ at $(0,t)$ has the form  
\begin{align*}
J F(0,t)= 
\begin{pmatrix}
E_n & * \\
0 & 1
\end{pmatrix},
\end{align*}
where the asterisk represents some entries whose explicit form is irrelevant in this context.  
Since the Jacobian matrix is non-singular, the inverse function theorem guarantees the existence of positive real numbers $r_t>0$ and $\delta_t>0$ such that the restricted map 
\begin{align*}
F|_{D(r_t) \times [t-\delta_t, t+\delta_t]}\colon D(r_t) \times [t-\delta_t, t+\delta_t] \to \mathbb{R}^n \times [0,1]
\end{align*}
is a diffeomorphism onto its image.
Due to the compactness of $[0,1]$, there exists a monotonely increasing sequence 
$t_1,...,t_n\in [0,1]$ such that $\bigcup_{i=1}^{n}[t_i-\delta_{t_i},t_i+\delta_{t_i}]=[0,1]$.
If we set $r = \min \{r_{t_1}, \dots, r_{t_n}\}$, then $F|_{D(r) \times [0,1]} : D(r) \times [0,1] \to \mathbb{R}^n \times [0,1]$ is a diffeomorphism onto its image.
The subspace $F(D(r)\times [0,1])\subset \mathbb{R}^n\times [0,1]$
is compact, so there exists a positive real number $r^{\prime}>0$ such that $F(D(r)\times [0,1])\subset D(r^{\prime})\times [0,1]$.
($0<r\leq r^{\prime}$ since $F(D(r)\times \{1\})=D(r)\times \{1\} \subset D(r^{\prime})\times \{1\}$.)
Therefore, $F$ is a homotopy that gives $f|_{D(r)}\simeq i$.
\item Since $SL(n;\mathbb{R})$ is path-connected, the path connecting $T$ and $E_n$ gives the homotopy.
\end{enumerate}
\end{proof}

Given a $\mathbb{Z}_2$-graded representation $\hat{S}$ of $Cl_{2k}$, let\,$\hat{\mu}_{S}\colon D^{2k}\to End(\hat{S})$ be defined as 
\begin{align*} \hat{\mu}_{S}(x_1,...,x_{2k+1})=\sum_{i=1}^{2k+1}x_{i}\hat{\gamma}_{i}.
\end{align*} 
The orthogonal complement of the embedding $\hat{S} \subset \mathcal{H}_{2k}$ as a graded representation is denoted as $\hat{S}^{\perp}$, and the action of $Cl_{2k+1}$, which is an extension of the action of $Cl_{2k}$, on $\hat{S}^{\perp} \cong \mathcal{H}_{2k}$ is denoted as $\hat{\gamma}^{\perp}$.

\begin{thm}
Suppose that a continuous mapping 
\begin{align*}
\hat{A} \colon(D^{2k},\partial D^{2k})\to (\mathcal{F}_{0}(\mathcal{\hat{H}}),\mathcal{F}^{*}_{0}(\mathcal{\hat{H}}))
\end{align*}
satisfies the following assumptions:
\begin{enumerate}
\item The Hilbert space \( \hat{\mathcal{H}} \) admits a direct sum decomposition 
\( \hat{\mathcal{H}} = \hat{S}_{+} \oplus \hat{S}_{+}^{\perp} \), and accordingly, 
the operator \( \hat{A}(x) \) can be decomposed as 
\[
\hat{A}(x) = \hat{a}(x) + \hat{a}^{\perp}(x),
\]
where \( \hat{a}(x) \colon \hat{S}_{+} \to \hat{S}_{+} \subset \hat{\mathcal{H}} \) 
and \( \hat{a}^{\perp}(x) \colon \hat{S}_{+}^{\perp} \to \hat{\mathcal{H}} \).\\
\item For any $x \in D^{2k}$, we have $\hat{a}^{\perp}(x)\in \mathcal{F}^{*}_{0}(\mathcal{\hat{\mathcal{H}}})$.\\
\item There exists a smooth mapping $f=(f_1,...,f_{2k})\colon D^{2k}\to \mathbb{R}^{2k}$ such that:\\
\begin{itemize}
    \item  For any $x \in D^{2k}$, the map $\hat{a}$ admits the expression $\hat{a}(x)=\sum_{i=1}^{2k}f_i(x)\hat{\gamma}_i$.
    \item $f^{-1}(\{0\})=\{0\}$.
    \item $\det Jf(0)>0$.
\end{itemize}
\end{enumerate}
In this case, under an isomorphism $K^{0}(D^{2k},\partial D^{2k})\cong \mathbb{Z}$, the map $\hat{A}$ represents the generator $1 \in \mathbb{Z}$.
\end{thm}

\begin{proof}
\begin{enumerate}
\item Consider the case where $f$ satisfies $\det{Jf(0)}=1$.

Under the third assumption, Lemma \ref{lem:4.9} guarantees the existence of positive real numbers \( r' \ge r > 0 \) such that the map \( f : D(r) \to D(r') \) is a diffeomorphism and is homotopy equivalent to the inclusion \( i : D(r) \to D(r') \).

If necessary, $r$ and $r^{\prime}$ may be replaced so as to be $r\leq r^{\prime}\leq1$.
From the long exact sequence in cohomology for the triple \( (D(r'), D(r') \setminus \operatorname{int}(D(r)), \partial D(r')) \), we obtain the following isomorphism:
\begin{align*}
j^* \colon K^{-1}(D(r^{\prime}),D(r^{\prime}) \setminus \text{int}(D(r)) \cong K^{-1}(D(r^{\prime}),\partial D(r^{\prime})).
\end{align*}
Therefore, from this isomorphism and the excision theorem, we obtain the following isomorphism:
\begin{align*}
f^*=i^*\colon K^{-1}(D(r^{\prime}),\partial D(r^{\prime})) \cong K^{-1}(D(r),\partial D(r)).
\end{align*}
Then we obtain the following sequence of equalities:
\begin{align*}
i^{*}([\hat{\mu}_{S} + \hat{\gamma}^{\perp}|_{D(r^{\prime})}])&=f^{*}([\hat{\mu}_{S} + \hat{\gamma}^{\perp}])=[\hat{\mu}_{S} \circ f + \hat{\gamma}^{\perp} \circ f]\\
&=\left[(\sum_{i=1}^{2k+1} f_i \hat{\gamma}_i) + \hat{a}^{\perp}\right]
=i^*([\hat{A}|_{D(r^{\prime})}]).
\end{align*}

Thus, it follows that $[\hat{\mu}_{S} + \hat{\gamma}^{\perp}|_{D(r^{\prime})}] = [\hat{A}|_{D(r^{\prime})}]$. 

We note that $D^{2k+1} = D(1)$. From the long exact sequence in cohomology for the triple \( (D^{2k+1}, D^{2k+1} \setminus \operatorname{int}(D(r')), \partial D^{2k+1}) \), we obtain the following isomorphism:
\begin{align*}
j^* \colon K^{-1}(D^{2k+1}, D^{2k+1} \setminus \operatorname{int}(D(r'))) \cong K^{-1}(D^{2k+1}, \partial D^{2k+1}).
\end{align*}
Under the assumption that \( f^{-1}(\{0\}) = \{0\} \), the operator \( \hat{A} \) is invertible on \( D^{2k+1} \setminus \operatorname{int}(D(r') \). Therefore, \( \hat{A} \) represents an element in \( K^{-1}(D^{2k+1}, D^{2k+1} \setminus \operatorname{int}(D(r'))) \). From this isomorphism and the excision theorem, we obtain the following isomorphism:
\begin{align*}
i^*\colon K^{-1}(D^{2k+1},\partial D^{2k+1}) \cong K^{-1}(D(r^{\prime}),\partial D(r^{\prime})).
\end{align*}
Consequently, from $i^*([\hat{\mu}_{S} + \hat{\gamma}^{\perp}]) = i^*([\hat{A}])$, 
we deduce that $[\hat{\mu}_{S} + \hat{\gamma}^{\perp}] = [\hat{A}]$.
\item Consider the case of a general $f$.

From Lemma \ref{Decomposition of f}, we can decompose \( f \) as \( f = f_1 \circ T^{-1} \), where \( T \) is a homeomorphism which maps the origin to itself. Lemma \ref{lem:4.9} guarantees the existence of positive real numbers \( r, r' \) with \( 0 < r \le r' \) such that the map
\[
f_1 : D(r) \to D(r')
\]
is a diffeomorphism which is homotopic to the inclusion \( i \), that is, \( f \simeq i \).  
By Lemma \ref{lem:4.9}, There exists a positive real number \( r^{\prime\prime} > 0 \) such that
\[
D(r^{\prime\prime}) \subset \operatorname{Im}(T|_{D(r)})
\]
and the map
\[
T^{-1} : D(r^{\prime\prime}) \to D(r)
\]
is homotopic to the inclusion \( i : D(r^{\prime\prime}) \to D(r) \).  
Consequently, we have
\[
f = f_1 \circ T^{-1} : D(r^{\prime\prime}) \to D(r').
\]
By Lemma \ref{Decomposition of f}, this implies that
\[
f^* = f_1^* : K^{-1}(D(r'), \partial D(r')) \to K^{-1}(D(r^{\prime\prime}), \partial D(r^{\prime\prime})).
\]
Hence, the claim follows from the discussion in (1).
\end{enumerate}
\end{proof}

Let $\hat{S}_{+}$ and $\hat{S}_{-}$ be two $\mathbb{Z}_2$-graded irreducible representations of $Cl_{2k+2}$ that are inequivalent to each other.
(If necessary, the $\mathbb{Z}_2$-graded irreducible representations of $Cl_{2k+1}$ obtained by ignoring the action of $\gamma_{2k+2}\in Cl_{2k+2}$ are assumed to be identical.)
Given a $\mathbb{Z}_2$-graded representation $\hat{S}$ of $Cl_{2k+2}$, let\,$\hat{\mu}_{S}\colon D^{2k+1}\to End(\hat{S})$ be defined as 
 \begin{align*} 
\hat{\mu}_{S}(x_1,...,x_{2k+1})=\sum_{i=1}^{2k+1}x_{i}\hat{\gamma}_{i}.
\end{align*} 
The orthogonal complement of the embedding $\hat{S} \subset \mathcal{H}_{2k+2}$ as a graded representation is denoted as $\hat{S}^{\perp}$, and the action of $Cl_{2k+3}$, which is an extension of the action of $Cl_{2k+2}$, on $\hat{S}^{\perp} \cong \mathcal{H}_{2k+2}$ is denoted as $\hat{\gamma}^{\perp}$.

\begin{thm}\label{thm:4.11}
Suppose that a continuous mapping 
\begin{align*}
\hat{A}\colon(D^{2k+1},\partial D^{2k+1})\to (\mathcal{F}_{1}(\mathcal{\hat{H}}),\mathcal{F}^{*}_{1}(\mathcal{\hat{H}}))
 \end{align*}
 satisfies the following assumptions:
\begin{enumerate}
\item The Hilbert space \( \hat{\mathcal{H}} \) admits an orthogonal decomposition 
\( \hat{\mathcal{H}} = \hat{S}_{+} \oplus \hat{S}_{+}^{\perp} \), and accordingly, 
the operator \( \hat{A}(x) \) can be decomposed as a sum 
\[
\hat{A}(x) = \hat{a}(x) + \hat{a}^{\perp}(x),
\]
where \( \hat{a}(x) \colon \hat{S}_{+} \to \hat{S}_{+} \subset \hat{\mathcal{H}} \) 
and \( \hat{a}^{\perp}(x) \colon \hat{S}_{+}^{\perp} \to \hat{\mathcal{H}} \).\\
\item For any $x \in D^{2k+1}$, we have $\hat{a}^{\perp}(x)\in \mathcal{F}^{*}_{1}(\mathcal{\mathcal{H}})$.\\
\item There exists a smooth mapping $f=(f_1,...,f_{2k+1})\colon D^{2k+1}\to \mathbb{R}^{2k+1}$ such that:
\begin{itemize}
    \item  For any $x \in D^{2k+1}$, the map $\hat{a}$ admits the expression $\hat{a}(x)=\sum_{i=1}^{2k+1}f_i(x)\hat{\gamma}_i$.
    \item $f^{-1}(\{0\})=\{0\}$.
    \item $\det Jf(0)>0$.
\end{itemize}
\end{enumerate}
In this case, under an isomorphism $K^{-1}(D^{2k+1},\partial D^{2k+1})\cong \mathbb{Z}$, the map $\hat{A}$ represents the generator $1 \in \mathbb{Z}$.
\end{thm}

\begin{proof}
The proof proceeds similarly in the even-dimensional case.
\end{proof}                                                 

\begin{rem}\label{rem:3}
Consider the $\mathbb{Z}_2$-graded representation $\hat{S}$ of the Clifford algebra $Cl_{2k+1}$, defined as $\hat{S} = S^0 \oplus S^1$, where $S^0 = S^1$. Under this representation, we express the following matrices:
\begin{align*}
\hat{\epsilon}&=\begin{pmatrix}
1_S & 0 \\
0 & -1_S
\end{pmatrix},&
\hat{\gamma}_i&=\begin{pmatrix}
0 & \gamma_i \\
\gamma_i & 0
\end{pmatrix},&
\hat{\gamma}_{2k+2}&=\begin{pmatrix}
0 & -\sqrt{-1}\cdot1_S \\
\sqrt{-1}\cdot1_S & 0
\end{pmatrix}.
\end{align*}
where $i$ ranges from 1 to $2k+1$. Here, $\gamma_1, \dots, \gamma_{2k+1}$ are self-adjoint homomorphisms on $S$, which collectively provide an ungraded representation of $Cl_{2k+1}$.

In this framework, we define the operators $\hat{a}(x)$ and $\hat{\mu}(x)$ as follows:
\begin{align*}
\hat{a}(x)&=\begin{pmatrix}
0 & \sum_{i=1}^{2k+1}f_i(x)\gamma_i \\
\sum_{i=1}^{2k+1}f_i(x)\gamma_i & 0
\end{pmatrix},&
\hat{\mu}(x)&=\begin{pmatrix}
0 & \sum_{i=1}^{2k+1}x_i\gamma_i \\
\sum_{i=1}^{2k+1}x_i\gamma_i & 0
\end{pmatrix}.
\end{align*}
From these definitions, it follows that a statement concerning $\hat{a}(x)$ can be equivalently reformulated as a statement about $a(x)$.
\end{rem}

We define $Fred_{sa}^{1,*}(\mathcal{H}) \subset Fred_{sa}^{1}(\mathcal{H})$ as the subspace of invertible operators.

Let $S_{+}$ and $S_{-}$ be two ungraded irreducible representations of $Cl_{2k+1}$ that are inequivalent to each other. Furthermore, consider a separable infinite-dimensional Hilbert space $\mathcal{H}$, and take the direct sum $S_{+}\oplus \mathcal{H}$ with $S_{+}$. In this case, the following corollary is obtained.


\begin{cor}
Consider a continuous map
\begin{align*}
A \colon (D^{2k+1}, \partial D^{2k+1}) \to (Fred_{sa}^{1}(S_{+} \oplus \mathcal{H}), Fred_{sa}^{1,*}(S_{+} \oplus \mathcal{H})).
\end{align*}
We denote the \( S_{+} \)-component and the \( \mathcal{H} \)-component of \( A \) 
by \( a \) and \( a^{\perp} \), respectively. That is, we write
\[
A(x) = a(x) + a^{\perp}(x),
\]
where \( a(x) \colon S_{+} \to S_{+} \subset \mathcal{H} \) and 
\( a^{\perp}(x) \colon S_{+}^{\perp} \to \mathcal{H} \). We assume that $A$ satisfies the following conditions.
\begin{enumerate}
\item For any $x \in D^{2k+1}$, we have $a^{\perp}(x)\in Fred_{sa}^{1,*}(S_{+}\oplus \mathcal{H})$.\\
\item There exists a smooth mapping $f=(f_1,...,f_{2k+1})\colon D^{2k+1}\to \mathbb{R}^{2k+1}$ such that:
\begin{itemize}
    \item  For any $x \in D^{2k+1}$, the map a admits the expression $a(x)=\sum_{i=1}^{2k+1}f_i(x)\gamma_i$.
    \item $f^{-1}(\{0\})=\{0\}$.
    \item $\det Jf(0)>0$.
\end{itemize}
\end{enumerate}
In this case, under an isomorphism $K^{-1}(D^{2k+1},\partial D^{2k+1})\cong \mathbb{Z}$, the map $A$ represents the generator $1 \in \mathbb{Z}$.
\end{cor}

\begin{proof}
The claim follows from the correspondence between $Fred_{sa}^{1}$ and $\mathcal{F}_1$, along with Theorem \ref{thm:4.11} and Remark \ref{rem:3}.
\end{proof}




