\node (b) at (3.2, 0) {$K^1(D^{n}, \partial D^{n})$};
\node (c) at (6.8, 0) {$K^1(X, X \setminus \text{int}(D^n))$};   
\node (d) at (10.2, 0) {$K^1(X, X \setminus F)$};
\node (e) at (10.2, -3) {$K^1(X)$}; 

% 横方向の矢印（上下ラベル）
\draw[->] (a) -- 
