\end{enumerate}
\end{proof}

\begin{lem}\label{lem:4.14}
Let $X$ be a compact, oriented, differentiable manifold, and $\mathcal{H}$ a separable infinite-dimensional Hilbert space. Let $A \colon X \to \mathrm{Fred}_{sa}(\mathcal{H})$ be a continuous mapping. In this case, the points in $F$ that are Fermi points are isolated points.
\end{lem}

\begin{proof}
Suppose $x\in F$ has a sign coordinate but is not an isolated point. Then, for any sign coordinate of $x$, denoted $(U,x=(x_1,\dots,x_n))$, there exists $x^{\prime}\in F \cap U \setminus \{x\}$. However, by the definition of a sign coordinate, the only point in $U$  where $A_{<\mu}=0$ holds is $x$. This implies that no such $x^{\prime} \neq x$ can exist in $U\cap F$, leading to a contradiction.
\end{proof}

\begin{lem}\label{lem:4.15}
Let $X$ be a compact, oriented, differentiable manifold, and $\mathcal{H}$ a separable infinite-dimensional Hilbert space. Let $A \colon X\to Fred_{sa}(\mathcal{H}) $ be a continuous mapping, and let us assume that each point of the Fermi set \(F\) is a Fermi point. Then, \(F\) is a finite set.
\end{lem}

\begin{proof}
Since $A$ is a continuous map, $F$ is a closed set. Therefore, $V=X \backslash F$ is an open set. From the Lemma \ref{lem:4.14}, for any $x \in F$, there exists an open neighborhood $U_x$ of $x$ such that $U_x \cap F=\{x\}$ holds. In this case, $X=V\cup \bigcup_{x\in F} U_x$ is an open covering of $X$, so due to the compactness, $X$ can be covered by a finite number of these. Then, $F \cap V=\phi$ means that $F$ is a finite set.
\end{proof}


\begin{thm}[Theorem \ref{thm:odd main theorem}]\label{thm:odd main thm}
Let $k$ be a non-negative integer. Let $X$ be a compact, oriented, $(2k+1)$-dimensional differentiable manifold, and \,$A\colon X\to \mathcal{F}_{1}(\mathcal{H})$ a continuous map. Then, the following holds.
\begin{enumerate}
\item When each point $x \in F$ is a Fermi point, the sum of signs $\sum_{x \in F}\operatorname{sign}(x)$ depends only on $[A] \in K^1(X)$.
\item Under the assumption of $(1)$, the following equality holds.
\begin{align*}
\int_X \operatorname{ch}_{k+\frac{1}{2}}([A]) = \sum_{x \in F}\operatorname{sign}(x) \in \mathbb{Z}.
\end{align*} 
\end{enumerate} 
\end{thm}

\begin{proof}
The sum $\sum_{x \in F}\operatorname{sign}(x)$ is finite by Lemma \ref{lem:4.15}. Since the integral of the Chern character depends only on the homotopy class of $A$, it is sufficient to prove the second claim. From Lemma \ref{lem:4.13}, we can prove the case where $F=\{x\}$. From the Proposition     \ref{prop:chern character and push forward}, the following diagram commutes.\\
