\node (a) at (0, 3) {$K^{0}(F)$}; 
\node (x) at (3.5, 3) {$H^{\mathrm{even}}(F;\mathbb{Q})$};
\node (b) at (0, 0) {$K^{1}(X)$};   
\node (y) at (3.5, 0) {$H^{\mathrm{odd}}(X;\mathbb{Q})$};

% 矢印
\draw[->] (a) -- node[midway, above] {\(\scriptstyle \operatorname{Ch}\)} (x);
\draw[->] (x) -- node[midway, right] {\(\scriptstyle i_*^H\)} (y);
