\subsection{Proof of the bulk-edge correspondence}
\label{subsec:Proof of the bulk-edge correspondence}

Here we give a proof of the bulk-edge correspondence for four-dimensional class AI topological insulators. The idea of the proof originates from \cite{G1}.

Let $\hat{H} \colon T^4\to Herm(\mathbb{C}^r)^{*}$ be a continuous map  from the 4-dimensional torus $T^4=\mathbb{R}^4/2\pi \mathbb{Z}^4$
to the space $Herm(\mathbb{C}^r)^{*}$ of invertible $r$ by $r$ Hermitian matrices. We assume that $\hat{H}(k)$ has  both positive and negative eigenvalues
at each $k\in T^4$. Associated to $\hat{H}$ is the Bloch vector bundle $E_{\hat{H}}\to T^4$ whose fiber at $k\in T^4$ consists of negative eigenvectors of 
$\hat{H}(k)$
\begin{align*}
E_{\hat{H}}=\bigcup_{k \in T^4}\bigoplus_{\lambda <0}\ker(\hat{H}(k)-\lambda)\subset T^4\times \mathbb{C}^r.
\end{align*}
 By evaluating the fundamental class $[T^4]\in H_{4}(T^4;\mathbb{Z})$ of $T^4$ by the second Chern class $c_2(E_{\hat{H}}) \in H^4(T^4;\mathbb{Z})$ of 
 Bloch bundle, we get the second Chern number of $E_{\hat{H}}$, which we denote by
 \begin{align*}
 c_2(\hat{H})=\langle c_2(E_{\hat{H}}), [T^4]\rangle \in \mathbb{Z}.
 \end{align*}

We define \( S^1 = \mathbb{R} / 2\pi \mathbb{Z} \), and identify \( T^4 = S^1 \times S^1 \times S^1 \times S^1 \).
For $(k_1, k_2, k_3) \in T^3=S^1\times S^1 \times S^1$,  
we define $\hat{H}^\sharp(k_1, k_2, k_3) : l^2(\mathbb{N}, \mathbb{C}^r) \to l^2(\mathbb{N}, \mathbb{C}^r)$ to be the compression of the multiplication operator with 
 $\hat{H}(k_1, k_2, k_3, \cdot) : T^3 \to Herm(\mathbb{C}^r)^{*}$, namely, the composition of
 $$
l^2(\mathbb{N}, \mathbb{C}^r) \overset{\hat{P}^*}{\longrightarrow}
l^2(\mathbb{Z}, \mathbb{C}^r) \overset{\hat{H}(k_1, k_2, k_3, \cdot)}{\longrightarrow}
l^2(\mathbb{Z}, \mathbb{C}^r) \overset{\hat{P}}{\longrightarrow}
l^2(\mathbb{N}, \mathbb{C}^r),
$$
where $\hat{P}$ is the orthogonal projection. Notice that $\hat{H}^\sharp(k_1, k_2, k_3)$ is essentially the Toeplitz operator \cite{Douglas} associated to $\hat{H}(k_1,k_2,k_3, \cdot).$ Then $\hat{H}^\sharp(k_1, k_2, k_3)$ is a self-adjoint bounded Fredholm operator. By the assumption that $\hat{H}(k_1, k_2, k_3, k_4)$ has both positive and negative eigenvalues, we obtain a continuous map $\hat{H}^\sharp : S^1 \to Fred_{sa}^1$.

We define the involution \(\tau\) on the torus \(T^4\) as follows:  
\[
\tau(k)=-k.
\]  
We assume that $\hat{H}$ has time-reversal symmetry corresponding to class AI.
That is, we assume that $K\hat{H}_xK=\hat{H}_{\tau(x)}$ for any $x\in T^4$. Here, \(K\) is the complex conjugation acting on \(\mathbb{C}^r\). That is, for \((a_1, a_2, \dots, a_r) \in \mathbb{C}^r\),
\begin{align*}
K(a_1, a_2, \dots, a_r) = (\bar{a_1}, \bar{a_2}, \dots, \bar{a_r}).
\end{align*}
In this case, the Bloch bundle $E_{\hat{H}}$ becomes a real vector bundle in the sense of Atiyah \cite{Atiyah66}. The Bloch bundle $E_{\hat{H}}$ is a real vector bundle because $K$ induces an antilinear map between the fibers over $x \in X$ and $\tau(x) \in X$.

\begin{thm}\label{BG}
If $\hat{H} : T^4 \to Herm(\mathbb{C}^r)^*$ is a continuous map with time-reversal symmetry of class AI and $\hat{H}(k)$ has positive and negative eigenvalues at
each $k \in T^4$, then $c_2(\hat{H}) = \int_{T^3}\operatorname{ch}_{\frac{3}{2}}([\hat{H}^\sharp])$.
\end{thm}

The proof of Theorem \ref{BG} will be given below.

Tentatively, we denote by $Herm_p(\mathbb{C}^r)$ the space of invertible Hermitian matrices which have $p$ negative eigenvalues and $r - p$ positive eigenvalues.

\begin{lem}\label{homotopy}
The following hold:
\begin{enumerate}
    \item The spaces \(\text{Herm}_p(\mathbb{C}^r)\) and \(\text{Gr}_p(\mathbb{C}^r)\) are \(\mathbb{Z}_2\)-equivariantly homotopy equivalent under the actions \(\tau(H) = \overline{H}\) and \(\varrho(V) = \overline{V}\).
    \item For a \(\mathbb{Z}_2\)-equivariant map \(\hat{H}: T^4 \to \text{Herm}_p(\mathbb{C}^r)\), the pullback of the universal bundle \(\mathcal{U}_p^\infty\) via this homotopy equivalence corresponds to the Bloch bundle \(E_{\hat{H}}\), i.e., \(h \circ \Phi_*([\hat{H}]) = [E_{\hat{H}}]\), where \(\Phi_*: [T^4, \text{Herm}_p(\mathbb{C}^r)]_{\mathbb{Z}_2} \to [T^4, \text{Gr}_p(\mathbb{C}^r)]_{\mathbb{Z}_2}\) is the map induced by the homotopy equivalence and \(h: [T^4, \text{Gr}_p(\mathbb{C}^r)]_{\mathbb{Z}_2} \to \text{Vect}_{\mathfrak{R}}^p(T^4)\) is defined by \(h([g]) = [g^*\mathcal{U}_p^\infty])\).
\end{enumerate}
\end{lem}

\begin{proof}
We define \(\Phi: \text{Herm}_p(\mathbb{C}^r) \to \text{Gr}_p(\mathbb{C}^r)\) by \(\Phi(H) = \ker(1 + \frac{H}{\|H\|})\), where the norm \(\|H\|\) is the maximum absolute value of the eigenvalues of \(H\), given by \(\|H\| = \max(|\lambda_{\text{max}}(H)|, |\lambda_{\text{min}}(H)|)\), with \(\lambda_{\text{max}}(H)\) being the largest positive eigenvalue and \(\lambda_{\text{min}}(H)\) the smallest negative eigenvalue of \(H\). We also define \(\Psi: \text{Gr}_p(\mathbb{C}^r) \to \text{Herm}_p(\mathbb{C}^r)\) by \(\Psi(V) = -P_V + P_{V^\perp}\), where \(P_V\) is the orthogonal projection onto the \(p\)-dimensional subspace \(V \subset \mathbb{C}^r\) and \(P_{V^\perp}\) is the orthogonal projection onto its orthogonal complement \(V^\perp\). 

We first verify the \(\mathbb{Z}_2\)-equivariance of these maps. For \(\Phi\),
\begin{align*}
\Phi(\tau(H)) &= \ker\left(1 + \frac{\overline{H}}{\|\overline{H}\|}\right) = \overline{\ker\left(1 + \frac{H}{\|H\|}\right)} = \varrho(\Phi(H)),
\end{align*}
and for \(\Psi\),
\begin{align*}
\Psi(\varrho(V)) &= -P_{\overline{V}} + P_{\overline{V}^\perp} = \overline{-P_V + P_{V^\perp}} = \tau(\Psi(V)).
\end{align*}

To establish that $\Psi$ is a homotopy inverse of $\Phi$, that is, $\Phi \circ \Psi \simeq \mathrm{id}$ and $\Psi \circ \Phi \simeq \mathrm{id}$, we compute \(\Phi \circ \Psi(V)\) as follows:
\[
\Phi \circ \Psi(V) = \Phi(-P_V + P_{V^\perp}) = \ker(1 + (-P_V + P_{V^\perp})).
\]
Since \(-P_V + P_{V^\perp}\) has eigenvalue \(-1\) on \(V\) and eigenvalue \(1\) on \(V^\perp\), the operator \(1 + (-P_V + P_{V^\perp})\) has kernel equal to \(V\). Therefore, we obtain \(\Phi \circ \Psi(V) = V\). Thus, \(\Phi \circ \Psi = 1_{\text{Gr}_p(\mathbb{C}^r)}\). For \(\Psi \circ \Phi\), we define a homotopy 
\begin{align*}
H_t = (1 - t)H + t(-P_{V_H} + P_{V_H^\perp}), \quad t \in [0,1],
\end{align*}
where \(V_H = \Phi(H)\). The matrix \(H_t\) remains Hermitian with \(p\) negative eigenvalues throughout \(t \in [0,1]\), and it satisfies \(\tau(H_t) = \overline{H_t}\), ensuring that \(H_t\) lies in \(\text{Herm}_p(\mathbb{C}^r)\). This homotopy connects \(H\) to \(\Psi(\Phi(H))\), proving that \(\Psi \circ \Phi \simeq 1_{\text{Herm}_p(\mathbb{C}^r)}\). Hence, $\Psi$ is a $\mathbb{Z}_2$-equivariant homotopy inverse of $\Phi$.

Next, we consider a \(\mathbb{Z}_2\)-equivariant map \(\hat{H}: T^4 \to \text{Herm}_p(\mathbb{C}^r)\) satisfying \(\hat{H}(\tau(k)) = \overline{\hat{H}(k)}\). The induced map \(\Phi_*([\hat{H}]) = [\Phi \circ \hat{H}]\) maps to \([T^4, \text{Gr}_p(\mathbb{C}^r)]_{\mathbb{Z}_2}\), and we compute \(h([\Phi \circ \hat{H}]) = [(\Phi \circ \hat{H})^*\mathcal{U}^\infty]\). Since \(\mathcal{U}^\infty_p\) over \(\text{Gr}_p(\mathbb{C}^r)\) corresponds to the tautological bundle \(\{(V, v) \mid v \in V\}\) under the equivalence \(\text{Gr}_p(\mathbb{C}^r) \simeq BU(p)\), the pullback is
\begin{align*}
(\Phi \circ \hat{H})^*\mathcal{U}^\infty_{p} = \{(k, v) \mid v \in V_{\hat{H}(k)}\},
\end{align*}
where \(V_{\hat{H}(k)} = \ker(1 + \frac{\hat{H}(k)}{\|\hat{H}(k)\|})\) is the negative eigenspace of \(\hat{H}(k)\). The Bloch bundle \(E_{\hat{H}}\) is defined as 
\begin{align*}
E_{\hat{H}} = \{(k, v) \mid \hat{H}(k)v = \lambda(k)v, \lambda(k) < 0\},
\end{align*}
which coincides with \(V_{\hat{H}(k)}\) by the construction of \(\Phi\). Therefore, we have \([(\Phi \circ \hat{H})^*\mathcal{U}^\infty_{p}] = [E_{\hat{H}}]\), and it follows that \(h \circ \Phi_*([\hat{H}]) = [E_{\hat{H}}]\).
\end{proof}

\begin{lem}\label{lem:5.9}
For any integer $n \in \mathbb{Z}$, we define $\hat{H}_n : T^4 \to \mathbb{C}^4$ by
\begin{align*}
\hat{H}_{n}(k_1, k_2, k_3, k_4)=\begin{pmatrix}
   a(k) & \bar{c}(k)-e^{ik_{4}} & 0 & \bar{b}(k) \\
   c(k)-e^{-ik_{4}} & -a(k) & \bar{b}(k) & 0 \\
   0 & b(k) & a(k) & -c(k)+e^{-ik_{4}} \\
   b(k) & 0 & -\bar{c}(k)+e^{ik_{4}} & -a(k)
\end{pmatrix}
\end{align*}
where 
\begin{align*}
&a(k)=-\cos(k_2+k_3), \\
&b(k)=-e^{-\sqrt{-1}nk_1}-e^{-\sqrt{-1}k_2}, \\
&c(k)=-1-e^{-\sqrt{-1}k_3}.
\end{align*}
Then, $c_2(\hat{H}_n)=-2n$.
\end{lem}

\begin{proof}
In the case that $n=1$, according to the results of previous research \cite{R}, $c_2(\hat{H})=-2$.
The map $H_n$ factors as $\hat{H}_n = \hat{H}_1 \circ f_n$, where $f_n : T^4 \to T^4$ is given by $f_n(k_1, k_2, k_3, k_4) = (n k_1, k_2, k_3, k_4)$. Since $f_n$ carries the fundamental class $[T^4] \in H_4(T^4; \mathbb{Z}) \cong \mathbb{Z}$ of the torus to $n [T^4]$, it follows that $c_2(\hat{H}_n) =-2n$.
\end{proof}

\begin{lem}\label{lem:5.10}
For each $m\geq 2$ there exsits a bijection 
\begin{align*}
\text{Vect}_{\mathcal{R}}^m(T^4, \tau) \cong 2\mathbb{Z}
\end{align*}
provided by the map $c_2 \circ J$.
\end{lem}

\begin{proof}
Refer to \cite{DG}.
\end{proof}

\begin{lem}\label{lem:5:11}
Let $2 \le p < r$ and let $k$ be a sufficiently large natural number. Then, there exists an isomorphism
\begin{align*}
[T^4, \mathrm{Herm}_p(\mathbb{C}^{r+k})]_{eq} \cong 2\mathbb{Z},
\end{align*}
which is given by the map
\begin{align*}
\hat{H} \mapsto c_2(E_{\hat{H}}).
\end{align*}
\end{lem}

\begin{proof}
We define
\begin{align*}
\hat{F}_{n}(k) &= \hat{H}_{n}(k) \oplus -1_{\mathbb{C}^{p-2}} \oplus 1_{\mathbb{C}^{(r+k)-p-2}}
\end{align*}
by using $\hat{H}_n$ as specified in Lemma~\ref{lem:5.9}, where $1$ denotes the identity map. Since Lemma~\ref{lem:5.9} shows that
\begin{align*}
c_2(\hat{F}_n) = -2n,
\end{align*}
the claim follows from Lemma~\ref{homotopy}, Lemma~\ref{lem:5.10}, and Theorem~\ref{thm:classyfy}.
\end{proof}

\begin{lem}\label{lem:4.21}
For $n \in \mathbb{Z}$, we have $\int_{T^3}\operatorname{ch}_{\frac{3}{2}}([\hat{H}_n^\sharp]=-2n$
\end{lem}

\begin{proof}
By solving the equations $a(k) = 0$, $b(k) = 0$, and $|c(k)| \leq 0$ derived from Proposition \ref{lem:5.8}, we can identify the Fermi set as follows:
\[
F = \bigcup_{l=1}^{n} \left\{ \left( \frac{2\pi}{3n} + \frac{2(l-1)\pi}{n}, \frac{4\pi}{3}, \frac{7\pi}{6} \right),\left( \frac{4\pi}{3n} + \frac{2(l-1)\pi}{n}, \frac{2\pi}{3}, \frac{5\pi}{6} \right) \right\}.
\]
Consequently, from Theorem \ref{thm:even main thm}, we obtain 
\[
\int_{T^3} \operatorname{ch}_{\frac{3}{2}}([\hat{H}_n^\sharp]) = -2n.
\]
\end{proof}

We are now in the position to prove Theorem \ref{BG}:

\begin{proof}
Because of Lemma \ref{lem:5:11}, if a map $\hat{H} : T^4 \to Herm(\mathbb{C}^r)^*$ satisfying the hypothesis of Theorem \ref{BG} has the Chern number $c_2(\hat{H}) = -2n$, then for a sufficiently large natural number $k$, $\hat{H} \oplus 1_{\mathbb{C}^k}$ is homotopic to $\hat{F}_n$. Here, \(\hat{F}_n\) is the map defined in the proof of Lemma \ref{lem:5:11}. Then, the associated families of self-adjoint Fredholm operators $(\hat{H} \oplus 1_{\mathbb{C}^k})^\sharp : T^3 \to Fred_{sa}^1$, $\hat{H}^\sharp : T^3 \to Fred_{sa}^1$, and $\hat{F}^\sharp_n : T^3 \to Fred_{sa}^1$ are also homotopic. Since the Chern character is a homotopy invariant, it follows that 
\[
\int_{T^3} \operatorname{ch}_{\frac{3}{2}}([(\hat{H} \oplus 1_{\mathbb{C}^k})^\sharp]) = \int_{T^3} \operatorname{ch}_{\frac{3}{2}}(\hat{F}^\sharp_n).
\]
By Lemma \ref{lem:4.21}, we see 
\[
\int_{T^3} \operatorname{ch}_{\frac{3}{2}}(\hat{F}^\sharp_n) = \int_{T^3} \operatorname{ch}_{\frac{3}{2}}([\hat{H}_n^\sharp]) = -2n.
\]
Hence $c_2(\hat{H}) = \int_{T^3} ch_{\frac{3}{2}}([\hat{H}_n^\sharp])$ is established.
\end{proof}

