\begin{figure}[h!]
 \centerline{\includegraphics[width=6cm]{casimir-4-plaques.jpg}} 
 \caption{ \small \it By assuming that the two plates are themselves confined between two other plates at large distance $d$, we see that the force exerted form the outside is negligible, since the force scales as $1/d^4$.
} \label{fig:Casimir2}
